                        "components": .object(["type": .string("object"), "description": .string("新的 MathComponent JSON tree，同 insert_equation(components:) 格式")]),
                        "display_mode": .object(["type": .string("boolean"), "description": .string("是否為獨立區塊（預設保留原值）")])
                    ]),
