    // MARK: - Dual-Mode Document Resolution

    /// Resolve document from either source_path (Direct Mode) or doc_id (Session Mode)
    /// - Returns: (document, isTemporary) - isTemporary=true means opened just for this call
    private func resolveDocument(args: [String: Value]) async throws -> (WordDocument, Bool) {
        if let sourcePath = args["source_path"]?.stringValue {
            // Direct Mode - open temporarily, read-only
            guard FileManager.default.fileExists(atPath: sourcePath) else {
                throw WordError.fileNotFound(sourcePath)
            }
            let sourceURL = URL(fileURLWithPath: sourcePath)
            let lockFile = sourceURL.deletingLastPathComponent()
                .appendingPathComponent("~$" + sourceURL.lastPathComponent)
            if FileManager.default.fileExists(atPath: lockFile.path) {
                throw WordError.invalidFormat("File is open in Microsoft Word. Please save and close it first: \(sourceURL.lastPathComponent)")
            }
            var document = try DocxReader.read(from: sourceURL)
            // #221 RED-instrumentation: records the specific tempDir this
            // one Direct Mode call extracted, so a test can assert on THAT
            // exact path (see DocumentProfileToolsTests's precedent) rather
            // than diffing the whole shared `$TMPDIR/che-word-mcp/`
            // namespace, which is racy against any other concurrently
            // running process touching a real .docx. Captured BEFORE
            // `close()`, which nils out `archiveTempDir`.
            logDebug(event: "resolveDocument.directModeArchiveExtracted", [
                ("archive_temp_dir", document.archiveTempDir?.path ?? "nil"),
            ])
            // #221: `DocxReader.read` hands ownership of its unzip tempDir to
            // `document.preservedArchive` and documents "Caller MUST call
            // `close()`" — every one of this function's 20+ call sites
            // destructures the `isTemporary` flag straight into `_` and
            // never does. Direct Mode is read-only (doc comment above) and
            // every field a Direct-Mode caller reads off `document`
            // (paragraphs/runs/images-as-`Data`/etc.) is already fully
            // materialized by `read()` — no Direct-Mode caller reads
            // `archiveTempDir` afterward (that lazy raw-XML-part access
            // path — `readArchivePart`/`setTheme`/header-footer tools — is
            // Session-Mode-only, via `openDocuments[docId]`, never through
            // this function) — so releasing the tempDir right here, before
            // handing the document back, is safe and closes the leak at
            // its one shared choke point instead of in each of the 20+
            // callers individually.
            document.close()
            return (document, true)
        } else if let docId = args["doc_id"]?.stringValue {
            // Session Mode - use already-opened document
            guard let doc = openDocuments[docId] else {
                throw WordError.documentNotFound(docId)
            }
            return (doc, false)
        } else {
            throw WordError.missingParameter("source_path or doc_id")
        }
    }

    // MARK: - Document Management

    private func createDocument(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        if openDocuments[docId] != nil {
            throw WordError.documentAlreadyOpen(docId)
        }

        let autosave = try optionalBool(args, "autosave") ?? false
        // #170: this used to enable track changes unconditionally, so every new
        // document shipped with `<w:trackChanges/>` in settings.xml — the
        // recipient opened it in Word with the Track Changes button lit, and
        // their first keystroke became a red revision mark.
        //
        // A brand-new document has nothing to track. "Review mode" means
        // "mark changes against existing content", and there is no existing
        // content. The default belongs off.
        //
        // v3.0.0 (#13) already flipped this default for `open_document` and
        // stopped here — the same fix, applied to one of the two ways a session
        // begins. Defaults now match, and both take `track_changes: true` to
        // opt in.
        let trackChanges = try optionalBool(args, "track_changes") ?? false
        let profile = try resolveDocumentProfile(args: args, context: .newDocument)
        var doc = WordDocument()
        if let profile { try doc.applyFormattingProfile(profile, context: .newDocument) }
        if trackChanges {
            doc.enableTrackChanges(author: defaultRevisionAuthor)
        }
        initializeSession(docId: docId, document: doc, sourcePath: nil, autosave: autosave)
        // Override trackChangesEnforced default (initializeSession sets true),
        // exactly as open_document does. Without this the handler flag above is
        // cosmetic: `enforceTrackChangesIfNeeded` runs on every dirty store and
        // re-enables track changes whenever `documentTrackChangesEnforced` is
        // true, so the first insert_paragraph would put the mode back and the
        // saved settings.xml would still carry <w:trackChanges/>.
        //
        // That is what #13 missed — it added this override to open_document and
        // not here, so the two entry points disagreed for two major versions
        // while both reported a default.
        documentTrackChangesEnforced[docId] = trackChanges

        if profile?.kind == .official {
            try await storeDocument(doc, for: docId)
        }

        return trackChanges
            ? "Created new document with id: \(docId). Track changes enabled (requested)."
            : "Created new document with id: \(docId). Track changes disabled (default since #170; pass track_changes: true to enable)."
    }

    private func openDocument(args: [String: Value]) async throws -> String {
        guard let path = args["path"]?.stringValue else {
            throw WordError.missingParameter("path")
        }
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        if openDocuments[docId] != nil {
            throw WordError.documentAlreadyOpen(docId)
        }
        let autosave = try optionalBool(args, "autosave") ?? false
        // BREAKING v3.0.0: track_changes default flipped from on → off (Refs #13)
        let trackChanges = try optionalBool(args, "track_changes") ?? false
        // Phase 4 (v3.6.0, closes #37): per-N-mutations checkpoint throttle.
        // Phase C (Design B, #40): default flipped from 0 to 1.
        // Callers wanting zero autosave overhead must explicitly pass autosave_every: 0.
        let autosaveEveryN = try optionalInt(args, "autosave_every") ?? 1
        let profile = try resolveDocumentProfile(args: args, context: .existingDocument)

        let url = URL(fileURLWithPath: path)
        var doc = try DocxReader.read(from: url)
        // #232 R4 test seam: records which extracted-archive path THIS open
        // attempt owns, the moment DocxReader.read succeeds — independent of
        // whether the rest of this call later fails and rolls the session
        // back. Lets a test assert on that ONE specific path's fate instead
        // of diffing ooxml-swift's shared, unscoped `che-word-mcp` temp
        // namespace (which every concurrently-running test that touches any
        // real .docx also writes into, and which nothing here can redirect
        // per-test — see DocumentProfileToolsTests.swift's root-cause doc
        // comment). No-op unless debug logging is enabled.
        logDebug(event: "openDocument.archiveExtracted", [("doc_id", docId), ("archive_temp_dir", doc.archiveTempDir?.path ?? "nil")])
        do {
            if let profile { try doc.applyFormattingProfile(profile, context: .existingDocument) }
        } catch {
            doc.close()
            throw error
        }
        if trackChanges && !doc.isTrackChangesEnabled() {
            doc.enableTrackChanges(author: defaultRevisionAuthor)
        }
        initializeSession(
            docId: docId, document: doc, sourcePath: path,
            autosave: autosave, autosaveEveryN: autosaveEveryN
        )
        // This call owns a new session only: the duplicate-id guard ran before
        // reading the document. Roll back all session state and its extracted
        // archive if profile-triggered autosave fails after initialization.
        var openedSuccessfully = false
        defer { if !openedSuccessfully { removeSession(docId: docId) } }
        recordImageBaseline(docId: docId, path: path)
        // Override trackChangesEnforced default (initializeSession sets true)
        documentTrackChangesEnforced[docId] = trackChanges

        // Capture disk-hash + mtime from freshly opened file (3.0.0 — Refs #15)
        if let hash = try? SessionState.computeSHA256(path: path) {
            documentDiskHash[docId] = hash
        }
        if let mtime = try? SessionState.readMtime(path: path) {
            documentDiskMtime[docId] = mtime
        }

        if profile?.kind == .official {
            try await storeDocument(doc, for: docId)
        }

        let tcLabel = trackChanges ? "Track changes enabled." : "Track changes disabled (default since v3.0.0; pass track_changes: true to enable)."
        openedSuccessfully = true
        return "Opened document '\(path)' with id: \(docId). \(tcLabel)"
    }

    // MARK: - #175 image-consistency save gate (PsychQuant/macdoc#175)

    /// Pure decision core for the save-time image-consistency gate. Given the
    /// part-qualified orphan image relationships of the bytes about to be
    /// written, the orphans snapshotted at open (or last gated save), and the
    /// raw report counts, return the refusal message — or nil to allow.
    ///
    /// Only NEW orphans (absent from the baseline) block: files opened with
    /// pre-existing unreferenced image relationships — a state Word tolerates
    /// and third-party writers produce — keep saving normally.
    static func imageConsistencyRefusalMessage(
        orphanIds: [String],
        baselineOrphanIds: Set<String>,
        bodyDrawingCount: Int,
        imageRelationshipCount: Int,
        mediaEntryCount: Int
    ) -> String? {
        let newOrphans = orphanIds.filter { !baselineOrphanIds.contains($0) }
        guard !newOrphans.isEmpty else { return nil }
        return """
        E_IMAGE_CONSISTENCY — refusing to save: \(newOrphans.count) image relationship(s) declared in the package have no reference in their own part (the PsychQuant/macdoc#175 silent-image-loss signature). No file was written; the session is still open.
        Orphan relationship(s): \(newOrphans.joined(separator: ", "))
        Counts: bodyDrawings=\(bodyDrawingCount), imageRelationships=\(imageRelationshipCount), mediaEntries=\(mediaEntryCount)
        Two possible causes — check before acting:
          1. An image inserted this session was dropped from the document body. Compare list_images with get_paragraphs; only if the image is missing from the text, re-insert it and save again.
          2. You deliberately deleted a paragraph that contained an image; the leftover relationship is harmless. Re-run with allow_orphan_images: true.
        Do not route around this error via checkpoint, autosave, or saving to another path: those carry the same check and the baseline is fixed at open time, so the refusal repeats.
        """
    }

    /// Fail-closed variant: the check itself could not run. Refusing here is
    /// what makes "the gate passed" mean something (R1 codex F3 / logic M5).
    static func imageConsistencyInspectionRefusal(reason: String) -> String {
        """
        E_IMAGE_CONSISTENCY_INSPECTION — could not verify image consistency before saving: \(reason). No file was written; the session is still open.
        Retry the save. If it repeats, the package could not be inspected at all — do NOT bypass with allow_orphan_images (that flag acknowledges known orphans, it does not cover an uninspectable package); report the reason above and use checkpoint (default recovery sidecar) to preserve the session state.
        """
    }

    /// Parse `allow_orphan_images`: absent / JSON null → false; a boolean →
    /// itself; anything else is an error rather than a silent false (R1 #14).
    static func allowOrphanImagesFlag(_ args: [String: Value]) throws -> Bool {
        guard let v = args["allow_orphan_images"] else { return false }
        switch v {
        case .bool(let b): return b
        case .null: return false
        default:
            throw WordError.invalidParameter(
                "allow_orphan_images",
                "must be a boolean (true/false); got \(v). Strings such as \"true\" are not accepted.")
        }
    }

    /// Snapshot the part-qualified image orphans of the package at `path`.
    /// An unreadable / uninspectable package snapshots as empty, which makes
    /// the next gated save fail closed (E_IMAGE_CONSISTENCY_INSPECTION) rather
    /// than silently pass.
    private func recordImageBaseline(docId: String, path: String) {
        guard let data = FileManager.default.contents(atPath: path),
              let report = try? PackageInspector.imageConsistencyReport(of: data) else {
            documentImageOrphanBaseline[docId] = []
            documentImageRelationshipCountAtBaseline[docId] = Int.max   // uninspectable → never short-circuit
            return
        }
        documentImageOrphanBaseline[docId] = Set(report.orphanImageRelationshipRefs.map(\.qualified))
        documentImageRelationshipCountAtBaseline[docId] = report.imageRelationshipCount
    }

    /// Serialize-and-check wrapper shared by save_document / finalize_document,
    /// the autosave:true path, the shutdown flush, and checkpoint-to-source.
    /// Returns a refusal message, or nil to allow the write.
    ///
    /// Documents with no images skip the gate entirely: a session-new orphan
    /// can only come from `insertImage`, which always appends to `images`
    /// (R1 regression M4 — halves save cost for the common case).
    /// True when any part of the package can carry an image relationship
    /// (body images, or header/footer image relationships). Header/footer
    /// images are not in `document.images`, so the earlier `images.isEmpty`
    /// short-circuit silently skipped the per-part inspector's new coverage
    /// (R2 requirements R2-2 / logic M3).
    static func documentMayCarryImages(_ document: WordDocument, packageImageRelationshipsAtBaseline: Int) -> Bool {
        if packageImageRelationshipsAtBaseline > 0 { return true }          // anything declared anywhere in the opened package
        if !document.images.isEmpty { return true }                         // session-added body images
        if document.headers.contains(where: { !$0.relationships.imageRelationships.isEmpty }) { return true }
        if document.footers.contains(where: { !$0.relationships.imageRelationships.isEmpty }) { return true }
        return false
    }

    private func documentMayCarryImages(_ document: WordDocument, docId: String) -> Bool {
        Self.documentMayCarryImages(document, packageImageRelationshipsAtBaseline: documentImageRelationshipCountAtBaseline[docId] ?? 0)
    }

    /// The exact bytes `persistDocumentToDisk` is about to write: overlay
    /// mode (`DocxWriter.write(_:to:)`) when the document carries a preserved
    /// source archive, scratch mode when it does not — the SAME branch
    /// `DocxWriter` itself takes internally on `document.archiveTempDir`.
    ///
    /// che-word-mcp#220: the save gate used to inspect `DocxWriter.writeData`,
    /// which is ALWAYS scratch mode (only typed-model-managed parts). A real
    /// save from an opened document goes through the overlay path instead,
    /// which additionally preserves parts the typed model does not manage at
    /// all — charts, header/footer image relationships nested inside them,
    /// diagrams. Those parts (and any orphan image relationship declared
    /// inside them) were therefore invisible to the gate even though they are
    /// written verbatim to the real output file: "gate passed" asserted
    /// nothing about them. Writing to a throwaway temp URL through the public
    /// `DocxWriter.write(_:to:)` entry point — the same call
    /// `persistDocumentToDisk` makes — and reading those bytes back is the
    /// only way to reach the overlay branch without duplicating its
    /// internal `document.archiveTempDir != nil` decision here.
    static func persistableBytes(for document: WordDocument) throws -> Data {
        let tempURL = FileManager.default.temporaryDirectory
            .appendingPathComponent("che-word-mcp-gate-\(UUID().uuidString).docx")
        defer { try? FileManager.default.removeItem(at: tempURL) }
        try DocxWriter.write(document, to: tempURL)
        return try Data(contentsOf: tempURL)
    }

    private func imageConsistencySaveRefusal(_ document: WordDocument, docId: String) -> String? {
        guard documentMayCarryImages(document, docId: docId) else { return nil }
        let data: Data
        do { data = try Self.persistableBytes(for: document) }
        catch { return Self.imageConsistencyInspectionRefusal(reason: "serialization failed: \(error.localizedDescription)") }
        let report: ImageConsistencyReport
        do { report = try PackageInspector.imageConsistencyReport(of: data) }
        catch { return Self.imageConsistencyInspectionRefusal(reason: "package inspection failed: \(error.localizedDescription)") }
        guard !report.isConsistent else { return nil }
        return Self.imageConsistencyRefusalMessage(
            orphanIds: report.orphanImageRelationshipRefs.map(\.qualified),
            baselineOrphanIds: documentImageOrphanBaseline[docId] ?? [],
            bodyDrawingCount: report.bodyDrawingCount,
            imageRelationshipCount: report.imageRelationshipCount,
            mediaEntryCount: report.mediaEntryCount)
    }
    private func saveDocument(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let explicitPath = args["path"]?.stringValue
        let path = try effectiveSavePath(for: docId, explicitPath: explicitPath)   // path errors first (R1 #14)
        let allowOrphanImages = try Self.allowOrphanImagesFlag(args)
        if !allowOrphanImages, let refusal = imageConsistencySaveRefusal(doc, docId: docId) {
            throw ToolRefusal(refusal)
        }
        let keepBak = try optionalBool(args, "keep_bak") ?? false
        try persistDocumentToDisk(doc, docId: docId, path: path, keepBak: keepBak)
        if documentMayCarryImages(doc, docId: docId) { recordImageBaseline(docId: docId, path: path) }   // acknowledged state is the new baseline
        // Phase 4: clean up <source>.autosave.docx after successful save.
        cleanupAutosaveFile(for: docId)

        let bakSuffix = keepBak && FileManager.default.fileExists(atPath: path + ".bak")
            ? " (pre-save bytes preserved at \(path).bak)"
            : ""
        if explicitPath == nil {
            return "Saved document to original path: \(path)\(bakSuffix)"
        }
        return "Saved document to: \(path)\(bakSuffix)"
    }

    private func closeDocument(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard openDocuments[docId] != nil else {
            throw WordError.documentNotFound(docId)
        }
        // v3.0.0: explicit discard flag (Refs #12)
        let discardChanges = try optionalBool(args, "discard_changes") ?? false

        if isDirty(docId: docId) && !discardChanges {
            throw ToolRefusal("""
            E_DIRTY_DOC — document '\(docId)' has uncommitted changes.
            Choose one:
              - call save_document first to persist your edits, then close_document
              - pass discard_changes: true to release without saving
              - use finalize_document for save+close in one step
            """)
        }

        removeSession(docId: docId)
        let suffix = (discardChanges && openDocuments[docId] == nil) ? " (changes discarded)" : ""
        return "Closed document: \(docId)\(suffix)"
    }

    private func finalizeDocument(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let explicitPath = args["path"]?.stringValue
        let path = try effectiveSavePath(for: docId, explicitPath: explicitPath)
        let allowOrphanImages = try Self.allowOrphanImagesFlag(args)
        if !allowOrphanImages, let refusal = imageConsistencySaveRefusal(doc, docId: docId) {
            throw ToolRefusal(refusal)    // refusal precedes persist AND removeSession — the session survives
        }
        try persistDocumentToDisk(doc, docId: docId, path: path)
        // Phase 4: clean up <source>.autosave.docx after successful finalize.
        cleanupAutosaveFile(for: docId)
        removeSession(docId: docId)

        return "Finalized document '\(docId)' to: \(path)"
    }

    // MARK: - Phase 4 (v3.6.0, closes #37) — checkpoint + recover_from_autosave

    /// `checkpoint` MCP tool — manual session state write. Defaults to
    /// `<source>.autosave.docx`; explicit `path` overrides. Does NOT clear
    /// is_dirty (unlike save_document), does NOT update disk_hash/disk_mtime.
    private func checkpoint(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let target: String
        if let explicit = args["path"]?.stringValue, !explicit.isEmpty {
            target = explicit
        } else {
            guard let sourcePath = documentOriginalPaths[docId], !sourcePath.isEmpty else {
                throw WordError.invalidParameter(
                    "path",
                    "checkpoint default path requires the document to have a known source path; pass explicit path or open from disk first."
                )
            }
            target = sourcePath + ".autosave.docx"
        }

        // macdoc#175 R2/R3: any EXPLICIT checkpoint path is a deliverable-shaped
        // write (a case variant or symlink of the source, or a file someone
        // will open) — it carries the same gate as save_document, with the
        // same allow_orphan_images escape. Only the default recovery sidecar
        // (`<source>.autosave.docx`) is ungated: it never clobbers the source
        // and, since the baseline is an open-time snapshot, cannot launder it.
        // Path-string comparison was bypassed by case/symlink variants
        // (R2 security S2/S3, logic N3) — so the rule is by intent, not by path.
        // #232 R6 (review H2b): parsed unconditionally, before the
        // explicitTarget gate — a mistyped allow_orphan_images supplied
        // WITHOUT an explicit path used to be silently ignored (never read
        // at all), since only the explicit-path branch consulted it.
        let allow = try Self.allowOrphanImagesFlag(args)
        let explicitTarget = args["path"]?.stringValue.map { !$0.isEmpty } ?? false
        if explicitTarget {
            if !allow, let refusal = imageConsistencySaveRefusal(doc, docId: docId) {
                throw ToolRefusal(refusal)
            }
        }
        try DocxWriter.write(doc, to: URL(fileURLWithPath: target))
        return "Checkpoint written for '\(docId)' to: \(target)"
    }

    /// `recover_from_autosave` MCP tool — replace in-memory doc with bytes
    /// from `<source>.autosave.docx`, set is_dirty: true, do NOT delete the
    /// autosave file (cleanup deferred to next save_document).
    private func recoverFromAutosave(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard openDocuments[docId] != nil else {
            throw WordError.documentNotFound(docId)
        }
        guard let sourcePath = documentOriginalPaths[docId], !sourcePath.isEmpty else {
            throw ToolRefusal("E_NO_AUTOSAVE — document '\(docId)' has no known source path.")
        }
        let autosavePath = sourcePath + ".autosave.docx"
        guard FileManager.default.fileExists(atPath: autosavePath) else {
            throw ToolRefusal("E_NO_AUTOSAVE — no autosave file at '\(autosavePath)'.")
        }

        let discardChanges = try optionalBool(args, "discard_changes") ?? false
        if isDirty(docId: docId) && !discardChanges {
            throw ToolRefusal("""
            E_DIRTY_DOC — document '\(docId)' has uncommitted changes.
            Choose one:
              - call save_document first to persist current edits, then recover_from_autosave
              - pass discard_changes: true to overwrite in-memory state with autosave bytes
              - use finalize_document to save+close before recovering
            """)
        }

        let recoveredDoc = try DocxReader.read(from: URL(fileURLWithPath: autosavePath))
        // R2 (#221 H1): mirrors `openDocument.archiveExtracted` — lets tests
        // pin the exact tempDir THIS read extracted, the same "one specific
        // path, not a namespace diff" technique #221's own tests use.
        logDebug(event: "recoverFromAutosave.archiveExtracted", [
            ("doc_id", docId), ("archive_temp_dir", recoveredDoc.archiveTempDir?.path ?? "nil"),
        ])
        replaceOpenDocument(docId: docId, with: recoveredDoc)
        documentDirtyState[docId] = true
        return "Recovered document '\(docId)' from autosave: \(autosavePath). Call save_document to persist."
    }

    private func getDocumentSessionState(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let dirty = isDirty(docId: docId)
        let autosaveEnabled = documentAutosave[docId] ?? false
        let trackChangesEnforced = documentTrackChangesEnforced[docId] ?? true
        let trackChangesEnabled = doc.isTrackChangesEnabled()
        let originalPath = documentOriginalPaths[docId]
        let closeReady = !dirty
        let saveReady = originalPath != nil
        let finalizeReady = saveReady

        return """
        Document Session State (\(docId)):
        - Dirty: \(dirty)
        - Autosave enabled: \(autosaveEnabled)
        - Track changes enabled: \(trackChangesEnabled)
        - Track changes enforced by server: \(trackChangesEnforced)
        - Original path: \(originalPath ?? "(none)")
        - Save without explicit path available: \(saveReady)
        - Close without save allowed: \(closeReady)
        - Finalize without explicit path available: \(finalizeReady)
        """
    }

    // MARK: - v3.0.0 Session State API (Refs #12 #13 #15)

    /// ISO8601 formatter for serialized session responses. Lazy static.
    private static let iso8601Formatter: ISO8601DateFormatter = {
        let f = ISO8601DateFormatter()
        f.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return f
    }()

    /// Hex encoding for SHA256 Data.
    private func hexString(_ data: Data) -> String {
        return data.map { String(format: "%02x", $0) }.joined()
    }

    /// get_session_state — superset of get_document_session_state
    private func getSessionState(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let view = sessionStateView(for: docId) else {
            throw WordError.documentNotFound(docId)
        }
        let diskHashHex = view.diskHash.map { hexString($0) } ?? "(none)"
        let diskMtime = view.diskMtime.map { Self.iso8601Formatter.string(from: $0) } ?? "(none)"
        return """
        Session State (\(docId)):
        - source_path: \(view.sourcePath)
        - disk_hash_hex: \(diskHashHex)
        - disk_mtime_iso8601: \(diskMtime)
        - is_dirty: \(view.isDirty)
        - track_changes_enabled: \(view.trackChangesEnabled)
        - autosave_detected: \(view.autosaveDetected)
        - autosave_path: \(view.autosavePath ?? "(none)")
        """
    }

    /// revert_to_disk — re-read sourcePath, replace in-memory doc, reset dirty. Destructive-by-design.
    private func revertToDisk(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard openDocuments[docId] != nil else {
            throw WordError.documentNotFound(docId)
        }
        guard let path = documentOriginalPaths[docId], !path.isEmpty else {
            throw ToolRefusal("document '\(docId)' has no known source path to revert from")
        }

        let url = URL(fileURLWithPath: path)
        let fresh = try DocxReader.read(from: url)
        // R2 (#221 H1): see `recoverFromAutosave`'s matching comment.
        logDebug(event: "revertToDisk.archiveExtracted", [
            ("doc_id", docId), ("archive_temp_dir", fresh.archiveTempDir?.path ?? "nil"),
        ])
        replaceOpenDocument(docId: docId, with: fresh)
        documentDirtyState[docId] = false
        recordImageBaseline(docId: docId, path: path)
        if let hash = try? SessionState.computeSHA256(path: path) {
            documentDiskHash[docId] = hash
        }
        if let mtime = try? SessionState.readMtime(path: path) {
            documentDiskMtime[docId] = mtime
        }
        return "Reverted '\(docId)' to disk state from \(path). All in-memory edits discarded."
    }

    /// reload_from_disk — cooperative reload (requires force on dirty).
    private func reloadFromDisk(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard openDocuments[docId] != nil else {
            throw WordError.documentNotFound(docId)
        }
        let force = try optionalBool(args, "force") ?? false
        if isDirty(docId: docId) && !force {
            throw ToolRefusal("""
            document '\(docId)' has uncommitted changes. Your in-memory edits would be lost.
            Options:
              - call save_document first to persist your edits, then retry reload_from_disk
              - pass force: true to discard your edits and reload from disk
            """)
        }
        // Same semantics as revert from here.
        guard let path = documentOriginalPaths[docId], !path.isEmpty else {
            throw ToolRefusal("document '\(docId)' has no known source path to reload from")
        }
        let url = URL(fileURLWithPath: path)
        let fresh = try DocxReader.read(from: url)
        // R2 (#221 H1): see `recoverFromAutosave`'s matching comment.
        logDebug(event: "reloadFromDisk.archiveExtracted", [
            ("doc_id", docId), ("archive_temp_dir", fresh.archiveTempDir?.path ?? "nil"),
        ])
        replaceOpenDocument(docId: docId, with: fresh)
        documentDirtyState[docId] = false
        recordImageBaseline(docId: docId, path: path)
        if let hash = try? SessionState.computeSHA256(path: path) {
            documentDiskHash[docId] = hash
        }
        if let mtime = try? SessionState.readMtime(path: path) {
            documentDiskMtime[docId] = mtime
        }
        return "Reloaded '\(docId)' from disk at \(path). External edits picked up."
    }

    /// check_disk_drift — informational status, never errors except for missing doc_id.
    private func checkDiskDrift(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard openDocuments[docId] != nil else {
            throw WordError.documentNotFound(docId)
        }
        guard let path = documentOriginalPaths[docId], !path.isEmpty else {
            return """
            Disk drift for '\(docId)':
            - drifted: true
            - reason: no known source path (cannot compare)
            """
        }
        let storedHash = documentDiskHash[docId]
        let storedMtime = documentDiskMtime[docId]
        let currentHash: Data?
        let currentMtime: Date?
        do {
            currentHash = try SessionState.computeSHA256(path: path)
            currentMtime = try SessionState.readMtime(path: path)
        } catch {
            return """
            Disk drift for '\(docId)':
            - drifted: true
            - reason: source file unreadable (\(error.localizedDescription))
            """
        }
        let hashMatches = (storedHash != nil) && (storedHash == currentHash)
        let mtimeMatches = (storedMtime != nil) && (storedMtime == currentMtime)
        let drifted = !hashMatches || !mtimeMatches
        let storedMtimeStr = storedMtime.map { Self.iso8601Formatter.string(from: $0) } ?? "(none)"
        let currentMtimeStr = currentMtime.map { Self.iso8601Formatter.string(from: $0) } ?? "(none)"
        return """
        Disk drift for '\(docId)':
        - drifted: \(drifted)
        - disk_mtime: \(currentMtimeStr)
        - stored_mtime: \(storedMtimeStr)
        - disk_hash_matches: \(hashMatches)
        """
    }

    private func listOpenDocuments() async -> String {
        if openDocuments.isEmpty {
            return "No documents currently open"
        }

        let ids = openDocuments.keys.sorted()
        return "Open documents:\n" + ids.map { "- \($0)" }.joined(separator: "\n")
    }

    private func getDocumentInfo(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)

        let info = doc.getInfo()
        let label = args["doc_id"]?.stringValue ?? args["source_path"]?.stringValue ?? "unknown"
        let rows = Self.collectImageRows(doc)
        let (report, failureReason, unreferencedMedia) = imageConsistencyInspection(forDoc: doc, args: args)
        let imagesLine = Self.documentInfoImagesLine(rows: rows, report: report, inspectionFailureReason: failureReason, unreferencedMediaFiles: unreferencedMedia)
        return """
        Document Info (\(label)):
        - Paragraphs: \(info.paragraphCount)
        - Characters: \(info.characterCount)
        - Words: \(info.wordCount)
        - Tables: \(info.tableCount)
        - Images: \(imagesLine)
        """
    }

    /// #199/#217/#219 shared row model: one entry per image relationship this
    /// reader can name. Document-part rows come from `doc.getImages()` (rels
    /// authority already, per v0.13.1) and always carry a concrete pixel size
    /// (0x0 for a body relationship with no matching `<w:drawing>` — a real
    /// value, not a placeholder for "unknown"). Header/footer rows come from
    /// each container's own `relationships.imageRelationships` (#219) — this
    /// reader has no typed pixel size for those, so `widthPx`/`heightPx` are
    /// `nil` ("not applicable here", not "zero").
    static func collectImageRows(_ doc: WordDocument) -> [(part: String, id: String, fileName: String, widthPx: Int?, heightPx: Int?)] {
        var rows: [(part: String, id: String, fileName: String, widthPx: Int?, heightPx: Int?)] = []
        for img in doc.getImages() {
            rows.append((part: "word/document.xml", id: img.id, fileName: img.fileName, widthPx: img.widthPx, heightPx: img.heightPx))
        }
        for header in doc.headers {
            for rel in header.relationships.imageRelationships {
                rows.append((part: "word/\(header.fileName)", id: rel.id, fileName: (rel.target as NSString).lastPathComponent, widthPx: nil, heightPx: nil))
            }
        }
        for footer in doc.footers {
            for rel in footer.relationships.imageRelationships {
                rows.append((part: "word/\(footer.fileName)", id: rel.id, fileName: (rel.target as NSString).lastPathComponent, widthPx: nil, heightPx: nil))
            }
        }
        return rows
    }

    /// #199 — the same authoritative signal `imageConsistencySaveRefusal`
    /// (the save gate) reads: `PackageInspector.imageConsistencyReport` over
    /// the serialized package bytes (Direct Mode: the bytes on disk; Session
    /// Mode: `DocxWriter.writeData(doc)`, a pure call that does not dirty the
    /// session). `report == nil` means the check itself could not run — the
    /// caller gets `failureReason`, never a silent "assume consistent".
    ///
    /// #208 R2 F2: also returns `unreferencedMediaFiles` — the "reverse
    /// orphan" `PackageInspector` does not cover (a media file with ZERO
    /// relationships pointing at it, not a relationship with none — see
    /// `stripWatermark`'s doc comment for how a pre-R2 watermark
    /// insert/remove cycle produced exactly this). Computed independently of
    /// `PackageInspector`: this reader already has, from the typed model, the
    /// complete set of media filenames any relationship it knows about
    /// (`document.images`, every header's and footer's
    /// `relationships.imageRelationships`) — cross-referencing that against
    /// the package's actual `word/media/` directory listing needs no rels
    /// re-parsing (the #137/#138 rabbit hole `PackageInspector` itself exists
    /// to avoid re-treading).
    private func imageConsistencyInspection(forDoc doc: WordDocument, args: [String: Value]) -> (report: ImageConsistencyReport?, failureReason: String?, unreferencedMediaFiles: [String]) {
        let packageData: Data?
        if let sourcePath = args["source_path"]?.stringValue {
            packageData = FileManager.default.contents(atPath: sourcePath)
        } else {
            packageData = try? DocxWriter.writeData(doc)
        }
        guard let packageData else { return (nil, "package bytes unavailable", []) }

        let report: ImageConsistencyReport?
        let failureReason: String?
        do {
            report = try PackageInspector.imageConsistencyReport(of: packageData)
            failureReason = nil
        } catch {
            report = nil
            failureReason = error.localizedDescription
        }

        var unreferenced: [String] = []
        if let tempDir = try? ZipHelper.unzip(data: packageData) {
            defer { ZipHelper.cleanup(tempDir) }
            let mediaDir = tempDir.appendingPathComponent("word/media")
            if let files = try? FileManager.default.contentsOfDirectory(atPath: mediaDir.path) {
                unreferenced = Self.unreferencedMediaFiles(mediaDirFiles: files, doc: doc)
            }
        }
        return (report, failureReason, unreferenced)
    }

    /// #208 R2 F2: media file names present in `word/media/` that no
    /// relationship this reader can enumerate (document body, any header,
    /// any footer) declares as its `target`. Pure and independent of
    /// `PackageInspector` — see `imageConsistencyInspection`'s doc comment.
    static func unreferencedMediaFiles(mediaDirFiles: [String], doc: WordDocument) -> [String] {
        var referenced = Set(doc.images.map(\.fileName))
        for header in doc.headers {
            for rel in header.relationships.imageRelationships {
                referenced.insert((rel.target as NSString).lastPathComponent)
            }
        }
        for footer in doc.footers {
            for rel in footer.relationships.imageRelationships {
                referenced.insert((rel.target as NSString).lastPathComponent)
            }
        }
        return mediaDirFiles.filter { !referenced.contains($0) }.sorted()
    }

    /// #217 — one-line image summary for `get_document_info`. Never reports a
    /// bare relationship count as if it were "images that exist": counts are
    /// always split into referenced vs. orphan once the check ran.
    static func documentInfoImagesLine(
        rows: [(part: String, id: String, fileName: String, widthPx: Int?, heightPx: Int?)],
        report: ImageConsistencyReport?,
        inspectionFailureReason: String?,
        unreferencedMediaFiles: [String] = []
    ) -> String {
        let mediaSuffix = unreferencedMediaFiles.isEmpty ? "" : "; \(unreferencedMediaFiles.count) unreferenced media file(s) in word/media/ — see list_images"
        guard !rows.isEmpty else {
            if let report, report.imageRelationshipCount > 0 {
                return "0 referenced here, but the package declares \(report.imageRelationshipCount) image relationship(s) elsewhere (see list_images)" + mediaSuffix
            }
            return "0" + mediaSuffix
        }
        guard let report else {
            return "\(rows.count) declared (referenced/orphan status unknown: \(inspectionFailureReason ?? "check unavailable"); see list_images)" + mediaSuffix
        }
        let orphanSet = Set(report.orphanImageRelationshipRefs)
        let knownRefs = rows.map { ImageRelationshipRef(part: $0.part, id: $0.id) }
        let orphanCount = knownRefs.filter { orphanSet.contains($0) }.count
        let referencedCount = rows.count - orphanCount
        if orphanCount > 0 {
            return "\(referencedCount) referenced, \(orphanCount) orphan (declared but not referenced in their own part — see list_images; save_document refuses to write NEW orphans unless allow_orphan_images: true)" + mediaSuffix
        }
        return "\(referencedCount) referenced" + mediaSuffix
    }

    /// #199/#219 — package-authoritative image listing text. `report` is the
    /// same signal `save_document`'s gate reads (see
    /// `imageConsistencyInspection`); a row's `referenced` status here can
    /// never diverge from what a subsequent save would refuse on.
    static func imageListing(
        rows: [(part: String, id: String, fileName: String, widthPx: Int?, heightPx: Int?)],
        report: ImageConsistencyReport?,
        inspectionFailureReason: String?,
        unreferencedMediaFiles: [String] = []
    ) -> String {
        if rows.isEmpty {
            if let report, report.imageRelationshipCount > 0 {
                var text = "Document part and known header/footer parts have no images; the package declares \(report.imageRelationshipCount) image relationship(s) elsewhere (not listed here).\n"
                    + "Package: bodyDrawings=\(report.bodyDrawingCount), imageRelationships=\(report.imageRelationshipCount), mediaEntries=\(report.mediaEntryCount)"
                if !unreferencedMediaFiles.isEmpty {
                    text += "\n\n⚠ Unreferenced media file(s) in word/media/ — no relationship (document, header, or footer) points at them (#208 R2 F2 — e.g. left behind by a watermark insert/remove cycle before this check existed): "
                        + unreferencedMediaFiles.joined(separator: ", ")
                }
                return text
            }
            if !unreferencedMediaFiles.isEmpty {
                return "No images in document, but word/media/ has \(unreferencedMediaFiles.count) unreferenced file(s): "
                    + unreferencedMediaFiles.joined(separator: ", ")
            }
            return "No images in document"
        }

        let orphanSet = Set(report?.orphanImageRelationshipRefs ?? [])
        let knownRefs = Set(rows.map { ImageRelationshipRef(part: $0.part, id: $0.id) })
        var referencedCount = 0
        var orphanCount = 0
        var rowLines: [String] = []
        for row in rows {
            let ref = ImageRelationshipRef(part: row.part, id: row.id)
            let status: String
            if report == nil {
                status = "unknown"
            } else if orphanSet.contains(ref) {
                status = "NO (orphan)"; orphanCount += 1
            } else {
                status = "yes"; referencedCount += 1
            }
            var line = "- part: \(row.part), id: \(row.id), file: \(row.fileName)"
            if let w = row.widthPx, let h = row.heightPx { line += ", size: \(w)x\(h)px" }
            line += ", referenced: \(status)"
            rowLines.append(line)
        }

        let headerLine = report == nil
            ? "Found \(rows.count) image(s):"
            : "Found \(rows.count) image(s) — \(referencedCount) referenced, \(orphanCount) orphan (relationship declared, no reference in its own part):"

        var blocks: [String] = [([headerLine] + rowLines).joined(separator: "\n")]

        if let inspectionFailureReason {
            blocks.append("⚠ body-reference check unavailable: \(inspectionFailureReason)")
        }

        if orphanCount > 0, let report {
            let namedOrphans = report.orphanImageRelationshipRefs.filter { knownRefs.contains($0) }.map(\.qualified)
            blocks.append((["⚠ Orphan image relationship(s) — declared but not referenced in their own part (PsychQuant/macdoc#175 signature). save_document will refuse (E_IMAGE_CONSISTENCY) unless allow_orphan_images: true:"]
                + namedOrphans.map { "  - \($0)" }).joined(separator: "\n"))
        }

        if let report {
            let otherRefs = (report.declaredImageRelationshipRefs + report.orphanImageRelationshipRefs)
                .filter { !knownRefs.contains($0) }
            let otherUnique = Array(Set(otherRefs)).sorted { $0.qualified < $1.qualified }
            if !otherUnique.isEmpty {
                blocks.append("⚠ Declared elsewhere in the package (not listed above — this reader only enumerates word/document.xml + headers/footers): "
                    + otherUnique.map(\.qualified).joined(separator: ", "))
            }
            if !report.unparsableParts.isEmpty {
                blocks.append("⚠ package parts that could not be inspected (image references there are unknown): " + report.unparsableParts.joined(separator: ", "))
            }
            blocks.append("Package: bodyDrawings=\(report.bodyDrawingCount), imageRelationships=\(report.imageRelationshipCount), mediaEntries=\(report.mediaEntryCount)")
        }

        if !unreferencedMediaFiles.isEmpty {
            blocks.append("⚠ Unreferenced media file(s) in word/media/ — no relationship (document, header, or footer) points at them (#208 R2 F2 — e.g. left behind by a watermark insert/remove cycle before this check existed): "
                + unreferencedMediaFiles.joined(separator: ", "))
        }

        return blocks.joined(separator: "\n\n") + "\n"
    }

    // MARK: - Content Operations

    private func getText(args: [String: Value]) async throws -> String {
        guard let sourcePath = args["source_path"]?.stringValue else {
            throw WordError.missingParameter("source_path")
        }
        guard FileManager.default.fileExists(atPath: sourcePath) else {
            throw WordError.fileNotFound(sourcePath)
        }
        let sourceURL = URL(fileURLWithPath: sourcePath)
        let lockFile = sourceURL.deletingLastPathComponent()
            .appendingPathComponent("~$" + sourceURL.lastPathComponent)
        if FileManager.default.fileExists(atPath: lockFile.path) {
            throw WordError.invalidFormat("File is open in Microsoft Word. Please save and close it first: \(sourceURL.lastPathComponent)")
        }
        var document = try DocxReader.read(from: sourceURL)
        // #244 (sister leak to #221): `get_text`/`get_document_text` are
        // source_path-only (Tier 1, no `doc_id` branch at all — see their
        // Tool schemas) and never route through `resolveDocument`, so
        // #221's fix at that shared choke point never covered this
        // hand-written Direct Mode open. `document.getText()` below only
        // walks the already-materialized typed `body` — it never touches
        // `archiveTempDir` — so releasing the extracted tempDir right here,
        // before reading the text out, is safe, same as #221 H2's
        // `exportMarkdown.archiveExtracted` fix.
        logDebug(event: "getText.archiveExtracted", [
            ("archive_temp_dir", document.archiveTempDir?.path ?? "nil"),
        ])
        document.close()
        return document.getText()
    }

    private func getParagraphs(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)

        // Spec word-mcp-markdown-export — Requirement: Truncation policy via
        // summarize parameter. #178: this cut every paragraph at 50 characters
        // and appended "..." UNCONDITIONALLY, so a paragraph reading "Hi" was
        // printed as "Hi..." — the reader could not tell a short paragraph from
        // a truncated one. Wrong in both directions at once: it truncated
        // without being asked, and claimed elision that had not happened.
        // #232 R6 (review H2a): parsed before the empty-document early
        // return, not after — same fix as R1's list_comments; a mistyped
        // summarize on a document with no paragraphs used to succeed
        // silently instead of erroring.
        let summarize = try optionalBool(args, "summarize") ?? false

        let paragraphs = doc.getParagraphs()
        if paragraphs.isEmpty {
            return "No paragraphs in document"
        }

        var result = "Paragraphs:\n"
        for (index, para) in paragraphs.enumerated() {
            let style = para.properties.style ?? "Normal"
            let text = truncateText(para.getText(), summarize: summarize)
            result += "[\(index)] (\(style)) \(text)\n"
        }
        return result
    }

    private func insertParagraph(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let style = args["style"]?.stringValue

        var para = Paragraph(text: text)
        if let style = style {
            para.properties.style = style
        }

        // anchor-dx-consistency (#71): reject conflicting anchors before the dispatcher.
        // Spec: openspec/changes/anchor-dx-consistency/specs/.../spec.md R1.
        // #80: anchor list resolved from WordMCPServer.toolAnchorWhitelists (SoT).
        let presentAnchors = WordMCPServer.detectPresentAnchors(args, tool: "insert_paragraph")
        if presentAnchors.count > 1 {
            throw ToolRefusal("insert_paragraph: received conflicting anchors: \(presentAnchors.joined(separator: " + ")). Specify exactly one.")
        }

        // Anchor priority (mirrors insert_image_from_path):
        // into_table_cell > after_image_id > after_text > before_text > index > append
        let textInstance = try optionalInt(args, "text_instance") ?? 1
        // anchor-dx-consistency (#72): explicit text_instance < 1 rejected.
        if let explicit = try optionalInt(args, "text_instance"), explicit < 1 {
            throw ToolRefusal("insert_paragraph: text_instance must be ≥ 1, got \(explicit).")
        }
        // #232 R5: parsed here, unconditionally, rather than inside the last
        // `else if` of the anchor-priority dispatch below — a mistyped
        // `index` supplied alongside a HIGHER-priority anchor (e.g.
        // `after_text`) used to never be reached at all, since the dispatch
        // takes the earlier branch and the last `else if let index = ...`
        // is simply never evaluated.
        let indexArg = try optionalInt(args, "index")
        let resultMessage: String

        if let cellDict = args["into_table_cell"]?.objectValue {
            // F5 (v3.15.1): malformed partial dict returns structured error instead of silent fallthrough.
            // #232 R4: each field parsed independently (not chained in one
            // guard) so a wrong-typed field is always caught, even when an
            // earlier field in the dict happens to be absent — a chained
            // `guard let a = ..., let b = ...` short-circuits on the first
            // nil and never evaluates b at all.
            let tableIdxArg = try optionalInt(cellDict, "table_index")
            let rowArg = try optionalInt(cellDict, "row")
            let colArg = try optionalInt(cellDict, "col")
            guard let tableIdx = tableIdxArg, let row = rowArg, let col = colArg else {
                throw ToolRefusal("insert_paragraph: into_table_cell requires all three fields (table_index, row, col); got partial dict")
            }
            do {
                try doc.insertParagraph(para, at: .intoTableCell(tableIndex: tableIdx, row: row, col: col))
                resultMessage = "Inserted paragraph into table[\(tableIdx)] cell (row: \(row), col: \(col))"
            } catch let InsertLocationError.tableIndexOutOfRange(i) {
                throw ToolRefusal("insert_paragraph: table index \(i) out of range")
            } catch let InsertLocationError.tableCellOutOfRange(t, r, c) {
                throw ToolRefusal("insert_paragraph: table[\(t)] cell (row: \(r), col: \(c)) out of range")
            }
        } else if let afterImageId = args["after_image_id"]?.stringValue {
            // F1 (v3.15.1): after_image_id anchor.
            do {
                try doc.insertParagraph(para, at: .afterImageId(afterImageId))
                resultMessage = "Inserted paragraph after image '\(afterImageId)'"
            } catch let InsertLocationError.imageIdNotFound(rId) {
                throw ToolRefusal("insert_paragraph: image rId '\(rId)' not found")
            }
        } else if let afterText = args["after_text"]?.stringValue {
            do {
                try doc.insertParagraph(para, at: .afterText(afterText, instance: textInstance))
                resultMessage = "Inserted paragraph after text '\(afterText)' (instance \(textInstance))"
            } catch let InsertLocationError.textNotFound(searchText, instance) {
                throw ToolRefusal("insert_paragraph: text '\(searchText)' not found (instance \(instance))")
            }
        } else if let beforeText = args["before_text"]?.stringValue {
            do {
                try doc.insertParagraph(para, at: .beforeText(beforeText, instance: textInstance))
                resultMessage = "Inserted paragraph before text '\(beforeText)' (instance \(textInstance))"
            } catch let InsertLocationError.textNotFound(searchText, instance) {
                throw ToolRefusal("insert_paragraph: text '\(searchText)' not found (instance \(instance))")
            }
        } else if let index = indexArg {
            doc.insertParagraph(para, at: index)
            resultMessage = "Inserted paragraph at index \(index)"
        } else {
            doc.appendParagraph(para)
            // #69: report body.children index (matches Document.insertParagraph(_:at:Int)
            // semantics — Document.swift:266-270). getParagraphs() skips tables/SDTs so
            // its count - 1 mis-reports the index in docs with non-paragraph body children.
            resultMessage = "Inserted paragraph at index \(doc.body.children.count - 1)"
        }

        try await storeDocument(doc, for: docId)

        return resultMessage
    }

    private func updateParagraph(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let index = try optionalInt(args, "index") else {
            throw WordError.missingParameter("index")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        try doc.updateParagraph(at: index, text: text)
        try await storeDocument(doc, for: docId)

        return "Updated paragraph at index \(index)"
    }

    private func deleteParagraph(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let index = try optionalInt(args, "index") else {
            throw WordError.missingParameter("index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        try doc.deleteParagraph(at: index)
        try await storeDocument(doc, for: docId)

        return "Deleted paragraph at index \(index)"
    }

    // MARK: - #190: cross-run replace format preservation
    //
    // ooxml-swift's `TextReplacementEngine` (a dependency this repo does not
    // modify) flattens a paragraph's runs, finds matches, and splices the
    // replacement back in. For a match spanning more than one run, the whole
    // replacement text lands in the *starting* run — inheriting only that
    // run's `rPr` — while every other matched run is emptied out, discarding
    // its own `rPr` for good. A form's checkbox-glyph run and its label run
    // commonly declare different fonts (`ascii`/`hAnsi`/`cs` for the glyph,
    // `eastAsia` for the CJK label); replacing "□免除審查" with "■免除審査"
    // silently turns "免除審査" from 標楷體 into whatever the glyph run
    // declares (or docDefaults, if it doesn't declare `eastAsia` at all).
    // `get_tables`/cell-text comparisons never catch this — the text is
    // correct, only the run structure carrying it changed.
    //
    // Repair strategy (implemented entirely in che-word-mcp, calling
    // `doc.replaceText` unchanged for the actual mutation):
    // 1. Before the call, scan `doc.body.children` (body paragraphs +
    //    top-level table cells — not headers/footers/footnotes/endnotes,
    //    not hyperlink/fieldSimple/contentControl-wrapped runs, not nested
    //    tables) for matches whose span crosses more than one run with
    //    genuinely different `rPr`.
    // 2. A match is repairable when (a) it is the *only* cross-run match in
    //    that paragraph's run array (so post-mutation run-array positions
    //    stay predictable without re-deriving them — see `applyCrossRunRepair`),
    //    (b) `find.count == replacement.count` (a same-length swap, the
    //    checkbox-toggle shape — for anything else, splitting the
    //    replacement back onto the original run boundaries has no
    //    well-defined mapping), and (c) every run strictly between the
    //    match's first and last run is a plain, removable text run (mirrors
    //    `TextReplacementEngine`'s own removal predicate — anything else
    //    would leave the post-mutation run count different from what this
    //    repair layer assumes).
    // 3. Call `doc.replaceText` — unchanged, still delegates every surface
    //    (hyperlinks, tables, headers, content controls, OMML boundaries,
    //    comment-reference preservation) to the dependency.
    // 4. For each repairable match, replace the two resulting runs (the
    //    engine never removes a run for a 2-run-adjacent match, and any
    //    fully-removable middle runs collapse to exactly one survivor
    //    alongside the start run — see the proof in `applyCrossRunRepair`)
    //    with fresh runs built directly from the *original* per-run text
    //    lengths and `rPr`, sliced out of the (same-length) replacement.
    // Anything not repairable (different lengths, `regex: true`, more than
    // one cross-run match in the same paragraph, or a non-removable run in
    // the middle) keeps the old collapsing behaviour, but the tool's return
    // string says so instead of staying silent.

    /// One physical run's slice of a repairable cross-run match: the
    /// (unmatched) text on either side of the match that this run
    /// contributed, how many matched characters it contributed, and the
    /// run's own *original* `RunProperties` (captured before any mutation).
    private struct CrossRunRepairSegment {
        let prefix: String
        let matchedLength: Int
        let suffix: String
        let properties: RunProperties
    }

    /// A single cross-run match's repair recipe. `startRunIndex` is the
    /// match's first run's index in the *original* (pre-`doc.replaceText`)
    /// run array — see `applyCrossRunRepair` for why that's still the right
    /// anchor after the dependency call has run.
    private struct CrossRunRepairPlan {
        let startRunIndex: Int
        let segments: [CrossRunRepairSegment]
    }

    /// Mirrors `TextReplacementEngine`'s own (private) `isTextRun` predicate:
    /// a run whose `text` is what actually gets flattened/matched (no field
    /// code, no drawing).
    private func isMutableTextRun(_ run: Run) -> Bool {
        run.rawXML == nil && run.drawing == nil
    }

    /// Mirrors the engine's removal predicate for runs strictly between a
    /// match's first and last run: only a plain text run with no structural
    /// payload (`<w:commentReference>` etc.) is removed; anything else
    /// survives, and this repair layer refuses to guess the resulting index.
    private func isRemovableMiddleRun(_ run: Run) -> Bool {
        isMutableTextRun(run) && (run.rawElements?.isEmpty ?? true)
    }

    /// Read-only mirror of `TextReplacementEngine.flattenRuns`: the flat
    /// matchable text plus a per-character `(runIdx, offsetInRun)` map.
    private func flattenRunsForRepairScan(_ runs: [Run]) -> (flat: String, map: [(runIdx: Int, offset: Int)]) {
        var flat = ""
        var map: [(runIdx: Int, offset: Int)] = []
        for (runIdx, run) in runs.enumerated() where isMutableTextRun(run) {
            for (charIdx, _) in run.text.enumerated() {
                map.append((runIdx, charIdx))
            }
            flat += run.text
        }
        return (flat, map)
    }

    /// Plans the repair (if any) for one paragraph's/cell's `runs` array.
    /// Returns the plan (nil when nothing is repairable) and the count of
    /// cross-run matches whose span has genuinely differing formatting but
    /// could NOT be repaired — the caller aggregates this into the tool's
    /// warning.
    private func planCrossRunRepair(
        runs: [Run], find: String, replacementLength: Int, matchCase: Bool
    ) -> (plan: CrossRunRepairPlan?, unrepairedFormatAffecting: Int) {
        guard !find.isEmpty else { return (nil, 0) }
        let (flat, map) = flattenRunsForRepairScan(runs)
        guard !flat.isEmpty else { return (nil, 0) }
        let cmpOptions: String.CompareOptions = matchCase ? [] : [.caseInsensitive]

        struct RawMatch { let sRunIdx: Int; let eRunIdx: Int; let sOffset: Int; let eOffsetExclusive: Int }
        var rawMatches: [RawMatch] = []
        var searchStart = flat.startIndex
        while searchStart < flat.endIndex,
              let range = flat.range(of: find, options: cmpOptions, range: searchStart..<flat.endIndex) {
            defer { searchStart = range.upperBound }
            let startCharIdx = flat.distance(from: flat.startIndex, to: range.lowerBound)
            let endCharIdx = flat.distance(from: flat.startIndex, to: range.upperBound)
            guard startCharIdx < map.count else { continue }
            let (sRunIdx, sOffset) = map[startCharIdx]
            let eRunIdx: Int
            let eOffsetExclusive: Int
            if endCharIdx < map.count {
                (eRunIdx, eOffsetExclusive) = map[endCharIdx]
            } else {
                let lastTextRunIdx = runs.lastIndex(where: isMutableTextRun) ?? sRunIdx
                eRunIdx = lastTextRunIdx
                eOffsetExclusive = runs[lastTextRunIdx].text.count
            }
            rawMatches.append(RawMatch(sRunIdx: sRunIdx, eRunIdx: eRunIdx, sOffset: sOffset, eOffsetExclusive: eOffsetExclusive))
        }

        // R2 review Finding 5: when a match's last character is exactly the
        // last character of a run, `map[endCharIdx]` (one index past the
        // match) resolves to offset 0 of the NEXT run — a run the match
        // never actually touches. Using that raw `eRunIdx` to decide "does
        // this match span multiple differently-formatted runs" would
        // over-include that untouched neighbour. `effectiveEndRunIndex` is
        // the last run the match actually has any characters in; used ONLY
        // for classification (is this a cross-run match at all? does
        // formatting genuinely differ across it?) below. Segment-building
        // further down deliberately keeps using the raw `eRunIdx`/
        // `eOffsetExclusive` — that already matches `TextReplacementEngine`'s
        // own post-mutation run layout exactly (confirmed against a real
        // binary: the spillover run's prefix/suffix math reconstructs it
        // byte-unchanged either way), so narrowing it there would be an
        // unnecessary, unproven behaviour change to already-correct code.
        func effectiveEndRunIndex(_ m: RawMatch) -> Int {
            (m.eOffsetExclusive == 0 && m.eRunIdx > m.sRunIdx) ? m.eRunIdx - 1 : m.eRunIdx
        }

        let crossRunMatches = rawMatches.filter { effectiveEndRunIndex($0) > $0.sRunIdx }
        guard !crossRunMatches.isEmpty else { return (nil, 0) }

        func spanFormatDiffers(_ m: RawMatch) -> Bool {
            let props = (m.sRunIdx...effectiveEndRunIndex(m)).map { runs[$0].properties }
            return props.dropFirst().contains { $0 != props[0] }
        }
        let formatAffectingCount = crossRunMatches.filter(spanFormatDiffers).count

        // Repair is only attempted when there is exactly ONE cross-run match
        // in this run array: `doc.replaceText` processes matches within a
        // paragraph right-to-left, so an earlier (lower-index) match's run
        // positions stay valid after a later match's removal — but only if
        // there IS no later match to interact with. Two-or-more cross-run
        // matches in the same paragraph fall back to "detect and warn"
        // rather than risk mis-tracking a shifted index.
        guard crossRunMatches.count == 1, let match = crossRunMatches.first, spanFormatDiffers(match) else {
            return (nil, formatAffectingCount)
        }
        guard find.count == replacementLength else { return (nil, formatAffectingCount) }
        if match.eRunIdx - match.sRunIdx > 1 {
            for idx in (match.sRunIdx + 1)..<match.eRunIdx where !isRemovableMiddleRun(runs[idx]) {
                return (nil, formatAffectingCount)
            }
        }

        var segments: [CrossRunRepairSegment] = []
        for idx in match.sRunIdx...match.eRunIdx {
            let text = runs[idx].text
            let prefix = idx == match.sRunIdx ? String(text.prefix(match.sOffset)) : ""
            let matchedLength: Int
            if idx == match.sRunIdx {
                matchedLength = text.count - match.sOffset
            } else if idx == match.eRunIdx {
                matchedLength = match.eOffsetExclusive
            } else {
                matchedLength = text.count
            }
            let suffix = idx == match.eRunIdx ? String(text.suffix(text.count - match.eOffsetExclusive)) : ""
            segments.append(CrossRunRepairSegment(
                prefix: prefix, matchedLength: max(0, matchedLength), suffix: suffix, properties: runs[idx].properties
            ))
        }
        return (CrossRunRepairPlan(startRunIndex: match.sRunIdx, segments: segments), 0)
    }

    /// Applies a repair plan to the run array *after* `doc.replaceText` has
    /// already mutated it.
    ///
    /// Why `plan.startRunIndex` is still the right position: the plan is the
    /// only cross-run match in this run array (guaranteed by
    /// `planCrossRunRepair`), so nothing else in this array shifted indices
    /// around it. The engine's own splice (see `TextReplacementEngine.
    /// applyOneReplacement`) leaves exactly two runs spanning the match: for
    /// an adjacent 2-run match it never removes anything, and for a wider
    /// span every strictly-between run is removable-by-construction (also
    /// guaranteed by the plan), so exactly one run remains between the start
    /// and end positions after removal. Either way, post-mutation, the
    /// match's collapsed result occupies exactly `[startRunIndex,
    /// startRunIndex + 1]` — the "start run holding prefix + full
    /// replacement" and "end run holding the suffix".
    @discardableResult
    private func applyCrossRunRepair(runs: inout [Run], plan: CrossRunRepairPlan, replacement: String) -> Bool {
        let endPos = plan.startRunIndex + 1
        guard plan.startRunIndex >= 0, endPos < runs.count else { return false }

        var cursor = replacement.startIndex
        var newRuns: [Run] = []
        for segment in plan.segments {
            guard let sliceEnd = replacement.index(cursor, offsetBy: segment.matchedLength, limitedBy: replacement.endIndex) else {
                return false
            }
            let slice = String(replacement[cursor..<sliceEnd])
            cursor = sliceEnd
            let text = segment.prefix + slice + segment.suffix
            guard !text.isEmpty else { continue }
            newRuns.append(Run(text: text, properties: segment.properties))
        }
        // R2 review Finding 6: `planCrossRunRepair`'s `find.count ==
        // replacementLength` guard is the only thing that currently
        // guarantees every character of `replacement` gets consumed by the
        // segments above — this is a second, independent check at the
        // point of use, so a future change that loosens or bypasses that
        // upstream guard (e.g. to attempt regex repair) fails loudly here
        // instead of silently truncating `replacement`'s trailing
        // characters. Mutation-testing this guard away (temporarily, while
        // developing R2) confirmed it is currently reachable and would
        // otherwise silently drop text with no error.
        guard cursor == replacement.endIndex else { return false }
        guard !newRuns.isEmpty else { return false }
        runs.replaceSubrange(plan.startRunIndex...endPos, with: newRuns)
        return true
    }

    /// Visits every direct `runs` array under `children` in a stable,
    /// deterministic order (body paragraphs, then top-level table cells'
    /// paragraphs row-major, recursing through block-level content
    /// controls) — the SAME order for a read-only pre-scan and a later
    /// mutating pass, so a positional index computed in one pass still
    /// identifies the same run array in the other. Deliberately does not
    /// descend into `cell.nestedTables` (#188 territory) or into
    /// hyperlink/fieldSimple/alternateContent/contentControl-inline runs —
    /// #190's repair layer is scoped to the surfaces `update_cell` and
    /// `search_text` already treat as the primary editing surface.
    private func forEachDirectRunsArray(
        in children: inout [BodyChild], index: inout Int, action: (Int, inout [Run]) -> Void
    ) {
        for i in children.indices {
            switch children[i] {
            case .paragraph(var para):
                action(index, &para.runs)
                children[i] = .paragraph(para)
                index += 1
            case .table(var table):
                for r in table.rows.indices {
                    for c in table.rows[r].cells.indices {
                        for p in table.rows[r].cells[c].paragraphs.indices {
                            action(index, &table.rows[r].cells[c].paragraphs[p].runs)
                            index += 1
                        }
                    }
                }
                children[i] = .table(table)
            case .contentControl(let metadata, var inner):
                forEachDirectRunsArray(in: &inner, index: &index, action: action)
                children[i] = .contentControl(metadata, children: inner)
            case .bookmarkMarker, .rawBlockElement:
                continue
            }
        }
    }

    /// Runs `doc.replaceText` with the #190 cross-run format repair layered
    /// on top. `doc.replaceText` itself is called unchanged. Returns the
    /// dependency's own replacement count plus how many matches this layer
    /// repaired and how many it detected as collapsed-but-unrepairable.
    private func replaceTextPreservingCrossRunFormat(
        doc: inout WordDocument, find: String, replacement: String, options: ReplaceOptions
    ) throws -> (count: Int, repaired: Int, collapsedUnrepaired: Int) {
        guard !options.regex else {
            // Regex repair isn't attempted (#190 documented limitation —
            // per-match matched text can vary in length even when `find`
            // doesn't, so the length gate below can't be evaluated up
            // front). Behaviour is unchanged from before #190.
            let count = try doc.replaceText(find: find, with: replacement, options: options)
            return (count, 0, 0)
        }

        var repairPlans: [Int: CrossRunRepairPlan] = [:]
        var collapsedUnrepaired = 0
        var scanChildren = doc.body.children
        var scanIndex = 0
        forEachDirectRunsArray(in: &scanChildren, index: &scanIndex) { idx, runs in
            let (plan, unrepaired) = self.planCrossRunRepair(
                runs: runs, find: find, replacementLength: replacement.count, matchCase: options.matchCase
            )
            if let plan { repairPlans[idx] = plan }
            collapsedUnrepaired += unrepaired
        }

        let count = try doc.replaceText(find: find, with: replacement, options: options)

        var repaired = 0
        if !repairPlans.isEmpty {
            var applyIndex = 0
            forEachDirectRunsArray(in: &doc.body.children, index: &applyIndex) { idx, runs in
                guard let plan = repairPlans[idx] else { return }
                if self.applyCrossRunRepair(runs: &runs, plan: plan, replacement: replacement) {
                    repaired += 1
                } else {
                    collapsedUnrepaired += 1
                }
            }
        }

        return (count, repaired, collapsedUnrepaired)
    }

    /// Builds the human-readable suffix #190 adds to `replace_text` /
    /// `replace_text_batch` result strings.
    private func crossRunRepairSummary(repaired: Int, collapsedUnrepaired: Int) -> String {
        var suffix = ""
        if repaired > 0 {
            suffix += "; preserved per-run formatting across \(repaired) cross-run match(es)"
        }
        if collapsedUnrepaired > 0 {
            suffix += "; WARNING: \(collapsedUnrepaired) cross-run match(es) spanned runs with different formatting and could not be format-preserved — the merged text inherited only the first run's formatting. Please verify manually."
        }
        return suffix
    }

    /// #187: `replaceTextPreservingCrossRunFormat` (the #190 layer) with a
    /// whitespace-normalized retry on top, for the same reason `search_text`
    /// has one (see that tool's doc comment for the confirmed root cause).
    ///
    /// Only attempted when the literal call replaces zero occurrences AND
    /// `find` contains whitespace — an already-working replace (the common
    /// case) takes the exact same code path as before #187, unconditionally.
    ///
    /// `find` is normalized for the retry (stripped of whitespace, to match
    /// what the lossy parsed model actually contains) but `replacement` is
    /// passed through **unstripped** — deliberately. The replacement text is
    /// written fresh into the typed model, not re-parsed through the same
    /// Foundation `XMLDocument` code path that lost the original whitespace,
    /// so a caller's intended spacing in `replacement` survives correctly
    /// into the saved file even though the *matched* text's original spacing
    /// could not be recovered. Regex retries aren't attempted — a stripped
    /// pattern doesn't have a well-defined relationship to the original
    /// pattern's semantics.
    ///
    /// **Consistency with `search_text` (R2 review Finding 3)**: the retry
    /// compares `stripWhitespace(find)` against the runs' own unstripped
    /// text (via `doc.replaceText` → `TextReplacementEngine`) — never a
    /// stripped copy of the document's text. `search_text`'s fallback was
    /// changed to perform the identical comparison, so for the same
    /// find/query against the same document, both tools now always agree on
    /// whether a normalized match exists.
    private func replaceTextWithWhitespaceFallback(
        doc: inout WordDocument, find: String, replacement: String, options: ReplaceOptions
    ) throws -> (count: Int, repaired: Int, collapsedUnrepaired: Int, usedNormalizedFallback: Bool) {
        let (count, repaired, collapsedUnrepaired) = try replaceTextPreservingCrossRunFormat(
            doc: &doc, find: find, replacement: replacement, options: options
        )
        guard count == 0, !options.regex, find.contains(where: isWhitespaceCharacter) else {
            return (count, repaired, collapsedUnrepaired, false)
        }
        let strippedFind = stripWhitespace(find)
        guard !strippedFind.isEmpty, strippedFind != find else {
            return (count, repaired, collapsedUnrepaired, false)
        }
        let (retryCount, retryRepaired, retryCollapsed) = try replaceTextPreservingCrossRunFormat(
            doc: &doc, find: strippedFind, replacement: replacement, options: options
        )
        guard retryCount > 0 else {
            // Normalizing didn't help either — report the original (zero)
            // outcome rather than a confusing "replaced 0 via fallback".
            return (count, repaired, collapsedUnrepaired, false)
        }
        return (retryCount, retryRepaired, retryCollapsed, true)
    }

    /// replace_text MCP tool — now flatten-then-map + scope + regex.
    ///
    /// Args:
    /// - doc_id (required)
    /// - find (required): plain string or regex pattern (if regex=true)
    /// - replace (required): replacement text; when regex=true supports $1..$N
    /// - scope: "body" (default) | "all" — "all" adds headers/footers/footnotes/endnotes
    /// - regex: Bool (default false)
    /// - match_case: Bool (default true)
    ///
    /// BREAKING changes from previous release:
    /// - `all: Bool` argument removed (was "replace all occurrences"; now always
    ///   replaces all — to emulate old `all: false` behavior, call once and check
    ///   the returned count, or use a regex with an anchor).
    /// - Cross-run matches now succeed (previously failed silently).
    /// - #190: a same-length cross-run match (e.g. toggling a checkbox glyph
    ///   next to a label run) now preserves each surviving character's
    ///   original `rPr` instead of collapsing to the first run's formatting;
    ///   an unrepairable cross-run merge is now disclosed in the return
    ///   string instead of staying silent.
    private func replaceText(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let find = args["find"]?.stringValue else {
            throw WordError.missingParameter("find")
        }
        guard let replace = args["replace"]?.stringValue else {
            throw WordError.missingParameter("replace")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #253: value errors were already rejected (the `default:` throw
        // below), but a wrong JSON TYPE (`scope: 5`) took `?.stringValue`'s
        // `nil` straight into the `?? "body"` fallback and was silently
        // treated as if the caller had asked for "body" — same failure
        // shape #240 closed for schema-declared `enum` parameters, applied
        // here to a parameter that never declared one.
        let scopeString = try Self.optionalStrictEnumString(args, "scope", allowed: ["body", "all"]) ?? "body"
        let scope: ReplaceScope = (scopeString == "all") ? .all : .bodyAndTables
        let regex = try optionalBool(args, "regex") ?? false
        let matchCase = try optionalBool(args, "match_case") ?? true

        let options = ReplaceOptions(scope: scope, regex: regex, matchCase: matchCase)
        do {
            let (count, repaired, collapsedUnrepaired, usedNormalizedFallback) = try replaceTextWithWhitespaceFallback(
                doc: &doc, find: find, replacement: replace, options: options
            )
            try await storeDocument(doc, for: docId)
            // #255: wire #189's glyph-coverage probe into the #192 advisory
            // channel. Only when something actually changed, and only for
            // `.noGlyph` verdicts — see `GlyphCoverageAdvisory.swift`.
            if count > 0 {
                for message in glyphCoverageAdvisories(doc: doc, replacement: replace, scope: scope) {
                    recordAdvisory(message)
                }
            }
            let scopeLabel = scope == .all ? " (scope: all)" : ""
            let repairSummary = crossRunRepairSummary(repaired: repaired, collapsedUnrepaired: collapsedUnrepaired)
            let normalizedNote = usedNormalizedFallback
                ? "; NOTE: literal text had no match, used whitespace-normalized matching instead (#187) — a whitespace-only run may be missing from the parsed document; please verify the surrounding layout"
                : ""
            return "Replaced \(count) occurrence(s) of '\(find)' with '\(replace)'\(scopeLabel)\(repairSummary)\(normalizedNote)"
        } catch ReplaceError.invalidRegex(let pattern) {
            throw ToolRefusal("invalid regex pattern '\(pattern)'")
        }
    }

    /// search_text_batch MCP tool — 批次搜尋多個 query，單一 doc load（Session Mode）或
    /// 單次檔案 parse（Direct Mode）。對每個 query 呼叫 existing `searchText(args:)`，
    /// 組合成單一 batch response。
    private func searchTextBatch(args: [String: Value]) async throws -> String {
        guard case .array(let queriesValue)? = args["queries"] else {
            throw WordError.missingParameter("queries (array)")
        }

        var output = ""
        for (idx, qValue) in queriesValue.enumerated() {
            let queryStr: String
            let caseSensitive: Bool
            switch qValue {
            case .string(let s):
                queryStr = s
                caseSensitive = false
            case .object(let obj):
                // #232 R1/R5: a per-item type error must fail that item, not
                // the whole batch — same "malformed entry" soft-fail shape
                // as the guard below, not a thrown error escaping the loop.
                // Parsed BEFORE the `query` guard (not after) so a mistyped
                // case_sensitive is always caught even on an item that is
                // ALSO missing `query` — independent fields of the same
                // object, not gated on each other.
                do {
                    caseSensitive = try optionalBool(obj, "case_sensitive") ?? false
                } catch {
                    output += "\n=== [\(idx)] FAIL: \(error) ===\n"
                    continue
                }
                guard let q = obj["query"]?.stringValue else {
                    output += "\n=== [\(idx)] FAIL: missing 'query' field ===\n"
                    continue
                }
                queryStr = q
            default:
                output += "\n=== [\(idx)] FAIL: query must be string or object ===\n"
                continue
            }

            // Build per-query args by copying original args (preserves doc_id / source_path)
            var subArgs = args
            subArgs["query"] = .string(queryStr)
            subArgs["case_sensitive"] = .bool(caseSensitive)
            subArgs.removeValue(forKey: "queries")

            do {
                let result = try await searchText(args: subArgs)
                output += "\n=== [\(idx)] query='\(queryStr)' ===\n\(result)\n"
            } catch {
                output += "\n=== [\(idx)] query='\(queryStr)' ERROR: \(error) ===\n"
            }
        }
        return output.isEmpty ? "(no queries)" : output
    }

    /// replace_text_batch MCP tool — 批次 sequential replacement，單次 save（或 dry_run 跳過）。
    ///
    /// Semantics:
    /// - Replacements apply in array order. Each sees results of previous.
    /// - Non-atomic per-item: individual failures (invalid regex) reported but
    ///   don't rollback prior successes.
    /// - `stop_on_first_failure: true` halts on first error; already-applied
    ///   items stay applied.
    /// - `dry_run: true` skips disk save; in-memory doc is still mutated
    ///   (document this caveat in schema).
    private func replaceTextBatch(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard case .array(let replacementsValue)? = args["replacements"] else {
            throw WordError.missingParameter("replacements (array)")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        let stopOnFirstFailure = try optionalBool(args, "stop_on_first_failure") ?? false
        let dryRun = try optionalBool(args, "dry_run") ?? false

        var results: [[String: Any]] = []
        var succeeded = 0
        var failed = 0
        // #255: dedup across items in the SAME batch call — two items that
        // both land the same unsafe (character, font) pair should not each
        // repeat an identical advisory block.
        var recordedGlyphAdvisories = Set<String>()

        for (idx, itemValue) in replacementsValue.enumerated() {
            guard case .object(let item) = itemValue else {
                results.append(["index": idx, "error": "replacement entry must be object"])
                failed += 1
                if stopOnFirstFailure { break } else { continue }
            }
            // #232 R1/R5: a per-item type error must fail that item, not the
            // whole batch — same "malformed entry" soft-fail shape as the
            // guards below, not a thrown error escaping the loop. Parsed
            // BEFORE the find/replace guards (not after) so a mistyped
            // regex/match_case is always caught even on an item that is ALSO
            // missing find/replace — those are independent fields of the
            // same object, not gated on each other.
            let regex: Bool
            let matchCase: Bool
            do {
                regex = try optionalBool(item, "regex") ?? false
                matchCase = try optionalBool(item, "match_case") ?? true
            } catch {
                results.append(["index": idx, "error": "\(error)"])
                failed += 1
                if stopOnFirstFailure { break } else { continue }
            }
            guard let find = item["find"]?.stringValue else {
                results.append(["index": idx, "error": "missing 'find' field"])
                failed += 1
                if stopOnFirstFailure { break } else { continue }
            }
            guard let replace = item["replace"]?.stringValue else {
                results.append(["index": idx, "error": "missing 'replace' field", "find": find])
                failed += 1
                if stopOnFirstFailure { break } else { continue }
            }

            // per-item options, fall back to no-op defaults
            // R2 (independent review F1): `scope` declares an `enum` in
            // this tool's schema (`items.properties.scope`, `["body",
            // "all"]`) but was read with `item["scope"]?.stringValue ??
            // "body"` — any non-"all" string, INCLUDING a wrong JSON type
            // or a typo like "bogus", silently became `.bodyAndTables`.
            // Same #240 failure shape as `wrap_type`, just at the
            // array-item level instead of the tool's top level. Same
            // soft-fail shape as `regex`/`matchCase` above: a malformed
            // `scope` fails THIS item via `results`/`failed`, not the
            // whole batch.
            let scopeString: String
            do {
                scopeString = try Self.optionalStrictEnumString(item, "scope", allowed: ["body", "all"]) ?? "body"
            } catch {
                results.append(["index": idx, "error": "\(error)"])
                failed += 1
                if stopOnFirstFailure { break } else { continue }
            }
            let scope: ReplaceScope = (scopeString == "all") ? .all : .bodyAndTables
            let options = ReplaceOptions(scope: scope, regex: regex, matchCase: matchCase)

            do {
                let (count, repaired, collapsedUnrepaired, usedNormalizedFallback) = try replaceTextWithWhitespaceFallback(
                    doc: &doc, find: find, replacement: replace, options: options
                )
                // #255: same wiring as `replace_text` — see that call site's
                // comment and `GlyphCoverageAdvisory.swift`.
                if count > 0 {
                    for message in glyphCoverageAdvisories(doc: doc, replacement: replace, scope: scope)
                    where !recordedGlyphAdvisories.contains(message) {
                        recordedGlyphAdvisories.insert(message)
                        recordAdvisory(message)
                    }
                }
                results.append([
                    "index": idx, "find": find, "replaced_count": count,
                    "cross_run_repaired": repaired, "cross_run_collapsed_unrepaired": collapsedUnrepaired,
                    "used_normalized_fallback": usedNormalizedFallback,
                ])
                succeeded += 1
            } catch ReplaceError.invalidRegex(let pattern) {
                results.append(["index": idx, "find": find, "error": "invalid regex: \(pattern)"])
                failed += 1
                if stopOnFirstFailure { break }
            } catch {
                results.append(["index": idx, "find": find, "error": "\(error)"])
                failed += 1
                if stopOnFirstFailure { break }
            }
        }

        if !dryRun {
            try await storeDocument(doc, for: docId)
        } else {
            // Update openDocuments even in dry_run so caller can observe the
            // in-memory effect; skip only the disk write.
            openDocuments[docId] = doc
        }

        // Build human-readable summary + JSON-ish detail
        var summary = "Replace batch: \(succeeded) applied, \(failed) failed"
        if dryRun { summary += " (dry_run; disk not saved)" }
        summary += "\n\nDetails:\n"
        for r in results {
            let idx = r["index"] ?? "?"
            if let err = r["error"] as? String {
                summary += "  [\(idx)] FAIL: \(err)\n"
            } else {
                let find = r["find"] as? String ?? ""
                let count = r["replaced_count"] as? Int ?? 0
                let repaired = r["cross_run_repaired"] as? Int ?? 0
                let collapsedUnrepaired = r["cross_run_collapsed_unrepaired"] as? Int ?? 0
                let usedNormalizedFallback = r["used_normalized_fallback"] as? Bool ?? false
                let normalizedNote = usedNormalizedFallback
                    ? "; NOTE: used whitespace-normalized matching (#187)"
                    : ""
                summary += "  [\(idx)] '\(find)' → \(count) replaced\(crossRunRepairSummary(repaired: repaired, collapsedUnrepaired: collapsedUnrepaired))\(normalizedNote)\n"
            }
        }
        return summary
    }

    // MARK: - Formatting

    private func formatText(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        var format = RunProperties()
        if let bold = try optionalBool(args, "bold") { format.bold = bold }
        if let italic = try optionalBool(args, "italic") { format.italic = italic }
        if let underline = try optionalBool(args, "underline") { format.underline = underline ? .single : nil }
        // #234: validate before ×2 (points→half-points); Int*Int overflow traps the process.
        if let fontSize = try optionalInt(args, "font_size") {
            format.fontSize = try Self.validatedScaledMeasurement(fontSize, key: "font_size", range: Self.fontSizePointsRange, multiplier: 2)
        }
        if let fontName = args["font_name"]?.stringValue { format.fontName = fontName }
        if let color = args["color"]?.stringValue { format.color = color }

        // v3.12.0+ (#45): per-call opt-in for revision-tracked formatting.
        let asRevision = try optionalBool(args, "as_revision") ?? false
        // #232 R4: parsed before the as_revision gate — a mistyped run_index
        // supplied without as_revision:true used to be silently ignored.
        let runIndexIfPresent = try optionalInt(args, "run_index")
        if asRevision {
            let runIndex = runIndexIfPresent ?? 0
            let author = args["author"]?.stringValue
            let date = parseISODate(args["date"]?.stringValue)
            // Index exactly as applyRunPropertiesAsRevision and formatParagraph
            // do — direct body children only. getParagraphs() also descends
            // into block-level SDTs, so after any SDT paragraph it would seed
            // the patch from a different paragraph than the one being changed.
            let paragraphs: [Paragraph] = doc.body.children.compactMap {
                if case .paragraph(let paragraph) = $0 { return paragraph }
                return nil
            }
            guard paragraphIndex >= 0, paragraphIndex < paragraphs.count else {
                throw WordError.invalidIndex(paragraphIndex)
            }
            let runs = paragraphs[paragraphIndex].runs
            guard runIndex >= 0, runIndex < runs.count else {
                throw WordError.invalidIndex(runIndex)
            }
            // applyRunPropertiesAsRevision replaces the complete rPr value.
            // Start from the existing run so omitted MCP arguments remain
            // unchanged; explicit false/nil assignments remain intentional.
            var replacement = runs[runIndex].properties
            if let bold = try optionalBool(args, "bold") { replacement.bold = bold }
            if let italic = try optionalBool(args, "italic") { replacement.italic = italic }
            if let underline = try optionalBool(args, "underline") {
                replacement.underline = underline ? .single : nil
            }
            // R8 (`rev232b` review of #234, LOW-1): this call is
            // defense-in-depth, not an independently reachable second
            // failure site. `font_size` was already read and validated
            // UNCONDITIONALLY above (line ~8197) before this `asRevision`
            // branch is even entered — `optionalInt`/`validatedScaledMeasurement`
            // are pure functions of the same `args`, so if that earlier
            // call didn't throw, this identical call can't throw either.
            // #234's CHANGELOG describes 8 independently-triggerable sites
            // including this one as a separate count; that overcounts by
            // one — 7 sites are independently reachable, this is the 8th
            // only in the sense that it duplicates the same validation
            // logic, not a second exposure. Left in place (not deleted)
            // because it costs nothing at runtime and keeps this branch
            // safe on its own terms if the unconditional check above is
            // ever made conditional by a future change.
            if let fontSize = try optionalInt(args, "font_size") {
                replacement.fontSize = try Self.validatedScaledMeasurement(fontSize, key: "font_size", range: Self.fontSizePointsRange, multiplier: 2)
            }
            if let fontName = args["font_name"]?.stringValue {
                replacement.fontName = fontName
            }
            if let color = args["color"]?.stringValue { replacement.color = color }
            let revId = try doc.applyRunPropertiesAsRevision(
                atParagraph: paragraphIndex, atRunIndex: runIndex,
                newProperties: replacement, author: author, date: date
            )
            try await storeDocument(doc, for: docId)
            return "Applied formatting to paragraph \(paragraphIndex) run \(runIndex) as revision \(revId)"
        }

        try doc.formatParagraph(at: paragraphIndex, with: format)
        try await storeDocument(doc, for: docId)

        return "Applied formatting to paragraph \(paragraphIndex)"
    }

    private func setParagraphFormat(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        var props = ParagraphProperties()
        if let alignment = args["alignment"]?.stringValue {
            props.alignment = Alignment(rawValue: alignment)
        }
        // #232 R6: `.doubleValue` only matches the `.double` JSON case — a
        // whole-valued `line_spacing` (JSON `2`, decoded as `.int` on this
        // platform) silently fell through to `nil` here and was dropped
        // without error, even though it's a legal, documented value. Fixed
        // by `optionalDouble`, which accepts both `.int` and `.double`.
        // #232 R7 (`rev232b` review M2): the multiply-then-`Int(...)` used to
        // happen inline and could trap the whole process on an
        // out-of-range value; `Self.twipsLine(fromLineSpacingMultiplier:)`
        // validates finiteness, positivity, and the OOXML-typed range first.
        if let lineSpacing = try optionalDouble(args, "line_spacing") {
            props.spacing = Spacing(line: try Self.twipsLine(fromLineSpacingMultiplier: lineSpacing)) // 轉換為 1/240 點
        }
        // #234: validate before ×20 (points→twips); Int*Int overflow traps the process.
        if let spaceBefore = try optionalInt(args, "space_before") {
            if props.spacing == nil { props.spacing = Spacing() }
            props.spacing?.before = try Self.validatedScaledMeasurement(spaceBefore, key: "space_before", range: Self.paragraphSpacingPointsRange, multiplier: 20)
        }
        if let spaceAfter = try optionalInt(args, "space_after") {
            if props.spacing == nil { props.spacing = Spacing() }
            props.spacing?.after = try Self.validatedScaledMeasurement(spaceAfter, key: "space_after", range: Self.paragraphSpacingPointsRange, multiplier: 20)
        }

        let asRevision = try optionalBool(args, "as_revision") ?? false
        if asRevision {
            let author = args["author"]?.stringValue
            let date = parseISODate(args["date"]?.stringValue)
            let revId = try doc.applyParagraphPropertiesAsRevision(
                atParagraph: paragraphIndex, newProperties: props,
                author: author, date: date
            )
            try await storeDocument(doc, for: docId)
            return "Applied paragraph format to index \(paragraphIndex) as revision \(revId)"
        }

        try doc.setParagraphFormat(at: paragraphIndex, properties: props)
        try await storeDocument(doc, for: docId)

        return "Applied paragraph format to index \(paragraphIndex)"
    }

    // MARK: - Programmatic Track Changes (#45)

    /// Parse an optional ISO 8601 timestamp string into a Date. Nil input
    /// returns nil (callers default to `Date()`).
    private func parseISODate(_ s: String?) -> Date? {
        guard let s = s, !s.isEmpty else { return nil }
        return ISO8601DateFormatter().date(from: s)
    }

    private func insertTextAsRevision(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let position = try optionalInt(args, "position") else {
            throw WordError.missingParameter("position")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let author = args["author"]?.stringValue
        let date = parseISODate(args["date"]?.stringValue)
        let revId = try doc.insertTextAsRevision(
            text: text, atParagraph: paragraphIndex, position: position,
            author: author, date: date
        )
        try await storeDocument(doc, for: docId)
        return "Inserted text as revision id \(revId)"
    }

    private func deleteTextAsRevision(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let start = try optionalInt(args, "start") else {
            throw WordError.missingParameter("start")
        }
        guard let end = try optionalInt(args, "end") else {
            throw WordError.missingParameter("end")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #238: ooxml-swift's WordDocument.deleteTextAsRevision guards
        // `start >= 0, end >= start, end <= totalLength` as one compound
        // condition and always throws `WordError.invalidIndex(end)` — so
        // `start: -1, end: 3` and `start: 1000, end: 3` both say "Invalid
        // index: 3", blaming `end` when `start` is what is actually out of
        // range. Pre-validate ourselves and name the true culprit — but
        // only once track-changes-off and an out-of-range paragraph_index
        // have already had their chance to fire exactly as before (same
        // precondition order the library checks internally), so this only
        // changes which value gets named for a bad start/end, not which
        // error fires first for the other cases.
        if doc.isTrackChangesEnabled() {
            var bodyChildIdx: Int? = nil
            var seen = 0
            for (i, child) in doc.body.children.enumerated() {
                if case .paragraph = child {
                    if seen == paragraphIndex { bodyChildIdx = i; break }
                    seen += 1
                }
            }
            if let bodyChildIdx, case .paragraph(let paragraph) = doc.body.children[bodyChildIdx] {
                let totalLength = paragraph.runs.reduce(0) { $0 + $1.text.count }
                if start < 0 {
                    throw ToolRefusal("delete_text_as_revision: start must be >= 0, got start=\(start)")
                }
                if end < start {
                    throw ToolRefusal("delete_text_as_revision: start must be <= end (end=\(end)), got start=\(start)")
                }
                if end > totalLength {
                    throw ToolRefusal("delete_text_as_revision: end must be <= paragraph length \(totalLength), got end=\(end)")
                }
            }
            // else: paragraph_index itself is out of range — fall through
            // to the library call, which reports that correctly already.
        }

        let author = args["author"]?.stringValue
        let date = parseISODate(args["date"]?.stringValue)
        let revId = try doc.deleteTextAsRevision(
            atParagraph: paragraphIndex, start: start, end: end,
            author: author, date: date
        )
        try await storeDocument(doc, for: docId)
        return "Deleted text as revision id \(revId)"
    }

    private func moveTextAsRevision(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let fromPara = try optionalInt(args, "from_paragraph_index") else {
            throw WordError.missingParameter("from_paragraph_index")
        }
        guard let fromStart = try optionalInt(args, "from_start") else {
            throw WordError.missingParameter("from_start")
        }
        guard let fromEnd = try optionalInt(args, "from_end") else {
            throw WordError.missingParameter("from_end")
        }
        guard let toPara = try optionalInt(args, "to_paragraph_index") else {
            throw WordError.missingParameter("to_paragraph_index")
        }
        guard let toPos = try optionalInt(args, "to_position") else {
            throw WordError.missingParameter("to_position")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let author = args["author"]?.stringValue
        let date = parseISODate(args["date"]?.stringValue)
        let result = try doc.moveTextAsRevision(
            fromParagraph: fromPara, fromStart: fromStart, fromEnd: fromEnd,
            toParagraph: toPara, toPosition: toPos,
            author: author, date: date
        )
        try await storeDocument(doc, for: docId)
        return "Moved text as revisions: from_id=\(result.fromId) to_id=\(result.toId)"
    }

    private func applyStyle(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let style = args["style"]?.stringValue else {
            throw WordError.missingParameter("style")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        try doc.applyStyle(at: paragraphIndex, style: style)
        try await storeDocument(doc, for: docId)

        return "Applied style '\(style)' to paragraph \(paragraphIndex)"
    }

    // MARK: - Table

    private func insertTable(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let rows = try optionalInt(args, "rows") else {
            throw WordError.missingParameter("rows")
        }
        guard let cols = try optionalInt(args, "cols") else {
            throw WordError.missingParameter("cols")
        }
        // R8: see `tableRowCountRange`/`tableColumnCountRange`'s doc
        // comment — `Table(rowCount:columnCount:)` traps or exhausts
        // memory unguarded.
        try Self.validateTableDimensions(rows: rows, cols: cols)
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        var table = Table(rowCount: rows, columnCount: cols)

        // 如果有提供資料，填入表格
        if let dataArray = args["data"]?.arrayValue {
            for (rowIndex, rowData) in dataArray.enumerated() {
                if let rowArray = rowData.arrayValue {
                    for (colIndex, cellData) in rowArray.enumerated() {
                        if let text = cellData.stringValue,
                           rowIndex < table.rows.count && colIndex < table.rows[rowIndex].cells.count {
                            table.rows[rowIndex].cells[colIndex] = TableCell(text: text)
                        }
                    }
                }
            }
        }

        let index = try optionalInt(args, "index")
        if let index = index {
            doc.insertTable(table, at: index)
        } else {
            doc.appendTable(table)
        }

        try await storeDocument(doc, for: docId)

        return "Inserted \(rows)x\(cols) table"
    }

    /// #188: renders one nested table (and, recursively, any tables nested
    /// inside *its* cells) as an indented block appended under the host row
    /// that contains it. `pathPrefix` names the hosting cell so the printed
    /// path matches what `update_cell`'s `nested_table_index` /
    /// `nested_row` / `nested_col` (one level) or a human reader (any level)
    /// needs. Pre-#188, nested tables were entirely absent from this tool's
    /// output — `get_tables` only ever enumerated `body.children`'s
    /// top-level `.table` cases (see `WordDocument.getTables()`,
    /// ooxml-swift, unchanged), so a cell's `nestedTables` were invisible.
    private func nestedTableBlock(
        cell: TableCell, pathPrefix: String, indent: String, summarize: Bool,
        summarizedRowCap: Int, summarizedColCap: Int
    ) -> String {
        var block = ""
        for (nestedIdx, nested) in cell.nestedTables.enumerated() {
            let path = "\(pathPrefix) > nested table \(nestedIdx)"
            let rows = nested.rows.count
            let widths = nested.rows.map { $0.cells.count }
            let maxCols = widths.max() ?? 0
            let minCols = widths.min() ?? 0
            let sizeLabel = minCols == maxCols
                ? "\(rows)x\(maxCols) table"
                : "\(rows)x\(maxCols) table (ragged: \(minCols)..\(maxCols) columns per row)"
            block += "\(indent)Nested table at \(path): \(sizeLabel)\n"

            let shownRows = summarize ? Array(nested.rows.prefix(summarizedRowCap)) : nested.rows
            for (rowIdx, row) in shownRows.enumerated() {
                let shownCells = summarize ? Array(row.cells.prefix(summarizedColCap)) : row.cells
                var cellTexts = shownCells.map { c -> String in
                    let text = truncateText(c.getText(), summarize: summarize)
                    return text.isEmpty ? "(empty)" : text
                }
                let hiddenCols = row.cells.count - shownCells.count
                if hiddenCols > 0 {
                    cellTexts.append("... (\(hiddenCols) more column\(hiddenCols == 1 ? "" : "s"))")
                }
                block += "\(indent)  Row \(rowIdx): \(cellTexts.joined(separator: " | "))\n"
                for (cellIdx, deeperCell) in shownCells.enumerated() {
                    let cellPath = "\(path), row \(rowIdx), col \(cellIdx)"
                    block += nestedTableBlock(
                        cell: deeperCell, pathPrefix: cellPath, indent: indent + "  ", summarize: summarize,
                        summarizedRowCap: summarizedRowCap, summarizedColCap: summarizedColCap
                    )
                }
            }
            let hiddenRows = nested.rows.count - shownRows.count
            if hiddenRows > 0 {
                block += "\(indent)  ... (\(hiddenRows) more row\(hiddenRows == 1 ? "" : "s"))\n"
            }
        }
        return block
    }

    private func getTables(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)

        // Spec word-mcp-markdown-export — Requirement: Truncation policy via
        // summarize parameter. Default (summarize omitted/false) SHALL return
        // complete content with no upper bound. #177: this tool previously
        // truncated unconditionally (first-row column count in the header,
        // 3 rows, 3 columns, 15 characters per cell) and disclosed only the
        // row truncation, so its own header contradicted its own body.
        // #232 R6 (review H2a): parsed before the empty-document early
        // return, not after — same fix as R1's list_comments.
        let summarize = try optionalBool(args, "summarize") ?? false
        let summarizedRowCap = 3
        let summarizedColCap = 3

        let tables = doc.getTables()
        if tables.isEmpty {
            return "No tables in document"
        }

        var result = "Tables in document:\n"
        for (index, table) in tables.enumerated() {
            let rows = table.rows.count
            // Header reports the widest row, not the first one: a ragged table
            // (rows differing in <w:tc> count, e.g. after a horizontal merge)
            // has no single width, and reporting the first row's understates
            // which column indices are addressable.
            let widths = table.rows.map { $0.cells.count }
            let maxCols = widths.max() ?? 0
            let minCols = widths.min() ?? 0
            if minCols == maxCols {
                result += "[\(index)] \(rows)x\(maxCols) table\n"
            } else {
                result += "[\(index)] \(rows)x\(maxCols) table (ragged: \(minCols)..\(maxCols) columns per row)\n"
            }

            let shownRows = summarize ? Array(table.rows.prefix(summarizedRowCap)) : table.rows
            for (rowIdx, row) in shownRows.enumerated() {
                let shownCells = summarize ? Array(row.cells.prefix(summarizedColCap)) : row.cells
                var cellTexts = shownCells.map { cell -> String in
                    let text = truncateText(cell.getText(), summarize: summarize)
                    return text.isEmpty ? "(empty)" : text
                }
                let hiddenCols = row.cells.count - shownCells.count
                if hiddenCols > 0 {
                    cellTexts.append("... (\(hiddenCols) more column\(hiddenCols == 1 ? "" : "s"))")
                }
                result += "  Row \(rowIdx): \(cellTexts.joined(separator: " | "))\n"
                // #188: cells can carry their own nested `<w:tbl>`, invisible
                // above because `cell.getText()` never includes them.
                for (cellIdx, cell) in shownCells.enumerated() where !cell.nestedTables.isEmpty {
                    let cellPath = "Table \(index), row \(rowIdx), col \(cellIdx)"
                    result += nestedTableBlock(
                        cell: cell, pathPrefix: cellPath, indent: "    ", summarize: summarize,
                        summarizedRowCap: summarizedRowCap, summarizedColCap: summarizedColCap
                    )
                }
            }
            let hiddenRows = table.rows.count - shownRows.count
            if hiddenRows > 0 {
                result += "  ... (\(hiddenRows) more row\(hiddenRows == 1 ? "" : "s"))\n"
            }
        }
        return result
    }

    /// che-word-mcp#191: does `RunProperties` declare any font at all (the
    /// `rFonts` 4-axis struct or the legacy single-axis `fontName`)? A run
    /// with no declared font renders in Word's `docDefaults` font, which is
    /// exactly the failure mode this issue is about — so a "fallback" run's
    /// properties only count as usable if they'd actually pin a font.
    private func hasDeclaredFont(_ properties: RunProperties) -> Bool {
        if let rFonts = properties.rFonts,
           rFonts.ascii != nil || rFonts.hAnsi != nil || rFonts.eastAsia != nil || rFonts.cs != nil {
            return true
        }
        return properties.fontName != nil
    }

    /// A short, stable key distinguishing declared fonts for frequency
    /// counting. Not meant to be exhaustive over every `RunProperties` field
    /// (bold/italic/etc. don't matter for "which font renders this text") —
    /// only the axes that determine which face Word picks.
    private func declaredFontFingerprint(_ properties: RunProperties) -> String {
        if let rFonts = properties.rFonts {
            return "rFonts:\(rFonts.ascii ?? "")|\(rFonts.hAnsi ?? "")|\(rFonts.eastAsia ?? "")|\(rFonts.cs ?? "")"
        }
        return "fontName:\(properties.fontName ?? "")"
    }

    /// che-word-mcp#191 Tier 2: the most common declared-font `RunProperties`
    /// among every non-empty run in the document (body paragraphs, all table
    /// cells, one level of nested tables, and block-level content-control
    /// children). This is the document's "dominant" font — for a form whose
    /// main body is entirely one font (890 `eastAsia="標楷體"` runs in the
    /// #191 reproducer) with only `docDefaults` disagreeing, this recovers
    /// the form's actual declared font rather than the default nobody chose.
    private func dominantDeclaredFontProperties(in doc: WordDocument) -> RunProperties? {
        var counts: [String: (count: Int, properties: RunProperties)] = [:]
        func note(_ properties: RunProperties) {
            guard hasDeclaredFont(properties) else { return }
            let key = declaredFontFingerprint(properties)
            if let existing = counts[key] {
                counts[key] = (existing.count + 1, existing.properties)
            } else {
                counts[key] = (1, properties)
            }
        }
        func walk(paragraph: Paragraph) {
            for run in paragraph.runs where !run.text.isEmpty {
                note(run.properties)
            }
        }
        func walk(cell: TableCell) {
            for paragraph in cell.paragraphs { walk(paragraph: paragraph) }
            for nested in cell.nestedTables { walk(table: nested) }
        }
        func walk(table: Table) {
            for row in table.rows {
                for cell in row.cells { walk(cell: cell) }
            }
        }
        func walk(children: [BodyChild]) {
            for child in children {
                switch child {
                case .paragraph(let paragraph):
                    walk(paragraph: paragraph)
                case .table(let table):
                    walk(table: table)
                case .contentControl(_, let inner):
                    walk(children: inner)
                case .bookmarkMarker, .rawBlockElement:
                    continue
                }
            }
        }
        walk(children: doc.body.children)
        return counts.values.max(by: { $0.count < $1.count })?.properties
    }

    /// che-word-mcp#191 (R2 review Finding 2 hardening): builds a
    /// `RunProperties` carrying ONLY the font-determining fields from
    /// `donor` — `rFonts` (all 4 axes), the legacy single-axis `fontName`,
    /// `fontSize` (OOXML `<w:sz>`; ooxml-swift's typed `RunProperties` does
    /// not model a separate complex-script size field, so `fontSize` is the
    /// only size axis available to copy), and `lang`. Every other field
    /// (`bold`, `italic`, `underline`, `strikethrough`, `color`,
    /// `highlight`, `verticalAlign`, `characterSpacing`, `textEffect`,
    /// `rStyle`, `kern`, `noProof`, ...) is left at `RunProperties()`'s
    /// default.
    ///
    /// Why this matters: `fallbackCellRunProperties` picks a donor run only
    /// because it's the *nearest* one that happens to declare a font — nothing
    /// about that selection says the donor's OTHER formatting is appropriate
    /// to copy. A form's "*必填" (required) label is routinely bold, red,
    /// and/or shaded — exactly the kind of donor `fallbackCellRunProperties`
    /// picks when it's the only formatted run in the row. Without this
    /// narrowing, the value a caller fills in next to that label would
    /// silently inherit the label's emphasis too (confirmed against a real
    /// binary before this fix: a plain paragraph of filled-in text came back
    /// bold and red) — the exact "text layer is correct, appearance is wrong,
    /// nobody notices until a human opens the file" failure mode this whole
    /// issue cluster is about, reintroduced by the fix meant to prevent it.
    private func fontOnlyProperties(from donor: RunProperties) -> RunProperties {
        var result = RunProperties()
        result.rFonts = donor.rFonts
        result.fontName = donor.fontName
        result.fontSize = donor.fontSize
        result.lang = donor.lang
        return result
    }

    /// che-word-mcp#191: pick a fallback `RunProperties` for a cell that has
    /// no existing run to inherit from — `updateCell`'s own "if the cell
    /// already has a run, reuse its `rPr`" branch (ooxml-swift, unmodified)
    /// only covers cells that already have *some* run. Priority:
    /// 1. another cell in the *same row* of `table` that has a non-empty run
    ///    with a declared font (any column, not just to the left — a caller
    ///    filling column 0 of a row whose label lives in column 1 still gets
    ///    the row's font);
    /// 2. failing that, the document's dominant declared font (see
    ///    `dominantDeclaredFontProperties`).
    /// Returns `nil` when neither search finds anything — the new run then
    /// stays unformatted, matching pre-#191 behaviour rather than fabricating
    /// a font out of nothing.
    ///
    /// The result always passes through `fontOnlyProperties` — donor runs
    /// are searched for by "has a declared font", but what's copied is never
    /// more than the font itself (R2 review Finding 2; see that function's
    /// doc comment). Both callers (the top-level `update_cell` path and the
    /// #188 nested-table path, via `applyCellTextWrite`) get this narrowing
    /// for free since they both consume this function's return value
    /// directly.
    private func fallbackCellRunProperties(doc: WordDocument, table: Table, row: Int, excludingCol: Int) -> RunProperties? {
        if row < table.rows.count {
            for (colIndex, cell) in table.rows[row].cells.enumerated() where colIndex != excludingCol {
                for paragraph in cell.paragraphs {
                    for run in paragraph.runs where !run.text.isEmpty {
                        if hasDeclaredFont(run.properties) {
                            return fontOnlyProperties(from: run.properties)
                        }
                    }
                }
            }
        }
        return dominantDeclaredFontProperties(in: doc).map(fontOnlyProperties(from:))
    }

    /// The `body.children` index of the `tableIndex`-th top-level `.table`
    /// (mirrors ooxml-swift's own private `getTableIndices()` addressing —
    /// che-word-mcp cannot call that directly, so this reimplements the same
    /// "Nth `.table` case among direct body children" rule it documents).
    private func topLevelTableBodyIndex(_ doc: WordDocument, tableIndex: Int) -> Int? {
        var count = 0
        for (i, child) in doc.body.children.enumerated() {
            if case .table = child {
                if count == tableIndex { return i }
                count += 1
            }
        }
        return nil
    }

    /// #188: writes `text` into `cell`'s first paragraph exactly like
    /// ooxml-swift's `updateCell` does for a top-level cell (preserve the
    /// first run's own `rPr` when one already exists; otherwise apply
    /// `fallbackProperties` per #191, or leave the new run unformatted when
    /// `fallbackProperties` is nil). Used for the `nested_table_index` write
    /// path below, since `doc.updateCell` itself has no nested-table
    /// addressing — che-word-mcp reimplements just this one cell-mutation
    /// step rather than modifying ooxml-swift.
    private func applyCellTextWrite(cell: inout TableCell, text: String, fallbackProperties: RunProperties?) {
        if var updatedPara = cell.paragraphs.first, let firstRun = updatedPara.runs.first {
            var updatedRun = firstRun
            updatedRun.text = text
            updatedPara.runs = [updatedRun]
            if cell.paragraphs.isEmpty {
                cell.paragraphs = [updatedPara]
            } else {
                cell.paragraphs[0] = updatedPara
            }
        } else {
            var updatedPara = cell.paragraphs.first ?? Paragraph()
            var newRun = Run(text: text)
            if let fallbackProperties {
                newRun.properties = fallbackProperties
            }
            updatedPara.runs = [newRun]
            if cell.paragraphs.isEmpty {
                cell.paragraphs = [updatedPara]
            } else {
                cell.paragraphs[0] = updatedPara
            }
        }
    }

    private func updateCell(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let tableIndex = try optionalInt(args, "table_index") else {
            throw WordError.missingParameter("table_index")
        }
        guard let row = try optionalInt(args, "row") else {
            throw WordError.missingParameter("row")
        }
        guard let col = try optionalInt(args, "col") else {
            throw WordError.missingParameter("col")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #188: `table_index`/`row`/`col` address the HOST cell; this
        // addresses a table nested *inside* that cell (`TableCell.
        // nestedTables[nested_table_index]`), at (`nested_row`,
        // `nested_col`) within the nested table. One level of nesting only
        // (matches every real-world reproducer seen so far and ooxml-swift's
        // own parser scope — deeper nesting can chain `nested_table_index`
        // additions later if a real case ever needs it). `doc.updateCell`
        // has no nested addressing at all, so this path writes the whole
        // way through `doc.body.children` itself rather than delegating.
        if let nestedTableIndex = try optionalInt(args, "nested_table_index") {
            guard let nestedRow = try optionalInt(args, "nested_row") else {
                throw WordError.missingParameter("nested_row")
            }
            guard let nestedCol = try optionalInt(args, "nested_col") else {
                throw WordError.missingParameter("nested_col")
            }
            guard let bodyIndex = topLevelTableBodyIndex(doc, tableIndex: tableIndex),
                  case .table(var table) = doc.body.children[bodyIndex] else {
                throw WordError.invalidIndex(tableIndex)
            }
            guard row >= 0, row < table.rows.count else {
                throw WordError.invalidIndex(row)
            }
            guard col >= 0, col < table.rows[row].cells.count else {
                throw WordError.invalidFormat("Invalid col index \(col) for row \(row): row has \(table.rows[row].cells.count) cell(s)")
            }
            let hostCell = table.rows[row].cells[col]
            guard nestedTableIndex >= 0, nestedTableIndex < hostCell.nestedTables.count else {
                throw WordError.invalidParameter(
                    "nested_table_index",
                    "cell table[\(tableIndex)][\(row)][\(col)] has \(hostCell.nestedTables.count) nested table(s)"
                )
            }
            var nested = hostCell.nestedTables[nestedTableIndex]
            guard nestedRow >= 0, nestedRow < nested.rows.count else {
                throw WordError.invalidParameter("nested_row", "nested table has \(nested.rows.count) row(s)")
            }
            guard nestedCol >= 0, nestedCol < nested.rows[nestedRow].cells.count else {
                throw WordError.invalidParameter(
                    "nested_col", "nested table row \(nestedRow) has \(nested.rows[nestedRow].cells.count) cell(s)"
                )
            }

            var targetCell = nested.rows[nestedRow].cells[nestedCol]
            // R2 review Finding 4 / coordinator item 3: this path only
            // supports ONE level of nesting (`nested_table_index` addresses
            // a table directly inside the host cell — there is no parameter
            // to go a level deeper). A target cell that itself contains
            // another nested table is refused explicitly here, rather than
            // silently writing text into its paragraph while leaving its own
            // `nestedTables` untouched-but-now-orphaned-looking and reporting
            // success — a caller would have no way to tell, from this tool's
            // response alone, that the cell they just "updated" still has
            // unaddressed content underneath it.
            guard targetCell.nestedTables.isEmpty else {
                throw WordError.invalidParameter(
                    "nested_table_index",
                    "cell table[\(tableIndex)][\(row)][\(col)] > nested table \(nestedTableIndex)[\(nestedRow)][\(nestedCol)] itself contains \(targetCell.nestedTables.count) more nested table(s) — only one level of nesting is supported by nested_table_index/nested_row/nested_col"
                )
            }
            let cellHasNoRuns = targetCell.paragraphs.first?.runs.first == nil
            let fallbackProperties = cellHasNoRuns
                ? fallbackCellRunProperties(doc: doc, table: nested, row: nestedRow, excludingCol: nestedCol)
                : nil
            applyCellTextWrite(cell: &targetCell, text: text, fallbackProperties: fallbackProperties)
            nested.rows[nestedRow].cells[nestedCol] = targetCell
            table.rows[row].cells[col].nestedTables[nestedTableIndex] = nested
            doc.body.children[bodyIndex] = .table(table)
            if tableIndex < doc.body.tables.count {
                doc.body.tables[tableIndex] = table
            }
            // This path never calls `doc.updateCell` (which self-marks dirty
            // internally) — it writes through `doc.body.children` directly,
            // so it must mark the part dirty itself or `DocxWriter`'s overlay
            // mode has no signal to re-emit `word/document.xml` on save.
            doc.markPartDirty("word/document.xml")

            try await storeDocument(doc, for: docId)
            return "Updated cell at table[\(tableIndex)][\(row)][\(col)] > nested table \(nestedTableIndex)[\(nestedRow)][\(nestedCol)]"
        }

        // che-word-mcp#191: determine BEFORE the write whether the target
        // cell has zero runs — that's the exact condition under which
        // ooxml-swift's `updateCell` creates a brand-new, unformatted run
        // (its "else" branch). Computed from a best-effort read; if the
        // coordinates are invalid this silently skips the fallback and lets
        // `doc.updateCell` below throw its own (better) validated error.
        var fallbackProperties: RunProperties?
        let tablesBeforeWrite = doc.getTables()
        if tableIndex >= 0, tableIndex < tablesBeforeWrite.count {
            let table = tablesBeforeWrite[tableIndex]
            if row >= 0, row < table.rows.count, col >= 0, col < table.rows[row].cells.count {
                let cellHasNoRuns = table.rows[row].cells[col].paragraphs.first?.runs.first == nil
                if cellHasNoRuns {
                    fallbackProperties = fallbackCellRunProperties(doc: doc, table: table, row: row, excludingCol: col)
                }
            }
        }

        try doc.updateCell(tableIndex: tableIndex, row: row, col: col, text: text)

        if let fallbackProperties,
           let bodyIndex = topLevelTableBodyIndex(doc, tableIndex: tableIndex),
           case .table(var table) = doc.body.children[bodyIndex],
           row < table.rows.count, col < table.rows[row].cells.count,
           var paragraph = table.rows[row].cells[col].paragraphs.first,
           var newRun = paragraph.runs.first {
            newRun.properties = fallbackProperties
            paragraph.runs[0] = newRun
            table.rows[row].cells[col].paragraphs[0] = paragraph
            doc.body.children[bodyIndex] = .table(table)
            if tableIndex < doc.body.tables.count {
                doc.body.tables[tableIndex] = table
            }
        }

        try await storeDocument(doc, for: docId)

        return "Updated cell at table[\(tableIndex)][\(row)][\(col)]"
    }

    private func getCellParagraphs(args: [String: Value]) async throws -> String {
        guard let tableIndex = try optionalInt(args, "table_index") else {
            throw WordError.missingParameter("table_index")
        }
        guard let row = try optionalInt(args, "row") else {
            throw WordError.missingParameter("row")
        }
        guard let col = try optionalInt(args, "col") else {
            throw WordError.missingParameter("col")
        }
        let (doc, _) = try await resolveDocument(args: args)
        let texts = try doc.cellParagraphTexts(tableIndex: tableIndex, row: row, col: col)
        var result = "Cell table[\(tableIndex)][\(row)][\(col)] has \(texts.count) paragraph(s):"
        for (index, text) in texts.enumerated() {
            result += "\n[\(index)] \(text)"
        }
        return result
    }

    private func updateCellParagraph(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let tableIndex = try optionalInt(args, "table_index") else {
            throw WordError.missingParameter("table_index")
        }
        guard let row = try optionalInt(args, "row") else {
            throw WordError.missingParameter("row")
        }
        guard let col = try optionalInt(args, "col") else {
            throw WordError.missingParameter("col")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        try doc.updateCellParagraph(tableIndex: tableIndex, row: row, col: col, paragraphIndex: paragraphIndex, text: text)
        try await storeDocument(doc, for: docId)

        return "Updated paragraph \(paragraphIndex) in cell table[\(tableIndex)][\(row)][\(col)]"
    }

    private func deleteTable(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let tableIndex = try optionalInt(args, "table_index") else {
            throw WordError.missingParameter("table_index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        try doc.deleteTable(at: tableIndex)
        try await storeDocument(doc, for: docId)

        return "Deleted table at index \(tableIndex)"
    }

    private func mergeCells(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let tableIndex = try optionalInt(args, "table_index") else {
            throw WordError.missingParameter("table_index")
        }
        guard let direction = args["direction"]?.stringValue else {
            throw WordError.missingParameter("direction")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #232 R4: all four parsed unconditionally, before the direction
        // switch — a mistyped end_row supplied with direction:"horizontal"
        // (or a mistyped end_col with direction:"vertical") used to be
        // silently ignored, since each switch case only ever read the
        // fields relevant to its own direction. Which ones are REQUIRED
        // still depends on direction; only the type validation is now
        // unconditional.
        let rowArg = try optionalInt(args, "row")
        let colArg = try optionalInt(args, "col")
        let endColArg = try optionalInt(args, "end_col")
        let endRowArg = try optionalInt(args, "end_row")

        switch direction.lowercased() {
        case "horizontal":
            guard let row = rowArg else {
                throw WordError.missingParameter("row")
            }
            guard let col = colArg else {
                throw WordError.missingParameter("col")
            }
            guard let endCol = endColArg else {
                throw WordError.missingParameter("end_col")
            }
            try doc.mergeCellsHorizontal(tableIndex: tableIndex, row: row, startCol: col, endCol: endCol)
            try await storeDocument(doc, for: docId)
            return "Merged cells horizontally: row \(row), columns \(col) to \(endCol)"

        case "vertical":
            guard let row = rowArg else {
                throw WordError.missingParameter("row")
            }
            guard let col = colArg else {
                throw WordError.missingParameter("col")
            }
            guard let endRow = endRowArg else {
                throw WordError.missingParameter("end_row")
            }
            try doc.mergeCellsVertical(tableIndex: tableIndex, col: col, startRow: row, endRow: endRow)
            try await storeDocument(doc, for: docId)
            return "Merged cells vertically: column \(col), rows \(row) to \(endRow)"

        default:
            throw WordError.invalidParameter("direction", "Must be 'horizontal' or 'vertical'")
        }
    }

    private func setTableStyle(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let tableIndex = try optionalInt(args, "table_index") else {
            throw WordError.missingParameter("table_index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        var results: [String] = []

        // #232 R2 (Codex finding): `border_size` used to be parsed only
        // inside the `border_style`-gated block, so a mistyped border_size
        // supplied WITHOUT border_style was never read and never errored —
        // the border feature is optional-on-border_style, but the
        // parameter's own type should not depend on a sibling's presence.
        // Same for `cell_row`/`cell_col` below: an `if let` chain
        // short-circuits, so a mistyped cell_col was never even evaluated
        // when cell_row was absent. Parse both unconditionally first so a
        // present-but-mistyped value always errors, then gate activation as
        // before.
        let borderSizeIfPresent = try optionalInt(args, "border_size")
        let cellRowIfPresent = try optionalInt(args, "cell_row")
        let cellColIfPresent = try optionalInt(args, "cell_col")

        // 設定邊框
        if let borderStyle = args["border_style"]?.stringValue {
            let style = BorderStyle(rawValue: borderStyle) ?? .single
            let size = borderSizeIfPresent ?? 4
            let color = args["border_color"]?.stringValue ?? "000000"

            let border = Border(style: style, size: size, color: color)
            let borders = TableBorders.all(border)

            try doc.setTableBorders(tableIndex: tableIndex, borders: borders)
            results.append("Set border style: \(borderStyle)")
        }

        // 設定儲存格底色
        if let cellRow = cellRowIfPresent,
           let cellCol = cellColIfPresent,
           let shadingColor = args["shading_color"]?.stringValue {
            let shading = CellShading(fill: shadingColor)
            try doc.setCellShading(tableIndex: tableIndex, row: cellRow, col: cellCol, shading: shading)
            results.append("Set cell shading at [\(cellRow)][\(cellCol)]: \(shadingColor)")
        }

        // #215: this used to storeDocument() unconditionally and only THEN
        // check whether anything had actually changed — a call with no
        // recognized style arguments (or a `cell_row`/`cell_col`/
        // `shading_color` combination that never became active) marked the
        // session dirty and reported "No style changes applied" as if that
        // were a normal, non-error outcome. No `isError`, no `Error:`
        // prefix — invisible to the #202 sweep. Refuse before persisting,
        // same convention as the rest of #202's ToolRefusal family.
        guard !results.isEmpty else {
            throw ToolRefusal("set_table_style: no style properties given (need border_style, or cell_row+cell_col+shading_color)")
        }

        try await storeDocument(doc, for: docId)
        return results.joined(separator: "\n")
    }

    // MARK: - Style Management

    private func listStyles(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)

        let styles = doc.getStyles()
        if styles.isEmpty {
            return "No styles defined"
        }

        var result = "Available Styles:\n"
        for style in styles {
            let defaultMark = style.isDefault ? " (default)" : ""
            let basedOnInfo = style.basedOn.map { " [based on: \($0)]" } ?? ""
            result += "- \(style.id) (\(style.name)) - \(style.type.rawValue)\(defaultMark)\(basedOnInfo)\n"

            // 顯示格式資訊
            if let runProps = style.runProperties {
                var formats: [String] = []
                if let fontName = runProps.fontName { formats.append("font: \(fontName)") }
                if let fontSize = runProps.fontSize { formats.append("size: \(fontSize / 2)pt") }
                if runProps.bold == true { formats.append("bold") }
                if runProps.italic == true { formats.append("italic") }
                if let color = runProps.color { formats.append("color: #\(color)") }
                if !formats.isEmpty {
                    result += "    Text: \(formats.joined(separator: ", "))\n"
                }
            }
        }
        return result
    }

    private func createStyle(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let styleId = args["style_id"]?.stringValue else {
            throw WordError.missingParameter("style_id")
        }
        guard let name = args["name"]?.stringValue else {
            throw WordError.missingParameter("name")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // 解析樣式類型
        // #253: neither a wrong JSON type NOR an unrecognized value was
        // ever rejected — `RawRepresentable(rawValue:)`'s `nil` on either
        // failure fell straight into `?? .paragraph`, reporting success
        // while silently building a DIFFERENT style type than requested.
        let typeStr = try Self.optionalStrictEnumString(args, "type", allowed: ["paragraph", "character", "table", "numbering"]) ?? "paragraph"
        let styleType = StyleType(rawValue: typeStr) ?? .paragraph

        // 解析段落屬性
        var paraProps = ParagraphProperties()
        if let alignment = args["alignment"]?.stringValue {
            paraProps.alignment = Alignment(rawValue: alignment)
        }
        // #234: validate before ×20 (points→twips); Int*Int overflow traps the process.
        if let spaceBefore = try optionalInt(args, "space_before") {
            if paraProps.spacing == nil { paraProps.spacing = Spacing() }
            paraProps.spacing?.before = try Self.validatedScaledMeasurement(spaceBefore, key: "space_before", range: Self.paragraphSpacingPointsRange, multiplier: 20)
        }
        if let spaceAfter = try optionalInt(args, "space_after") {
            if paraProps.spacing == nil { paraProps.spacing = Spacing() }
            paraProps.spacing?.after = try Self.validatedScaledMeasurement(spaceAfter, key: "space_after", range: Self.paragraphSpacingPointsRange, multiplier: 20)
        }

        // 解析 Run 屬性
        var runProps = RunProperties()
        if let fontName = args["font_name"]?.stringValue { runProps.fontName = fontName }
        // #234: validate before ×2 (points→half-points); Int*Int overflow traps the process.
        if let fontSize = try optionalInt(args, "font_size") {
            runProps.fontSize = try Self.validatedScaledMeasurement(fontSize, key: "font_size", range: Self.fontSizePointsRange, multiplier: 2)
        }
        if let bold = try optionalBool(args, "bold") { runProps.bold = bold }
        if let italic = try optionalBool(args, "italic") { runProps.italic = italic }
        if let color = args["color"]?.stringValue { runProps.color = color }

        // v3.10.0+ (#48): Office.js parity args
        let qFormat = try optionalBool(args, "q_format") ?? true
        let hidden = try optionalBool(args, "hidden") ?? false
        let semiHidden = try optionalBool(args, "semi_hidden") ?? false
        let linkedStyleId = args["linked_style_id"]?.stringValue
        let nextStyleId = args["next_style_id"]?.stringValue ?? args["next_style"]?.stringValue

        let style = Style(
            id: styleId,
            name: name,
            type: styleType,
            basedOn: args["based_on"]?.stringValue,
            nextStyle: nextStyleId,
            isDefault: false,
            isQuickStyle: qFormat,
            linkedStyleId: linkedStyleId,
            hidden: hidden,
            semiHidden: semiHidden,
            paragraphProperties: paraProps,
            runProperties: runProps
        )

        try doc.addStyle(style)
        try await storeDocument(doc, for: docId)

        return "Created style '\(styleId)' (\(name))"
    }

    private func updateStyle(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let styleId = args["style_id"]?.stringValue else {
            throw WordError.missingParameter("style_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // 建立更新資料
        var paraProps: ParagraphProperties? = nil
        if let alignment = args["alignment"]?.stringValue {
            paraProps = ParagraphProperties()
            paraProps?.alignment = Alignment(rawValue: alignment)
        }

        var runProps: RunProperties? = nil
        if args["font_name"] != nil || args["font_size"] != nil ||
           args["bold"] != nil || args["italic"] != nil || args["color"] != nil {
            runProps = RunProperties()
            if let fontName = args["font_name"]?.stringValue { runProps?.fontName = fontName }
            // #234: validate before ×2 (points→half-points); Int*Int overflow traps the process.
            if let fontSize = try optionalInt(args, "font_size") {
                runProps?.fontSize = try Self.validatedScaledMeasurement(fontSize, key: "font_size", range: Self.fontSizePointsRange, multiplier: 2)
            }
            if let bold = try optionalBool(args, "bold") { runProps?.bold = bold }
            if let italic = try optionalBool(args, "italic") { runProps?.italic = italic }
            if let color = args["color"]?.stringValue { runProps?.color = color }
        }

        // #232 R6 (review LOW-2): parsed unconditionally, before
        // `doc.updateStyle()` is even called — these three used to be read
        // only AFTER a successful update, inside the `firstIndex(where:)`
        // gate below. If `doc.updateStyle()` throws first for an unrelated
        // reason (e.g. the style id doesn't exist), a mistyped
        // q_format/hidden/semi_hidden on that same call was never reported:
        // the caller saw "style not found" and, after fixing the id alone,
        // would only discover the (also-present) type error on a second
        // call instead of both at once.
        let qFormatArg = try optionalBool(args, "q_format")
        let hiddenArg = try optionalBool(args, "hidden")
        let semiHiddenArg = try optionalBool(args, "semi_hidden")

        let updates = StyleUpdate(
            name: args["name"]?.stringValue,
            paragraphProperties: paraProps,
            runProperties: runProps
        )

        try doc.updateStyle(id: styleId, with: updates)

        // v3.10.0+ (#48): Office.js parity post-update for fields not in StyleUpdate
        if let idx = doc.styles.firstIndex(where: { $0.id == styleId }) {
            if let basedOn = args["based_on"]?.stringValue { doc.styles[idx].basedOn = basedOn }
            if let nextId = args["next_style_id"]?.stringValue { doc.styles[idx].nextStyle = nextId }
            if let linked = args["linked_style_id"]?.stringValue { doc.styles[idx].linkedStyleId = linked }
            if let qFormat = qFormatArg { doc.styles[idx].isQuickStyle = qFormat }
            if let hidden = hiddenArg { doc.styles[idx].hidden = hidden }
            if let semiHidden = semiHiddenArg { doc.styles[idx].semiHidden = semiHidden }
            doc.markPartDirty("word/styles.xml")
        }

        try await storeDocument(doc, for: docId)
        return "Updated style '\(styleId)'"
    }

    private func deleteStyle(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
