    private func insertPageBreak(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let index = try optionalInt(args, "at_index")
        doc.insertPageBreak(at: index)
        try await storeDocument(doc, for: docId)

        if let index = index {
            return "Inserted page break at position \(index)"
        } else {
            return "Inserted page break at end of document"
        }
    }

    private func insertSectionBreak(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #253: an unrecognized VALUE was already rejected below, but a
        // wrong JSON type (`type: 5`) took `?.stringValue`'s `nil` straight
        // into `?? "nextPage"` — a valid value — so the type error sailed
        // through undetected.
        let typeStr = try Self.optionalStrictEnumString(args, "type", allowed: ["nextPage", "continuous", "evenPage", "oddPage"]) ?? "nextPage"
        guard let breakType = SectionBreakType(rawValue: typeStr) else {
            throw WordError.invalidParameter("type", "Must be 'nextPage', 'continuous', 'evenPage', or 'oddPage'")
        }

        let index = try optionalInt(args, "at_index")
        doc.insertSectionBreak(type: breakType, at: index)
        try await storeDocument(doc, for: docId)

        if let index = index {
            return "Inserted \(breakType.rawValue) section break at position \(index)"
        } else {
            return "Inserted \(breakType.rawValue) section break at end of document"
        }
    }

    // MARK: - Header/Footer

    private func addHeader(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #253: had NO validation at all — a wrong JSON type OR an
        // unrecognized value (a typo like "frist") both silently produced a
        // `.default` header while reporting success. `optionalStrictString`
        // still rejects only the type; the value check (case-insensitive,
        // matching the pre-existing `.lowercased()` comparison so legitimate
        // callers passing "First"/"Default" keep working) is added here.
        let typeStr = try Self.optionalStrictString(args, "type") ?? "default"
        let headerType: HeaderFooterType
        switch typeStr.lowercased() {
        case "first": headerType = .first
        case "even": headerType = .even
        case "default": headerType = .default
        default:
            throw WordError.invalidParameter("type", "必須是 first/even/default 之一，不接受 '\(typeStr)'")
        }

        let header = doc.addHeader(text: text, type: headerType)
        try await storeDocument(doc, for: docId)

        return "Added header with id '\(header.id)' (type: \(headerType.rawValue))"
    }

    private func updateHeader(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let headerId = args["header_id"]?.stringValue else {
            throw WordError.missingParameter("header_id")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        try doc.updateHeader(id: headerId, text: text)
        try await storeDocument(doc, for: docId)

        return "Updated header '\(headerId)'"
    }

    private func addFooter(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #253: same shape as add_header.type above — no validation at all.
        let typeStr = try Self.optionalStrictString(args, "type") ?? "default"
        let footerType: HeaderFooterType
        switch typeStr.lowercased() {
        case "first": footerType = .first
        case "even": footerType = .even
        case "default": footerType = .default
        default:
            throw WordError.invalidParameter("type", "必須是 first/even/default 之一，不接受 '\(typeStr)'")
        }

        let footer: Footer
        if let text = args["text"]?.stringValue {
            footer = doc.addFooter(text: text, type: footerType)
        } else {
            // 沒有提供文字，使用頁碼
            footer = doc.addFooterWithPageNumber(format: .simple, type: footerType)
        }

        try await storeDocument(doc, for: docId)

        return "Added footer with id '\(footer.id)' (type: \(footerType.rawValue))"
    }

    private func updateFooter(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let footerId = args["footer_id"]?.stringValue else {
            throw WordError.missingParameter("footer_id")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        try doc.updateFooter(id: footerId, text: text)
        try await storeDocument(doc, for: docId)

        return "Updated footer '\(footerId)'"
    }

    private func insertPageNumber(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // 解析頁碼格式
        let formatStr = args["format"]?.stringValue ?? "simple"
        let format: PageNumberFormat
        switch formatStr.lowercased() {
        case "simple": format = .simple
        case "pageoftotal": format = .pageOfTotal
        case "withdash": format = .withDash
        default:
            // 自訂格式（包含 # 的字串）
            if formatStr.contains("#") {
                format = .withText(formatStr)
            } else {
                format = .simple
            }
        }

        let footer = doc.addFooterWithPageNumber(format: format, type: .default)
        try await storeDocument(doc, for: docId)

        return "Inserted page number in footer '\(footer.id)' with format '\(formatStr)'"
    }

    // MARK: - Image Operations

    private func insertImage(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let base64 = args["base64"]?.stringValue else {
            throw WordError.missingParameter("base64")
        }
        guard let fileName = args["file_name"]?.stringValue else {
            throw WordError.missingParameter("file_name")
        }
        guard let width = try optionalInt(args, "width") else {
            throw WordError.missingParameter("width")
        }
        guard let height = try optionalInt(args, "height") else {
            throw WordError.missingParameter("height")
        }
        // #234: ooxml-swift's `Drawing.from(widthPx:heightPx:)` does an
        // unguarded `widthPx * 9525`/`heightPx * 9525` (pixels → EMU) — see
        // `imagePixelDimensionRange`'s doc comment for why this is checked
        // here, on this side of the package boundary, and for the
        // ST_PositiveCoordinate derivation of the bound.
        guard Self.imagePixelDimensionRange.contains(width) else {
            throw WordError.invalidParameter(
                "width", "必須介於 \(Self.imagePixelDimensionRange.lowerBound) 到 \(Self.imagePixelDimensionRange.upperBound) 之間（像素）"
            )
        }
        guard Self.imagePixelDimensionRange.contains(height) else {
            throw WordError.invalidParameter(
                "height", "必須介於 \(Self.imagePixelDimensionRange.lowerBound) 到 \(Self.imagePixelDimensionRange.upperBound) 之間（像素）"
            )
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let index = try optionalInt(args, "index")
        let name = args["name"]?.stringValue ?? "Picture"
        let description = args["description"]?.stringValue ?? ""

        let imageId = try doc.insertImage(
            base64: base64,
            fileName: fileName,
            widthPx: width,
            heightPx: height,
            at: index,
            name: name,
            description: description
        )

        try await storeDocument(doc, for: docId)

        return "Inserted image '\(fileName)' with id '\(imageId)' (\(width)x\(height) pixels)"
    }

    /// insert_image_from_path MCP tool — now supports auto-aspect + table-cell insertion.
    ///
    /// BREAKING from previous release:
    /// - `width` and `height` are now OPTIONAL. If exactly one is supplied, the
    ///   missing dimension is computed from the image's native aspect ratio via
    ///   `ImageDimensions.detect`. If both are omitted, native pixel size is used.
    /// - New `into_table_cell: { table_index, row, col }` anchor inserts the
    ///   image as a new paragraph inside the specified table cell.
    /// - Legacy `index` argument still accepted for body-level paragraph insertion.
    private func insertImageFromPath(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let path = args["path"]?.stringValue else {
            throw WordError.missingParameter("path")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // anchor-dx-consistency (#71): reject conflicting anchors BEFORE any IO
        // (filesystem stat / image dimension probe), logging, or anchor-priority
        // derivation. Verify-71 P2 (Devil's Advocate refutation): previously this
        // check sat after fileExists check + resolveImageDimensions(throws) + the
        // entry log write, so a caller passing "bad image path + 2 anchors" would
        // see the file-IO error and never the conflict error — making this tool
        // inconsistent with the other 3 #61-target handlers and violating the
        // bundle's "anchor-dx-consistency" promise.
        // Spec: openspec/changes/anchor-dx-consistency/specs/.../spec.md R1.
        // #80: anchor list resolved from WordMCPServer.toolAnchorWhitelists (SoT).
        let presentAnchors = WordMCPServer.detectPresentAnchors(args, tool: "insert_image_from_path")
        if presentAnchors.count > 1 {
            throw ToolRefusal("insert_image_from_path: received conflicting anchors: \(presentAnchors.joined(separator: " + ")). Specify exactly one.")
        }

        guard FileManager.default.fileExists(atPath: path) else {
            throw WordError.fileNotFound(path)
        }

        // #16: PDF input is rasterized (native PDFKit/CoreGraphics — no
        // external CLI) to a temporary PNG before reaching the exact same
        // `doc.insertImage(path:)` call every other format uses below;
        // downstream code never needs to know the source was a PDF.
        // `page` only makes sense for a PDF source — providing it for a
        // PNG/JPEG path is a caller mistake worth naming rather than
        // silently ignoring.
        let isPDFSource = (path as NSString).pathExtension.lowercased() == "pdf"
        let pageArg = try optionalInt(args, "page")
        if let pageArg, !isPDFSource {
            throw WordError.invalidParameter("page", "只適用於 .pdf 來源；'\(path)' 不是 PDF")
        }
        var effectivePath = path
        var pdfRasterizeTempDir: URL?
        defer { if let pdfRasterizeTempDir { try? FileManager.default.removeItem(at: pdfRasterizeTempDir) } }
        var pdfSourceDescription: String?
        if isPDFSource {
            let page = pageArg ?? 1
            guard page >= 1 else {
                throw WordError.invalidParameter("page", "必須是 1 以上的整數，不接受 \(page)")
            }
            let rasterized = try PDFImageRasterizer.rasterize(pdfPath: path, page: page)
            effectivePath = rasterized.url.path
            pdfRasterizeTempDir = rasterized.url.deletingLastPathComponent()
            pdfSourceDescription = "'\((path as NSString).lastPathComponent)' page \(page) (rasterized to PNG @ \(Int(PDFImageRasterizer.defaultDPI))dpi)"
        }

        // Phase A (#41 investigation): structured entry log.
        // #74: detection priority must mirror dispatch priority below
        // (into_table_cell > after_image_id > after_text > before_text > index).
        let anchorKind: String
        if args["into_table_cell"]?.objectValue != nil { anchorKind = "intoTableCell" }
        else if args["after_image_id"]?.stringValue != nil { anchorKind = "after_image_id" }
        else if args["after_text"]?.stringValue != nil { anchorKind = "after_text" }
        else if args["before_text"]?.stringValue != nil { anchorKind = "before_text" }
        else { anchorKind = "index" }
        let startTime = Date()
        logDebug(event: "insertImageFromPath.entry", [
            ("doc_id", docId),
            ("anchor", anchorKind),
            ("imagePath", (path as NSString).lastPathComponent),
            ("bodyChildrenCount", String(doc.body.children.count)),
            ("imagesCount", String(doc.images.count))
        ])

        // Resolve width/height (auto-aspect)
        let widthArg = try optionalInt(args, "width")
        let heightArg = try optionalInt(args, "height")
        let (width, height) = try resolveImageDimensions(path: effectivePath, width: widthArg, height: heightArg)
        // #234: `resolveImageDimensions`'s `safeInt` guard only protects the
        // AUTO-COMPUTED dimension (when only one of width/height was given)
        // from the aspect-ratio math itself trapping — it does NOT protect
        // `doc.insertImage`'s own `widthPx * 9525`/`heightPx * 9525` further
        // downstream in ooxml-swift, which every path through here reaches
        // regardless of whether width/height came from the user directly,
        // were computed from aspect ratio, or came from the native image
        // file. Validated here, once, after resolution, covering all of
        // those paths uniformly — see `imagePixelDimensionRange`'s doc
        // comment for the ST_PositiveCoordinate-derived bound.
        guard Self.imagePixelDimensionRange.contains(width) else {
            throw WordError.invalidParameter(
                "width", "必須介於 \(Self.imagePixelDimensionRange.lowerBound) 到 \(Self.imagePixelDimensionRange.upperBound) 之間（像素）"
            )
        }
        guard Self.imagePixelDimensionRange.contains(height) else {
            throw WordError.invalidParameter(
                "height", "必須介於 \(Self.imagePixelDimensionRange.lowerBound) 到 \(Self.imagePixelDimensionRange.upperBound) 之間（像素）"
            )
        }

        let name = args["name"]?.stringValue ?? "Picture"
        let description = args["description"]?.stringValue ?? ""

        // Resolve anchor: priority is into_table_cell > after_image_id > after_text > before_text > index
        let imageId: String
        let textInstance = try optionalInt(args, "text_instance") ?? 1
        // anchor-dx-consistency (#72): explicit text_instance < 1 rejected.
        if let explicit = try optionalInt(args, "text_instance"), explicit < 1 {
            throw ToolRefusal("insert_image_from_path: text_instance must be ≥ 1, got \(explicit).")
        }
        // #232 R5: parsed here, unconditionally, rather than inside the last
        // `else` of the anchor-priority dispatch below — a mistyped `index`
        // supplied alongside a HIGHER-priority anchor (e.g. `after_text`)
        // used to never be reached at all.
        let indexArg = try optionalInt(args, "index")
        if let cellDict = args["into_table_cell"]?.objectValue {
            // F5 (v3.15.1): malformed partial dict returns structured error instead of silent fallthrough.
            // #232 R4: each field parsed independently (not chained in one
            // guard) so a wrong-typed field is always caught, even when an
            // earlier field in the dict happens to be absent — a chained
            // `guard let a = ..., let b = ...` short-circuits on the first
            // nil and never evaluates b at all.
            let tableIdxArg = try optionalInt(cellDict, "table_index")
            let rowArg = try optionalInt(cellDict, "row")
            let colArg = try optionalInt(cellDict, "col")
            guard let tableIdx = tableIdxArg, let row = rowArg, let col = colArg else {
                throw ToolRefusal("insert_image_from_path: into_table_cell requires all three fields (table_index, row, col); got partial dict")
            }
            do {
                imageId = try doc.insertImage(
                    path: effectivePath,
                    widthPx: width,
                    heightPx: height,
                    at: .intoTableCell(tableIndex: tableIdx, row: row, col: col),
                    name: name,
                    description: description
                )
            } catch let InsertLocationError.tableIndexOutOfRange(i) {
                throw ToolRefusal("insert_image_from_path: table index \(i) out of range")
            } catch let InsertLocationError.tableCellOutOfRange(t, r, c) {
                throw ToolRefusal("insert_image_from_path: table[\(t)] cell (row: \(r), col: \(c)) out of range")
            }
        } else if let afterImageId = args["after_image_id"]?.stringValue {
            // F1 (v3.15.1): after_image_id anchor.
            do {
                imageId = try doc.insertImage(
                    path: effectivePath,
                    widthPx: width,
                    heightPx: height,
                    at: .afterImageId(afterImageId),
                    name: name,
                    description: description
                )
            } catch let InsertLocationError.imageIdNotFound(rId) {
                throw ToolRefusal("insert_image_from_path: image rId '\(rId)' not found")
            }
        } else if let afterText = args["after_text"]?.stringValue {
            do {
                imageId = try doc.insertImage(
                    path: effectivePath,
                    widthPx: width,
                    heightPx: height,
                    at: .afterText(afterText, instance: textInstance),
                    name: name,
                    description: description
                )
            } catch let InsertLocationError.textNotFound(text, instance) {
                throw ToolRefusal("insert_image_from_path: text '\(text)' not found (instance \(instance))")
            }
        } else if let beforeText = args["before_text"]?.stringValue {
            do {
                imageId = try doc.insertImage(
                    path: effectivePath,
                    widthPx: width,
                    heightPx: height,
                    at: .beforeText(beforeText, instance: textInstance),
                    name: name,
                    description: description
                )
            } catch let InsertLocationError.textNotFound(text, instance) {
                throw ToolRefusal("insert_image_from_path: text '\(text)' not found (instance \(instance))")
            }
        } else {
            // body-level: use legacy index-based API
            let index = indexArg
            imageId = try doc.insertImage(
                path: effectivePath,
                widthPx: width,
                heightPx: height,
                at: index,
                name: name,
                description: description
            )
        }

        try await storeDocument(doc, for: docId)

        // Phase A (#41 investigation): structured exit log.
        let elapsedMs = Int(Date().timeIntervalSince(startTime) * 1000)
        logDebug(event: "insertImageFromPath.exit", [
            ("doc_id", docId),
            ("imageId", imageId),
            ("elapsedMs", String(elapsedMs))
        ])

        if let pdfSourceDescription {
            return "Inserted image \(pdfSourceDescription) with id '\(imageId)' (\(width)x\(height) pixels)"
        }
        let url = URL(fileURLWithPath: path)
        return "Inserted image '\(url.lastPathComponent)' with id '\(imageId)' (\(width)x\(height) pixels)"
    }

    /// Compute (width, height) from user-provided args + image's native aspect.
    /// - Both provided: use as-is.
    /// - Width only: height = width / aspectRatio.
    /// - Height only: width = height * aspectRatio.
    /// - Neither: use native pixel size.
    private func resolveImageDimensions(path: String, width: Int?, height: Int?) throws -> (Int, Int) {
        if let w = width, let h = height {
            return (w, h)
        }
        let native = try ImageDimensions.detect(path: path)
        switch (width, height) {
        case let (.some(w), nil):
            // #234: see `safeInt(fromArithmeticResult:key:)`'s doc comment —
            // naming "width" here since that's the parameter the caller
            // actually supplied and would need to change.
            let h = native.aspectRatio > 0
                ? try Self.derivedImageDimension(Double(w) / native.aspectRatio, derived: "高度", suppliedKey: "width")
                : native.heightPx
            return (w, h)
        case let (nil, .some(h)):
            let w = try Self.derivedImageDimension(Double(h) * native.aspectRatio, derived: "寬度", suppliedKey: "height")
            return (w, h)
        default:
            return (native.widthPx, native.heightPx)
        }
    }

    private func updateImage(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let imageId = args["image_id"]?.stringValue else {
            throw WordError.missingParameter("image_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let width = try optionalInt(args, "width")
        let height = try optionalInt(args, "height")
        // #234: `Document.updateImage` does the same unguarded
        // `widthPx * 9525`/`heightPx * 9525` as `Drawing.from(widthPx:
        // heightPx:)` (ooxml-swift) — see `imagePixelDimensionRange`'s doc
        // comment.
        if let width, !Self.imagePixelDimensionRange.contains(width) {
            throw WordError.invalidParameter(
                "width", "必須介於 \(Self.imagePixelDimensionRange.lowerBound) 到 \(Self.imagePixelDimensionRange.upperBound) 之間（像素）"
            )
        }
        if let height, !Self.imagePixelDimensionRange.contains(height) {
            throw WordError.invalidParameter(
                "height", "必須介於 \(Self.imagePixelDimensionRange.lowerBound) 到 \(Self.imagePixelDimensionRange.upperBound) 之間（像素）"
            )
        }

        try doc.updateImage(imageId: imageId, widthPx: width, heightPx: height)
        try await storeDocument(doc, for: docId)

        var changes: [String] = []
        if let w = width { changes.append("width: \(w)px") }
        if let h = height { changes.append("height: \(h)px") }

        return "Updated image '\(imageId)': \(changes.joined(separator: ", "))"
    }

    private func deleteImage(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let imageId = args["image_id"]?.stringValue else {
            throw WordError.missingParameter("image_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        try doc.deleteImage(imageId: imageId)
        try await storeDocument(doc, for: docId)

        return "Deleted image '\(imageId)'"
    }

    private func listImages(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)
        var rows = Self.collectImageRows(doc)
        // #219 (reopened): chart-part images have no typed representation at
        // all, so they can only be found by reading the actual package
        // bytes. `packageBytesForPartEnumeration` picks the byte source that
        // won't silently drop them (see that function's doc comment).
        //
        // R2 (independent review, real-binary run): `collectImageRows`'s
        // header/footer rows above are the untouched pre-#219 path — they
        // extract only a DISPLAY filename from `rel.target`
        // (`lastPathComponent`), never resolving it through
        // `UntypedPartImages`'s safety check at all. Left alone, an unsafe
        // header/footer Target showed up here as an ordinary row while
        // `export_all_images`/`export_image` (which DO go through that
        // check) silently skipped the very same relationship — a caller
        // reading `list_images` saw nothing alarming. Now: any
        // header/footer row `UntypedPartImages.entries` itself refused is
        // removed from the ordinary listing and folded into the same
        // "refused for security" line chart rows already used.
        var refusedEntries: [UntypedPartImages.RefusedEntry] = []
        if let packageData = packageBytesForPartEnumeration(doc: doc, args: args),
           let tempDir = try? ZipHelper.unzip(data: packageData) {
            defer { ZipHelper.cleanup(tempDir) }
            let (allEntries, refused) = UntypedPartImages.entries(doc: doc, tempDir: tempDir)
            let chartRows: [(part: String, id: String, fileName: String, widthPx: Int?, heightPx: Int?)] = allEntries
                .filter { $0.part.hasPrefix("word/charts/") }
                .map { (part: $0.part, id: $0.id, fileName: $0.fileName, widthPx: nil, heightPx: nil) }
            rows += chartRows
            refusedEntries = refused
            let refusedKeys = Set(refused.map { "\($0.part)|\($0.id)" })
            rows.removeAll { refusedKeys.contains("\($0.part)|\($0.id)") }
        }
        let (report, failureReason, unreferencedMedia) = imageConsistencyInspection(forDoc: doc, args: args)
        var text = Self.imageListing(rows: rows, report: report, inspectionFailureReason: failureReason, unreferencedMediaFiles: unreferencedMedia)
        // Security: a header/footer/chart rels Target that would have
        // escaped the unzipped package (or declares TargetMode="External")
        // is refused, never read — but never silently dropped either. See
        // `UntypedPartImages`'s doc comment.
        if !refusedEntries.isEmpty {
            text += "\n\n⚠ \(refusedEntries.count) image relationship(s) refused for security and NOT listed above (Target escapes the package, or is TargetMode=\"External\"): "
                + refusedEntries.map { "\($0.part):\($0.id) (\($0.reason))" }.joined(separator: ", ")
        }
        return text
    }

    // MARK: - 9.17 export_image - 匯出單一圖片
    //
    // #219 (reopened): `image_id` used to only ever search `doc.images`
    // (the document part). A header/footer/chart-only image was
    // unreachable — "找不到圖片 ID" even for an id `list_images` had just
    // printed. Fallback order: document part (existing, in-memory, no
    // package read needed) → header/footer/chart (package bytes required —
    // see `packageBytesForPartEnumeration`). First match wins; a part-level
    // id collision (rare — different parts each define their own id
    // namespace) is not disambiguated further, same limitation `list_images`
    // already lives with via its `part:` column.
    private func exportImage(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let imageId = args["image_id"]?.stringValue else {
            throw WordError.missingParameter("image_id")
        }
        guard let savePath = args["save_path"]?.stringValue else {
            throw WordError.missingParameter("save_path")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let url = URL(fileURLWithPath: savePath)
        let directory = url.deletingLastPathComponent()
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)

        if let imageRef = doc.images.first(where: { $0.id == imageId }) {
            try imageRef.data.write(to: url)
            let sizeKB = imageRef.data.count / 1024
            return "Saved image \(imageId) to \(savePath) (\(sizeKB)KB)"
        }

        if let packageData = packageBytesForPartEnumeration(doc: doc, args: args),
           let tempDir = try? ZipHelper.unzip(data: packageData) {
            defer { ZipHelper.cleanup(tempDir) }
            let (found, refused) = UntypedPartImages.entries(doc: doc, tempDir: tempDir)
            if let entry = found.first(where: { $0.id == imageId }),
               let data = FileManager.default.contents(atPath: entry.mediaURL.path) {
                try data.write(to: url)
                let sizeKB = data.count / 1024
                return "Saved image \(imageId) to \(savePath) (\(sizeKB)KB) [\(entry.part)]"
            }
            // Security: name a refusal instead of falling through to the
            // generic "not found" below, which would look identical to a
            // truly-absent id and hide WHY nothing was exported.
            if let r = refused.first(where: { $0.id == imageId }) {
                throw ToolRefusal("圖片 ID '\(imageId)' 的關係 Target '\(r.target)' 無法安全解析（\(r.reason)），拒絕匯出")
            }
        }

        throw WordError.parseError("找不到圖片 ID: \(imageId)")
    }

    // MARK: - 9.18 export_all_images - 匯出所有圖片
    //
    // #219 (reopened): only ever exported `doc.images` (the document part).
    // A document with ONLY a header/footer/chart image reported "No images
    // to export" even though `list_images` correctly showed one. Now also
    // walks header/footer (typed relationships) and chart (untyped, parsed
    // from package bytes) images via `UntypedPartImages`.
    //
    // Filename collision handling (explicit #219 requirement): two parts
    // can each declare a relationship targeting a media file with the same
    // base name (own numbering per part, e.g. two independent "image1.png"
    // targets) — writing both into the SAME flat `output_dir` would let the
    // second overwrite the first silently. `writeUnique` renames on
    // collision (`name_2.ext`, `name_3.ext`, …) and the result text says so.
    private func exportAllImages(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let outputDir = args["output_dir"]?.stringValue else {
            throw WordError.missingParameter("output_dir")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let dirURL = URL(fileURLWithPath: outputDir)
        try FileManager.default.createDirectory(at: dirURL, withIntermediateDirectories: true)

        var writtenNames = Set<String>()
        func writeUnique(fileName: String, data: Data) throws -> (name: String, renamed: Bool) {
            var candidate = fileName
            var suffix = 2
            while writtenNames.contains(candidate) {
                let ns = fileName as NSString
                let ext = ns.pathExtension
                let base = ns.deletingPathExtension
                candidate = ext.isEmpty ? "\(base)_\(suffix)" : "\(base)_\(suffix).\(ext)"
                suffix += 1
            }
            writtenNames.insert(candidate)
            try data.write(to: dirURL.appendingPathComponent(candidate))
            return (candidate, candidate != fileName)
        }

        var lines: [String] = []
        var renamedCount = 0

        for imageRef in doc.images {
            let (name, renamed) = try writeUnique(fileName: imageRef.fileName, data: imageRef.data)
            if renamed { renamedCount += 1 }
            let sizeKB = imageRef.data.count / 1024
            let renameNote = renamed ? " [renamed from \(imageRef.fileName) — filename collision across parts]" : ""
            lines.append("  - \(name) (\(sizeKB)KB)\(renameNote)")
        }

        var refusedEntries: [UntypedPartImages.RefusedEntry] = []
        if let packageData = packageBytesForPartEnumeration(doc: doc, args: args),
           let tempDir = try? ZipHelper.unzip(data: packageData) {
            defer { ZipHelper.cleanup(tempDir) }
            let (found, refused) = UntypedPartImages.entries(doc: doc, tempDir: tempDir)
            refusedEntries = refused
            for entry in found {
                guard let data = FileManager.default.contents(atPath: entry.mediaURL.path) else { continue }
                let (name, renamed) = try writeUnique(fileName: entry.fileName, data: data)
                if renamed { renamedCount += 1 }
                let sizeKB = data.count / 1024
                let renameNote = renamed ? " [renamed from \(entry.fileName) — filename collision across parts]" : ""
                lines.append("  - \(name) (\(sizeKB)KB) [\(entry.part)]\(renameNote)")
            }
        }

        guard !lines.isEmpty || !refusedEntries.isEmpty else { return "No images to export" }

        var header = lines.isEmpty ? "Exported 0 image(s) to \(outputDir)" : "Exported \(lines.count) image(s) to \(outputDir)"
        if renamedCount > 0 {
            header += " (\(renamedCount) renamed to avoid filename collisions across parts)"
        }
        var result = header + ":\n" + lines.joined(separator: "\n")
        // Security: a relationship Target that would have escaped the
        // unzipped package (or declares TargetMode="External") is refused,
        // never read — but named here instead of silently absent from the
        // export. See `UntypedPartImages`'s doc comment.
        if !refusedEntries.isEmpty {
            result += "\n⚠ \(refusedEntries.count) image relationship(s) refused for security and NOT exported (Target escapes the package, or is TargetMode=\"External\"): "
                + refusedEntries.map { "\($0.part):\($0.id) (\($0.reason))" }.joined(separator: ", ")
        }
        return result + "\n"
    }

    private func setImageStyle(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let imageId = args["image_id"]?.stringValue else {
            throw WordError.missingParameter("image_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let hasBorder = try optionalBool(args, "has_border")
        let borderColor = args["border_color"]?.stringValue
        let borderWidth = try optionalInt(args, "border_width")
        if let borderWidth {
            _ = try Self.validatedParamRange(borderWidth, "border_width", Self.lineWidthEMURange)
        }
        let hasShadow = try optionalBool(args, "has_shadow")

        try doc.setImageStyle(
            imageId: imageId,
            hasBorder: hasBorder,
            borderColor: borderColor,
            borderWidth: borderWidth,
            hasShadow: hasShadow
        )

        try await storeDocument(doc, for: docId)

        var changes: [String] = []
        if let border = hasBorder { changes.append("border: \(border)") }
        if let color = borderColor { changes.append("color: \(color)") }
        if let width = borderWidth { changes.append("width: \(width)") }
        if let shadow = hasShadow { changes.append("shadow: \(shadow)") }

        return "Updated image style for '\(imageId)': \(changes.joined(separator: ", "))"
    }

    // MARK: - Export

    private func exportText(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let path = args["path"]?.stringValue else {
            throw WordError.missingParameter("path")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let text = doc.getText()
        try text.write(toFile: path, atomically: true, encoding: .utf8)

        return "Exported text to: \(path)"
    }

    private func exportMarkdown(args: [String: Value]) async throws -> String {
        guard let sourcePath = args["source_path"]?.stringValue else {
            throw WordError.missingParameter("source_path")
        }
        guard let outputPath = args["path"]?.stringValue else {
            throw WordError.missingParameter("path")
        }
        guard FileManager.default.fileExists(atPath: sourcePath) else {
            throw WordError.fileNotFound(sourcePath)
        }

        // 檢查 Word lock file
        let sourceURL = URL(fileURLWithPath: sourcePath)
        let lockFile = sourceURL.deletingLastPathComponent()
            .appendingPathComponent("~$" + sourceURL.lastPathComponent)
        if FileManager.default.fileExists(atPath: lockFile.path) {
            throw WordError.invalidFormat("File is open in Microsoft Word. Please save and close it first: \(sourceURL.lastPathComponent)")
        }

        var document = try DocxReader.read(from: sourceURL)
        // R2 (#221 H2, `review-cwm450.md` finding): `export_markdown` is
        // read-only (`source_path` only, no `doc_id`/session persistence)
        // and `wordConverter.convertToString` never touches
        // `document.archiveTempDir` (checked against `word-to-md-swift`'s
        // source) — safe to release the extracted tempDir right here,
        // before conversion, same as #221's `resolveDocument` fix.
        logDebug(event: "exportMarkdown.archiveExtracted", [
            ("archive_temp_dir", document.archiveTempDir?.path ?? "nil"),
        ])
        document.close()

        // 圖片輸出目錄：預設與 .md 同層的 figures/
        let figuresDir: URL
        if let customFigDir = args["figures_directory"]?.stringValue {
            figuresDir = URL(fileURLWithPath: customFigDir)
        } else {
            figuresDir = URL(fileURLWithPath: outputPath)
                .deletingLastPathComponent()
                .appendingPathComponent("figures")
        }

        // 建立轉換選項（預設 Tier 2：Markdown + 圖片提取）
        let options = ConversionOptions(
            includeFrontmatter: try optionalBool(args, "include_frontmatter") ?? false,
            hardLineBreaks: try optionalBool(args, "hard_line_breaks") ?? false,
            fidelity: .markdownWithFigures,
            figuresDirectory: figuresDir
        )

        // 轉換為 Markdown
        let markdown = try wordConverter.convertToString(document: document, options: options)

        // 寫入檔案
        try markdown.write(toFile: outputPath, atomically: true, encoding: .utf8)
        let figCount = (try? FileManager.default.contentsOfDirectory(atPath: figuresDir.path))?.count ?? 0
        if figCount > 0 {
            return "Exported Markdown to: \(outputPath) (\(figCount) figures in \(figuresDir.path))"
        }
        return "Exported Markdown to: \(outputPath)"
    }

