            throw WordError.missingParameter("paragraph_index")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }

        let endnoteId = try doc.insertEndnote(text: text, paragraphIndex: paragraphIndex)
        try await storeDocument(doc, for: docId)
        return "Inserted endnote \(endnoteId) at paragraph \(paragraphIndex)"
    }

    private func deleteEndnote(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let endnoteId = try optionalInt(args, "endnote_id") else {
            throw WordError.missingParameter("endnote_id")
        }

        try doc.deleteEndnote(endnoteId: endnoteId)
        try await storeDocument(doc, for: docId)
        return "Deleted endnote \(endnoteId)"
    }

    // MARK: - Advanced Features (P7)

    private func insertTOC(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let index = try optionalInt(args, "index")
        let title = args["title"]?.stringValue
        let minLevelArg = try optionalInt(args, "min_level")
        let maxLevelArg = try optionalInt(args, "max_level")
        let minLevel = minLevelArg ?? 1
        let maxLevel = maxLevelArg ?? 3
        // R8 (independent fuzzer, `rev232b` M-234-5): `minLevel...maxLevel`
        // traps (`Range requires lowerBound <= upperBound`) whenever
        // `min_level > max_level`. Word supports exactly 9 built-in heading
        // levels (Heading 1 through Heading 9), so `1...9` is the full
        // legal span regardless of ordering; the ordering itself is
        // enforced by rejecting `minLevel > maxLevel` outright rather than
        // silently swapping the two, since a caller that got the order
        // backwards likely made a mistake worth surfacing.
        // R9 (review `rev232c` LOW-1): name the parameter that is actually
        // out of range, and say where a defaulted value came from.
        guard (1...9).contains(minLevel) else {
            throw WordError.invalidParameter("min_level", "必須介於 1 到 9 之間")
        }
        guard (1...9).contains(maxLevel) else {
            throw WordError.invalidParameter("max_level", "必須介於 1 到 9 之間")
        }
        guard minLevel <= maxLevel else {
            let minNote = minLevelArg == nil ? "（未提供，預設 1）" : ""
            let maxNote = maxLevelArg == nil ? "（未提供，預設 3）" : ""
            throw WordError.invalidParameter(
                "min_level", "min_level \(minLevel)\(minNote) 不可大於 max_level \(maxLevel)\(maxNote)"
            )
        }
        let includePageNumbers = try optionalBool(args, "include_page_numbers") ?? true
        let useHyperlinks = try optionalBool(args, "use_hyperlinks") ?? true

        doc.insertTableOfContents(
            at: index,
            title: title,
            headingLevels: minLevel...maxLevel,
            includePageNumbers: includePageNumbers,
            useHyperlinks: useHyperlinks
        )
        try await storeDocument(doc, for: docId)

        return "Inserted table of contents (heading levels \(minLevel)-\(maxLevel))"
    }

    private func insertTextField(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let name = args["name"]?.stringValue else {
            throw WordError.missingParameter("name")
        }

        let defaultValue = args["default_value"]?.stringValue
        let maxLength = try optionalInt(args, "max_length")

        try doc.insertTextField(at: paragraphIndex, name: name, defaultValue: defaultValue, maxLength: maxLength)
        try await storeDocument(doc, for: docId)

        return "Inserted text field '\(name)' at paragraph \(paragraphIndex)"
    }

    private func insertCheckbox(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let name = args["name"]?.stringValue else {
            throw WordError.missingParameter("name")
        }

        // #232: this used to read "is_checked", a key the schema never
        // declared (it declares "checked") — every caller's checked value,
        // of any type, was silently ignored and the checkbox always
        // inserted unchecked.
        let isChecked = try optionalBool(args, "checked") ?? false

        try doc.insertCheckbox(at: paragraphIndex, name: name, isChecked: isChecked)
        try await storeDocument(doc, for: docId)

        return "Inserted checkbox '\(name)' (checked: \(isChecked)) at paragraph \(paragraphIndex)"
    }

    private func insertDropdown(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let name = args["name"]?.stringValue else {
            throw WordError.missingParameter("name")
        }
        guard let optionsValue = args["options"] else {
            throw WordError.missingParameter("options")
        }

        // 解析 options array
        var options: [String] = []
        if case .array(let arr) = optionsValue {
            for item in arr {
                if let str = item.stringValue {
                    options.append(str)
                }
            }
        }

        if options.isEmpty {
            throw WordError.missingParameter("options (array of strings)")
        }

        let selectedIndex = try optionalInt(args, "selected_index") ?? 0

        try doc.insertDropdown(at: paragraphIndex, name: name, options: options, selectedIndex: selectedIndex)
        try await storeDocument(doc, for: docId)

        return "Inserted dropdown '\(name)' with \(options.count) options at paragraph \(paragraphIndex)"
    }

    /// insert_equation MCP tool — emits structurally correct OMML.
    ///
    /// Two input paths:
    /// - `components:` argument — JSON tree with `type` discriminator. Primary
    ///   path for callers needing fine control.
    /// - `latex:` argument — LaTeX subset delegated to `LaTeXMathSwift.LaTeXMathParser`.
    ///   Supports `\frac`, `\sqrt`, `\hat`, `\bar`, `\tilde`, `\left/\right`,
    ///   `\sum`/`\int`/`\prod` with bounds, `\ln`/`\sin`/`\cos`/etc.,
    ///   `\sup`/`\inf`/`\lim`, `\text{}`, all Greek letters (lowercase /
    ///   uppercase / variants), and common operators. Anything else returns
    ///   an error naming the unrecognized token. See latex-math-swift README
    ///   for the canonical macro list.
    ///
    /// MCP defaults `display_mode` to true because agent callers normally want
    /// block equations. That intentionally differs from the lower-level
    /// OOXMLSwift lib default, which preserves inline behavior for direct API
    /// callers.
    private func insertEquation(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #98 v2 (post-verify): both `latex` and `components` paths feed into
        // the same `[MathComponent]` AST and use handler-side OMML build via
        // `MathComponent.toOMML()`. Lib's `Document.insertEquation` overload
        // internally uses deprecated flat `MathEquation` (Field.swift:301)
        // which produces broken plain-text OOXML — see Insert step below for
        // full rationale. Path origin is preserved in error messages but the
        // insertion mechanic is unified.
        // #122 / #125 (R2 revision — see #232's design comment above
        // `optionalInt`/`optionalBool` for the principle this now follows):
        // presence is "key exists and is not JSON null" — NOT "key exists
        // and happens to decode to the expected type". Those are two
        // different questions with two different answers:
        //   (a) absent-or-null  → this side simply wasn't provided; try the
        //       other side, or fall through to "either ... required".
        //   (b) present-but-wrong-type → the caller DID provide this side,
        //       just with the wrong JSON shape. That must throw a named,
        //       value-echoing error (same #129 `formatReceivedValue`
        //       convention as everywhere else in this function) — it must
        //       NEVER be silently treated as "not provided", because that
        //       either (i) produces a false "you gave neither" message when
        //       the caller plainly gave one, or (ii) silently drops the
        //       malformed side and proceeds on the other, which is even
        //       worse when both were given (see R1's `[1,2,3]` + real
        //       `latex` regression: R1's `.objectValue != nil` check made
        //       the array-typed `components` invisible to the conflict
        //       check, so it silently lost and the call "succeeded" using
        //       only `latex`).
        //
        // R1 used `.objectValue != nil` / `.stringValue != nil` as the
        // presence test itself, which conflates (a) and (b) exactly the way
        // the `optionalInt`/`optionalBool` comment describes as the original
        // #232 bug: "a wrong JSON type... OR a JSON null OR an absent key
        // all fall through to nil identically". This revision separates
        // them: `componentsRaw`/`latexRaw` capture "present and non-null"
        // (mirrors `display_mode`'s existing `!= .null` pattern below), and
        // each branch below validates ITS OWN type and throws its own named
        // error rather than falling through.
        //
        // (#122 was filed under a title copied from a different issue in
        // this batch — its actual body is this exact null-sentinel problem,
        // and it is the same fix as #125's `latex` half; both are closed by
        // this change, together with the R1 regression flagged in review.)
        let componentsRaw: Value? = {
            if let v = args["components"], v != .null { return v }
            return nil
        }()
        let latexRaw: Value? = {
            if let v = args["latex"], v != .null { return v }
            return nil
        }()
        let componentsPresent = componentsRaw != nil
        let latexPresent = latexRaw != nil
        if componentsPresent && latexPresent,
           let componentsValue = componentsRaw, let latexValue = latexRaw {
            throw ToolRefusal("insert_equation: pass either 'components' (JSON tree) OR 'latex' (LaTeX subset), not both (received components: \(WordMCPServer.formatReceivedValue(componentsValue)), latex: \(WordMCPServer.formatReceivedValue(latexValue)))")
        }

        let components: [MathComponent]
        if componentsPresent, let componentsValue = componentsRaw {
            // Type check happens HERE, named and value-echoing, before
            // parsing — not left to `parseMathComponent`'s generic nested-
            // component message (that message is still correct for a
            // non-object found *inside* a components tree, e.g. a bad
            // `numerator[]` entry; this guard is specifically for the
            // top-level `components:` argument itself).
            guard componentsValue.objectValue != nil else {
                throw ToolRefusal("insert_equation: components must be a JSON object (received \(WordMCPServer.formatReceivedValue(componentsValue)))")
            }
            do {
                components = [try parseMathComponent(from: componentsValue)]
            } catch MathParseError.unknownType(let t) {
                throw ToolRefusal("insert_equation: unknown math component type '\(t)'. Supported: run, fraction, radical, subSuperScript, nary.")
            } catch MathParseError.missingField(let f, let t) {
                throw ToolRefusal("insert_equation: math component '\(t)' missing required field '\(f)'")
            } catch MathParseError.invalidStructure(let msg) {
                throw ToolRefusal("insert_equation: invalid components structure: \(msg)")
            }
        } else if latexPresent, let latexValue = latexRaw {
            guard let latex = latexValue.stringValue else {
                throw ToolRefusal("insert_equation: latex must be a string (received \(WordMCPServer.formatReceivedValue(latexValue)))")
            }
            do {
                components = try parseLatex(latex)
            } catch LaTeXParseError.unrecognizedToken(let tok) {
                throw ToolRefusal("insert_equation: unrecognized LaTeX token '\(tok)'. Use `components:` argument for full MathComponent control.")
            } catch LaTeXParseError.malformed(let msg) {
                throw ToolRefusal("insert_equation: malformed LaTeX: \(msg). Use `components:` for complex expressions.")
            } catch LaTeXParseError.empty {
                throw ToolRefusal("insert_equation: empty LaTeX input.")
            }
        } else {
            throw ToolRefusal("insert_equation: either 'components' (JSON tree) or 'latex' (LaTeX subset) argument required")
        }

        // Not folded into `optionalBool` (#232): Issue98InsertEquationLibBypassTests
        // pins an error message that names both "display_mode" and (English)
        // "boolean" — `optionalBool`'s message is in Chinese, matching this
        // file's other invalidParameter messages, and changing that core
        // wording is still out of scope here. #129 only appends the
        // *received* value as a parenthetical suffix: the pinned test only
        // asserts `.contains("display_mode")` and `.contains("boolean")`
        // case-insensitively, so text appended after the pinned sentence
        // does not break it. Same "present-but-mistyped errors" contract
        // either way.
        let displayMode: Bool
        if let displayModeValue = args["display_mode"], displayModeValue != .null {
            guard let bool = displayModeValue.boolValue else {
                throw ToolRefusal("insert_equation: display_mode must be a boolean true/false, not a string or other JSON type (received \(WordMCPServer.formatReceivedValue(displayModeValue)))")
            }
            displayMode = bool
        } else {
            // #232 R1: explicit JSON null now counts as absent here too,
            // matching optionalBool's contract everywhere else in this file
            // — it used to fall into the guard above and throw.
            displayMode = true
        }
        let paragraphIndex = try optionalInt(args, "paragraph_index")
        let afterText = args["after_text"]?.stringValue
        let beforeText = args["before_text"]?.stringValue
        let afterImageId = args["after_image_id"]?.stringValue          // v3.15.1
        let intoTableCellDict = args["into_table_cell"]?.objectValue    // v3.15.1
        let textInstance = try optionalInt(args, "text_instance") ?? 1
        // anchor-dx-consistency (#72): explicit text_instance < 1 rejected.
        if let explicit = try optionalInt(args, "text_instance"), explicit < 1 {
            throw ToolRefusal("insert_equation: text_instance must be ≥ 1, got \(explicit).")
        }

        // Anchors only meaningful in display mode (block-level new paragraph).
        // Inline mode appends an OMML run into an existing paragraph; anchor
        // semantics are ambiguous — reject explicitly to surface the misuse.
        if !displayMode && (afterText != nil || beforeText != nil
                            || afterImageId != nil || intoTableCellDict != nil) {
            throw ToolRefusal("insert_equation: anchor parameters (after_text / before_text / after_image_id / into_table_cell) only supported when display_mode=true (inline equations append to an existing paragraph; use paragraph_index instead)")
        }

        // #98: inline mode requires explicit `paragraph_index`. Pre-fix handler
        // silently fell back to `body.children.count` (= invalid index) and
        // either silent-clamped via the Int overload OR (post-#98 lib path)
        // would surface as `invalidParagraphIndex(N)`. Explicit pre-check yields
        // a more actionable error than the index-out-of-range message.
        if !displayMode && paragraphIndex == nil {
            throw ToolRefusal("insert_equation: inline mode (display_mode=false) requires paragraph_index anchor (inline equations append OMML run to existing paragraph)")
        }

        // anchor-dx-consistency (#71): reject conflicting anchors in display mode.
        // Spec R1 — display mode anchor set: into_table_cell / after_image_id /
        // after_text / before_text / paragraph_index. Inline mode handled by the
        // pre-existing rejection above (only paragraph_index allowed).
        if displayMode {
            // #80: anchor list resolved from WordMCPServer.toolAnchorWhitelists (SoT).
            let presentAnchors = WordMCPServer.detectPresentAnchors(args, tool: "insert_equation")
            if presentAnchors.count > 1 {
                throw ToolRefusal("insert_equation: received conflicting anchors: \(presentAnchors.joined(separator: " + ")). Specify exactly one.")
            }
        }

        // Resolve anchor → InsertLocation + anchorInfo. Anchor priority
        // (display mode): into_table_cell > after_image_id > after_text >
        // before_text > paragraph_index > append.
        let location: InsertLocation
        let anchorInfo: String
        if displayMode, let cellDict = intoTableCellDict {
            // F5 (v3.15.1): malformed partial dict returns structured error.
            // #232 R4: each field parsed independently (not chained in one
            // guard) so a wrong-typed field is always caught, even when an
            // earlier field in the dict happens to be absent — a chained
            // `guard let a = ..., let b = ...` short-circuits on the first
            // nil and never evaluates b at all.
            let tableIdxArg = try optionalInt(cellDict, "table_index")
            let rowArg = try optionalInt(cellDict, "row")
            let colArg = try optionalInt(cellDict, "col")
            guard let tableIdx = tableIdxArg, let row = rowArg, let col = colArg else {
                throw ToolRefusal("insert_equation: into_table_cell requires all three fields (table_index, row, col); got partial dict")
            }
            location = .intoTableCell(tableIndex: tableIdx, row: row, col: col)
            anchorInfo = "into table[\(tableIdx)] cell (row: \(row), col: \(col))"
        } else if displayMode, let afterImageId = afterImageId {
            location = .afterImageId(afterImageId)
            anchorInfo = "after image '\(afterImageId)'"
        } else if displayMode, let afterText = afterText {
            location = .afterText(afterText, instance: textInstance)
            anchorInfo = "after text '\(afterText)' (instance \(textInstance))"
        } else if displayMode, let beforeText = beforeText {
            location = .beforeText(beforeText, instance: textInstance)
            anchorInfo = "before text '\(beforeText)' (instance \(textInstance))"
        } else {
            // Display mode with no explicit anchor appends at end by passing
            // body.children.count. The throwing lib insert accepts idx == count
            // as append-at-end, while larger indices still return out-of-range.
            let insertIdx = paragraphIndex ?? doc.body.children.count
            location = .paragraphIndex(insertIdx)
            anchorInfo = "at index \(insertIdx)"
        }

        // #98 v2 (post-verify): both paths use MathComponent.toOMML() for
        // structurally correct OMML. The lib's `Document.insertEquation(at:
        // InsertLocation, latex:, displayMode:)` overload internally uses
        // `MathEquation(latex:).toXML()` which is `@available(*, deprecated, ...)`
        // flat output (Field.swift:301): emits `<m:r><m:t>processed_string</m:t></m:r>`
        // (e.g., `\frac{a}{b}` → `(a)/(b)` plain text), and worse, wraps in
        // `<w:p>` for displayMode causing nested `<w:p><w:p>` invalid OOXML
        // when used inside a Paragraph context. Codex verify (#98 6-AI ensemble)
        // flagged this as P1 regression.
        //
        // Resolution: handler builds OMML via MathComponent AST for both paths;
        // borrows lib's bounds-check via throwing `insertParagraph(_:at: InsertLocation)`
        // (display mode) and replicates lib's bounds-check pattern for inline mode
        // (handler-side append, since lib has no structured-OMML inline-append API).
        let xmlns = "xmlns:m=\"http://schemas.openxmlformats.org/officeDocument/2006/math\""
        let inner = components.map { $0.toOMML() }.joined()
        let ommlXML = displayMode
            ? "<m:oMathPara \(xmlns)><m:oMath>\(inner)</m:oMath></m:oMathPara>"
            : "<m:oMath \(xmlns)>\(inner)</m:oMath>"

        do {
            if displayMode {
                // Display mode: build new paragraph carrying the OMML, insert
                // via lib's throwing InsertLocation overload (centralized
                // bounds-check + structured errors).
                var eqRun = Run(text: "")
                eqRun.rawXML = ommlXML
                // Match lib's #85 BLOCKING #2 pattern: set both rawXML fields so
                // the post-cluster #99-#103 flatten walker sees this freshly-
                // inserted equation before the next save→reload cycle.
                eqRun.properties.rawXML = ommlXML
                var eqPara = Paragraph(runs: [eqRun])
                // Match lib's display-mode convention (Document.swift:4025):
                // display equations are centered. v2 verify Codex sanity-check
                // P2 finding — without this, latex display equations regressed
                // from centered (lib delegate convention) to left-aligned.
                eqPara.properties.alignment = .center
                try doc.insertParagraph(eqPara, at: location)
            } else {
                // Inline mode: append OMML run to existing paragraph at
                // `paragraph_index`. The pre-check above already rejected
                // inline + nil paragraph_index, so this is unreachable with a
                // nil `paragraphIndex` today.
                //
                // #127: kept as a thrown error instead of `paragraphIndex!`.
                // A force-unwrap panics the whole MCP server *process* (a
                // crash, not an error return) — every other open session goes
                // down with it — if a future refactor of the anchor-
                // resolution block above ever lets inline mode reach this
                // branch with a nil index. This guard costs one branch and
                // turns that failure mode into a structured per-call error
                // instead.
                guard let idx = paragraphIndex else {
                    throw ToolRefusal("insert_equation: internal error — inline mode reached without paragraph_index (this should be unreachable; please report it as a che-word-mcp bug)")
                }
                // Bounds check matches lib's pattern at Document.swift:3990-3997
                // (#91 Defect 2): count only top-level `.paragraph` body
                // children, NOT recursing into block-level SDTs.
                let topLevelParaCount = doc.body.children.reduce(0) { count, child in
                    if case .paragraph = child { return count + 1 }
                    return count
                }
                guard idx >= 0, idx < topLevelParaCount else {
                    throw InsertLocationError.invalidParagraphIndex(idx)
                }
                // Walk top-level paragraphs, find target, append OMML run.
                var paraCounter = 0
                for (i, child) in doc.body.children.enumerated() {
                    guard case .paragraph(var para) = child else { continue }
                    if paraCounter == idx {
                        var eqRun = Run(text: "")
                        eqRun.rawXML = ommlXML
                        eqRun.properties.rawXML = ommlXML
                        para.runs.append(eqRun)
                        doc.body.children[i] = .paragraph(para)
                        doc.markPartDirty("word/document.xml")
                        break
                    }
                    paraCounter += 1
                }
            }
        } catch let InsertLocationError.tableIndexOutOfRange(i) {
            throw ToolRefusal("insert_equation: table index \(i) out of range")
        } catch let InsertLocationError.tableCellOutOfRange(t, r, c) {
            throw ToolRefusal("insert_equation: table[\(t)] cell (row: \(r), col: \(c)) out of range")
        } catch let InsertLocationError.imageIdNotFound(rId) {
            throw ToolRefusal("insert_equation: image rId '\(rId)' not found")
        } catch let InsertLocationError.textNotFound(searchText, instance) {
            throw ToolRefusal("insert_equation: text '\(searchText)' not found (instance \(instance))")
        } catch let InsertLocationError.invalidParagraphIndex(idx) {
            throw ToolRefusal("insert_equation: paragraph_index \(idx) out of range")
        }

        try await storeDocument(doc, for: docId)

        return "Inserted equation (display mode: \(displayMode), \(anchorInfo))"
    }

    // MARK: - splice_omath_from_source / splice_paragraph_omath_from_source (#273)

    /// Resolve source paragraph from either source_path (Direct mode, read-only)
    /// or source_doc_id (already-open doc). Returns the Paragraph.
    private func resolveSourceParagraph(args: [String: Value]) async throws -> Paragraph {
        guard let sourceParaIdx = try optionalInt(args, "source_paragraph_index") else {
            throw WordError.missingParameter("source_paragraph_index")
        }
        var sourceDoc: WordDocument
        // R2 (#221 H2, `review-cwm450.md` finding): only a `source_path`
        // read creates a NEW extracted archive this function owns and must
        // release. `source_doc_id`'s `sourceDoc = opened` is a COPY of an
        // ALREADY-OPEN session document — closing it here would be wrong:
        // ooxml-swift's `PreservedArchive` is a class (reference type), so
        // every copy of that `WordDocument` shares the SAME underlying
        // tempDir-cleanup state (see `removeSession`'s comment on the same
        // mechanism). Calling `.close()` on this copy would delete the
        // ACTIVE session's tempDir out from under it. Only the
        // `source_path` branch's OWN, exclusively-held copy may be closed.
        var isTemporary = false
        if let sourcePath = args["source_path"]?.stringValue {
            guard FileManager.default.fileExists(atPath: sourcePath) else {
                throw WordError.fileNotFound(sourcePath)
            }
            sourceDoc = try DocxReader.read(from: URL(fileURLWithPath: sourcePath))
            isTemporary = true
            logDebug(event: "resolveSourceParagraph.archiveExtracted", [
                ("archive_temp_dir", sourceDoc.archiveTempDir?.path ?? "nil"),
            ])
        } else if let sourceDocId = args["source_doc_id"]?.stringValue {
            guard let opened = openDocuments[sourceDocId] else {
                throw WordError.documentNotFound(sourceDocId)
            }
            sourceDoc = opened
        } else {
            throw WordError.missingParameter("source_path or source_doc_id")
        }
        defer { if isTemporary { sourceDoc.close() } }

        // Body-paragraph index (counts only `.paragraph` body children)
        var paraCounter = 0
        for child in sourceDoc.body.children {
            if case .paragraph(let p) = child {
                if paraCounter == sourceParaIdx { return p }
                paraCounter += 1
            }
        }
        throw WordError.invalidFormat("source_paragraph_index \(sourceParaIdx) out of range (only \(paraCounter) body paragraphs in source)")
    }

    /// #253: replaces the old `parseRpRMode(_ s: String?)` /
    /// `parseNamespacePolicy(_ s: String?)`, which took an already-lossy
    /// `String?` (produced by `args[key]?.stringValue`, which silently turns
    /// any non-string JSON value into `nil`) and had NO `default:` rejection
    /// path at all — a wrong type (`rpr_mode: 5`) and an unrecognized value
    /// (`rpr_mode: "bogus"`) were both read identically to "omitted",
    /// reporting success while silently splicing with a different rPr
    /// policy than the caller asked for. These take `args` directly so the
    /// type check happens before the value is ever collapsed to `String?`.
    private func strictRpRMode(_ args: [String: Value]) throws -> OMathSpliceRpRMode {
        switch try Self.optionalStrictEnumString(args, "rpr_mode", allowed: ["full", "omathOnly", "discard"]) {
        case "omathOnly": return .omathOnly
        case "discard": return .discard
        default: return .full // nil (omitted) or "full"
        }
    }

    private func strictNamespacePolicy(_ args: [String: Value]) throws -> OMathSpliceNamespacePolicy {
        try Self.optionalStrictEnumString(args, "namespace_policy", allowed: ["lenient", "strict"]) == "strict" ? .strict : .lenient
    }

    private func formatSpliceError(_ err: OMathSpliceError, tool: String) -> String {
        switch err {
        case .sourceHasNoOMath:
            return "\(tool): source paragraph contains no OMath blocks"
        case .omathIndexOutOfRange(let req, let avail):
            return "\(tool): omath_index \(req) out of range (source has \(avail) OMath block\(avail == 1 ? "" : "s"))"
        case .targetParagraphOutOfRange(let idx):
            return "\(tool): target_paragraph_index \(idx) out of range"
        case .anchorNotFound(let anchor, let instance):
            return "\(tool): anchor '\(anchor)' not found in target paragraph (instance \(instance))"
        case .namespaceMismatch(let src, let tgt):
            return "\(tool): namespace mismatch — source URI '\(src)' vs target URI '\(tgt)'"
        case .contextAnchorNotFound(let i, let snippet):
            return "\(tool): context anchor not found for omath_index=\(i), snippet='\(snippet)' (reviewer edit may have changed surrounding prose)"
        }
    }

    private func spliceOMathFromSource(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var target = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let targetParaIdx = try optionalInt(args, "target_paragraph_index") else {
            throw WordError.missingParameter("target_paragraph_index")
        }
        guard let positionRaw = args["position"]?.stringValue else {
            throw WordError.missingParameter("position")
        }
        // #253: validate BEFORE `resolveSourceParagraph` (which reads a
        // source file / open document) — the same "reject cheap parameter
        // mistakes before doing real work" ordering `insert_caption` already
        // documents for its own anchor parsing. Previously `rpr_mode` /
        // `namespace_policy` were parsed AFTER source resolution, via
        // `parseRpRMode`/`parseNamespacePolicy`, which had no rejection path
        // for either a wrong JSON type or an unrecognized value at all.
        let rPrMode = try strictRpRMode(args)
        let nsPolicy = try strictNamespacePolicy(args)

        let sourcePara = try await resolveSourceParagraph(args: args)

        // Build OMathSplicePosition.
        let position: OMathSplicePosition
        let instance = try optionalInt(args, "instance") ?? 1
        if instance < 1 {
            throw ToolRefusal("splice_omath_from_source: instance must be ≥ 1, got \(instance)")
        }
        switch positionRaw {
        case "atStart":
            position = .atStart
        case "atEnd":
            position = .atEnd
        case "afterText":
            guard let anchor = args["anchor"]?.stringValue, !anchor.isEmpty else {
                throw ToolRefusal("splice_omath_from_source: position='afterText' requires non-empty 'anchor' argument")
            }
            position = .afterText(anchor, instance: instance)
        case "beforeText":
            guard let anchor = args["anchor"]?.stringValue, !anchor.isEmpty else {
                throw ToolRefusal("splice_omath_from_source: position='beforeText' requires non-empty 'anchor' argument")
            }
            position = .beforeText(anchor, instance: instance)
        default:
            throw ToolRefusal("splice_omath_from_source: position must be one of 'atStart' / 'atEnd' / 'afterText' / 'beforeText', got '\(positionRaw)'")
        }

        let omathIndex = try optionalInt(args, "omath_index") ?? 0

        do {
            let n = try target.spliceOMath(
                from: sourcePara,
                toBodyParagraphIndex: targetParaIdx,
                position: position,
                omathIndex: omathIndex,
                rPrMode: rPrMode,
                namespacePolicy: nsPolicy
            )
            try await storeDocument(target, for: docId)
            return "Spliced \(n) OMath block (omath_index=\(omathIndex), position=\(positionRaw), rpr_mode=\(args["rpr_mode"]?.stringValue ?? "full"), namespace_policy=\(args["namespace_policy"]?.stringValue ?? "lenient"))"
        } catch let err as OMathSpliceError {
            throw ToolRefusal(formatSpliceError(err, tool: "splice_omath_from_source"))
        }
    }

    private func spliceParagraphOMathFromSource(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var target = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let targetParaIdx = try optionalInt(args, "target_paragraph_index") else {
            throw WordError.missingParameter("target_paragraph_index")
        }

        // #215 (comment): `WordDocument.spliceParagraphOMath` returns `0`
        // (a graceful no-op, by design, for batch driver loops — see
        // ooxml-swift's WordDocument+SpliceOMath.swift) when the source
        // paragraph has no OMath at all, WITHOUT ever validating
        // `target_paragraph_index` — that bound is only checked inside the
        // per-OMath `spliceOMath` call, which the 0-OMath path never
        // reaches. So an out-of-range index used to sail through silently
        // as long as the source also happened to have no OMath. Validate
        // the same bound here ourselves (top-level `.paragraph` body
        // children only, matching `bodyParagraphIndices` exactly) so it is
        // always enforced, not just on the path that reaches the library.
        let targetParagraphCount = target.body.children.reduce(into: 0) { count, child in
            if case .paragraph = child { count += 1 }
        }
        guard targetParaIdx >= 0 && targetParaIdx < targetParagraphCount else {
            throw ToolRefusal("splice_paragraph_omath_from_source: target_paragraph_index \(targetParaIdx) out of range (document has \(targetParagraphCount) body paragraph(s))")
        }

        // #253: validated before `resolveSourceParagraph` — see
        // `spliceOMathFromSource`'s identical comment above.
        let rPrMode = try strictRpRMode(args)
        let nsPolicy = try strictNamespacePolicy(args)

        let sourcePara = try await resolveSourceParagraph(args: args)

        do {
            let n = try target.spliceParagraphOMath(
                from: sourcePara,
                toBodyParagraphIndex: targetParaIdx,
                rPrMode: rPrMode,
                namespacePolicy: nsPolicy
            )
            // #215: `n == 0` means the source paragraph had no OMath to
            // splice — the document was not touched. Refuse instead of
            // storeDocument()-ing an unchanged document and reporting
            // "Spliced 0 OMath block(s)" as if that were success.
            guard n > 0 else {
                throw ToolRefusal("splice_paragraph_omath_from_source: source paragraph has no OMath block to splice")
            }
            try await storeDocument(target, for: docId)
            return "Spliced \(n) OMath block(s) into target_paragraph_index=\(targetParaIdx) (rpr_mode=\(args["rpr_mode"]?.stringValue ?? "full"), namespace_policy=\(args["namespace_policy"]?.stringValue ?? "lenient"))"
        } catch let err as OMathSpliceError {
            throw ToolRefusal(formatSpliceError(err, tool: "splice_paragraph_omath_from_source"))
        }
    }

    // MARK: - Math parsers (insert_equation helpers)

    private enum MathParseError: Error {
        case unknownType(String)
        case missingField(field: String, forType: String)
        case invalidStructure(String)
    }

    /// #116/#117 — `parseMathComponent` recurses into `numerator`/
    /// `denominator`/`radicand`/`base`/`sub`/`sup` with no depth counter.
    /// The `components` argument is caller-supplied JSON, not hand-typed
    /// LaTeX — a fuzzer or an AI-agent caller can trivially construct a
    /// tree thousands of levels deep, and each recursive call consumes a
    /// non-trivial slice of the Swift call stack.
    ///
    /// **R2 correction (`review-cwm450.md` C1/M2) — read before touching
    /// this number.** The original R1 comment here claimed this guard,
    /// alone, prevents the server process from crashing on a deep
    /// `components` tree, with "two orders of magnitude" of stack margin.
    /// An independent review proved that false with a real release binary
    /// over real stdio: the actual crash is in `swift-sdk`'s own JSON
    /// decode/re-encode of the raw message, which runs BEFORE this guard
    /// (before any che-word-mcp handler code at all), and is reachable via
    /// ANY tool call, not just `insert_equation`. This guard only ever sees
    /// a `Value` tree that already survived that decode — it cannot, by
    /// itself, stop the crash the issue described. The actual guard against
    /// that crash is `DepthLimitedTransport` (see its own doc comment and
    /// `WordMCPServer.transportMaxRawJSONDepth`'s doc comment for the
    /// measured crash threshold), which rejects the raw bytes before
    /// swift-sdk's decoder ever runs.
    ///
    /// So what IS this guard still for? Two things, both true independent
    /// of the transport-layer fix above:
    /// - It is the more SPECIFIC of the two errors — `"components tree
    ///   exceeds max nesting depth 24"` names the actual problem, versus
    ///   the transport layer's generic `"JSON nesting depth N exceeds
    ///   server limit 64"`. A caller who ONLY sees the transport error has
    ///   no idea `insert_equation` was involved at all.
    /// - It still protects `parseMathComponent`'s own recursion as a
    ///   defense in depth, in case `insertEquation` is ever reached through
    ///   a path other than the JSON-RPC transport (e.g. a future direct
    ///   Swift API, or a test harness that constructs a `Value` tree
    ///   in-process — see `Issue116ParseMathComponentDepthCapTests`, which
    ///   does exactly that and therefore exercises THIS guard specifically,
    ///   not the transport one).
    ///
    /// **24, not the R1 value of 64 — measured, not assumed.** The two caps
    /// are in different units: this one counts logical `MathComponent`
    /// tree levels; `transportMaxRawJSONDepth` counts raw `{`/`[` bytes
    /// across the whole JSON-RPC message. For THIS argument's shape
    /// (`radical` wrapping `radical`, matching both the original #117 report
    /// and the R2 review's reproduction), each logical level costs 2 raw
    /// bytes of nesting (one `{`, one `[`), and the `tools/call` → `params`
    /// → `arguments` envelope itself costs 3 more before the `components`
    /// value's own outer `{` — measured directly against real generated
    /// JSON, not derived: raw_depth = 2×(logical depth) + 4. At the R1
    /// value of 64, raw_depth would be 132 — already past
    /// `transportMaxRawJSONDepth` (64), meaning that value's own specific
    /// error would NEVER be reachable through the real JSON-RPC transport;
    /// the blunter transport error would always fire first. 24 keeps
    /// raw_depth at 52 for calls right at the cap, leaving a real window
    /// (logical depths 25–30, raw depth 54–64) where this guard's more
    /// specific error is still reachable before the transport cap takes
    /// over at 31+ — confirmed against the real binary (see `wave1-crash.md`
    /// "R2"). 24 remains generous for genuine use: Word's own equation
    /// editor UI does not let a human author nest fractions/radicals/
    /// scripts anywhere near this deep.
    private static let maxMathComponentDepth = 24

    /// Parse an MCP Value (JSON) into a MathComponent tree.
    /// Supported types: `run`, `fraction`, `radical`, `subSuperScript`, `nary`.
    private func parseMathComponent(from value: Value, depth: Int = 0) throws -> MathComponent {
        guard depth <= Self.maxMathComponentDepth else {
            throw MathParseError.invalidStructure(
                "components tree exceeds max nesting depth \(Self.maxMathComponentDepth)"
            )
        }
        guard case .object(let obj) = value else {
            throw MathParseError.invalidStructure("expected object, got non-object value")
        }
        guard let type = obj["type"]?.stringValue else {
            throw MathParseError.invalidStructure("missing 'type' discriminator")
        }

        switch type {
        case "run":
            guard let text = obj["text"]?.stringValue else {
                throw MathParseError.missingField(field: "text", forType: type)
            }
            let style = obj["style"]?.stringValue.flatMap { MathStyle(rawValue: $0) }
            return MathRun(text: text, style: style)

        case "fraction":
            guard case .array(let num)? = obj["numerator"] else {
                throw MathParseError.missingField(field: "numerator", forType: type)
            }
            guard case .array(let den)? = obj["denominator"] else {
                throw MathParseError.missingField(field: "denominator", forType: type)
            }
            return MathFraction(
                numerator: try num.map { try parseMathComponent(from: $0, depth: depth + 1) },
                denominator: try den.map { try parseMathComponent(from: $0, depth: depth + 1) }
            )

        case "radical":
            guard case .array(let radicand)? = obj["radicand"] else {
                throw MathParseError.missingField(field: "radicand", forType: type)
            }
            var degree: [MathComponent]?
            if case .array(let d)? = obj["degree"] {
                degree = try d.map { try parseMathComponent(from: $0, depth: depth + 1) }
            }
            return MathRadical(
                radicand: try radicand.map { try parseMathComponent(from: $0, depth: depth + 1) },
                degree: degree
            )

        case "subSuperScript":
            guard case .array(let base)? = obj["base"] else {
                throw MathParseError.missingField(field: "base", forType: type)
            }
            var sub: [MathComponent]?
            if case .array(let s)? = obj["sub"] {
                sub = try s.map { try parseMathComponent(from: $0, depth: depth + 1) }
            }
            var sup: [MathComponent]?
            if case .array(let s)? = obj["sup"] {
                sup = try s.map { try parseMathComponent(from: $0, depth: depth + 1) }
            }
            return MathSubSuperScript(
                base: try base.map { try parseMathComponent(from: $0, depth: depth + 1) },
                sub: sub,
                sup: sup
            )

        case "nary":
            guard let opStr = obj["op"]?.stringValue,
                  let op = MathNary.NaryOperator(rawValue: opStr) else {
                throw MathParseError.missingField(field: "op (one of: ∑, ∫, ∏, ∬, ∮, ⋃, ⋂)", forType: type)
            }
            var sub: [MathComponent]?
            var sup: [MathComponent]?
            if case .array(let s)? = obj["sub"] { sub = try s.map { try parseMathComponent(from: $0, depth: depth + 1) } }
            if case .array(let s)? = obj["sup"] { sup = try s.map { try parseMathComponent(from: $0, depth: depth + 1) } }
            guard case .array(let base)? = obj["base"] else {
                throw MathParseError.missingField(field: "base", forType: type)
            }
            return MathNary(
                op: op,
                sub: sub,
                sup: sup,
                base: try base.map { try parseMathComponent(from: $0, depth: depth + 1) }
            )

        default:
            throw MathParseError.unknownType(type)
        }
    }

    /// LaTeX subset parser delegated to `LaTeXMathSwift.LaTeXMathParser`.
    ///
    /// Returns an array of `MathComponent` instead of a single component
    /// because real-world equations are sequences of atoms (`R_t = a + b`)
    /// not single trees. The caller joins their OMML output for the
    /// `<m:oMath>` body.
    ///
    /// Supported macros: see `latex-math-swift` README. Anything outside the
    /// supported set throws `LaTeXParseError.unrecognizedToken`.
    private func parseLatex(_ latex: String) throws -> [MathComponent] {
        return try LaTeXMathParser.parse(latex)
    }

    /// #139: `setParagraphBorder`/`setParagraphShading`/`setCharacterSpacing`/
    /// `setTextEffect` (ooxml-swift, `.build/checkouts/ooxml-swift/`) each
    /// bounds-check `paragraph_index` against `getParagraphs().count` — the
    /// readback family, which recurses into block-level SDTs — but the
    /// mutation loop right below that check walks `body.children` counting
    /// only TOP-LEVEL `.paragraph` children (silently skipping
    /// `.contentControl` SDT wrappers without incrementing its own
    /// counter). In a document with a block-level SDT, an index that is
    /// in-bounds for the readback count but at/past the top-level count
    /// makes the mutation loop walk off the end and return having changed
    /// nothing — `storeDocument` still runs, so the call reports success.
    /// An index in-bounds for BOTH families still targets whichever
    /// top-level paragraph the mutation loop's own counter lands on, which
    /// may not be the paragraph the caller meant by that index under the
    /// readback numbering.
    ///
    /// che-word-mcp cannot modify ooxml-swift (read-only dependency), so the
    /// fix is a STRICTER pre-check on this side, using the exact same
    /// counting model the mutation loop uses, before ever calling into the
    /// library function at all.
    private func topLevelParagraphCount(_ doc: WordDocument) -> Int {
        doc.body.children.reduce(0) { count, child in
            if case .paragraph = child { return count + 1 }
            return count
        }
    }

    /// #250: `insertFieldCode` (shared by `insertIfField`/
    /// `insertCalculationField`/`insertDateField`/`insertPageField`/
    /// `insertMergeField`/`insertSequenceField`) and `insertContentControl`
    /// (ooxml-swift, `.build/checkouts/ooxml-swift/`) both bounds-check
    /// `paragraph_index` against `getParagraphs().count` — the readback
    /// family, which recurses into block-level SDTs — but their own
    /// "not found" fallback walks only TOP-LEVEL `.paragraph` body children
    /// (the exact same counting model `topLevelParagraphCount` above uses,
    /// added for #139's identical shape). In a document with a table or
    /// block-level SDT, an index at/past the top-level count but still
    /// within the readback count falls through that fallback and silently
    /// APPENDS a brand-new paragraph at the very end of the document,
    /// reporting success — never targeting the paragraph the caller asked
    /// for by `paragraph_index`.
    ///
    /// `insertFieldCode` always targets an EXISTING top-level paragraph (it
    /// appends a run to it) — there is no legitimate "append" use of an
    /// out-of-range index, so the valid range is `0..<topLevelParagraphCount`.
    private func requireExistingTopLevelParagraphIndex(_ paragraphIndex: Int, in doc: WordDocument) throws {
        let count = topLevelParagraphCount(doc)
        guard paragraphIndex >= 0, paragraphIndex < count else {
            throw WordError.invalidParameter(
                "paragraph_index",
                "超出頂層段落範圍（頂層段落數：\(count)）；index \(paragraphIndex) 沒有對應到任何既有頂層段落"
            )
        }
    }

    /// `insertContentControl` is different from `insertFieldCode`:
    /// `paragraph_index == topLevelParagraphCount` is an established, tested
    /// convention meaning "insert as the new last top-level paragraph" (see
    /// `ContentControlToolsTests` / `InvoiceTemplateE2ETests`, which
    /// sequentially call this tool with `paragraph_index` equal to the
    /// CURRENT top-level paragraph count to append one control after
    /// another). So its valid range is inclusive of that one extra
    /// position — only an index STRICTLY PAST it (the gap opened up by
    /// SDT-inner / table-cell paragraphs in the readback count, or anything
    /// further still) is rejected.
    private func requireContentControlParagraphIndex(_ paragraphIndex: Int, in doc: WordDocument) throws {
        let count = topLevelParagraphCount(doc)
        guard paragraphIndex >= 0, paragraphIndex <= count else {
            throw WordError.invalidParameter(
                "paragraph_index",
                "超出頂層段落範圍（頂層段落數：\(count)；合法範圍 0...\(count)，\(count) 代表附加為新的最後一個段落）"
            )
        }
    }

    private func setParagraphBorder(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard paragraphIndex >= 0, paragraphIndex < topLevelParagraphCount(doc) else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        // #253: neither a wrong JSON type nor an unrecognized value was
        // ever rejected — `RawRepresentable(rawValue:)`'s `nil` on either
        // failure fell straight into `?? .single`.
        let typeStr = try Self.optionalStrictEnumString(
            args, "type", allowed: ["none", "single", "thick", "double", "dotted", "dashed", "dashDotStroked", "threeDEmboss", "threeDEngrave", "wave"]
        ) ?? "single"
        let size = try optionalInt(args, "size") ?? 4
        let color = args["color"]?.stringValue ?? "000000"
        let space = try optionalInt(args, "space") ?? 1

        // 解析邊框類型
        let borderType = ParagraphBorderType(rawValue: typeStr) ?? .single
        let borderStyle = ParagraphBorderStyle(type: borderType, color: color, size: size, space: space)

        // 解析要套用的邊
        var topStyle: ParagraphBorderStyle? = borderStyle
        var bottomStyle: ParagraphBorderStyle? = borderStyle
        var leftStyle: ParagraphBorderStyle? = borderStyle
        var rightStyle: ParagraphBorderStyle? = borderStyle

        if let sidesValue = args["sides"] {
            if case .array(let arr) = sidesValue {
                topStyle = nil; bottomStyle = nil; leftStyle = nil; rightStyle = nil
                for item in arr {
                    if let side = item.stringValue {
                        switch side.lowercased() {
                        case "top": topStyle = borderStyle
                        case "bottom": bottomStyle = borderStyle
                        case "left": leftStyle = borderStyle
                        case "right": rightStyle = borderStyle
                        default: break
                        }
                    }
                }
            }
        }

        let border = ParagraphBorder(
            top: topStyle,
            bottom: bottomStyle,
            left: leftStyle,
            right: rightStyle
        )

        try doc.setParagraphBorder(at: paragraphIndex, border: border)
        try await storeDocument(doc, for: docId)

        return "Set border on paragraph \(paragraphIndex)"
    }

    private func setParagraphShading(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard paragraphIndex >= 0, paragraphIndex < topLevelParagraphCount(doc) else {
            throw WordError.invalidIndex(paragraphIndex)
        }
        guard let fill = args["fill"]?.stringValue else {
            throw WordError.missingParameter("fill")
        }

        var pattern: ShadingPattern? = nil
        if let patternStr = args["pattern"]?.stringValue {
            pattern = ShadingPattern(rawValue: patternStr)
        }

        try doc.setParagraphShading(at: paragraphIndex, fill: fill, pattern: pattern)
        try await storeDocument(doc, for: docId)

        return "Set shading on paragraph \(paragraphIndex) (fill: #\(fill))"
    }

    private func setCharacterSpacing(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard paragraphIndex >= 0, paragraphIndex < topLevelParagraphCount(doc) else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        let spacing = try optionalInt(args, "spacing")
        let position = try optionalInt(args, "position")
        let kern = try optionalInt(args, "kern")
        // #235: `spacing`/`position` → ST_SignedTwipsMeasure/ST_SignedHpsMeasure
        // (signed; bounded to what Word's 32-bit read can hold), `kern` →
        // ST_HpsMeasure (unsigned). See the range constants' doc comments.
        if let spacing { _ = try Self.validatedParamRange(spacing, "spacing", Self.signedHalfPointOrTwipsRange) }
        if let position { _ = try Self.validatedParamRange(position, "position", Self.signedHalfPointOrTwipsRange) }
        if let kern { _ = try Self.validatedParamRange(kern, "kern", Self.unsignedHpsOrTwipsRange) }

        try doc.setCharacterSpacing(at: paragraphIndex, spacing: spacing, position: position, kern: kern)
        try await storeDocument(doc, for: docId)

        var changes: [String] = []
        if let spacing = spacing { changes.append("spacing: \(spacing)") }
        if let position = position { changes.append("position: \(position)") }
        if let kern = kern { changes.append("kern: \(kern)") }

        return "Set character spacing on paragraph \(paragraphIndex): \(changes.joined(separator: ", "))"
    }

    private func setTextEffect(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard paragraphIndex >= 0, paragraphIndex < topLevelParagraphCount(doc) else {
            throw WordError.invalidIndex(paragraphIndex)
        }
        guard let effectType = args["effect"]?.stringValue else {
            throw WordError.missingParameter("effect")
        }

        // TextEffect 是 enum：blinkBackground, lights, antsBlack, antsRed, shimmer, sparkle, none
        guard let effect = TextEffect(rawValue: effectType) else {
            throw WordError.invalidParameter("effect", "Unknown effect type: \(effectType). Valid: blinkBackground, lights, antsBlack, antsRed, shimmer, sparkle, none")
        }

        try doc.setTextEffect(at: paragraphIndex, effect: effect)
        try await storeDocument(doc, for: docId)

        return "Applied '\(effectType)' effect to paragraph \(paragraphIndex)"
    }

    // MARK: - 8.1 Comment Replies and Resolution

    private func replyToComment(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        // #232 R4: both parsed unconditionally — `??` used to short-circuit
        // on a non-nil comment_id, so a present-but-mistyped
        // parent_comment_id was silently never validated.
        let commentIdArg = try optionalInt(args, "comment_id")
        let parentCommentIdArg = try optionalInt(args, "parent_comment_id")
        guard let commentId = commentIdArg ?? parentCommentIdArg else {
            throw WordError.missingParameter("comment_id")
        }
        guard let replyText = try resolveCommentReplyText(args: args) else {
            throw WordError.missingParameter("reply_text or text or template")
        }
        let author = args["author"]?.stringValue ?? "User"
        let shouldResolve = try optionalBool(args, "resolve") ?? false

        // #137: `CommentsCollection.addReply` only checks that the parent id
        // exists, not that it's a thread root — replying to a reply builds an
        // in-memory parentId chain that commentsExtended.xml's single
        // `paraIdParent` attribute cannot represent, so Word's thread view
        // would disagree with the model. Reject before mutating, and name
        // the reason (not just "not found") so a caller who typed a reply's
        // own id understands why.
        guard let target = doc.comments.comments.first(where: { $0.id == commentId }) else {
            throw WordError.invalidParameter("comment_id", "Comment with ID \(commentId) not found")
        }
        guard target.parentId == nil else {
            throw WordError.invalidParameter("comment_id", "cannot reply to a reply (comment_id \(commentId) has parent_id \(target.parentId!)); reply to the thread root instead")
        }

        // 使用 CommentsCollection.addReply 方法
        guard let reply = doc.comments.addReply(to: commentId, author: author, text: replyText) else {
            throw WordError.invalidParameter("comment_id", "Comment with ID \(commentId) not found")
        }
        if shouldResolve {
            doc.comments.markAsDone(commentId, done: true)
        }
        doc.markPartDirty("word/comments.xml")
        markCommentsExtendedTypedPartsDirtyIfNeeded(&doc)

        try await storeDocument(doc, for: docId)
        let resolvedSuffix = shouldResolve ? " and resolved comment \(commentId)" : ""
        return "Added reply to comment \(commentId) by \(author) (reply ID: \(reply.id))\(resolvedSuffix)"
    }

    private func resolveComment(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let commentId = try optionalInt(args, "comment_id") else {
            throw WordError.missingParameter("comment_id")
        }
        let resolved = try optionalBool(args, "resolved") ?? true

        // #252 (R2: dedupe — this comment block used to be duplicated
        // verbatim here): consistent with #137's `add_comment_reply`/
        // `reply_to_comment` rejection — Word's "done" state is a
        // THREAD-ROOT-level flag (`w15:done` on `commentEx`, keyed by the
        // root's `paraId`), not a per-comment one. Marking a reply done
        // alone produces a state Word itself cannot display consistently
        // (the thread's done indicator is read from the root, not from
        // whichever reply happened to be marked). Reject before mutating
        // and name the thread root the caller should target instead, the
        // same shape #137 already established for the write side of a
        // reply.
        if let target = doc.comments.comments.first(where: { $0.id == commentId }),
           let parentId = target.parentId {
            throw WordError.invalidParameter(
                "comment_id",
                "cannot resolve a reply (comment_id \(commentId) has parent_id \(parentId)); resolve the thread root instead"
            )
        }

        // 使用 CommentsCollection.markAsDone 方法
        doc.comments.markAsDone(commentId, done: resolved)
        markCommentsExtendedTypedPartsDirtyIfNeeded(&doc)
        try await storeDocument(doc, for: docId)

        return "Comment \(commentId) \(resolved ? "resolved" : "reopened")"
    }

    /// #134 workaround (che-word-mcp side; root cause is cross-repo in
    /// ooxml-swift's `DocxWriter.hasNewTypedParts`/`hasNewTypedRelationships`
    /// — see report). Neither helper checks `comments.hasExtendedComments`,
    /// so in overlay mode a document that never had `word/commentsExtended.xml`
    /// before this call gets the part's bytes written to the archive without
    /// a matching `[Content_Types].xml` Override or
    /// `word/_rels/document.xml.rels` relationship — Word then ignores the
    /// done/reply state the part encodes. `markPartDirty` is the public API
    /// ooxml-swift documents exactly for this ("external consumers... that
    /// write directly to `archiveTempDir` bypassing the typed mutation
    /// methods"): marking these two dirty makes the overlay writer recompute
    /// both through `ContentTypesOverlay`/`RelationshipsOverlay`, which merge
    /// with (not replace) whatever the source document already declared.
    private func markCommentsExtendedTypedPartsDirtyIfNeeded(_ doc: inout WordDocument) {
        guard doc.comments.hasExtendedComments else { return }
        doc.markPartDirty("word/commentsExtended.xml")
        doc.markPartDirty("[Content_Types].xml")
        doc.markPartDirty("word/_rels/document.xml.rels")
    }

    private func bulkResolveComments(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let ids = args["comment_ids"]?.arrayValue else {
            throw WordError.missingParameter("comment_ids")
        }
        // R2 fix (review finding 2 / DEFECT-B): the cap used to be checked
        // against `ids.count` (the raw, pre-dedup array), so 1001 copies of
        // the same id — which resolve exactly one comment — were rejected
        // outright even though the actual work is trivial. Issue #132's own
        // Strategy dedupes first and only then checks `uniqueIds.count`;
        // the cap now applies inside the dedup loop below, so it bounds real
        // work, not array literal length.
        let maxBulkResolveIds = 1000
        // The unique-id cap bounds the resolving work, but the raw array needs
        // a ceiling too: each wrong-typed element adds a line to `failed`, so
        // an unbounded array produced an unbounded response. 100 times the
        // unique cap leaves room for any realistic amount of duplication.
        let maxBulkResolveRawElements = 100_000
        guard ids.count <= maxBulkResolveRawElements else {
            throw WordError.invalidParameter("comment_ids", "陣列最多 \(maxBulkResolveRawElements) 個元素（含重複），收到 \(ids.count) 個")
        }

        var failed: [String] = []
        // #132: dedupe by parsed id before touching the document — `[5, 5, 5]`
        // used to call `markAsDone` three times (idempotent on state) but
        // still incremented `resolvedCount` three times, so the response
        // claimed 3 resolved comments when only 1 comment was ever resolved.
        // `Set.insert` keeps first-seen order via `uniqueIds`.
        var uniqueIds: [Int] = []
        var seenIds = Set<Int>()
        // #232 R7 (`rev232b` review LOW-3): `value.intValue` only matches the
        // `.int` JSON case — the same inconsistency `anchorPresence` had
        // before R6's `looksLikeIntAnchor` fix, just for a batch tool
        // instead of an anchor. A whole-valued `.double(3.0)` element (only
        // reachable in-process, since JSON integers decode to `.int` on this
        // platform — see the `optionalInt` doc comment above) used to be
        // rejected as `invalid_id` even though it's numerically a valid
        // comment id. Matches `Int(exactly:)`, same as `optionalInt`/
        // `looksLikeIntAnchor`. Also now reports which array position
        // failed (`index`), not just the element's own value — the old
        // `"comment_id":null` gave no way to tell which of several
        // wrong-typed elements a given failure line came from.
        for (index, value) in ids.enumerated() {
            let id: Int?
            switch value {
            case .int(let v): id = v
            case .double(let d): id = Int(exactly: d)
            default: id = nil
            }
            guard let id else {
                failed.append("{\"index\":\(index),\"comment_id\":null,\"error\":\"invalid_id\"}")
                continue
            }
            if seenIds.insert(id).inserted {
                uniqueIds.append(id)
                // Refuse as soon as the cap is crossed; the rest of the array
                // cannot change the outcome.
                guard uniqueIds.count <= maxBulkResolveIds else {
                    throw WordError.invalidParameter("comment_ids", "去重後不重複的 ID 超過 \(maxBulkResolveIds) 筆（在第 \(index) 個元素處超過上限）")
                }
            }
        }

        // #132: O(M+N) — one pass over the document builds an id→index map,
        // then each of the (now-deduped) requested ids is an O(1) dictionary
        // lookup + direct mutation, instead of the old `contains(where:)` /
        // `markAsDone` pair which each re-scanned the whole comment array
        // (O(M×N), the "100k IDs × mid-size document blocks the actor for
        // tens of seconds" case the issue named).
        var indexById: [Int: Int] = [:]
        indexById.reserveCapacity(doc.comments.comments.count)
        for (i, comment) in doc.comments.comments.enumerated() {
            indexById[comment.id] = i
        }

        var resolvedCount = 0
        for id in uniqueIds {
            guard let index = indexById[id] else {
                failed.append("{\"comment_id\":\(id),\"error\":\"not_found\"}")
                continue
            }
            // #252 (R2: dedupe — this comment block used to be duplicated
            // verbatim here): same rejection `resolveComment` now applies
            // for a single id (see its #137-consistency comment above) —
            // Word's "done" state is a thread-root-level flag, and this
            // tool's own documented contract is "不中斷於單筆失敗": a reply
            // id fails THAT entry via `failed`, it does not abort the
            // whole batch or silently mark the reply done.
            if let parentId = doc.comments.comments[index].parentId {
                failed.append("{\"comment_id\":\(id),\"error\":\"is_reply\",\"parent_id\":\(parentId)}")
                continue
            }
            doc.comments.comments[index].done = true
            resolvedCount += 1
        }

        if resolvedCount > 0 {
            markCommentsExtendedTypedPartsDirtyIfNeeded(&doc)
            try await storeDocument(doc, for: docId)
        }

        return "{\"resolved\":\(resolvedCount),\"failed\":[\(failed.joined(separator: ","))]}"
    }

    private func resolveCommentReplyText(args: [String: Value]) throws -> String? {
        if let text = args["reply_text"]?.stringValue ?? args["text"]?.stringValue {
            return text
        }
        guard let templateName = args["template"]?.stringValue else {
            return nil
        }
        let templates = [
            "fix_done": "Fixed in ${commit_sha} (Refs #${issue_number})",
            "noted": "Noted.",
            "wontfix": "Won't fix: ${reason}",
            "more_info_needed": "Need more information: ${question}"
        ]
        guard var rendered = templates[templateName] else {
            throw WordError.invalidParameter("template", "Unknown template '\(templateName)'")
        }

        let vars = args["vars"]?.objectValue ?? [:]
        for (key, value) in vars {
            if let str = templateVariableString(value) {
                rendered = rendered.replacingOccurrences(of: "${\(key)}", with: str)
            }
        }
        if rendered.range(of: #"\$\{[^}]+\}"#, options: .regularExpression) != nil {
            throw WordError.invalidParameter("vars", "Missing template variable for '\(templateName)'")
        }
        return rendered
    }

    private func templateVariableString(_ value: Value) -> String? {
        if let str = value.stringValue { return str }
        if let int = value.intValue { return String(int) }
        if let bool = value.boolValue { return String(bool) }
        return nil
    }

    // MARK: - 8.2 Floating Images

    /// R8 (independent review of #232 R7, M-R7-1): R7 gave
    /// `horizontal_position`/`vertical_position` a schema `"type"` that was
    /// a JSON-Schema-legal ARRAY of primitive type names (`["integer",
    /// "string"]`) so one parameter could accept either an EMU offset or an
    /// alignment keyword. That is valid JSON Schema, but NOT valid OpenAPI
    /// 3.0 — and Gemini's `FunctionDeclaration.parameters` field is
    /// explicitly documented as accepting only "a select subset of an
    /// OpenAPI 3.0 schema object," where `type` must be a single string.
    /// A client that converts this tool's `inputSchema` into that shape
    /// could reject the WHOLE tool list over one malformed property — R7's
    /// own `tools/list` was (and, before this fix, remained) the only
    /// place in this 246-tool file where `"type"` was ever an array.
    ///
    /// Fixed by splitting each axis into two single-typed parameters
    /// instead — `horizontal_position` (integer, EMU offset) +
    /// `horizontal_align` (string, alignment keyword), and the vertical
    /// equivalents — rather than switching to `anyOf` (the schema's other
    /// escape hatch): `anyOf` support is itself inconsistent across Gemini
    /// API versions (some generations of the API reportedly don't support
    /// it in this field), while splitting into two plain-typed properties
    /// is trivially supported by every MCP client, no matter how minimal
    /// its JSON Schema handling. This also matches #232's own "one
    /// parameter, one JSON type" design more directly than either union
    /// shape did. Providing BOTH the offset and the alignment for the same
    /// axis is rejected as conflicting (`ToolRefusal`), not silently
    /// resolved by picking one.
    /// R9 (review `rev232c` M-2): a string parameter that is present but not
    /// a string (or `null`) is an error naming the parameter, not "absent".
    /// `?.stringValue` would silently drop `5`/`true`/`["top"]`, which is the
    /// exact #232 failure shape. Deliberately applied only to the two
    /// alignment parameters R8 introduced, not retrofitted to the ~500
    /// existing string reads.
    static func optionalStrictString(_ args: [String: Value], _ key: String) throws -> String? {
        guard let value = args[key] else { return nil }
        switch value {
        case .string(let s): return s
        case .null: return nil
        default: throw WordError.invalidParameter(key, "必須是字串")
        }
    }

    /// #240: the enum-shaped counterpart to `optionalStrictString` above —
    /// same shape as #232's `optionalInt`/`optionalBool` closing "wrong
    /// type silently ignored", extended to string parameters that also have
    /// a fixed, closed set of legal VALUES (JSON Schema `"enum"`, or values
    /// only enumerated in the description's prose). Before this helper,
    /// call sites read these with plain `?.stringValue ?? default` and
    /// either matched the result against known cases with a silent
    /// `default:` fallback, or built the matching typed enum with `guard
    /// let ... else { return .default }` — both shapes throw away BOTH a
    /// wrong JSON type (`wrap_type: 5`) AND a well-typed-but-unrecognized
    /// value (`wrap_type: "bogus"`) identically, reporting success either
    /// way while quietly substituting a default the caller never asked for.
    /// Reuses `optionalStrictString` for the type check, then additionally
    /// rejects any string not in `allowed`, naming the parameter and the
    /// legal values (mirroring `insert_floating_image`'s pre-existing
    /// `horizontal_align`/`vertical_align` value-rejection message shape).
    static func optionalStrictEnumString(_ args: [String: Value], _ key: String, allowed: [String]) throws -> String? {
        guard let value = try optionalStrictString(args, key) else { return nil }
        guard allowed.contains(value) else {
            throw WordError.invalidParameter(key, "必須是 \(allowed.joined(separator: "/")) 之一，不接受 '\(value)'")
        }
        return value
    }

    /// R9 (review `rev232c` LOW-4, LOW-6): the floating-image offset.
    /// - A string here is almost certainly a v4.3.x caller following the old
    ///   schema (`"center"`); say where alignment keywords live now.
    /// - `wp:posOffset` is `ST_PositionOffset` = `xsd:int`, so the value must
    ///   fit a 32-bit signed integer or the written file is invalid.
    func floatingImageOffset(_ args: [String: Value], _ key: String, alignKey: String) throws -> Int? {
        if case .string(let raw) = args[key] {
            // R9 review (rev232c LOW): a numeric string is a type mistake,
            // not an alignment keyword — don't point it at `*_align`.
            if Int(raw.trimmingCharacters(in: .whitespaces)) != nil {
                throw WordError.invalidParameter(key, "必須是 JSON 整數（EMU 偏移），不接受字串 \"\(raw)\"")
            }
            throw WordError.invalidParameter(
                key, "必須是整數（EMU 偏移）；對齊關鍵字（例如 \"center\"）請改用 \(alignKey)"
            )
        }
        guard let offset = try optionalInt(args, key) else { return nil }
        guard offset >= Int(Int32.min), offset <= Int(Int32.max) else {
            throw WordError.invalidParameter(
                key, "必須介於 \(Int32.min) 到 \(Int32.max) 之間（EMU；wp:posOffset 是 xsd:int）"
            )
        }
        return offset
    }

    private func insertFloatingImage(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let path = args["path"]?.stringValue else {
            throw WordError.missingParameter("path")
        }

        let paragraphIndex = try optionalInt(args, "paragraph_index") ?? 0
        let widthEmu = try optionalInt(args, "width") ?? 2000000  // ~2 inches default
        let heightEmu = try optionalInt(args, "height") ?? 2000000
        // #235: unlike insert_image/insert_image_from_path (pixels, converted
        // to EMU downstream), width/height here are ALREADY EMU and reach
        // <wp:extent cx/cy> directly — validate against ST_PositiveCoordinate
        // (see `floatingImageExtentEMURange`'s doc comment) before ever
        // calling into Drawing.anchor.
        _ = try Self.validatedParamRange(widthEmu, "width", Self.floatingImageExtentEMURange)
        _ = try Self.validatedParamRange(heightEmu, "height", Self.floatingImageExtentEMURange)
        // R8: see this function's doc comment above for why
        // horizontal_position/vertical_position are plain integer EMU
        // offsets again, paired with separate string alignment parameters.
        let horizontalOffset = try floatingImageOffset(args, "horizontal_position", alignKey: "horizontal_align")
        var horizontalAlign: HorizontalAlignment? = nil
        if let raw = try Self.optionalStrictString(args, "horizontal_align") {
            guard let a = HorizontalAlignment(rawValue: raw) else {
                throw WordError.invalidParameter(
                    "horizontal_align", "必須是合法的對齊關鍵字 left/center/right/inside/outside，不接受 '\(raw)'"
                )
            }
            horizontalAlign = a
        }
        if horizontalOffset != nil, horizontalAlign != nil {
            throw ToolRefusal("insert_floating_image: horizontal_position 與 horizontal_align 不可同時提供，請擇一")
        }
        let verticalOffset = try floatingImageOffset(args, "vertical_position", alignKey: "vertical_align")
        var verticalAlign: VerticalAlignment? = nil
        if let raw = try Self.optionalStrictString(args, "vertical_align") {
            guard let a = VerticalAlignment(rawValue: raw) else {
                throw WordError.invalidParameter(
                    "vertical_align", "必須是合法的對齊關鍵字 top/center/bottom/inside/outside，不接受 '\(raw)'"
                )
            }
            verticalAlign = a
        }
        if verticalOffset != nil, verticalAlign != nil {
            throw ToolRefusal("insert_floating_image: vertical_position 與 vertical_align 不可同時提供，請擇一")
        }
        // #240: `wrap_type: 5` (wrong JSON type) and `wrap_type: "bogus"`
        // (well-typed but unrecognized value) both used to silently become
        // "square" — `?.stringValue` drops the former, the switch below's
        // `default:` branch absorbed the latter. Validated case-insensitively
        // (unlike `optionalStrictEnumString`'s exact-match contract) because
        // the switch below already normalized with `.lowercased()` before
        // this fix, and existing callers may rely on that leniency; only the
        // WRONG-type and WRONG-value failure shapes are new rejections.
        let wrapTypeRaw = try Self.optionalStrictString(args, "wrap_type")
        let wrapTypeStr = wrapTypeRaw?.lowercased() ?? "square"
        let allowedWrapTypes = ["none", "square", "tight", "through", "topandbottom", "behindtext", "infrontoftext"]
        guard allowedWrapTypes.contains(wrapTypeStr) else {
            throw WordError.invalidParameter(
                "wrap_type",
                "必須是 \(allowedWrapTypes.joined(separator: "/")) 之一（不分大小寫），不接受 '\(wrapTypeRaw ?? "")'"
            )
        }
        // #233: the schema declares `relative_to_h`/`relative_to_v`; the
        // handler used to read only the undocumented `horizontal_relative`
        // (kept here as a compat fallback for anyone who discovered it by
        // reading source, since it was never in the schema for a caller to
        // rely on per-contract) and never read `relative_to_v` at all — the
        // vertical reference point was always the AnchorPosition default
        // (`.paragraph`), silently ignoring whatever the caller sent. An
        // invalid value now fails loudly naming the parameter, rather than
        // being swallowed by the previous `if let hrel = ... { }` (no `else`)
        // that just left the default in place.
        let relativeToHRaw = try Self.optionalStrictString(args, "relative_to_h")
            ?? args["horizontal_relative"]?.stringValue
        var horizontalRelativeFrom: HorizontalRelativeFrom = .column
        if let raw = relativeToHRaw {
            guard let hrel = HorizontalRelativeFrom(rawValue: raw) else {
                throw WordError.invalidParameter(
                    "relative_to_h",
                    "必須是合法的參照點 margin/page/column/character/leftMargin/rightMargin/insideMargin/outsideMargin，不接受 '\(raw)'"
                )
            }
            horizontalRelativeFrom = hrel
        }
        var verticalRelativeFrom: VerticalRelativeFrom = .paragraph
        if let raw = try Self.optionalStrictString(args, "relative_to_v") {
            guard let vrel = VerticalRelativeFrom(rawValue: raw) else {
                throw WordError.invalidParameter(
                    "relative_to_v",
                    "必須是合法的參照點 margin/page/paragraph/line/topMargin/bottomMargin/insideMargin/outsideMargin，不接受 '\(raw)'"
                )
            }
            verticalRelativeFrom = vrel
        }
        let allowOverlap = try optionalBool(args, "allow_overlap") ?? true

        // 讀取圖片數據
        let url = URL(fileURLWithPath: path)
        let imageData = try Data(contentsOf: url)

        // 建立圖片參照
        let imageId = "rId\(doc.images.count + 10)"
        let imageRef = ImageReference(
            id: imageId,
            fileName: url.lastPathComponent,
            contentType: detectImageContentType(from: url),
            data: imageData
        )
        doc.images.append(imageRef)

        // 建立浮動圖片定位
        var anchorPosition = AnchorPosition()
        // #232 R7 (`rev232b` review M3): alignment and numeric offset are
        // mutually exclusive in the OOXML output (ooxml-swift's writer
        // checks `horizontalAlignment`/`verticalAlignment` first and only
        // falls back to `horizontalOffset`/`verticalOffset` when nil — see
        // `AnchorPosition`'s XML serialization), so only ONE of the pair is
        // set here per axis, not both. `?? 0` preserves the pre-#232
        // default (an omitted position parameter anchors at offset 0) for
        // the case where neither an offset nor an alignment was given.
        if let horizontalAlign {
            anchorPosition.horizontalAlignment = horizontalAlign
        } else {
            anchorPosition.horizontalOffset = horizontalOffset ?? 0
        }
        if let verticalAlign {
            anchorPosition.verticalAlignment = verticalAlign
        } else {
            anchorPosition.verticalOffset = verticalOffset ?? 0
        }
        anchorPosition.allowOverlap = allowOverlap
        anchorPosition.horizontalRelativeFrom = horizontalRelativeFrom
        anchorPosition.verticalRelativeFrom = verticalRelativeFrom

        // 設定文繞圖類型
        switch wrapTypeStr.lowercased() {
        case "none": anchorPosition.wrapType = .none
        case "square": anchorPosition.wrapType = .square
        case "tight": anchorPosition.wrapType = .tight
        case "through": anchorPosition.wrapType = .through
        case "topandbottom": anchorPosition.wrapType = .topAndBottom
        case "behindtext": anchorPosition.wrapType = .behindText
        case "infrontoftext": anchorPosition.wrapType = .inFrontOfText
        default: anchorPosition.wrapType = .square
        }

        // 建立浮動繪圖
        let drawing = Drawing.anchor(
            width: widthEmu,
            height: heightEmu,
            imageId: imageId,
            position: anchorPosition,
            name: url.lastPathComponent
        )

        // 插入到段落
        try doc.insertDrawing(drawing, at: paragraphIndex)
        try await storeDocument(doc, for: docId)

        return "Inserted floating image '\(url.lastPathComponent)' at paragraph \(paragraphIndex)"
    }

    private func detectImageContentType(from url: URL) -> String {
        let ext = url.pathExtension.lowercased()
        switch ext {
        case "png": return "image/png"
        case "jpg", "jpeg": return "image/jpeg"
        case "gif": return "image/gif"
        case "bmp": return "image/bmp"
        case "tiff", "tif": return "image/tiff"
        default: return "image/png"
        }
    }

    // MARK: - 8.3 Field Codes

    private func insertIfField(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        try requireExistingTopLevelParagraphIndex(paragraphIndex, in: doc)
        guard let leftOperand = args["left_operand"]?.stringValue else {
            throw WordError.missingParameter("left_operand")
        }
        guard let operatorStr = args["operator"]?.stringValue else {
            throw WordError.missingParameter("operator")
        }
        guard let rightOperand = args["right_operand"]?.stringValue else {
            throw WordError.missingParameter("right_operand")
        }
        guard let trueText = args["true_text"]?.stringValue else {
            throw WordError.missingParameter("true_text")
        }
        guard let falseText = args["false_text"]?.stringValue else {
            throw WordError.missingParameter("false_text")
        }

        // 轉換運算符字串為 enum
        let compOp: IFField.ComparisonOperator
        switch operatorStr {
        case "=", "==": compOp = .equal
        case "<>", "!=": compOp = .notEqual
        case "<": compOp = .lessThan
        case ">": compOp = .greaterThan
        case "<=": compOp = .lessThanOrEqual
        case ">=": compOp = .greaterThanOrEqual
        default: compOp = .equal
        }

        let ifField = IFField(
            leftOperand: leftOperand,
            comparisonOperator: compOp,
            rightOperand: rightOperand,
            trueText: trueText,
            falseText: falseText
        )

        try doc.insertFieldCode(ifField, at: paragraphIndex)
        try await storeDocument(doc, for: docId)

        return "Inserted IF field at paragraph \(paragraphIndex): IF \(leftOperand) \(operatorStr) \(rightOperand)"
    }

    private func insertCalculationField(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        try requireExistingTopLevelParagraphIndex(paragraphIndex, in: doc)
        guard let expression = args["expression"]?.stringValue else {
            throw WordError.missingParameter("expression")
        }
        let format = args["format"]?.stringValue

        // 表達式可以是完整的如 "=SUM(ABOVE)" 或 "SUM(ABOVE)"
        let calcField = CalculationField(
            expression: expression,
            numberFormat: format
        )

        try doc.insertFieldCode(calcField, at: paragraphIndex)
        try await storeDocument(doc, for: docId)

        return "Inserted calculation field '\(expression)' at paragraph \(paragraphIndex)"
    }

    private func insertDateField(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        try requireExistingTopLevelParagraphIndex(paragraphIndex, in: doc)
        let format = args["format"]?.stringValue ?? "yyyy-MM-dd"
        // #253: no validation at all — a wrong JSON type OR an unrecognized
        // value (e.g. "DATEE") both silently produced a DATE field while
        // reporting success. `optionalStrictString` rejects the type; the
        // value check below stays case-insensitive (pre-existing
        // `.uppercased()` comparison) but now has an explicit rejection
        // path instead of a silent `default: .date`.
        let typeStr = try Self.optionalStrictString(args, "type") ?? "DATE"

        let fieldType: DateTimeFieldType
        switch typeStr.uppercased() {
        case "DATE": fieldType = .date
        case "TIME": fieldType = .time
        case "PRINTDATE": fieldType = .printDate
        case "SAVEDATE": fieldType = .saveDate
        case "CREATEDATE": fieldType = .createDate
        case "EDITTIME": fieldType = .editTime
        default:
            throw WordError.invalidParameter("type", "必須是 DATE/TIME/PRINTDATE/SAVEDATE/CREATEDATE/EDITTIME 之一，不接受 '\(typeStr)'")
        }

        let dateField = DateTimeField(type: fieldType, dateFormat: format)

        try doc.insertFieldCode(dateField, at: paragraphIndex)
        try await storeDocument(doc, for: docId)

        return "Inserted \(typeStr) field with format '\(format)' at paragraph \(paragraphIndex)"
    }

    private func insertPageField(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        try requireExistingTopLevelParagraphIndex(paragraphIndex, in: doc)
        // #253: same shape as insert_date_field.type above — no validation
        // at all before this fix.
        let typeStr = try Self.optionalStrictString(args, "type") ?? "PAGE"

        let infoType: DocumentInfoFieldType
        switch typeStr.uppercased() {
        case "PAGE": infoType = .page
        case "NUMPAGES": infoType = .numPages
        case "NUMWORDS": infoType = .numWords
        case "NUMCHARS": infoType = .numChars
        case "FILENAME": infoType = .fileName
        case "AUTHOR": infoType = .author
        case "TITLE": infoType = .title
        case "SECTIONPAGES": infoType = .sectionPages
        default:
            throw WordError.invalidParameter("type", "必須是 PAGE/NUMPAGES/NUMWORDS/NUMCHARS/FILENAME/AUTHOR/TITLE/SECTIONPAGES 之一，不接受 '\(typeStr)'")
        }

        let infoField = DocumentInfoField(type: infoType)

        try doc.insertFieldCode(infoField, at: paragraphIndex)
        try await storeDocument(doc, for: docId)

        return "Inserted \(typeStr) field at paragraph \(paragraphIndex)"
    }

