    // MARK: - 8.4 Content Controls (SDT)

    /// #44 Phase 7.1: extended types + lock_type / list_items / date_format args.
    /// #44 Phase 7.3: SDT id allocation now uses doc.allocateSdtId() (max+1).
    /// repeatingSection type is rejected — callers must use insert_repeating_section.
    private func insertContentControl(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        try requireContentControlParagraphIndex(paragraphIndex, in: doc)
        guard let typeStr = args["type"]?.stringValue else {
            throw WordError.missingParameter("type")
        }
        guard let tag = args["tag"]?.stringValue else {
            throw WordError.missingParameter("tag")
        }

        let alias = args["alias"]?.stringValue
        let placeholder = args["placeholder"]?.stringValue
        let contentText = args["content"]?.stringValue ?? ""

        guard let sdtType = SDTType(rawValue: typeStr) else {
            throw WordError.invalidParameter("type",
                "Unknown SDT type: '\(typeStr)'. Valid: richText, text, picture, date, dropDownList, comboBox, checkbox, bibliography, citation, group, repeatingSectionItem")
        }
        // Phase 7.1: explicit reject for repeatingSection (use insert_repeating_section instead).
        if sdtType == .repeatingSection {
            throw WordError.invalidParameter("type",
                "type='repeatingSection' is rejected — use insert_repeating_section tool for repeating sections")
        }
        // Phase 7.1: list_items required for dropDownList / comboBox.
        if sdtType == .dropDownList || sdtType == .comboBox {
            guard let items = args["list_items"]?.arrayValue, !items.isEmpty else {
                throw WordError.missingParameter("list_items (required for \(typeStr))")
            }
            _ = items  // list_items currently surfaced via raw XML in placeholder; full schema lands in MCP-Phase 2 of #44.
        }

        let lockType: SDTLockType
        if let lockStr = args["lock_type"]?.stringValue {
            guard let parsed = SDTLockType(rawValue: lockStr) else {
                throw WordError.invalidParameter("lock_type",
                    "Unknown lock_type: '\(lockStr)'. Valid: unlocked, sdtLocked, contentLocked, sdtContentLocked")
            }
            lockType = parsed
        } else {
            lockType = .unlocked
        }

        let sdt = StructuredDocumentTag(
            id: doc.allocateSdtId(),  // Phase 7.3: deterministic max+1 (was Int.random)
            tag: tag,
            alias: alias,
            type: sdtType,
            lockType: lockType,
            placeholder: placeholder
        )

        let contentControl = ContentControl(sdt: sdt, content: contentText)

        try doc.insertContentControl(contentControl, at: paragraphIndex)
        try await storeDocument(doc, for: docId)

        return "Inserted \(typeStr) content control '\(tag)' (id=\(sdt.id ?? -1)) at paragraph \(paragraphIndex)"
    }

    /// #44 Phase 7.2: allow_insert_delete_sections arg passes through to OOXML.
    private func insertRepeatingSection(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let tag = args["tag"]?.stringValue else {
            throw WordError.missingParameter("tag")
        }

        let index = try optionalInt(args, "index") ?? 0
        let sectionTitle = args["section_title"]?.stringValue
        let itemsArray = args["items"]?.arrayValue ?? []
        let allowInsertDelete = try optionalBool(args, "allow_insert_delete_sections") ?? true

        var items: [RepeatingSectionItem] = []
        for item in itemsArray {
            if let content = item.stringValue {
                items.append(RepeatingSectionItem(tag: nil, content: content))
            }
        }
        if items.isEmpty {
            items.append(RepeatingSectionItem(content: ""))
        }

        var repeatingSection = RepeatingSection(
            tag: tag,
            alias: sectionTitle,
            items: items,
            allowInsertDeleteSections: allowInsertDelete,
            sectionTitle: sectionTitle
        )
        // Phase 7.3: assign deterministic id from allocator.
        repeatingSection.sdt.id = doc.allocateSdtId()

        try doc.insertRepeatingSection(repeatingSection, at: index)
        try await storeDocument(doc, for: docId)

        return "Inserted repeating section '\(tag)' (id=\(repeatingSection.sdt.id ?? -1)) with \(items.count) item(s) at index \(index)"
    }

    // MARK: - #44 Phase 5: Content Control Read Tools

    /// Phase 5.1: list_content_controls — flat (default) or nested tree.
    private func listContentControls(args: [String: Value]) async throws -> String {
        let doc = try await loadDocumentFromArgs(args)
        let nested = try optionalBool(args, "nested") ?? false

        // Walk all paragraphs (including inside tables and block-level SDTs)
        // to collect entries in document order with paragraph indices.
        struct Entry {
            let id: Int?
            let tag: String?
            let alias: String?
            let type: String
            let lockType: String
            let currentText: String
            let paragraphIndex: Int
            let parentSdtId: Int?
            let children: [Entry]
        }

        func entryFor(_ control: ContentControl, paragraphIndex: Int, parentSdtId: Int?) -> Entry {
            let kids = control.children.map {
                entryFor($0, paragraphIndex: paragraphIndex, parentSdtId: control.sdt.id)
            }
            return Entry(
                id: control.sdt.id,
                tag: control.sdt.tag,
                alias: control.sdt.alias,
                type: control.sdt.type.rawValue,
                lockType: control.sdt.lockType.rawValue,
                currentText: Self.extractTextFromContentXML(control.content),
                paragraphIndex: paragraphIndex,
                parentSdtId: parentSdtId,
                children: kids
            )
        }

        var topLevel: [Entry] = []
        var paraIndex = 0
        func walkBody(_ children: [BodyChild]) {
            for child in children {
                switch child {
                case .paragraph(let p):
                    for c in p.contentControls {
                        topLevel.append(entryFor(c, paragraphIndex: paraIndex, parentSdtId: nil))
                    }
                    paraIndex += 1
                case .table(let table):
                    for row in table.rows {
                        for cell in row.cells {
                            for cellPara in cell.paragraphs {
                                for c in cellPara.contentControls {
                                    topLevel.append(entryFor(c, paragraphIndex: paraIndex, parentSdtId: nil))
                                }
                                paraIndex += 1
                            }
                        }
                    }
                case .contentControl(let outer, children: let inner):
                    topLevel.append(entryFor(outer, paragraphIndex: paraIndex, parentSdtId: nil))
                    walkBody(inner)
                case .bookmarkMarker, .rawBlockElement:
                    // ooxml-swift v0.19.6+ (#58): body-level markers carry no
                    // content controls — skip.
                    continue
                }
            }
        }
        walkBody(doc.body.children)

        // Render as JSON-ish text. MCP responses are strings; structured output
        // uses readable JSON so callers can re-parse without ambiguity.
        func render(_ entry: Entry) -> String {
            var fields: [String] = []
            if let id = entry.id { fields.append("\"id\": \(id)") }
            if let tag = entry.tag { fields.append("\"tag\": \"\(Self.jsonEscape(tag))\"") }
            if let alias = entry.alias { fields.append("\"alias\": \"\(Self.jsonEscape(alias))\"") }
            fields.append("\"type\": \"\(entry.type)\"")
            fields.append("\"lock_type\": \"\(entry.lockType)\"")
            fields.append("\"current_text\": \"\(Self.jsonEscape(entry.currentText))\"")
            fields.append("\"paragraph_index\": \(entry.paragraphIndex)")
            if nested {
                let kidsRendered = entry.children.map { render($0) }.joined(separator: ", ")
                fields.append("\"children\": [\(kidsRendered)]")
            } else {
                if let pid = entry.parentSdtId {
                    fields.append("\"parent_sdt_id\": \(pid)")
                } else {
                    fields.append("\"parent_sdt_id\": null")
                }
            }
            return "{ " + fields.joined(separator: ", ") + " }"
        }

        if nested {
            // Tree mode: only top-level controls (children embedded).
            let topOnly = topLevel.filter { $0.parentSdtId == nil }
            return "[" + topOnly.map { render($0) }.joined(separator: ", ") + "]"
        } else {
            // Flat mode: include every control AND every nested child.
            var flat: [Entry] = []
            func collect(_ e: Entry) {
                flat.append(e)
                for k in e.children { collect(k) }
            }
            for e in topLevel { collect(e) }
            return "[" + flat.map { render($0) }.joined(separator: ", ") + "]"
        }
    }

    /// Phase 5.2: get_content_control — lookup by id / tag / alias (exactly one).
    private func getContentControl(args: [String: Value]) async throws -> String {
        let doc = try await loadDocumentFromArgs(args)
        let id = try optionalInt(args, "id")
        let tag = args["tag"]?.stringValue
        let alias = args["alias"]?.stringValue

        let provided = [id != nil, tag != nil, alias != nil].filter { $0 }.count
        guard provided == 1 else {
            throw WordError.invalidParameter("identifier",
                "Provide exactly one of: id, tag, alias (got \(provided))")
        }

        // Collect all controls (top-level + nested) with their paragraph index.
        var all: [(control: ContentControl, paragraphIndex: Int, parentSdtId: Int?)] = []
        func recordControl(_ c: ContentControl, paraIndex: Int, parentId: Int?) {
            all.append((c, paraIndex, parentId))
            for kid in c.children {
                recordControl(kid, paraIndex: paraIndex, parentId: c.sdt.id)
            }
        }
        var paraIndex = 0
        func walkBody(_ children: [BodyChild]) {
            for child in children {
                switch child {
                case .paragraph(let p):
                    for c in p.contentControls { recordControl(c, paraIndex: paraIndex, parentId: nil) }
                    paraIndex += 1
                case .table(let table):
                    for row in table.rows {
                        for cell in row.cells {
                            for cp in cell.paragraphs {
                                for c in cp.contentControls { recordControl(c, paraIndex: paraIndex, parentId: nil) }
                                paraIndex += 1
                            }
                        }
                    }
                case .contentControl(let outer, children: let inner):
                    recordControl(outer, paraIndex: paraIndex, parentId: nil)
                    walkBody(inner)
                case .bookmarkMarker, .rawBlockElement:
                    // ooxml-swift v0.19.6+ (#58): body-level markers carry no
                    // content controls — skip.
                    continue
                }
            }
        }
        walkBody(doc.body.children)

        let matches: [(control: ContentControl, paragraphIndex: Int, parentSdtId: Int?)]
        if let id = id {
            matches = all.filter { $0.control.sdt.id == id }
        } else if let tag = tag {
            matches = all.filter { $0.control.sdt.tag == tag }
        } else if let alias = alias {
            matches = all.filter { $0.control.sdt.alias == alias }
        } else {
            matches = []
        }

        if matches.isEmpty {
            return "{ \"error\": \"not_found\", \"query\": { \"id\": \(id.map(String.init) ?? "null"), \"tag\": \(tag.map { "\"\(Self.jsonEscape($0))\"" } ?? "null"), \"alias\": \(alias.map { "\"\(Self.jsonEscape($0))\"" } ?? "null") } }"
        }
        if matches.count > 1 {
            let ids = matches.compactMap { $0.control.sdt.id }
            return "{ \"error\": \"multiple_matches\", \"matching_ids\": [\(ids.map(String.init).joined(separator: ", "))] }"
        }

        let m = matches[0]
        var fields: [String] = []
        if let mid = m.control.sdt.id { fields.append("\"id\": \(mid)") }
        if let mtag = m.control.sdt.tag { fields.append("\"tag\": \"\(Self.jsonEscape(mtag))\"") }
        if let malias = m.control.sdt.alias { fields.append("\"alias\": \"\(Self.jsonEscape(malias))\"") }
        fields.append("\"type\": \"\(m.control.sdt.type.rawValue)\"")
        fields.append("\"lock_type\": \"\(m.control.sdt.lockType.rawValue)\"")
        fields.append("\"current_text\": \"\(Self.jsonEscape(Self.extractTextFromContentXML(m.control.content)))\"")
        fields.append("\"paragraph_index\": \(m.paragraphIndex)")
        if let pid = m.parentSdtId {
            fields.append("\"parent_sdt_id\": \(pid)")
        } else {
            fields.append("\"parent_sdt_id\": null")
        }
        fields.append("\"content_xml\": \"\(Self.jsonEscape(m.control.content))\"")
        return "{ " + fields.joined(separator: ", ") + " }"
    }

    /// Phase 5.3: list_repeating_section_items — items inside a repeating-section SDT.
    /// Note: ooxml-swift v0.15.0 still stores RepeatingSection as Run.rawXML (legacy
    /// path; #44 Phase 3 covered ContentControl SDTs but RepeatingSection write path
    /// is unchanged). We surface items by parsing the rawXML where the SDT lives.
    private func listRepeatingSectionItems(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let id = try optionalInt(args, "id") else {
            throw WordError.missingParameter("id")
        }

        // Locate the repeating section's rawXML in any paragraph.
        for paragraph in doc.getAllParagraphs() {
            for run in paragraph.runs {
                guard let raw = run.rawXML,
                      raw.contains("<w15:repeatingSection"),
                      raw.contains("w:id w:val=\"\(id)\"")
                else { continue }
                let items = Self.parseRepeatingSectionItems(rawXML: raw)
                let rendered = items.enumerated().map { (i, text) in
                    "{ \"index\": \(i), \"text\": \"\(Self.jsonEscape(text))\" }"
                }.joined(separator: ", ")
                return "[\(rendered)]"
            }
        }
        return "{ \"error\": \"not_found\", \"id\": \(id) }"
    }

    // MARK: - #44 Phase 6: Content Control Write Tools

    /// Phase 6.1: update_content_control_text — text replacement.
    private func updateContentControlText(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let id = try optionalInt(args, "id") else {
            throw WordError.missingParameter("id")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }

        do {
            try doc.updateContentControl(id: id, newText: text)
        } catch WordError.unsupportedSDTType(let type) {
            throw StructuredRefusal("{ \"error\": \"unsupported_type\", \"type\": \"\(type.rawValue)\" }")
        } catch WordError.contentControlNotFound(let nid) {
            throw StructuredRefusal("{ \"error\": \"not_found\", \"id\": \(nid) }")
        }

        try await storeDocument(doc, for: docId)
        return "Updated content control id=\(id) text"
    }

    /// Phase 6.2: replace_content_control_content — full XML replacement with whitelist.
    private func replaceContentControlContentTool(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let id = try optionalInt(args, "id") else {
            throw WordError.missingParameter("id")
        }
        guard let xml = args["content_xml"]?.stringValue else {
            throw WordError.missingParameter("content_xml")
        }

        do {
            try doc.replaceContentControlContent(id: id, contentXML: xml)
        } catch WordError.disallowedElement(let name) {
            throw StructuredRefusal("{ \"error\": \"disallowed_element\", \"element\": \"\(name)\" }")
        } catch WordError.contentControlNotFound(let nid) {
            throw StructuredRefusal("{ \"error\": \"not_found\", \"id\": \(nid) }")
        }

        try await storeDocument(doc, for: docId)
        return "Replaced content control id=\(id) content"
    }

    /// Phase 6.3: delete_content_control — remove SDT, optionally keep content.
    private func deleteContentControlTool(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let id = try optionalInt(args, "id") else {
            throw WordError.missingParameter("id")
        }
        let keepContent = try optionalBool(args, "keep_content") ?? true

        do {
            try doc.deleteContentControl(id: id, keepContent: keepContent)
        } catch WordError.contentControlNotFound(let nid) {
            throw StructuredRefusal("{ \"error\": \"not_found\", \"id\": \(nid) }")
        }

        try await storeDocument(doc, for: docId)
        return "Deleted content control id=\(id) (keep_content=\(keepContent))"
    }

    /// Phase 6.4: update_repeating_section_item — modify single item text.
    /// Currently operates on the rawXML carrier (RepeatingSection is still written
    /// via Run.rawXML). Surfaces out_of_bounds when item_index is invalid.
    private func updateRepeatingSectionItem(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        guard let parentId = try optionalInt(args, "parent_id") else {
            throw WordError.missingParameter("parent_id")
        }
        guard let itemIndex = try optionalInt(args, "item_index") else {
            throw WordError.missingParameter("item_index")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }

        // Mutate paragraphs in body (top-level only for now — repeating sections
        // are not nested in this SDD's scope). Locate by id substring in raw XML.
        let needle = "w:id w:val=\"\(parentId)\""
        var found = false
        for childIdx in 0..<doc.body.children.count {
            guard case .paragraph(var para) = doc.body.children[childIdx] else { continue }
            for runIdx in 0..<para.runs.count {
                guard let raw = para.runs[runIdx].rawXML,
                      raw.contains("<w15:repeatingSection"),
                      raw.contains(needle)
                else { continue }

                let items = Self.parseRepeatingSectionItems(rawXML: raw)
                guard itemIndex >= 0 && itemIndex < items.count else {
                    throw StructuredRefusal("{ \"error\": \"out_of_bounds\", \"index\": \(itemIndex), \"count\": \(items.count) }")
                }
                let updated = Self.updateRepeatingSectionItemXML(
                    rawXML: raw, itemIndex: itemIndex, newText: text
                )
                para.runs[runIdx].rawXML = updated
                doc.body.children[childIdx] = .paragraph(para)
                found = true
                break
            }
            if found { break }
        }
        guard found else {
            throw StructuredRefusal("{ \"error\": \"not_found\", \"parent_id\": \(parentId) }")
        }

        try await storeDocument(doc, for: docId)
        return "Updated repeating section parent_id=\(parentId) item_index=\(itemIndex)"
    }

    // MARK: - #44 Phase 8.1: list_custom_xml_parts stub
    // TODO: replace with real implementation in Change B
    // (`che-word-mcp-customxml-databinding`).

    private func listCustomXmlParts(args: [String: Value]) async throws -> String {
        // Validate doc_id / source_path is at least present (so we surface
        // bad-path errors consistently with future implementation).
        if args["doc_id"] == nil && args["source_path"] == nil {
            throw WordError.missingParameter("doc_id or source_path")
        }
        return "[]"
    }

    // MARK: - SDT helpers

    /// Load the document either from openDocuments (doc_id) or by reading
    /// the source_path directly. Used by read-only tools that support both modes.
    /// Shared by 7 read-only tools (`listContentControls`, `getContentControl`,
    /// `getStyleInheritanceChain`, `listNumberingDefinitions`,
    /// `getNumberingDefinition`, `getAllSections`, `getSectionHeaderMapTool`).
    private func loadDocumentFromArgs(_ args: [String: Value]) async throws -> WordDocument {
        if let docId = args["doc_id"]?.stringValue {
            guard let doc = openDocuments[docId] else {
                throw WordError.documentNotFound(docId)
            }
            return doc
        }
        if let path = args["source_path"]?.stringValue {
            // R2 (#221 H2, `review-cwm450.md` finding): every one of the 7
            // callers above is read-only and none of them touches
            // `archiveTempDir` afterward — safe to release the extracted
            // tempDir right here, before returning, same shape as #221's
            // `resolveDocument` Direct Mode fix.
            var doc = try DocxReader.read(from: URL(fileURLWithPath: path))
            logDebug(event: "loadDocumentFromArgs.archiveExtracted", [
                ("archive_temp_dir", doc.archiveTempDir?.path ?? "nil"),
            ])
            doc.close()
            return doc
        }
        throw WordError.missingParameter("doc_id or source_path")
    }

    /// Extract human-readable text from a ContentControl.content field.
    /// The content can be:
    /// - Plain text (no XML tags) — returned as-is
    /// - XML fragment with `<w:t>` runs — text content is concatenated
    /// MCP callers see "Acme Corp" regardless of how the SDT was inserted.
    static func extractTextFromContentXML(_ xml: String) -> String {
        guard !xml.isEmpty else { return "" }
        // Plain text fast path: no XML tags at all.
        if !xml.contains("<") {
            return xml
        }
        // Concatenate every <w:t ...>TEXT</w:t> body in document order.
        var out = ""
        let pattern = #"<w:t[^>]*>([^<]*)</w:t>"#
        guard let regex = try? NSRegularExpression(pattern: pattern) else { return xml }
        let range = NSRange(xml.startIndex..., in: xml)
        regex.enumerateMatches(in: xml, range: range) { match, _, _ in
            guard let m = match, let r = Range(m.range(at: 1), in: xml) else { return }
            out += xml[r]
        }
        return out
    }

    /// Parse the items inside a `<w15:repeatingSection>` rawXML blob and
    /// return their text contents in document order.
    static func parseRepeatingSectionItems(rawXML: String) -> [String] {
        // Each item is `<w:sdt>...<w15:repeatingSectionItem.../>...<w:sdtContent>...</w:sdtContent></w:sdt>`.
        // We extract the innermost `<w:t>...</w:t>` of each item.
        var items: [String] = []
        // Each item: `<w:sdt>...<w15:repeatingSectionItem ... />...</w:sdt>`.
        // The marker tag has `xmlns:w15="...//.../wordml"` attribute — URL slashes
        // mean we cannot use `[^/]*`, so we use a non-greedy `[^>]*?` up to `/>`.
        let itemPattern = #"<w:sdt>(?:(?!</w:sdt>).)*?<w15:repeatingSectionItem[^>]*?/>(?:(?!</w:sdt>).)*?</w:sdt>"#
        guard let itemRegex = try? NSRegularExpression(pattern: itemPattern, options: [.dotMatchesLineSeparators]) else {
            return []
        }
        let range = NSRange(rawXML.startIndex..., in: rawXML)
        let textPattern = #"<w:t[^>]*>([^<]*)</w:t>"#
        let textRegex = try? NSRegularExpression(pattern: textPattern)
        itemRegex.enumerateMatches(in: rawXML, range: range) { match, _, _ in
            guard let m = match, let r = Range(m.range, in: rawXML) else { return }
            let itemXml = String(rawXML[r])
            var text = ""
            let itemRange = NSRange(itemXml.startIndex..., in: itemXml)
            textRegex?.enumerateMatches(in: itemXml, range: itemRange) { tm, _, _ in
                guard let tm = tm, let tr = Range(tm.range(at: 1), in: itemXml) else { return }
                text += itemXml[tr]
            }
            items.append(text)
        }
        return items
    }

    /// Replace the text content of the Nth `<w15:repeatingSectionItem>` inside
    /// a rawXML blob. Used by `update_repeating_section_item`.
    static func updateRepeatingSectionItemXML(rawXML: String, itemIndex: Int, newText: String) -> String {
        // Each item: `<w:sdt>...<w15:repeatingSectionItem ... />...</w:sdt>`.
        // The marker tag has `xmlns:w15="...//.../wordml"` attribute — URL slashes
        // mean we cannot use `[^/]*`, so we use a non-greedy `[^>]*?` up to `/>`.
        let itemPattern = #"<w:sdt>(?:(?!</w:sdt>).)*?<w15:repeatingSectionItem[^>]*?/>(?:(?!</w:sdt>).)*?</w:sdt>"#
        guard let itemRegex = try? NSRegularExpression(pattern: itemPattern, options: [.dotMatchesLineSeparators]) else {
            return rawXML
        }
        let range = NSRange(rawXML.startIndex..., in: rawXML)
        let matches = itemRegex.matches(in: rawXML, range: range)
        guard itemIndex >= 0 && itemIndex < matches.count else { return rawXML }

        let itemMatchRange = matches[itemIndex].range
        guard let itemRange = Range(itemMatchRange, in: rawXML) else { return rawXML }
        let itemXml = String(rawXML[itemRange])

        // Replace the first <w:t...>...</w:t> in this item with the new text.
        let escaped = newText
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
        let replacement = "<w:t xml:space=\"preserve\">\(escaped)</w:t>"
        let textPattern = #"<w:t[^>]*>[^<]*</w:t>"#
        guard let textRegex = try? NSRegularExpression(pattern: textPattern) else { return rawXML }
        let updatedItem = textRegex.stringByReplacingMatches(
            in: itemXml,
            range: NSRange(itemXml.startIndex..., in: itemXml),
            withTemplate: replacement
        )

        return rawXML.replacingOccurrences(of: itemXml, with: updatedItem)
    }

    /// Minimal JSON string escaper — handles the cases that appear in SDT
    /// metadata (quotes, backslashes, control characters under ASCII 0x20).
    static func jsonEscape(_ s: String) -> String {
        var out = ""
        for scalar in s.unicodeScalars {
            switch scalar {
            case "\"": out += "\\\""
            case "\\": out += "\\\\"
            case "\n": out += "\\n"
            case "\r": out += "\\r"
            case "\t": out += "\\t"
            default:
                if scalar.value < 0x20 {
                    out += String(format: "\\u%04x", scalar.value)
                } else {
                    out += String(scalar)
                }
            }
        }
        return out
    }

    // MARK: - P9 新增功能

    // 9.1 insert_text - 在指定位置插入文字
    private func insertText(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let text = args["text"]?.stringValue else {
            throw WordError.missingParameter("text")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let position = try optionalInt(args, "position")

        // #140: bounds-check and the text this reads MUST use the same
        // counting model `doc.updateParagraph(at:)` mutates with below —
        // top-level `.paragraph` body children only, NOT `getParagraphs()`
        // (which additionally recurses into block-level SDTs). Using the
        // readback family here let an index that only existed because of an
        // SDT-inner paragraph pass the bounds check, read `currentText`
        // from that SDT-inner paragraph, and then have `updateParagraph`
        // (which only ever resolves top-level ordinals) silently overwrite
        // an unrelated top-level paragraph with it — reported as success
        // while discarding that paragraph's own text.
        let topLevelParagraphs: [Paragraph] = doc.body.children.compactMap {
            if case .paragraph(let p) = $0 { return p }
            return nil
        }
        guard paragraphIndex >= 0 && paragraphIndex < topLevelParagraphs.count else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        // 取得現有文字並在指定位置插入
        let currentText = topLevelParagraphs[paragraphIndex].getText()
        let insertPosition = position ?? currentText.count

        let startIndex = currentText.startIndex
        // R8 (independent fuzzer, `rev232b` H-234-4): `position: -1` trapped
        // `index(_:offsetBy:)`. R9 (review `rev232c` M-3): a negative position
        // is rejected, not clamped to 0. There was no contract to preserve
        // (negative values always crashed), the same-named `position` of
        // `insert_text_as_revision` already rejects it, and `-1` commonly
        // means "from the end" — clamping it to the START wrote the text in
        // the opposite place while reporting success. A position past the
        // end still lands at the end: that matches the schema's documented
        // default ("不指定則插入到段落末尾") and is the existing behavior.
        guard insertPosition >= 0 else {
            throw WordError.invalidParameter("position", "必須 ≥ 0（字元位置，從 0 起算）")
        }
        let actualPosition = min(insertPosition, currentText.count)
        let insertIndex = currentText.index(startIndex, offsetBy: actualPosition)
        let newText = String(currentText[..<insertIndex]) + text + String(currentText[insertIndex...])

        try doc.updateParagraph(at: paragraphIndex, text: newText)
        try await storeDocument(doc, for: docId)

        // R9 (review `rev232c` LOW-2): report where the text actually went,
        // not the requested value.
        if position == nil {
            return "Inserted text at paragraph \(paragraphIndex), position \(actualPosition) (at end)"
        }
        if actualPosition != insertPosition {
            return "Inserted text at paragraph \(paragraphIndex), position \(actualPosition) (requested \(insertPosition) is past the end; inserted at the end)"
        }
        return "Inserted text at paragraph \(paragraphIndex), position \(actualPosition)"
    }

    // 9.2 get_document_text - get_text 的別名
    private func getDocumentText(args: [String: Value]) async throws -> String {
        // 直接呼叫 getText，這是一個更直覺的別名
        return try await getText(args: args)
    }

    // 9.3 search_text - 搜尋文字
    /// #187: does `char` consist entirely of whitespace scalars? Mirrors the
    /// predicate `findInlineMathGaps` already uses for the same question.
    private func isWhitespaceCharacter(_ char: Character) -> Bool {
        char.unicodeScalars.allSatisfy { CharacterSet.whitespacesAndNewlines.contains($0) }
    }

    /// #187: `s` with every whitespace character removed. Used only to build
    /// the *query*/`find` side of a fallback comparison when a literal
    /// search/replace finds nothing — the fallback compares this stripped
    /// string against the paragraph's RAW (unstripped) parsed text, never a
    /// stripped copy of the haystack (R2 review Finding 3 — see
    /// `searchText`'s doc comment for why that distinction matters).
    private func stripWhitespace(_ s: String) -> String {
        String(s.filter { !isWhitespaceCharacter($0) })
    }

    /// #188: recursively walks a table's nested tables (`TableCell.
    /// nestedTables`), calling `visit` for every paragraph found — in the
    /// cell's own paragraphs AND at every nesting depth — with a `location`
    /// string that names the full path. `pathPrefix` already names the
    /// hosting cell (e.g. `"Table 1, row 26, col 0"`); this function appends
    /// `" > nested table N, row R, col C"` for each level of nesting so a
    /// caller can reconstruct the address `update_cell` accepts via
    /// `nested_table_index` / `nested_row` / `nested_col` (one level) or
    /// tell a human where to look (any level).
    private func walkNestedTables(
        in cell: TableCell, pathPrefix: String, visit: (Paragraph, String) -> Void
    ) {
        for (nestedIdx, nested) in cell.nestedTables.enumerated() {
            let tablePath = "\(pathPrefix) > nested table \(nestedIdx)"
            for (rowIdx, row) in nested.rows.enumerated() {
                for (cellIdx, nestedCell) in row.cells.enumerated() {
                    let cellPath = "\(tablePath), row \(rowIdx), col \(cellIdx)"
                    for para in nestedCell.paragraphs {
                        visit(para, cellPath)
                    }
                    // Recurse for depth > 1 (rare; ooxml-swift caps parsing
                    // depth at 5). `cellPath` becomes the next level's prefix.
                    walkNestedTables(in: nestedCell, pathPrefix: cellPath, visit: visit)
                }
            }
        }
    }

    /// search_text MCP tool.
    ///
    /// #187: `Paragraph.getText()` can return text with a whitespace-only
    /// run silently missing — a Foundation `XMLDocument` parsing limitation
    /// in the ooxml-swift dependency (not modified here; see #187 for the
    /// empirically-confirmed root cause). A literal search for text copied
    /// verbatim out of the source XML can then find nothing even though the
    /// text is right there in the file. When that happens AND `query`
    /// contains whitespace, this tool retries with whitespace stripped from
    /// the *query only*, matched against each paragraph's RAW parsed text.
    /// The literal pass is completely unchanged (same code, same output)
    /// whenever it finds at least one match — the fallback only ever adds
    /// results it would otherwise have silently omitted, never replaces or
    /// reorders existing ones.
    ///
    /// **Consistency with `replace_text` (R2 review Finding 3)**: the
    /// fallback here is deliberately the exact same comparison
    /// `replace_text`'s own fallback performs (matching a whitespace-
    /// stripped `find` against the runs' unstripped text via
    /// `doc.replaceText`) — for the same query/find against the same
    /// document, the two tools now always agree on whether a normalized
    /// match exists. An earlier version of this fallback stripped BOTH
    /// sides (query AND the paragraph's text), which made `search_text`
    /// report a "normalized match" merely because the query's whitespace
    /// *amount* differed from the document's — even when the document's own
    /// whitespace was intact and never lost — while `replace_text`, asked
    /// the identical question, correctly reported zero matches. Because a
    /// hit now requires the document's raw parsed text to have NO
    /// whitespace at all where the query expects some, a "normalized match"
    /// label is only ever shown when that specific, unambiguous kind of
    /// difference is present — see the result suffix text below.
    ///
    /// #188: recurses into nested tables (`TableCell.nestedTables`) that a
    /// pre-#188 version of this tool never visited — those cells were
    /// invisible to search, not merely mis-numbered.
    private func searchText(args: [String: Value]) async throws -> String {
        guard let query = args["query"]?.stringValue else {
            throw WordError.missingParameter("query")
        }
        let (doc, _) = try await resolveDocument(args: args)

        let caseSensitive = try optionalBool(args, "case_sensitive") ?? false

        struct SearchResult {
            let location: String
            let startPosition: Int
            let text: String
            let normalized: Bool
        }

        var results: [SearchResult] = []

        func searchInParagraph(_ para: Paragraph, location: String) {
            let paraText = para.getText()
            let haystack = caseSensitive ? paraText : paraText.lowercased()
            let needle = caseSensitive ? query : query.lowercased()

            var searchStart = haystack.startIndex
            while let range = haystack.range(of: needle, range: searchStart..<haystack.endIndex) {
                let position = haystack.distance(from: haystack.startIndex, to: range.lowerBound)
                let matchedText = String(paraText[range])
                results.append(SearchResult(location: location, startPosition: position, text: matchedText, normalized: false))
                searchStart = range.upperBound
            }
        }

        // #187 fallback pass (R2 review Finding 3 hardening): compares the
        // whitespace-stripped query against the paragraph's RAW (unstripped)
        // text — NOT a whitespace-stripped copy of the haystack. This is
        // deliberately the exact same comparison `replace_text`'s fallback
        // already performs (it calls `doc.replaceText(find: strippedFind,
        // ...)`, which matches `strippedFind` against the runs' own
        // unstripped text). Stripping the haystack too, as a pre-R2 version
        // of this function did, made `search_text` report a "normalized
        // match" whenever the query's whitespace *count* merely differed
        // from the document's — even when the document's own whitespace was
        // never lost at all (e.g. query "否  □是" with a typo'd extra space
        // against a document that correctly has "否 □是") — while
        // `replace_text`, asked the identical question, reported zero
        // matches for the same input. Matching against the raw haystack
        // means a hit can only occur when the document's parsed text has
        // NO whitespace at all between the characters the query expects it
        // between (the literal signature of a whitespace-only run's content
        // having been dropped during parsing) — the two tools now agree,
        // for any given query, on whether a normalized match exists.
        func searchInParagraphNormalized(_ para: Paragraph, location: String, strippedQuery: String) {
            let paraText = para.getText()
            guard !paraText.isEmpty else { return }
            let haystack = caseSensitive ? paraText : paraText.lowercased()
            let needle = caseSensitive ? strippedQuery : strippedQuery.lowercased()
            guard !needle.isEmpty else { return }

            var searchStart = haystack.startIndex
            while let range = haystack.range(of: needle, range: searchStart..<haystack.endIndex) {
                let position = haystack.distance(from: haystack.startIndex, to: range.lowerBound)
                let matchedText = String(paraText[range])
                results.append(SearchResult(location: location, startPosition: position, text: matchedText, normalized: true))
                searchStart = range.upperBound
            }
        }

        // 搜尋頂層段落和表格內的段落
        var paraIndex = 0
        var tableIndex = 0
        // Recursive walker so block-level SDT wrappers (#44) are transparent
        // for search purposes — matches inside SDT children appear with the
        // same paragraph/table index numbering as plain body siblings.
        func walk(_ children: [BodyChild], normalizedQuery: String?) {
            for child in children {
                switch child {
                case .paragraph(let para):
                    if let normalizedQuery {
                        searchInParagraphNormalized(para, location: "Paragraph \(paraIndex)", strippedQuery: normalizedQuery)
                    } else {
                        searchInParagraph(para, location: "Paragraph \(paraIndex)")
                    }
                    paraIndex += 1
                case .table(let table):
                    for (rowIdx, row) in table.rows.enumerated() {
                        for (cellIdx, cell) in row.cells.enumerated() {
                            let cellLocation = "Table \(tableIndex), row \(rowIdx), col \(cellIdx)"
                            for para in cell.paragraphs {
                                if let normalizedQuery {
                                    searchInParagraphNormalized(para, location: cellLocation, strippedQuery: normalizedQuery)
                                } else {
                                    searchInParagraph(para, location: cellLocation)
                                }
                            }
                            // #188: nested tables were previously invisible
                            // to search_text — not just mis-numbered.
                            walkNestedTables(in: cell, pathPrefix: cellLocation) { nestedPara, nestedLocation in
                                if let normalizedQuery {
                                    searchInParagraphNormalized(nestedPara, location: nestedLocation, strippedQuery: normalizedQuery)
                                } else {
                                    searchInParagraph(nestedPara, location: nestedLocation)
                                }
                            }
                        }
                    }
                    tableIndex += 1
                case .contentControl(_, children: let inner):
                    walk(inner, normalizedQuery: normalizedQuery)
                case .bookmarkMarker, .rawBlockElement:
                    // ooxml-swift v0.19.6+ (#58): body-level markers carry no
                    // searchable text — skip.
                    continue
                }
            }
        }
        walk(doc.body.children, normalizedQuery: nil)

        // #187: only attempted when the literal pass found nothing AND the
        // query actually contains whitespace (otherwise stripping changes
        // nothing and re-running would just waste a full document walk).
        if results.isEmpty, query.contains(where: isWhitespaceCharacter) {
            let strippedQuery = stripWhitespace(query)
            if !strippedQuery.isEmpty {
                paraIndex = 0
                tableIndex = 0
                walk(doc.body.children, normalizedQuery: strippedQuery)
            }
        }

        if results.isEmpty {
            return "No matches found for '\(query)'"
        }

        var output = "Found \(results.count) match(es) for '\(query)':\n"
        for result in results {
            let suffix = result.normalized
                ? " (normalized match — the parsed document text has NO whitespace between these characters even though the query does; a whitespace-only run may be missing from the parsed document, see search_text's tool description)"
                : ""
            output += "- \(result.location), position \(result.startPosition): \"\(result.text)\"\(suffix)\n"
        }
        return output
    }

    private func findInlineMathGaps(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)
        // Upper-bound clamps prevent caller-triggered Int overflow trap in
        // `i + contextChars` (issue #130). 4096 chars is far more context than
        // any human reads at a glance; min_gap_chars 1024 covers the longest
        // plausible accidental whitespace run (a fully-blanked paragraph).
        let minGapChars = min(max(1, try optionalInt(args, "min_gap_chars") ?? 2), 1024)
        let contextChars = min(max(0, try optionalInt(args, "context_chars") ?? 30), 4096)
        let excludeTableCaptions = try optionalBool(args, "exclude_table_captions") ?? true
        // #178 truncation policy: full text by default, opt in to elide.
        let summarize = try optionalBool(args, "summarize") ?? false
        // #131: a 1000-page document can produce tens of thousands of gaps,
        // each carrying its own paragraph's full flattened text — bound the
        // returned window the same way list_comments/find_unresolved_comments
        // do, with the same non-silent disclosure envelope.
        let (limit, offset) = try resolveLimitOffset(args, defaultLimit: 500, maxLimit: 5000)

        struct Gap {
            let paragraphIndex: Int
            let location: String
            let gapPosition: Int
            let gapLength: Int
            let contextBefore: String
            let contextAfter: String
            let flattenedText: String
        }

        var gaps: [Gap] = []

        func isWhitespace(_ char: Character) -> Bool {
            char.unicodeScalars.allSatisfy { CharacterSet.whitespacesAndNewlines.contains($0) }
        }

        func scanParagraph(_ para: Paragraph, paragraphIndex: Int?, location: String) {
            let text = para.flattenedDisplayText()
            guard !text.isEmpty else { return }
            // #136: pass paragraph (not text) so isLikelyTableCaption can check
            // Paragraph.properties.style as primary signal, with text-prefix fallback.
            if excludeTableCaptions && isLikelyTableCaption(para) { return }

            let chars = Array(text)
            var i = 0
            while i < chars.count {
                guard isWhitespace(chars[i]) else {
                    i += 1
                    continue
                }

                let start = i
                while i < chars.count, isWhitespace(chars[i]) {
                    i += 1
                }
                let length = i - start
                let hasNonWhitespaceBefore = start > 0 && !isWhitespace(chars[start - 1])
                let hasNonWhitespaceAfter = i < chars.count && !isWhitespace(chars[i])
                guard length >= minGapChars, hasNonWhitespaceBefore, hasNonWhitespaceAfter else {
                    continue
                }

                let beforeStart = max(0, start - contextChars)
                let afterEnd = min(chars.count, i + contextChars)
                gaps.append(Gap(
                    paragraphIndex: paragraphIndex ?? -1,
                    location: location,
                    gapPosition: start,
                    gapLength: length,
                    contextBefore: String(chars[beforeStart..<start]),
                    contextAfter: String(chars[i..<afterEnd]),
                    flattenedText: text
                ))
            }
        }

        var paragraphCounter = 0
        var tableCounter = 0

        func scanTable(_ table: Table, tablePath: String) {
            for (rowIndex, row) in table.rows.enumerated() {
                for (cellIndex, cell) in row.cells.enumerated() {
                    for (paraIndex, para) in cell.paragraphs.enumerated() {
                        scanParagraph(
                            para,
                            paragraphIndex: nil,
                            location: "\(tablePath).row[\(rowIndex)].col[\(cellIndex)].paragraph[\(paraIndex)]"
                        )
                    }
                    for (nestedIndex, nested) in cell.nestedTables.enumerated() {
                        scanTable(
                            nested,
                            tablePath: "\(tablePath).row[\(rowIndex)].col[\(cellIndex)].nested_table[\(nestedIndex)]"
                        )
                    }
                }
            }
        }

        func walk(_ children: [BodyChild]) {
            for child in children {
                switch child {
                case .paragraph(let para):
                    scanParagraph(para, paragraphIndex: paragraphCounter, location: "paragraph[\(paragraphCounter)]")
                    paragraphCounter += 1
                case .table(let table):
                    scanTable(table, tablePath: "table[\(tableCounter)]")
                    tableCounter += 1
                case .contentControl(_, children: let inner):
                    walk(inner)
                case .bookmarkMarker, .rawBlockElement:
                    continue
                }
            }
        }

        walk(doc.body.children)

        let total = gaps.count
        let startIndex = min(offset, total)
        let endIndex = min(startIndex + limit, total)
        let window = gaps[startIndex..<endIndex]

        let entries = window.map { gap in
            [
                "\"paragraph_index\":\(gap.paragraphIndex)",
                "\"location\":\"\(Self.jsonEscape(gap.location))\"",
                "\"gap_position\":\(gap.gapPosition)",
                "\"gap_length\":\(gap.gapLength)",
                "\"context_before\":\"\(Self.jsonEscape(gap.contextBefore))\"",
                "\"context_after\":\"\(Self.jsonEscape(gap.contextAfter))\"",
                // #131/#178: opt-in elision, not a silent hardcoded prefix.
                "\"flattened_text\":\"\(Self.jsonEscape(truncateText(gap.flattenedText, summarize: summarize)))\""
            ].joined(separator: ",")
        }.map { "{\($0)}" }

        return paginationEnvelope(total: total, offset: startIndex, returned: entries.count, arrayKey: "gaps", arrayJSON: "[\(entries.joined(separator: ","))]")
    }

    /// Detects whether a paragraph is likely a Word caption (Table / Figure / 表 / 圖 / etc.).
    ///
    /// Two-layer detection (#136 fix; verify finding from #112):
    ///
    /// **Layer 1 — Paragraph.style (primary, ground truth)**: Word's `Caption`
    /// style is the canonical OOXML signal. Substring match on lowercased
    /// style name catches `Caption`, `ImageCaption`, `TableCaption`, etc.
    ///
    /// **Layer 2 — text prefix (fallback)**: covers paragraphs without
    /// explicit style attribute (e.g. parsed from imported docx). Expanded
    /// from 5 to 11 prefix variants to cover Figure / Tab. / Fig. / Listing
    /// + CJK U+3000 ideographic space + 表数字 / 圖数字 (no separator).
    ///
    /// **False-positive guard**: previous text-only impl (`hasPrefix("Table ")`)
    /// matched body sentences like "Table reservations are required..."
    /// when no style was set. Layer 1 fires only on style match, so a
    /// `Heading 1`-styled paragraph beginning with "table" is NOT skipped.
    ///
    /// `internal` (not `private`) so `@testable import` tests can exercise
    /// the heuristic directly without spinning up the full MCP server.
    internal func isLikelyTableCaption(_ paragraph: Paragraph) -> Bool {
        // Layer 1: style-based detection (primary)
        if let style = paragraph.properties.style?.lowercased(),
           style.contains("caption") {
            return true
        }

        // Layer 2: expanded prefix fallback with digit-after-prefix guard
        //
        // The digit guard fixes the pre-existing false-positive case where
        // body sentences starting with "Table " (e.g. "Table reservations are
        // required..." or "Table of contents") were misidentified as captions.
        // Real captions virtually always have a number after the prefix:
        // "Table 1", "Figure 2", "圖 1", "表3-1". Body sentences don't.
        let trimmed = paragraph.flattenedDisplayText().trimmingCharacters(in: .whitespacesAndNewlines)
        let lower = trimmed.lowercased()

        // Helper: char immediately after a matched prefix is a digit.
        func nextCharIsDigit(after prefix: String, in source: String) -> Bool {
            guard source.count > prefix.count else { return false }
            let idx = source.index(source.startIndex, offsetBy: prefix.count)
            return source[idx].isNumber
        }

        // English caption prefixes (case-insensitive) — require digit follow-up
        let englishPrefixes = ["table ", "table\t", "figure ", "figure\t", "tab. ", "fig. ", "listing "]
        for prefix in englishPrefixes where lower.hasPrefix(prefix) {
            if nextCharIsDigit(after: prefix, in: lower) {
                return true
            }
            // Matched prefix but no digit after → likely body text ("Table of contents",
            // "Figure shows that..."). Don't return true; fall through to other layers
            // (none, but be explicit).
            return false
        }

        // CJK caption prefixes — separator variants + U+3000 ideographic space
        // Same digit-after-prefix guard for symmetry.
        let cjkPrefixes = [
            "表 ", "表\t", "表\u{3000}",
            "圖 ", "圖\t", "圖\u{3000}",
            "图 ", "图\t", "图\u{3000}"
        ]
        for prefix in cjkPrefixes where trimmed.hasPrefix(prefix) {
            if nextCharIsDigit(after: prefix, in: trimmed) {
                return true
            }
            return false
        }

        // 表格 / 图表 — multi-char CJK forms commonly used as caption labels
        // (less ambiguous than bare 表 / 圖). Keep accepting these without digit guard.
        if trimmed.hasPrefix("表格") || trimmed.hasPrefix("图表") {
            return true
        }

        // CJK no-separator forms: 表3-1 / 圖1 / 图2.5
        // Match `^[表圖图]\d` (prefix is one CJK char + digit; covers 表3-1, 圖1.2, 图2;
        // excludes 表面 / 圖案 / 图案 since second char must be digit).
        if let firstChar = trimmed.first,
           "表圖图".contains(firstChar),
           trimmed.count >= 2 {
            let secondIndex = trimmed.index(after: trimmed.startIndex)
            let secondChar = trimmed[secondIndex]
            if secondChar.isNumber {
                return true
            }
        }

        return false
    }

    // 9.4 list_hyperlinks - 列出所有超連結
    private func listHyperlinks(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)

        let hyperlinks = doc.getHyperlinks()
        if hyperlinks.isEmpty {
            return "No hyperlinks in document"
        }

        var output = "Hyperlinks in document (\(hyperlinks.count)):\n"
        for (index, link) in hyperlinks.enumerated() {
            let displayText = link.text
            let target = link.url ?? link.anchor ?? "(unknown target)"
            output += "[\(index)] (\(link.type)) \(displayText) -> \(target)\n"
        }
        return output
    }

    // 9.5 list_bookmarks - 列出所有書籤
    private func listBookmarks(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)

        let bookmarks = doc.getBookmarks()
        if bookmarks.isEmpty {
            return "No bookmarks in document"
        }

        var output = "Bookmarks in document (\(bookmarks.count)):\n"
        for (index, bookmark) in bookmarks.enumerated() {
            output += "[\(index)] \(bookmark.name)\n"
        }
        return output
    }

    // 9.6 list_footnotes - 列出所有腳註
    private func listFootnotes(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)

        // #178 — same shape as get_paragraphs: unconditional 50-char cut plus
        // an unconditional "..." that claimed an elision which may not have
        // happened.
        // #232 R6 (review H2a): parsed before the empty-document early
        // return, not after — same fix as R1's list_comments.
        let summarize = try optionalBool(args, "summarize") ?? false

        let footnotes = doc.getFootnotes()
        if footnotes.isEmpty {
            return "No footnotes in document"
        }

        var output = "Footnotes in document (\(footnotes.count)):\n"
        for footnote in footnotes {
            output += "[\(footnote.id)] \(truncateText(footnote.text, summarize: summarize))\n"
        }
        return output
    }

    // 9.7 list_endnotes - 列出所有尾註
    private func listEndnotes(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)

        // #178 — same shape as get_paragraphs / list_footnotes.
        // #232 R6 (review H2a): parsed before the empty-document early
        // return, not after — same fix as R1's list_comments.
        let summarize = try optionalBool(args, "summarize") ?? false

        let endnotes = doc.getEndnotes()
        if endnotes.isEmpty {
            return "No endnotes in document"
        }

        var output = "Endnotes in document (\(endnotes.count)):\n"
        for endnote in endnotes {
            output += "[\(endnote.id)] \(truncateText(endnote.text, summarize: summarize))\n"
        }
        return output
    }

    // 9.8 get_revisions - 取得所有修訂記錄
    private func getRevisions(args: [String: Value]) async throws -> String {
        // Reject deprecated full_text parameter (replaced by summarize, inverted default).
        // Spec: word-mcp-markdown-export — Requirement: full_text parameter is removed.
        if args["full_text"] != nil {
            throw WordError.invalidParameter(
                "full_text",
                "removed in this release; use 'summarize' (inverted default — pass summarize: true to enable elision; omit for complete text)"
            )
        }

        let (doc, _) = try await resolveDocument(args: args)
        let summarize = try optionalBool(args, "summarize") ?? false

        let revisions = doc.getRevisions()
        if revisions.isEmpty {
            return "No revisions in document"
        }

        var output = "Revisions in document (\(revisions.count)):\n"
        for revision in revisions {
            // revision.type 是 String (rawValue)
            let typeStr = revision.type.uppercased()
            let author = revision.author
            output += "[\(revision.id)] \(typeStr) by \(author) at paragraph \(revision.paragraphIndex)\n"
            if let original = revision.originalText {
                output += "    Original: \(truncateText(original, summarize: summarize))\n"
            }
            if let newText = revision.newText {
                output += "    New: \(truncateText(newText, summarize: summarize))\n"
            }
        }
        return output
    }

    // 9.9 accept_all_revisions - 接受所有修訂
    private func acceptAllRevisions(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let count = doc.getRevisions().count
        doc.acceptAllRevisions()
        try await storeDocument(doc, for: docId)

        return "Accepted \(count) revision(s)"
    }

    // 9.10 reject_all_revisions - 拒絕所有修訂
    private func rejectAllRevisions(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let count = doc.getRevisions().count
        doc.rejectAllRevisions()
        try await storeDocument(doc, for: docId)

        return "Rejected \(count) revision(s)"
    }

    // 9.11 set_document_properties - 設定文件屬性
    private func setDocumentProperties(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        var props = doc.properties

        if let title = args["title"]?.stringValue {
            props.title = title
        }
        if let subject = args["subject"]?.stringValue {
            props.subject = subject
        }
        if let creator = args["creator"]?.stringValue {
            props.creator = creator
        }
        if let keywords = args["keywords"]?.stringValue {
            props.keywords = keywords
        }
        if let description = args["description"]?.stringValue {
            props.description = description
        }

        doc.properties = props
        // v3.5.0: properties is a public field — direct assignment bypasses
        // ooxml-swift's instrumented setters, so we mark docProps/core.xml dirty
        // explicitly. Without this, save_document overlay mode would skip it.
        doc.markPartDirty("docProps/core.xml")
        try await storeDocument(doc, for: docId)

        return "Updated document properties"
    }

    // 9.12 get_document_properties - 取得文件屬性
    private func getDocumentProperties(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)

        let props = doc.properties

        var output = "Document Properties:\n"
        if let title = props.title { output += "- Title: \(title)\n" }
        if let subject = props.subject { output += "- Subject: \(subject)\n" }
        if let creator = props.creator { output += "- Creator: \(creator)\n" }
        if let keywords = props.keywords { output += "- Keywords: \(keywords)\n" }
        if let description = props.description { output += "- Description: \(description)\n" }
        if let lastModifiedBy = props.lastModifiedBy { output += "- Last Modified By: \(lastModifiedBy)\n" }
        if let revision = props.revision { output += "- Revision: \(revision)\n" }
        if let created = props.created { output += "- Created: \(created)\n" }
        if let modified = props.modified { output += "- Modified: \(modified)\n" }

        if output == "Document Properties:\n" {
            return "No document properties set"
        }

        return output
    }

    // 9.13 get_paragraph_runs - 取得段落的 runs 及格式
    private func getParagraphRuns(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let paragraphs = doc.getParagraphs()
        guard paragraphIndex >= 0 && paragraphIndex < paragraphs.count else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        let para = paragraphs[paragraphIndex]
        var output = "Paragraph [\(paragraphIndex)] Runs:\n"

        for (runIndex, run) in para.runs.enumerated() {
            output += "  Run [\(runIndex)]:\n"
            output += "    Text: \"\(run.text)\"\n"

            // 格式資訊
            let props = run.properties
            var formatParts: [String] = []

            if props.bold { formatParts.append("bold") }
            if props.italic { formatParts.append("italic") }
            if props.strikethrough { formatParts.append("strikethrough") }
            if let underline = props.underline { formatParts.append("underline:\(underline.rawValue)") }
            if let color = props.color { formatParts.append("color:#\(color)") }
            if let highlight = props.highlight { formatParts.append("highlight:\(highlight.rawValue)") }
            if let fontSize = props.fontSize { formatParts.append("size:\(fontSize / 2)pt") }
            if let fontName = props.fontName { formatParts.append("font:\(fontName)") }
            if let verticalAlign = props.verticalAlign { formatParts.append("vertAlign:\(verticalAlign.rawValue)") }

            if formatParts.isEmpty {
                output += "    Format: (none)\n"
            } else {
                output += "    Format: \(formatParts.joined(separator: ", "))\n"
            }
        }

        // 也顯示超連結
        if !para.hyperlinks.isEmpty {
            output += "  Hyperlinks:\n"
            for hyperlink in para.hyperlinks {
                output += "    - \"\(hyperlink.text)\" -> \(hyperlink.url ?? hyperlink.anchor ?? "unknown")\n"
            }
        }

        return output
    }

    // 9.14 get_text_with_formatting - 取得帶格式標記的文字
    private func getTextWithFormatting(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let paragraphs = doc.getParagraphs()

        // 如果指定了段落索引，只處理該段落
        if let paragraphIndex = try optionalInt(args, "paragraph_index") {
            guard paragraphIndex >= 0 && paragraphIndex < paragraphs.count else {
                throw WordError.invalidIndex(paragraphIndex)
            }
            return formatParagraphWithMarkup(paragraphs[paragraphIndex], index: paragraphIndex)
        }

        // 處理所有段落
        var output = ""
        for (index, para) in paragraphs.enumerated() {
            output += formatParagraphWithMarkup(para, index: index) + "\n"
        }

        return output.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    // Helper: 將段落轉換為帶格式標記的文字
    private func formatParagraphWithMarkup(_ para: Paragraph, index: Int) -> String {
        var result = "[\(index)] "

        for run in para.runs {
            var text = run.text
            let props = run.properties

            // 加入格式標記
            if props.bold {
                text = "**\(text)**"
            }
            if props.italic {
                text = "*\(text)*"
            }
            if props.strikethrough {
                text = "~~\(text)~~"
            }
            if let color = props.color {
                // 常見顏色轉換為名稱
                let colorName = colorHexToName(color)
                text = "{{color:\(colorName)}}\(text){{/color}}"
            }
            if let highlight = props.highlight {
                text = "{{highlight:\(highlight.rawValue)}}\(text){{/highlight}}"
            }
            if let underline = props.underline {
                text = "{{underline:\(underline.rawValue)}}\(text){{/underline}}"
            }

            result += text
        }

        // 加入超連結
        for hyperlink in para.hyperlinks {
            result += " [\(hyperlink.text)](\(hyperlink.url ?? "#\(hyperlink.anchor ?? "")"))"
        }

        return result
    }

    // Helper: 顏色 hex 轉名稱
    private func colorHexToName(_ hex: String) -> String {
        let upperHex = hex.uppercased()
        switch upperHex {
        case "FF0000": return "red"
        case "00FF00": return "green"
        case "0000FF": return "blue"
        case "FFFF00": return "yellow"
        case "00FFFF": return "cyan"
        case "FF00FF": return "magenta"
        case "000000": return "black"
        case "FFFFFF": return "white"
        case "808080": return "gray"
        case "FFA500": return "orange"
        case "800080": return "purple"
        default: return "#\(hex)"
        }
    }

    // 9.15 search_by_formatting - 搜尋特定格式的文字
    private func searchByFormatting(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // 取得搜尋條件
        let searchColor = args["color"]?.stringValue?.uppercased()
        let searchBold = try optionalBool(args, "bold")
        let searchItalic = try optionalBool(args, "italic")
        let searchHighlight = args["highlight"]?.stringValue

        let paragraphs = doc.getParagraphs()
        var results: [(paragraphIndex: Int, runIndex: Int, text: String, format: String)] = []

        for (paraIndex, para) in paragraphs.enumerated() {
            for (runIndex, run) in para.runs.enumerated() {
                let props = run.properties
                var matches = true

                // 檢查顏色
                if let color = searchColor {
                    if props.color?.uppercased() != color {
                        matches = false
                    }
                }

                // 檢查粗體
                if let bold = searchBold {
                    if props.bold != bold {
                        matches = false
                    }
                }

                // 檢查斜體
                if let italic = searchItalic {
                    if props.italic != italic {
                        matches = false
                    }
                }

                // 檢查螢光標記
                if let highlight = searchHighlight {
                    if props.highlight?.rawValue != highlight {
                        matches = false
                    }
                }

                // 如果符合且文字不為空，加入結果
                if matches && !run.text.isEmpty {
                    var formatParts: [String] = []
                    if props.bold { formatParts.append("bold") }
                    if props.italic { formatParts.append("italic") }
                    if let color = props.color { formatParts.append("color:#\(color)") }
                    if let highlight = props.highlight { formatParts.append("highlight:\(highlight.rawValue)") }

                    results.append((
                        paragraphIndex: paraIndex,
                        runIndex: runIndex,
                        text: run.text,
                        format: formatParts.isEmpty ? "(none)" : formatParts.joined(separator: ", ")
                    ))
                }
            }
        }

        if results.isEmpty {
            return "No text found matching the specified formatting"
        }

        var output = "Found \(results.count) match(es):\n"
        for result in results {
            output += "  [Para \(result.paragraphIndex), Run \(result.runIndex)]: \"\(result.text)\"\n"
            output += "    Format: \(result.format)\n"
        }

        return output
    }

    // 9.16 search_text_with_formatting - 搜尋文字並顯示格式
    private func searchTextWithFormatting(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let query = args["query"]?.stringValue else {
            throw WordError.missingParameter("query")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let caseSensitive = try optionalBool(args, "case_sensitive") ?? false
        // #234 (full-file audit, beyond the issue's 8 listed sites): this
        // was the only `context_chars` in the file with NO upper bound at
        // all — `find_inline_math_gaps` already clamps to `min(max(0, …),
        // 4096)`. Unbounded, `position - contextChars` / `position +
        // matchedText.count + contextChars` below can under/overflow Int
        // and trap (e.g. `context_chars: Int.min` on the subtraction,
        // `context_chars: Int.max` on the addition). Clamped to the same
        // [0, 4096] range as `find_inline_math_gaps` for consistency with
        // that sibling parameter rather than introducing a fourth policy —
        // this is a display/formatting knob with no OOXML-typed output, so
        // silent clamping (matching 3 existing siblings) rather than
        // rejecting is the less disruptive fix for a purely internal bound.
        let contextChars = min(max(0, try optionalInt(args, "context_chars") ?? 20), 4096)

        let paragraphs = doc.getParagraphs()
        var results: [(paraIndex: Int, position: Int, matchedText: String, context: String, formats: [String])] = []

        for (paraIndex, para) in paragraphs.enumerated() {
            let paraText = para.getText()
            let searchText = caseSensitive ? paraText : paraText.lowercased()
            let searchQuery = caseSensitive ? query : query.lowercased()

            var searchStart = searchText.startIndex
            while let range = searchText.range(of: searchQuery, range: searchStart..<searchText.endIndex) {
                let position = searchText.distance(from: searchText.startIndex, to: range.lowerBound)
                let matchedText = String(paraText[range])

                // 取得上下文
                let contextStart = max(0, position - contextChars)
                let contextEnd = min(paraText.count, position + matchedText.count + contextChars)
                let startIndex = paraText.index(paraText.startIndex, offsetBy: contextStart)
                let endIndex = paraText.index(paraText.startIndex, offsetBy: contextEnd)
                var context = String(paraText[startIndex..<endIndex])
                if contextStart > 0 { context = "..." + context }
                if contextEnd < paraText.count { context = context + "..." }

                // 找出該位置的格式
                var formats: [String] = []
                var currentPos = 0
                for run in para.runs {
                    let runEnd = currentPos + run.text.count
                    // 檢查這個 run 是否包含搜尋結果
                    if currentPos <= position && position < runEnd {
                        let props = run.properties
                        if props.bold { formats.append("bold") }
                        if props.italic { formats.append("italic") }
                        if props.strikethrough { formats.append("strikethrough") }
                        if let color = props.color {
                            formats.append("color:\(colorHexToName(color))")
                        }
                        if let highlight = props.highlight {
                            formats.append("highlight:\(highlight.rawValue)")
                        }
                        if let underline = props.underline {
                            formats.append("underline:\(underline.rawValue)")
                        }
                        break
                    }
                    currentPos = runEnd
                }

                results.append((paraIndex, position, matchedText, context, formats))
                searchStart = range.upperBound
            }
        }

        if results.isEmpty {
            return "No matches found for '\(query)'"
        }

        var output = "Found \(results.count) match(es) for '\(query)':\n"
        for result in results {
            output += "[Para \(result.paraIndex)] \(result.context)\n"
            if result.formats.isEmpty {
                output += "  Format: (none)\n"
            } else {
                output += "  Format: \(result.formats.joined(separator: ", "))\n"
            }
        }
        return output
    }

    // 9.17 list_all_formatted_text - 列出特定格式的所有文字
    private func listAllFormattedText(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let formatType = args["format_type"]?.stringValue?.lowercased() else {
            throw WordError.missingParameter("format_type")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let colorFilter = args["color_filter"]?.stringValue?.uppercased()
        let paragraphStart = try optionalInt(args, "paragraph_start") ?? 0
        let paragraphEnd = try optionalInt(args, "paragraph_end")

        let paragraphs = doc.getParagraphs()
        let endIndex = paragraphEnd ?? paragraphs.count - 1

        guard paragraphStart >= 0 && paragraphStart < paragraphs.count else {
            throw WordError.invalidIndex(paragraphStart)
        }
        guard endIndex >= paragraphStart && endIndex < paragraphs.count else {
            throw WordError.invalidIndex(endIndex)
        }

        var results: [(paraIndex: Int, text: String)] = []

        for paraIndex in paragraphStart...endIndex {
            let para = paragraphs[paraIndex]
            for run in para.runs {
                let props = run.properties
                var matches = false

                switch formatType {
                case "italic":
                    matches = props.italic
                case "bold":
                    matches = props.bold
                case "underline":
                    matches = props.underline != nil
                case "strikethrough":
                    matches = props.strikethrough
                case "highlight":
                    matches = props.highlight != nil
                case "color":
                    if let colorFilter = colorFilter {
                        matches = props.color?.uppercased() == colorFilter
                    } else {
                        matches = props.color != nil
                    }
                default:
                    break
                }

                if matches && !run.text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    results.append((paraIndex, run.text))
                }
            }
        }

        // #178 — this one already gated its ellipsis on length, so it never
        // claimed an elision that had not happened. What it violated is the
        // other half of the SHALL: a 60-character ceiling nobody asked for.
        // #232 R6 (review H2a): parsed before the empty-results early
        // return, not after — same fix as R1's list_comments.
        let summarize = try optionalBool(args, "summarize") ?? false

        if results.isEmpty {
            let rangeInfo = paragraphEnd != nil ? " in paragraphs \(paragraphStart)-\(endIndex)" : ""
            return "No \(formatType) text found\(rangeInfo)"
        }

        var output = "Found \(results.count) \(formatType) text segment(s):\n"
        for result in results {
            let displayText = truncateText(result.text, summarize: summarize)
            output += "[Para \(result.paraIndex)] \"\(displayText)\"\n"
        }
        return output
    }

    // 9.18 get_word_count_by_section - 按區段統計字數
    private func getWordCountBySection(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)

        // 解析區段標記
        var sectionMarkers: [String] = []
        if let markersValue = args["section_markers"] {
            if let markersArray = markersValue.arrayValue {
                sectionMarkers = markersArray.compactMap { $0.stringValue }
            }
        }

        // 解析排除區段
        var excludeSections: Set<String> = []
        if let excludeValue = args["exclude_sections"] {
            if let excludeArray = excludeValue.arrayValue {
                excludeSections = Set(excludeArray.compactMap { $0.stringValue })
            }
        }

        let paragraphs = doc.getParagraphs()

        // 如果沒有指定區段標記，直接計算總字數
        if sectionMarkers.isEmpty {
            var totalWords = 0
            var totalChars = 0
            for para in paragraphs {
                let text = para.getText()
                totalWords += countWords(text)
                totalChars += text.filter { !$0.isWhitespace }.count
            }
            return """
            Word Count Summary:
              Total words: \(formatNumber(totalWords))
              Total characters (no spaces): \(formatNumber(totalChars))
              Total paragraphs: \(paragraphs.count)
            """
        }

        // 找出每個區段的起始段落
        var sectionStarts: [(name: String, startIndex: Int)] = []
        for (index, para) in paragraphs.enumerated() {
            let paraText = para.getText().trimmingCharacters(in: .whitespacesAndNewlines)
            for marker in sectionMarkers {
                // 檢查段落是否以標記開頭（支援各種格式如 "1. Introduction", "Introduction:", "INTRODUCTION" 等）
                let lowerParaText = paraText.lowercased()
                let lowerMarker = marker.lowercased()
                if lowerParaText == lowerMarker ||
                   lowerParaText.hasPrefix(lowerMarker + ":") ||
                   lowerParaText.hasPrefix(lowerMarker + " ") ||
                   lowerParaText.hasSuffix(" " + lowerMarker) ||
                   lowerParaText.contains(". " + lowerMarker) {
                    sectionStarts.append((marker, index))
                    break
                }
            }
        }

        // 如果沒有找到任何區段，返回總字數
        if sectionStarts.isEmpty {
            var totalWords = 0
            for para in paragraphs {
                totalWords += countWords(para.getText())
            }
            return """
            No section markers found in document.
            Total words: \(formatNumber(totalWords))

            Tip: Section markers should match paragraph text (e.g., "Abstract", "Introduction", "References")
            """
        }

        // 計算每個區段的字數
        var sectionCounts: [(name: String, words: Int, excluded: Bool)] = []
        var totalWords = 0
        var excludedWords = 0

        // 處理第一個區段之前的內容
        if sectionStarts[0].startIndex > 0 {
            var preWords = 0
            for i in 0..<sectionStarts[0].startIndex {
                preWords += countWords(paragraphs[i].getText())
            }
            if preWords > 0 {
                sectionCounts.append(("(Before first section)", preWords, false))
                totalWords += preWords
            }
        }

        // 計算各區段
        for (i, section) in sectionStarts.enumerated() {
            let startIndex = section.startIndex
            let endIndex = (i + 1 < sectionStarts.count) ? sectionStarts[i + 1].startIndex : paragraphs.count

            var sectionWords = 0
            for j in startIndex..<endIndex {
                sectionWords += countWords(paragraphs[j].getText())
            }

            let isExcluded = excludeSections.contains(section.name)
            sectionCounts.append((section.name, sectionWords, isExcluded))
            totalWords += sectionWords
            if isExcluded {
                excludedWords += sectionWords
            }
        }

        // 生成輸出
        var output = "Word Count by Section:\n"
        for section in sectionCounts {
            let excludeTag = section.excluded ? " (excluded)" : ""
            output += "  \(section.name): \(formatNumber(section.words)) words\(excludeTag)\n"
        }
        output += "  ─────────────────────────────\n"
        if excludedWords > 0 {
            output += "  Main Text: \(formatNumber(totalWords - excludedWords)) words\n"
        }
        output += "  Total: \(formatNumber(totalWords)) words\n"

        return output
    }

    // #266 — Estimate a Word UI page reference back to get_paragraphs indices.
    // OOXML stores content, not rendered page boundaries; this intentionally
    // returns a candidate range with confidence/warning rather than a precise
    // paragraph anchor.
    /// #142 (v_v2): structural block walker emits typed records for the
    /// pagination heuristic. Body-paragraph blocks remain the indexable unit
    /// (so `paragraph_index` semantics across the rest of the MCP API are
    /// unchanged), but tables / image-only paragraphs / display equation
    /// paragraphs now contribute their proper visual char weight to the
    /// heuristic instead of being silently dropped or under-counted.
    fileprivate enum StructuralBlock {
        /// Body-stream paragraph (text-bearing, possibly with inline math).
        /// Maps 1:1 to the `paragraph_index` returned in
        /// `estimated_paragraph_range`. Char weight = `text.count + 1`.
        case paragraph(Paragraph)

        /// Table at top level of body. Char weight = `tableRows × avgCellChars`
        /// (with `200`-per-row fallback for empty tables). NOT a body-stream
        /// paragraph — does not increment `paragraph_count`.
        case table(Table)

        /// Body-stream paragraph that contains drawings (`Run.drawing != nil`)
        /// — visual height much greater than its text content. Counted in
        /// `paragraph_count` (it IS a body-stream paragraph), but char weight
        /// gets +200 per drawing on top of the run text.
        case imageOnlyParagraph(Paragraph, drawingCount: Int)

        /// Body-stream paragraph whose runs are all empty AND whose
        /// `unrecognizedChildren` carries `<m:oMathPara>` direct-child markup
        /// (Pandoc display-math pattern, see #99). Counted in
        /// `paragraph_count`. Char weight = `120` (≈ 1.5 lines under 12pt).
        case displayEquationParagraph(Paragraph)
    }

    /// Per-block char weight for the v2 heuristic. Constants calibrated for
    /// 12pt single-column document layout (matching `estimateCharsPerPage`'s
    /// `charsPerLine=50` × `linesPerPage=28` ≈ 1400 chars/page baseline).
    /// Caller can override via `chars_per_page` if their layout differs.
    fileprivate static let imageCharsPerDrawing = 200       // ~4 lines visual height
    fileprivate static let displayEquationChars = 120        // ~1.5 lines visual height
    fileprivate static let emptyTableRowFallbackChars = 200  // for layout-only tables

    fileprivate static func collectStructuralBlocks(from doc: WordDocument) -> [StructuralBlock] {
        var result: [StructuralBlock] = []
        for child in doc.body.children {
            collectStructuralBlocksFrom(child, into: &result)
        }
        return result
    }

    fileprivate static func collectStructuralBlocksFrom(_ child: BodyChild, into result: inout [StructuralBlock]) {
        switch child {
        case .paragraph(let para):
            result.append(classifyParagraph(para))
        case .table(let table):
            result.append(.table(table))
        case .contentControl(_, let children):
            for c in children { collectStructuralBlocksFrom(c, into: &result) }
        case .bookmarkMarker, .rawBlockElement:
            break
        }
    }

    /// Classify a body-stream paragraph: pure-text vs. image-bearing vs.
    /// display-equation. Mutually exclusive: a paragraph with text + drawing
    /// is `.imageOnlyParagraph` (the drawing weight is additive on top of
    /// run text), a paragraph that's only `oMathPara` is `.displayEquationParagraph`,
    /// otherwise `.paragraph`.
    fileprivate static func classifyParagraph(_ para: Paragraph) -> StructuralBlock {
        // 1. Display equation heuristic: empty runs + oMathPara in
        //    unrecognizedChildren (Pandoc display math, see #99).
        let allRunsEmpty = para.runs.allSatisfy { $0.text.isEmpty }
        let hasOMathPara = para.unrecognizedChildren.contains { child in
            child.rawXML.contains("<m:oMathPara") || child.rawXML.contains(":oMathPara")
        }
        if allRunsEmpty && hasOMathPara {
            return .displayEquationParagraph(para)
        }

        // 2. Image-bearing paragraph: any run carries a drawing
        let drawingCount = para.runs.reduce(0) { $0 + ($1.drawing != nil ? 1 : 0) }
        if drawingCount > 0 {
            return .imageOnlyParagraph(para, drawingCount: drawingCount)
        }

        // 3. Default: text paragraph
        return .paragraph(para)
    }

    /// v2 char-weight calculation per StructuralBlock case. Reuses
    /// `estimatedLayoutCharacterCount(for: Paragraph)` for the text portion
    /// of paragraph-bearing cases.
    fileprivate static func charWeight(for block: StructuralBlock) -> Int {
        switch block {
        case .paragraph(let para):
            return estimatedLayoutCharacterCount(for: para)
        case .table(let table):
            return tableCharWeight(table)
        case .imageOnlyParagraph(let para, let drawingCount):
            return estimatedLayoutCharacterCount(for: para) + drawingCount * imageCharsPerDrawing
        case .displayEquationParagraph(_):
            return displayEquationChars
        }
    }

    /// Rough char weight for a table: sum of all cell paragraphs'
    /// `flattenedDisplayText().count`, with `emptyTableRowFallbackChars`
    /// fallback per row when cells are empty (e.g. layout-only tables).
    fileprivate static func tableCharWeight(_ table: Table) -> Int {
        var total = 0
        for row in table.rows {
            var rowChars = 0
            for cell in row.cells {
                for cellPara in cell.paragraphs {
                    let text = cellPara.flattenedDisplayText()
                    rowChars += max(text.count, 1)  // each non-empty cell para >= 1
                }
            }
            // Fallback for rows where all cells are empty (rare, layout-only)
            total += rowChars > 0 ? rowChars : emptyTableRowFallbackChars
        }
        return total
    }

    private func estimateParagraphForPage(args: [String: Value]) async throws -> String {
        let (doc, _) = try await resolveDocument(args: args)

        guard let page = try optionalInt(args, "page") else {
            throw WordError.missingParameter("page")
        }
        // Upper-bound guard prevents (page - 1) * charsPerPage and page * charsPerPage
        // from triggering Int overflow trap on caller-controlled Int.max input.
        // 100_000 pages exceeds any real document by ~3 orders of magnitude.
        guard page >= 1 && page <= 100_000 else {
            throw ToolRefusal("estimate_paragraph_for_page: page must be 1..100000, got \(page)")
        }

        let charsPerPage: Int
        let layoutBasis: String
        if let override = try optionalInt(args, "chars_per_page") {
            // Same overflow concern: page * charsPerPage with charsPerPage=Int.max.
            // 200_000 chars/page is far beyond any plausible single-page density.
            guard override > 0 && override <= 200_000 else {
                throw ToolRefusal("estimate_paragraph_for_page: chars_per_page must be 1..200000, got \(override)")
            }
            charsPerPage = override
            layoutBasis = "caller_chars_per_page"
        } else {
            charsPerPage = try Self.estimateCharsPerPage(from: doc.sectionProperties)
            layoutBasis = "section_properties"
        }

        let contextParagraphs = try optionalInt(args, "context_paragraphs") ?? 2
        // Upper bound prevents rawStart - contextParagraphs underflow and
        // rawEnd + contextParagraphs overflow on Int.max input.
        guard contextParagraphs >= 0 && contextParagraphs <= 1024 else {
            throw ToolRefusal("estimate_paragraph_for_page: context_paragraphs must be 0..1024, got \(contextParagraphs)")
        }

        // #142: collect structural blocks (text paragraphs + tables + image
        // paragraphs + display equations). Body-stream paragraphs (everything
        // except .table) drive paragraph_index/paragraph_count semantics;
        // tables contribute char weight only.
        let blocks = Self.collectStructuralBlocks(from: doc)

        // Build the body-paragraph (paragraph-index) list — same set as old
        // `doc.getParagraphs()`. This preserves estimated_paragraph_range
        // semantics for callers.
        var bodyParagraphs: [Paragraph] = []
        for block in blocks {
            switch block {
            case .paragraph(let p), .imageOnlyParagraph(let p, _), .displayEquationParagraph(let p):
                bodyParagraphs.append(p)
            case .table:
                continue  // tables are NOT body-stream paragraphs
            }
        }

        // #145: this used to `return` a `{ "error": "empty_document", ... }`
        // string as if it were a normal successful result — `isError` was
        // never set, so a caller that only checks `isError` (rather than
        // parsing the body as JSON looking for an "error" key) believed the
        // call had succeeded, and the response shape (missing `confidence_
        // reason`/`layout_basis`/`page`/`structural_breakdown`/…) diverged
        // from the happy path with no schema documentation of either fact.
        // Same class of bug as #238 (`create_numbering_definition`); same
        // fix — throw, so this funnels through the one error convention
        // every other rejection in this function already uses.
        guard !bodyParagraphs.isEmpty else {
            throw ToolRefusal("estimate_paragraph_for_page: document has no paragraphs to estimate against (empty_document)")
        }

        // #142: per-paragraph spans align with bodyParagraphs index, but the
        // cumulative char count walks ALL blocks including tables. When we
        // hit a `.table`, we add its weight to the running total but do NOT
        // emit a span (tables are not paragraph-indexable).
        //
        // The spans array's ith entry corresponds to bodyParagraphs[i]'s
        // start/end byte range in the cumulative char stream — including
        // any tables that came BEFORE it.
        var spans: [(start: Int, end: Int)] = []
        var cumulative = 0
        // Per-category counters for structural_breakdown
        var tablesCounted = 0
        var tablesTotalChars = 0
        var imageOnlyCount = 0
        var imageCharsAdded = 0
        var displayEqCount = 0
        var equationCharsAdded = 0
        var pureTextParagraphCount = 0

        for block in blocks {
            let weight = Self.charWeight(for: block)
            switch block {
            case .paragraph:
                pureTextParagraphCount += 1
                let start = cumulative
                cumulative += weight
                spans.append((start: start, end: cumulative))
            case .imageOnlyParagraph(_, let drawingCount):
                imageOnlyCount += 1
                imageCharsAdded += drawingCount * Self.imageCharsPerDrawing
                let start = cumulative
                cumulative += weight
                spans.append((start: start, end: cumulative))
            case .displayEquationParagraph:
                displayEqCount += 1
                equationCharsAdded += Self.displayEquationChars
                let start = cumulative
                cumulative += weight
                spans.append((start: start, end: cumulative))
            case .table:
                tablesCounted += 1
                tablesTotalChars += weight
                cumulative += weight
                // intentionally NO spans.append — tables not paragraph-indexable
            }
        }

        let targetStart = (page - 1) * charsPerPage
        let targetEnd = page * charsPerPage
        let estimatedTotalPages = max(1, Int(ceil(Double(cumulative) / Double(charsPerPage))))
        let beyondEstimatedDocument = targetStart >= cumulative

        let rawStart: Int
        let rawEnd: Int
        if beyondEstimatedDocument {
            rawStart = bodyParagraphs.count - 1
            rawEnd = bodyParagraphs.count - 1
        } else {
            rawStart = spans.firstIndex { $0.end > targetStart } ?? (bodyParagraphs.count - 1)
            rawEnd = spans.lastIndex { $0.start < targetEnd } ?? rawStart
        }

        let startIndex = max(0, rawStart - contextParagraphs)
        let endIndex = min(bodyParagraphs.count - 1, rawEnd + contextParagraphs)

        // #143: confidence must reflect actual reliability, not merely
        // "did the caller skip providing chars_per_page". The pre-fix
        // branch only ever granted "medium" when layout_basis ==
        // "section_properties" — a caller who measured their own render
        // pipeline and passed chars_per_page could never score above
        // "low", which is a semantic inversion (caller calibration is MORE
        // trustworthy than the server's own guess, not less). Ordering
        // below is significant and each branch is mutually exclusive:
        //   1. Extrapolating past the estimated document is unreliable no
        //      matter how chars_per_page was obtained — this must outrank
        //      caller calibration, not lose to it.
        //   2. Caller-provided chars_per_page is the most reliable
        //      remaining case.
        //   3. Complex layout (tables / images / display equations) under
        //      the DEFAULT heuristic is the least reliable remaining case —
        //      these are exactly the structural weights (#142) that are the
        //      roughest approximations (fixed per-row/per-drawing/per-
        //      equation constants, not measured from the actual document).
        //   4. A longer simple-layout document under the default heuristic
        //      gets more confidence than a short one, because char-count
        //      noise has more paragraphs to average out over.
        let hasComplexLayout = tablesCounted > 0 || imageOnlyCount > 0 || displayEqCount > 0
        let confidence: String
        let confidenceReason: String
        if beyondEstimatedDocument {
            confidence = "low"
            confidenceReason = "beyond_estimated_document"
        } else if layoutBasis == "caller_chars_per_page" {
            confidence = "high"
            confidenceReason = "caller_provided_chars_per_page"
        } else if hasComplexLayout {
            confidence = "low"
            confidenceReason = "complex_layout_default_heuristic"
        } else if bodyParagraphs.count >= 10 {
            confidence = "medium"
            confidenceReason = "default_heuristic_simple_layout"
        } else {
            confidence = "low"
            confidenceReason = "short_doc_or_fallback_layout"
        }

        // #142 structural_breakdown: per-block-type tally so callers can see
        // what the heuristic counted.
        let structuralBreakdown: [String: Any] = [
            "paragraphs_with_text": pureTextParagraphCount,
            "tables_counted": tablesCounted,
            "tables_total_chars": tablesTotalChars,
            "image_only_paragraphs": imageOnlyCount,
            "image_chars_added": imageCharsAdded,
            "display_equations": displayEqCount,
            "equation_chars_added": equationCharsAdded,
            "estimated_total_chars": cumulative,
            "char_breakdown_method": "v2_with_structural_weights",
        ]

        return try Self.renderJSONString([
            "estimated_paragraph_range": [startIndex, endIndex],
            "raw_estimated_paragraph_range": [rawStart, rawEnd],
            "confidence": confidence,
            "confidence_reason": confidenceReason,
            "method": "char_count_heuristic_v2",
            "layout_basis": layoutBasis,
            "page": page,
            "assumed_chars_per_page": charsPerPage,
            "estimated_total_pages": estimatedTotalPages,
            "paragraph_count": bodyParagraphs.count,
            "total_estimated_chars": cumulative,
            "context_paragraphs": contextParagraphs,
            "requested_page_beyond_estimated_document": beyondEstimatedDocument,
            "structural_breakdown": structuralBreakdown,
            "warning": Self.pageEstimateWarning,
        ])
    }

    private static let pageEstimateWarning = "OOXML does not store page boundaries; this is an estimate based on character density and section page setup. Actual page boundaries depend on rendering, fonts, margins, line spacing, images, tables, and Word layout."

    fileprivate static func estimatedLayoutCharacterCount(for paragraph: Paragraph) -> Int {
        let text = paragraph.getText().replacingOccurrences(of: "\n", with: " ")
        // Empty paragraphs still consume vertical space, so count them as a
        // small visible unit plus a paragraph break.
        return max(text.count, 1) + 1
    }

    /// #237: `pageSize`/`pageMargins` here come from the OPENED document's
    /// `sectionProperties`, not from a tool argument — #234's input-side
    /// validation (`set_page_margins`/`set_page_size`) never runs on this
    /// path. Validate every operand THIS function actually consumes right
    /// before the arithmetic, so a hand-edited (or otherwise out-of-range)
    /// `.docx` is refused with a structured error instead of trapping the
    /// whole process on overflow/underflow. Once every operand is bounded
    /// to a range this small, no combination of a handful of them can
    /// possibly approach `Int` overflow — the guarantee does not depend on
    /// which specific value happens to be "the large one".
    private static func estimateCharsPerPage(from props: SectionProperties) throws -> Int {
        func validated(_ value: Int, _ field: String, _ range: ClosedRange<Int>) throws -> Int {
            guard range.contains(value) else {
                throw WordError.invalidParameter(
                    field,
                    "文件目前的頁面設定超出可估算範圍（\(range.lowerBound)–\(range.upperBound) twips），可能是損毀或手動編輯過的 .docx：\(value)"
                )
            }
            return value
        }

        let width = try validated(props.pageSize.width, "pageSize.width", pageSizeTwipsRange)
        let height = try validated(props.pageSize.height, "pageSize.height", pageSizeTwipsRange)
        // top/bottom are signed (Int32Value, negative allowed for
        // header/footer overlap); left/right/gutter are unsigned
        // (UInt32Value) — same split #234 established for set_page_margins,
        // see `pageMarginTwipsRange`/`pageMarginTwipsRangeUnsigned`'s doc
        // comments. `gutter` has no dedicated tool-input range because no
        // tool exposes it as a parameter, but it is the same OOXML type
        // family (`ST_TwipsMeasure`, unsigned) as left/right, so it shares
        // their range here.
        let left = try validated(props.pageMargins.left, "pageMargins.left", pageMarginTwipsRangeUnsigned)
        let right = try validated(props.pageMargins.right, "pageMargins.right", pageMarginTwipsRangeUnsigned)
        let gutter = try validated(props.pageMargins.gutter, "pageMargins.gutter", pageMarginTwipsRangeUnsigned)
        let top = try validated(props.pageMargins.top, "pageMargins.top", pageMarginTwipsRange)
        let bottom = try validated(props.pageMargins.bottom, "pageMargins.bottom", pageMarginTwipsRange)

        let usableWidthTwips = max(1440, width - left - right - gutter)
        let usableHeightTwips = max(1440, height - top - bottom)

        // Conservative 12pt document/review calibration: average character width
        // ~11pt, line height ~24pt. This intentionally favors a candidate range
        // over a false-precise point estimate.
        let charsPerLine = max(20, usableWidthTwips / 220)
        let linesPerPage = max(10, usableHeightTwips / 480)
        return max(400, charsPerLine * linesPerPage)
    }

    private static func renderJSONString(_ object: [String: Any]) throws -> String {
        let data = try JSONSerialization.data(withJSONObject: object, options: [.sortedKeys])
        return String(data: data, encoding: .utf8) ?? "{}"
    }

    // Helper: 計算字數（支援中英文混合）
    private func countWords(_ text: String) -> Int {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty { return 0 }

        // 分離中文和英文
        var englishWords = 0
        var chineseChars = 0

        // 用正規表達式分割
        let englishPattern = try? NSRegularExpression(pattern: "[a-zA-Z]+", options: [])
        let chinesePattern = try? NSRegularExpression(pattern: "[\\u4e00-\\u9fff]", options: [])

        let range = NSRange(trimmed.startIndex..., in: trimmed)

        if let matches = englishPattern?.matches(in: trimmed, options: [], range: range) {
            englishWords = matches.count
        }

        if let matches = chinesePattern?.matches(in: trimmed, options: [], range: range) {
            chineseChars = matches.count
        }

        // 中文每個字算一個詞
        return englishWords + chineseChars
    }

    // Helper: 格式化數字（加入千分位）
    private func formatNumber(_ number: Int) -> String {
        let formatter = NumberFormatter()
        formatter.numberStyle = .decimal
        return formatter.string(from: NSNumber(value: number)) ?? "\(number)"
    }

    // MARK: - Document Comparison

    private struct ParagraphSnapshot {
        let index: Int
        let text: String
        let textHash: Int
        let style: String?
        let formattedText: String
        let keepNext: Bool
    }

    private enum DiffType {
        case unchanged, modified, deleted, added, formatOnly
    }

    private struct DiffEntry {
        let type: DiffType
        let indexA: Int?
        let indexB: Int?
        let style: String?
        let textA: String?
        let textB: String?
        let formattedA: String?
        let formattedB: String?
    }

    private func snapshotParagraphs(_ doc: WordDocument) -> [ParagraphSnapshot] {
        let paragraphs = doc.getParagraphs()
        return paragraphs.enumerated().map { (index, para) in
            let text = para.getText().trimmingCharacters(in: .whitespacesAndNewlines)
            return ParagraphSnapshot(
                index: index,
                text: text,
                textHash: text.hashValue,
                style: para.properties.style,
                formattedText: formatParagraphWithMarkup(para, index: index),
                keepNext: para.properties.keepNext
            )
        }
    }

    private func computeLCS(_ a: [ParagraphSnapshot], _ b: [ParagraphSnapshot]) -> [[Int]] {
        let n = a.count
        let m = b.count
        var dp = Array(repeating: Array(repeating: 0, count: m + 1), count: n + 1)
        for i in 1...max(n, 1) {
            guard i <= n else { break }
            for j in 1...max(m, 1) {
                guard j <= m else { break }
                if a[i - 1].textHash == b[j - 1].textHash && a[i - 1].text == b[j - 1].text {
                    dp[i][j] = dp[i - 1][j - 1] + 1
                } else {
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
                }
            }
        }
        return dp
    }

    private func textSimilarity(_ a: String, _ b: String) -> Double {
        let wordsA = Set(a.lowercased().split(whereSeparator: { $0.isWhitespace || $0.isPunctuation }))
        let wordsB = Set(b.lowercased().split(whereSeparator: { $0.isWhitespace || $0.isPunctuation }))
        guard !wordsA.isEmpty || !wordsB.isEmpty else { return 1.0 }
        let intersection = wordsA.intersection(wordsB).count
        let union = wordsA.union(wordsB).count
        guard union > 0 else { return 0.0 }
        return Double(intersection) / Double(union)
    }

    private func buildDiffEntries(
        _ a: [ParagraphSnapshot],
        _ b: [ParagraphSnapshot],
        _ dp: [[Int]],
        mode: String
    ) -> [DiffEntry] {
        // Backtrack LCS to get aligned sequence
        var aligned: [(aIdx: Int?, bIdx: Int?)] = []
        var i = a.count
        var j = b.count
        while i > 0 || j > 0 {
            if i > 0 && j > 0 && a[i - 1].textHash == b[j - 1].textHash && a[i - 1].text == b[j - 1].text {
                aligned.append((i - 1, j - 1))
                i -= 1
                j -= 1
            } else if j > 0 && (i == 0 || dp[i][j - 1] >= dp[i - 1][j]) {
                aligned.append((nil, j - 1))
                j -= 1
            } else {
                aligned.append((i - 1, nil))
                i -= 1
            }
        }
        aligned.reverse()

        // Post-process: merge adjacent DELETED+ADDED into MODIFIED if similar
        var entries: [DiffEntry] = []
        var idx = 0
        while idx < aligned.count {
            let (aIdx, bIdx) = aligned[idx]
            if let ai = aIdx, let bi = bIdx {
                // Matched pair
                let checkFormatting = (mode == "formatting" || mode == "full")
                if checkFormatting && a[ai].formattedText != b[bi].formattedText {
                    entries.append(DiffEntry(
                        type: .formatOnly,
                        indexA: ai, indexB: bi,
                        style: a[ai].style ?? b[bi].style,
                        textA: a[ai].text, textB: b[bi].text,
                        formattedA: a[ai].formattedText, formattedB: b[bi].formattedText
                    ))
                } else {
                    entries.append(DiffEntry(
                        type: .unchanged,
                        indexA: ai, indexB: bi,
                        style: a[ai].style,
                        textA: a[ai].text, textB: nil,
                        formattedA: nil, formattedB: nil
                    ))
                }
                idx += 1
            } else if aIdx != nil && bIdx == nil {
                // Check if next is ADDED and they are similar → MODIFIED
                if idx + 1 < aligned.count,
                   aligned[idx + 1].aIdx == nil,
                   let bi = aligned[idx + 1].bIdx,
                   let ai = aIdx,
                   textSimilarity(a[ai].text, b[bi].text) > 0.5 {
                    entries.append(DiffEntry(
                        type: .modified,
                        indexA: ai, indexB: bi,
                        style: a[ai].style ?? b[bi].style,
                        textA: a[ai].text, textB: b[bi].text,
                        formattedA: a[ai].formattedText, formattedB: b[bi].formattedText
                    ))
                    idx += 2
                } else {
                    entries.append(DiffEntry(
                        type: .deleted,
                        indexA: aIdx, indexB: nil,
                        style: a[aIdx!].style,
                        textA: a[aIdx!].text, textB: nil,
                        formattedA: a[aIdx!].formattedText, formattedB: nil
                    ))
                    idx += 1
                }
            } else {
                // ADDED - check if next is DELETED and they are similar → MODIFIED
                if idx + 1 < aligned.count,
                   aligned[idx + 1].bIdx == nil,
                   let ai = aligned[idx + 1].aIdx,
                   let bi = bIdx,
                   textSimilarity(a[ai].text, b[bi].text) > 0.5 {
                    entries.append(DiffEntry(
                        type: .modified,
                        indexA: ai, indexB: bi,
                        style: a[ai].style ?? b[bi].style,
                        textA: a[ai].text, textB: b[bi].text,
                        formattedA: a[ai].formattedText, formattedB: b[bi].formattedText
                    ))
                    idx += 2
                } else {
                    entries.append(DiffEntry(
                        type: .added,
                        indexA: nil, indexB: bIdx,
                        style: b[bIdx!].style,
                        textA: nil, textB: b[bIdx!].text,
                        formattedA: nil, formattedB: b[bIdx!].formattedText
                    ))
                    idx += 1
                }
            }
        }
        return entries
    }

    /// Apply the unified truncation policy.
    ///
    /// Per `manuscript-review-markdown-export` design — Decision: Truncation Policy is
    /// Default-Complete and Decision: Elision Threshold is 5000 chars per entry.
    ///
    /// - When `summarize == false` (default), returns `text` unchanged. No upper bound.
    /// - When `summarize == true`, returns `text` unchanged if its length is `<= threshold`,
    ///   otherwise emits `<first 30 chars> [...] <last 30 chars>`.
    ///
    /// All MCP tools that return potentially long text route their per-entry text through
    /// this helper, threading the caller's `summarize` argument from tool input.
    private func truncateText(_ text: String, summarize: Bool = false, threshold: Int = 5000, contextChars: Int = 30) -> String {
        guard summarize, text.count > threshold else { return text }
        let start = text.prefix(contextChars)
        let end = text.suffix(contextChars)
        return "\(start) [...] \(end)"
    }

    private func formatStructureComparison(
        docIdA: String, docIdB: String,
        snapshotsA: [ParagraphSnapshot], snapshotsB: [ParagraphSnapshot],
        infoA: (paragraphs: Int, words: Int), infoB: (paragraphs: Int, words: Int),
        customHeadingStyles: [String]? = nil,
        summarize: Bool = false
    ) -> String {
        var output = """
        === Document Comparison (Structure) ===
        Base: \(docIdA) (\(infoA.paragraphs) paragraphs, \(formatNumber(infoA.words)) words)
        Compare: \(docIdB) (\(infoB.paragraphs) paragraphs, \(formatNumber(infoB.words)) words)

        --- Statistics ---
        Paragraph count: \(infoA.paragraphs) → \(infoB.paragraphs) (\(infoB.paragraphs >= infoA.paragraphs ? "+" : "")\(infoB.paragraphs - infoA.paragraphs))
        Word count: \(formatNumber(infoA.words)) → \(formatNumber(infoB.words)) (\(infoB.words >= infoA.words ? "+" : "")\(formatNumber(infoB.words - infoA.words)))

        --- Heading Outline: Base (\(docIdA)) ---

        """
        let builtinHeadingStyles = Set(["Heading1", "Heading2", "Heading3", "Heading 1", "Heading 2", "Heading 3", "heading 1", "heading 2", "heading 3", "Title"])
        let customSet: Set<String>? = customHeadingStyles.map { Set($0) }

        func isHeading(_ s: ParagraphSnapshot) -> (isMatch: Bool, isHeuristic: Bool) {
            guard let style = s.style else { return (false, false) }
            // Custom heading styles take priority
            if let custom = customSet {
                return (custom.contains(style), false)
            }
            // Built-in heading styles
            if builtinHeadingStyles.contains(style) {
                return (true, false)
            }
            // Heuristic: keepNext + short text likely indicates a heading
            if s.keepNext == true && s.text.count < 100 && !s.text.isEmpty {
                return (true, true)
            }
            return (false, false)
        }

        func headingIndent(_ style: String) -> String {
            style.contains("2") ? "  " : (style.contains("3") ? "    " : "")
        }

        for s in snapshotsA {
            let (isMatch, isHeuristic) = isHeading(s)
            if isMatch {
                let indent = headingIndent(s.style ?? "")
                let marker = isHeuristic ? " (?)" : ""
                output += "\(indent)[\(s.index)] (\(s.style ?? ""))\(marker) \(truncateText(s.text, summarize: summarize))\n"
            }
        }
        output += "\n--- Heading Outline: Compare (\(docIdB)) ---\n"
        for s in snapshotsB {
            let (isMatch, isHeuristic) = isHeading(s)
            if isMatch {
                let indent = headingIndent(s.style ?? "")
                let marker = isHeuristic ? " (?)" : ""
                output += "\(indent)[\(s.index)] (\(s.style ?? ""))\(marker) \(truncateText(s.text, summarize: summarize))\n"
            }
        }
        return output
    }

    private func formatComparisonResult(
        docIdA: String, docIdB: String,
        infoA: (paragraphs: Int, words: Int), infoB: (paragraphs: Int, words: Int),
        entries: [DiffEntry], mode: String, contextLines: Int, maxResults: Int = 0,
        summarize: Bool = false
    ) -> String {
        let unchanged = entries.filter { $0.type == .unchanged }.count
        let modified = entries.filter { $0.type == .modified }.count
        let added = entries.filter { $0.type == .added }.count
        let deleted = entries.filter { $0.type == .deleted }.count
        let formatOnly = entries.filter { $0.type == .formatOnly }.count

        if modified == 0 && added == 0 && deleted == 0 && formatOnly == 0 {
            return """
            === Document Comparison ===
            Base: \(docIdA) (\(infoA.paragraphs) paragraphs, \(formatNumber(infoA.words)) words)
            Compare: \(docIdB) (\(infoB.paragraphs) paragraphs, \(formatNumber(infoB.words)) words)
            Mode: \(mode)

            Documents are identical.
            """
        }

        var output = """
        === Document Comparison ===
        Base: \(docIdA) (\(infoA.paragraphs) paragraphs, \(formatNumber(infoA.words)) words)
        Compare: \(docIdB) (\(infoB.paragraphs) paragraphs, \(formatNumber(infoB.words)) words)
        Mode: \(mode)

        --- Summary ---
        Unchanged: \(unchanged)  Modified: \(modified)  Added: \(added)  Deleted: \(deleted)
        """
        if formatOnly > 0 {
            output += "  Format-only: \(formatOnly)"
        }
        output += "\n\n--- Differences ---\n"

        var diffCount = 0
        for (entryIdx, entry) in entries.enumerated() {
            if entry.type == .unchanged { continue }
            diffCount += 1
            if maxResults > 0 && diffCount > maxResults {
                let remaining = entries.filter { $0.type != .unchanged }.count - maxResults
                output += "\n... and \(remaining) more differences (limited by max_results=\(maxResults))\n"
                break
            }

            // Context: show preceding unchanged paragraphs
            if contextLines > 0 {
                var contextEntries: [DiffEntry] = []
                var lookBack = entryIdx - 1
                while lookBack >= 0 && contextEntries.count < contextLines {
                    if entries[lookBack].type == .unchanged {
                        contextEntries.insert(entries[lookBack], at: 0)
                    } else {
                        break
                    }
                    lookBack -= 1
                }
                for ctx in contextEntries {
                    output += "\n  . A[\(ctx.indexA ?? 0)] \(truncateText(ctx.textA ?? "", summarize: summarize))"
                }
            }

            let style = entry.style ?? "Normal"
            switch entry.type {
            case .modified:
                output += "\n[MODIFIED] A[\(entry.indexA!)] → B[\(entry.indexB!)] (\(style))"
                output += "\n  - \(truncateText(entry.textA ?? "", summarize: summarize))"
                output += "\n  + \(truncateText(entry.textB ?? "", summarize: summarize))"
            case .deleted:
                output += "\n[DELETED] A[\(entry.indexA!)] (\(style))"
                output += "\n  \(truncateText(entry.textA ?? "", summarize: summarize))"
            case .added:
                output += "\n[ADDED] B[\(entry.indexB!)] (\(style))"
                output += "\n  \(truncateText(entry.textB ?? "", summarize: summarize))"
            case .formatOnly:
                output += "\n[FORMAT_ONLY] A[\(entry.indexA!)] → B[\(entry.indexB!)] (\(style))"
                output += "\n  Text: \(truncateText(entry.textA ?? "", summarize: summarize))"
                // Show formatting diff
                let fmtA = entry.formattedA ?? ""
                let fmtB = entry.formattedB ?? ""
                output += "\n  Base fmt: \(truncateText(fmtA, summarize: summarize))"
                output += "\n  Comp fmt: \(truncateText(fmtB, summarize: summarize))"
            case .unchanged:
                break
            }
            output += "\n"
        }
        return output
    }

    private func compareDocuments(args: [String: Value]) async throws -> String {
        // Reject deprecated full_text parameter (replaced by summarize).
        // Spec: word-mcp-markdown-export — Requirement: full_text parameter is removed.
        if args["full_text"] != nil {
            throw WordError.invalidParameter(
                "full_text",
                "removed in this release; use 'summarize' (inverted default — pass summarize: true to enable elision; omit for complete text)"
            )
        }

        guard let docIdA = args["doc_id_a"]?.stringValue else {
            throw WordError.missingParameter("doc_id_a")
        }
        guard let docIdB = args["doc_id_b"]?.stringValue else {
            throw WordError.missingParameter("doc_id_b")
        }
        if docIdA == docIdB {
            throw ToolRefusal("doc_id_a and doc_id_b must be different documents.")
        }
        guard let docA = openDocuments[docIdA] else {
            throw WordError.documentNotFound(docIdA)
        }
        guard let docB = openDocuments[docIdB] else {
            throw WordError.documentNotFound(docIdB)
        }

        // #240: `mode: 5` or `mode: "bogus"` used to silently behave like
        // "text" — `?.stringValue` dropped the former, and every downstream
        // comparison (`mode == "structure"`, `mode == "formatting" || mode
        // == "full"` inside `buildDiffEntries`) simply never matched the
        // latter, falling through to plain-text diff behavior. Schema
        // already declares this parameter's `enum` (`text`/`formatting`/
        // `structure`/`full`); now enforced at runtime too.
        let mode = try Self.optionalStrictEnumString(args, "mode", allowed: ["text", "formatting", "structure", "full"]) ?? "text"
        let contextLines = min(max(try optionalInt(args, "context_lines") ?? 0, 0), 3)
        let maxResults = max(try optionalInt(args, "max_results") ?? 0, 0)
        let summarize = try optionalBool(args, "summarize") ?? false

        // Parse custom heading styles for structure mode
        let customHeadingStyles: [String]? = {
            guard let arr = args["heading_styles"]?.arrayValue else { return nil }
            let styles = arr.compactMap { $0.stringValue }
            return styles.isEmpty ? nil : styles
        }()

        let snapshotsA = snapshotParagraphs(docA)
        let snapshotsB = snapshotParagraphs(docB)

        if snapshotsA.isEmpty && snapshotsB.isEmpty {
            return "Both documents have no paragraphs."
        }
        if snapshotsA.isEmpty {
            return "Base document (\(docIdA)) has no paragraphs."
        }
        if snapshotsB.isEmpty {
            return "Compare document (\(docIdB)) has no paragraphs."
        }

        let wordsA = snapshotsA.reduce(0) { $0 + countWords($1.text) }
        let wordsB = snapshotsB.reduce(0) { $0 + countWords($1.text) }
        let infoA = (paragraphs: snapshotsA.count, words: wordsA)
        let infoB = (paragraphs: snapshotsB.count, words: wordsB)

        // Structure mode: only statistics + heading outline
        if mode == "structure" {
            return formatStructureComparison(
                docIdA: docIdA, docIdB: docIdB,
                snapshotsA: snapshotsA, snapshotsB: snapshotsB,
                infoA: infoA, infoB: infoB,
                customHeadingStyles: customHeadingStyles,
                summarize: summarize
            )
        }

        let dp = computeLCS(snapshotsA, snapshotsB)
        let entries = buildDiffEntries(snapshotsA, snapshotsB, dp, mode: mode)

        return formatComparisonResult(
            docIdA: docIdA, docIdB: docIdB,
            infoA: infoA, infoB: infoB,
            entries: entries, mode: mode, contextLines: contextLines, maxResults: maxResults,
            summarize: summarize
        )
    }

    // MARK: - manuscript-review-markdown-export change

    private func exportRevisionSummaryMarkdown(args: [String: Value]) async throws -> String {
        if args["full_text"] != nil {
            throw WordError.invalidParameter(
                "full_text",
                "removed in this release; use 'summarize' (inverted default — pass summarize: true to enable elision; omit for complete text)"
            )
        }
        let (doc, _) = try await resolveDocument(args: args)
        let fileName: String = {
            if let p = args["source_path"]?.stringValue { return URL(fileURLWithPath: p).lastPathComponent }
            if let id = args["doc_id"]?.stringValue { return id }
            return "document"
        }()
        let summarize = try optionalBool(args, "summarize") ?? false
        let includeRevisions = try optionalBool(args, "include_revisions") ?? true
        let includeComments = try optionalBool(args, "include_comments") ?? true
        // #240: `group_by: 5` or `group_by: "bogus"` used to silently fall
        // back to `.author` — same silent-default shape as `mode` above.
        let groupByStr = try Self.optionalStrictEnumString(args, "group_by", allowed: ["author", "section", "type", "none"])
        let groupBy: RevisionGroupBy = groupByStr.flatMap(RevisionGroupBy.init(rawValue:)) ?? .author

        return formatRevisionSummaryMarkdown(
            fileName: fileName,
            revisions: doc.getRevisions(),
            comments: doc.getComments(),
            includeRevisions: includeRevisions,
            includeComments: includeComments,
            groupBy: groupBy,
            summarize: summarize
        )
    }

    private func compareDocumentsMarkdown(args: [String: Value]) async throws -> String {
        if args["full_text"] != nil {
            throw WordError.invalidParameter(
                "full_text",
                "removed in this release; use 'summarize' (inverted default — pass summarize: true to enable elision; omit for complete text)"
            )
        }
        guard let docsArray = args["documents"]?.arrayValue else {
            throw WordError.missingParameter("documents")
        }
        let documents: [DocumentRef] = try docsArray.map { entry in
            guard
                let obj = entry.objectValue,
                let path = obj["path"]?.stringValue,
                let label = obj["label"]?.stringValue
            else {
                throw WordError.invalidParameter("documents", "each entry must be {path: String, label: String}")
            }
            return DocumentRef(path: path, label: label)
        }
        guard documents.count >= 2 else {
            throw WordError.invalidParameter("documents", "at least 2 documents required for a timeline; got \(documents.count)")
        }
        let includeSummary = try optionalBool(args, "include_summary_table") ?? true
        let includePerPairDiff = try optionalBool(args, "include_per_pair_diff") ?? true
        let summarize = try optionalBool(args, "summarize") ?? false
        // #240: `diff_format: 5` or `diff_format: "bogus"` used to silently
        // fall back to `.narrative` — same silent-default shape as `mode`.
        let diffFormatStr = try Self.optionalStrictEnumString(args, "diff_format", allowed: ["narrative", "table", "raw"])
        let format: DiffFormat = diffFormatStr.flatMap(DiffFormat.init(rawValue:)) ?? .narrative

        // Bulk-open: load every doc transiently, gather stats, run pairwise diffs, then release.
        var openedDocs: [(label: String, doc: WordDocument)] = []
        for ref in documents {
            guard FileManager.default.fileExists(atPath: ref.path) else {
                throw WordError.fileNotFound(ref.path)
            }
            let url = URL(fileURLWithPath: ref.path)
            let document = try DocxReader.read(from: url)
            openedDocs.append((label: ref.label, doc: document))
        }

        let stats: [DocStats] = openedDocs.map { entry in
            let info = entry.doc.getInfo()
            return DocStats(
                label: entry.label,
                revisionCount: entry.doc.getRevisions().count,
                commentCount: entry.doc.getComments().count,
                wordCount: info.wordCount
            )
        }

        var pairwiseDiffs: [(fromLabel: String, toLabel: String, diff: String)] = []
        if includePerPairDiff {
            for i in 0..<(openedDocs.count - 1) {
                let from = openedDocs[i]
                let to = openedDocs[i + 1]
                let snapA = snapshotParagraphs(from.doc)
                let snapB = snapshotParagraphs(to.doc)
                let dp = computeLCS(snapA, snapB)
                let entries = buildDiffEntries(snapA, snapB, dp, mode: "text")
                let infoA = (paragraphs: snapA.count, words: snapA.reduce(0) { $0 + countWords($1.text) })
                let infoB = (paragraphs: snapB.count, words: snapB.reduce(0) { $0 + countWords($1.text) })
                let diffText = formatComparisonResult(
                    docIdA: from.label, docIdB: to.label,
                    infoA: infoA, infoB: infoB,
                    entries: entries, mode: "text", contextLines: 0, maxResults: 0,
                    summarize: summarize
                )
                pairwiseDiffs.append((from.label, to.label, diffText))
            }
        }

        return formatCompareDocumentsMarkdown(
            documents: documents,
            docStats: stats,
            pairwiseDiffs: pairwiseDiffs,
            includeSummaryTable: includeSummary,
            includePerPairDiff: includePerPairDiff,
            diffFormat: format
        )
    }

    private func exportCommentThreadsMarkdown(args: [String: Value]) async throws -> String {
        if args["full_text"] != nil {
            throw WordError.invalidParameter(
                "full_text",
                "removed in this release; use 'summarize' (inverted default — pass summarize: true to enable elision; omit for complete text)"
            )
        }
        let (doc, _) = try await resolveDocument(args: args)
        let summarize = try optionalBool(args, "summarize") ?? false
        let detect = try optionalBool(args, "detect_old_pattern") ?? false
        let includeResolved = try optionalBool(args, "include_resolved") ?? true
        // #240: `format: 5` or `format: "bogus"` used to silently fall back
        // to `.table` — same silent-default shape as `mode` above.
        let formatStr = try Self.optionalStrictEnumString(args, "format", allowed: ["table", "threaded", "narrative"])
        let format: CommentThreadFormat = formatStr.flatMap(CommentThreadFormat.init(rawValue:)) ?? .table

        let aliasMap: [String: String] = {
            guard let obj = args["author_aliases"]?.objectValue else { return [:] }
            var dict: [String: String] = [:]
            for (key, value) in obj {
                if let s = value.stringValue { dict[key] = s }
            }
            return dict
        }()
        let aliases = AuthorAliasMap(aliasMap)

        let threads = buildCommentThreads(comments: doc.getCommentsFull(), aliases: aliases)

        return formatCommentThreadsMarkdown(
            threads: threads,
            format: format,
            includeResolved: includeResolved,
            detectOldPatternFlag: detect,
            summarize: summarize
        )
    }

    // MARK: - Phase 1: 進階排版功能

    /// 設定多欄排版
    private func setColumns(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let columns = try optionalInt(args, "columns") else {
            throw WordError.missingParameter("columns")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let numCols = min(max(columns, 1), 4)
        let space = try optionalInt(args, "space") ?? 720  // 預設 0.5 inch
        let _ = try optionalBool(args, "equal_width") ?? true  // equalWidth - 保留以備將來擴展
        let separator = try optionalBool(args, "separator") ?? false

        // #245: 過去只改了 `doc.sectionProperties.columns`（且從未寫
        // `columnSpacing`）。ooxml-swift 開啟既有文件時走 overlay
        // 模式——`word/document.xml` 只有在 `modifiedParts` 含這個 part
        // 時才會從 typed model 重新產生，否則原樣搬運原始位元組；沒有任何
        // 公開 API 直接呼叫，這個修改就在存檔時被丟棄。新建文件沒有原始
        // archive，一律重新產生，所以過去 columns 部分生效、space 從未
        // 生效。`markPartDirty("word/document.xml")`（ooxml-swift
        // v0.13.0+ 公開的 `markTypedDirty` 包裝，README 明講是給
        // che-word-mcp 這類外部呼叫端用的）讓兩種模式都從 typed model
        // 重新產生 `<w:cols w:num="…" w:space="…"/>`（`SectionProperties
        // .toXML()` 本來就會輸出 columnSpacing，只是沒被標記為需要重新
        // 產生）。
        doc.sectionProperties.columns = numCols
        doc.sectionProperties.columnSpacing = space
        doc.markPartDirty("word/document.xml")
        try await storeDocument(doc, for: docId)

        var result = "Set document to \(numCols) column(s)"
        if numCols > 1 {
            result += " (space: \(space) twips"
            if separator {
                result += ", with separator line"
            }
            result += ")"
        }
        return result
    }

    /// 插入分欄符號
    private func insertColumnBreak(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #251: this used to bounds-check `paragraphIndex` against
        // `doc.getParagraphs()` (the readback family, which recurses into
        // block-level SDTs but skips tables) and then insert at
        // `body.children[paragraphIndex + 1]` — a `body.children` position,
        // a DIFFERENT index family. In a document with a table or
        // block-level SDT before the target paragraph, the two counting
        // schemes diverge: a readback-in-range index could land the break
        // BEFORE the intended paragraph instead of after it, or target a
        // position that isn't even adjacent to a paragraph at all. Both
        // steps must use the SAME family — top-level paragraph ordinal,
        // matching `insert_horizontal_line`/`insert_symbol`/
        // `insert_drop_cap` and `docs/paragraph-index-conventions.md`: find
        // the target top-level paragraph's actual `body.children` position,
        // then insert one past THAT.
        let topLevelBodyIndices = doc.body.children.enumerated().compactMap { (i, child) -> Int? in
            if case .paragraph = child { return i }
            return nil
        }
        guard paragraphIndex >= 0 && paragraphIndex < topLevelBodyIndices.count else {
            throw WordError.invalidParameter(
                "paragraph_index",
                "超出頂層段落範圍（頂層段落數：\(topLevelBodyIndices.count)）"
            )
        }
        let actualIndex = topLevelBodyIndices[paragraphIndex]

        // 在指定段落後插入一個包含分欄符的段落
        var columnBreakPara = Paragraph()
        var columnBreakRun = Run(text: "")
        // 分欄符在 OOXML 中是 <w:br w:type="column"/>
        // Run 本身不直接支援，我們透過標記來處理
        columnBreakRun.text = "\u{000C}"  // Form feed 作為標記
        columnBreakPara.runs = [columnBreakRun]
        columnBreakPara.properties.pageBreakBefore = false

        // 插入到指定段落之後（body.children 的實際位置，不是讀取回報的索引）
        doc.insertParagraph(columnBreakPara, at: actualIndex + 1)
        try await storeDocument(doc, for: docId)

        return "Inserted column break after paragraph \(paragraphIndex)"
    }

    /// 設定行號
    private func setLineNumbers(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let enable = try optionalBool(args, "enable") else {
            throw WordError.missingParameter("enable")
        }
        guard openDocuments[docId] != nil else {
            throw WordError.documentNotFound(docId)
        }

        let start = try optionalInt(args, "start") ?? 1
        let countBy = try optionalInt(args, "count_by") ?? 1
        // #253: no validation at all — matched against the same
        // `LineNumberRestart` vocabulary `set_line_numbers_for_section`
        // actually persists, even though THIS tool is a stub (#245: it never
        // writes `<w:lnNumType>` at all). A stub still owes the caller a
        // real rejection instead of echoing back whatever nonsense was
        // passed as if it had been accepted.
        let restart = try Self.optionalStrictEnumString(args, "restart", allowed: ["continuous", "newSection", "newPage"]) ?? "continuous"
        let distance = try optionalInt(args, "distance") ?? 360  // 預設 0.25 inch

        // 行號需要在 sectPr 中設定 <w:lnNumType>
        // 目前 OOXMLSwift 的 SectionProperties 沒有直接支援
        // 這需要在 DocxWriter 中處理

        // 暫時只回傳設定訊息，實際需要擴展 ooxml-swift
        if enable {
            return "Line numbers enabled (start: \(start), count by: \(countBy), restart: \(restart), distance: \(distance) twips)"
        } else {
            return "Line numbers disabled"
        }
    }

    /// 設定頁面邊框
    private func setPageBorders(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #256:接上 ooxml-swift v3.18.0（#191）新增的 SectionProperties.pageBorders
        // — 這個工具過去（#245）驗證完參數後直接回一句描述成功的字串，從未寫
        // 任何 OOXML，因為 SectionProperties 當時根本沒有 `<w:pgBorders>` 對應
        // 欄位，只能誠實回 isError（`ToolNotImplemented`）。欄位補上後改為真的
        // 寫入；同時把每個參數的驗證從「型別錯就默默套用預設值」升級成
        // #240 那套「型別錯或值不合法都具名回 isError」的嚴格驗證。

        // `style` 是必填、封閉列舉：wrong type 與 well-typed-but-unrecognized
        // value 都要拒絕（`optionalStrictEnumString` 只涵蓋可省略的參數，這裡
        // 手寫同樣的兩段檢查）。刻意只維持既有 6 個值，不擴充到 ECMA-376
        // §17.18.2 另外定義的 ~150 種具名 art border 樣式——那組樣式的
        // `w:sz` 用點數（1–31）而非八分之一點，且 ooxml-swift 的
        // `PageBorderSide.style` 本身保留為原始字串正是為了不受限枚舉，
        // 擴充 art border 是這個 issue 之外的獨立擴充，不在此處臆測補齊。
        guard let styleValue = args["style"] else {
            throw WordError.missingParameter("style")
        }
        guard case .string(let style) = styleValue else {
            throw WordError.invalidParameter("style", "必須是字串")
        }
        let validStyles = ["single", "double", "dotted", "dashed", "thick", "none"]
        guard validStyles.contains(style) else {
            throw WordError.invalidParameter(
                "style",
                "必須是 \(validStyles.joined(separator: "/")) 之一，不接受 '\(style)'（本工具不支援 ECMA-376 art border 樣式）"
            )
        }

        let colorRaw = try Self.optionalStrictString(args, "color") ?? "000000"
        let color = try Self.validatedPageBorderColor(colorRaw)

        let sizeRaw = try optionalInt(args, "size") ?? 4
        let size = try Self.validatedParamRange(sizeRaw, "size", Self.pageBorderLineSizeRange)

        let spaceRaw = try optionalInt(args, "space") ?? 24
        let space = try Self.validatedParamRange(spaceRaw, "space", Self.pageBorderSpacePointsRange)

        let offsetFrom = try Self.optionalStrictEnumString(args, "offset_from", allowed: ["page", "text"]) ?? "text"

        let showTop = try optionalBool(args, "top") ?? true
        let showBottom = try optionalBool(args, "bottom") ?? true
        let showLeft = try optionalBool(args, "left") ?? true
        let showRight = try optionalBool(args, "right") ?? true

        // 四邊共用同一組 style/size/color/space；個別 boolean 只決定該邊要不要
        // 寫出 `<w:top|bottom|left|right>` 元素本身——`false` 省略元素（沒有這
        // 個邊框），`style: "none"` 則是明確寫出「這邊有邊框元素、但樣式是無」，
        // 兩者視覺結果相同但 OOXML 不同，都保留給呼叫端依需要選擇。
        let side = PageBorderSide(style: style, size: size, color: color, space: space)
        var pageBorders = PageBorders(offsetFrom: offsetFrom)
        if showTop { pageBorders.top = side }
        if showBottom { pageBorders.bottom = side }
        if showLeft { pageBorders.left = side }
        if showRight { pageBorders.right = side }

        doc.sectionProperties.pageBorders = pageBorders
        doc.markPartDirty("word/document.xml")
        try await storeDocument(doc, for: docId)

        var shownSides: [String] = []
        if showTop { shownSides.append("top") }
        if showBottom { shownSides.append("bottom") }
        if showLeft { shownSides.append("left") }
        if showRight { shownSides.append("right") }
        let sidesDescription = shownSides.isEmpty ? "none" : shownSides.joined(separator: ", ")
        return "Set page border (style: \(style), size: \(size), color: \(color), space: \(space)pt, "
            + "offset_from: \(offsetFrom), sides: \(sidesDescription))"
    }

    /// 插入特殊符號
    private func insertSymbol(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let charCode = args["char"]?.stringValue else {
            throw WordError.missingParameter("char")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let font = args["font"]?.stringValue
        // #253: no validation at all — a wrong JSON type OR an
        // unrecognized value (e.g. "middle") both silently fell into the
        // `else` (append at end) branch below.
        let position = try Self.optionalStrictEnumString(args, "position", allowed: ["start", "end"]) ?? "end"

        // 將十六進位字元碼轉換為字元
        guard let codePoint = UInt32(charCode, radix: 16),
              let scalar = Unicode.Scalar(codePoint) else {
            throw ToolRefusal("Invalid character code '\(charCode)'. Use hexadecimal format (e.g., F020).")
        }
        let symbolChar = String(Character(scalar))

        // 取得段落索引
        let paragraphIndices = doc.body.children.enumerated().compactMap { (i, child) -> Int? in
            if case .paragraph = child { return i }
            return nil
        }

        guard paragraphIndex >= 0 && paragraphIndex < paragraphIndices.count else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        let actualIndex = paragraphIndices[paragraphIndex]
        if case .paragraph(var para) = doc.body.children[actualIndex] {
            var symbolRun = Run(text: symbolChar)
            if let fontName = font {
                symbolRun.properties.fontName = fontName
            }

            if position == "start" {
                para.runs.insert(symbolRun, at: 0)
            } else {
                para.runs.append(symbolRun)
            }
            doc.body.children[actualIndex] = .paragraph(para)
        }

        try await storeDocument(doc, for: docId)

        var result = "Inserted symbol (U+\(charCode.uppercased()))"
        if let fontName = font {
            result += " using font '\(fontName)'"
        }
        result += " at \(position) of paragraph \(paragraphIndex)"
        return result
    }

    /// 設定文字方向
    private func setTextDirection(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let direction = args["direction"]?.stringValue else {
            throw WordError.missingParameter("direction")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let validDirections = ["lrTb", "tbRl", "btLr"]
        guard validDirections.contains(direction) else {
            throw ToolRefusal("Invalid text direction. Valid options: lrTb (left-to-right, top-to-bottom), tbRl (vertical, right-to-left), btLr (bottom-to-top, left-to-right)")
        }

        let paragraphIndex = try optionalInt(args, "paragraph_index")
        // #235: this tool is a stub (the described <w:textDirection> is never
        // actually written — tracked separately in
        // docs/paragraph-index-conventions.md's "Known stub tools"), but an
        // out-of-range paragraph_index must still be rejected rather than
        // reported as success. Top-level ordinal, matching sibling
        // paragraph-formatting tools (set_keep_lines 等).
        if let pIndex = paragraphIndex {
            guard pIndex >= 0, pIndex < topLevelParagraphCount(doc) else {
                throw WordError.invalidIndex(pIndex)
            }
        }

        // 文字方向需要在段落或節屬性中設定 <w:textDirection>
        // 目前 OOXMLSwift 沒有直接支援

        if let pIndex = paragraphIndex {
            return "Text direction set to '\(direction)' for paragraph \(pIndex)"
        } else {
            return "Text direction set to '\(direction)' for entire document"
        }
    }

    /// 插入首字放大（Drop Cap）
    private func insertDropCap(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #253: an unrecognized VALUE was already rejected below, but a
        // wrong JSON type (`type: 5`) took `?.stringValue`'s `nil` straight
        // into `?? "drop"` — a valid value — so the type error sailed
        // through undetected.
        let validTypes = ["drop", "margin", "none"]
        let dropCapType = try Self.optionalStrictEnumString(args, "type", allowed: validTypes) ?? "drop"
        let lines = min(max(try optionalInt(args, "lines") ?? 3, 2), 10)
        let distance = try optionalInt(args, "distance") ?? 0
        let font = args["font"]?.stringValue

        // 取得段落
        let paragraphIndices = doc.body.children.enumerated().compactMap { (i, child) -> Int? in
            if case .paragraph = child { return i }
            return nil
        }

        guard paragraphIndex >= 0 && paragraphIndex < paragraphIndices.count else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        let actualIndex = paragraphIndices[paragraphIndex]
        if case .paragraph(let para) = doc.body.children[actualIndex] {
            // Drop cap 需要特殊的 framePr 設定
            // 在 OOXML 中，首字放大是透過 <w:framePr> 實現
            // 目前 OOXMLSwift 沒有直接支援

            if dropCapType == "none" {
                // 移除 drop cap（清除 framePr）
                doc.body.children[actualIndex] = .paragraph(para)
                try await storeDocument(doc, for: docId)
                return "Drop cap removed from paragraph \(paragraphIndex)"
            }

            // 暫時只更新文件
            doc.body.children[actualIndex] = .paragraph(para)
        }

        try await storeDocument(doc, for: docId)

        var result = "Drop cap (\(dropCapType)) applied to paragraph \(paragraphIndex)"
        result += " (lines: \(lines), distance: \(distance) twips"
        if let fontName = font {
            result += ", font: \(fontName)"
        }
        result += ")"
        return result
    }

    /// 插入水平線
    private func insertHorizontalLine(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #253: matches the #253 issue body's own flagship example — an
        // unrecognized VALUE was already rejected below, but a wrong JSON
        // type (`style: 5`) silently became "single".
        let validStyles = ["single", "double", "dotted", "dashed", "thick"]
        let style = try Self.optionalStrictEnumString(args, "style", allowed: validStyles) ?? "single"
        let color = args["color"]?.stringValue ?? "000000"
        let size = try optionalInt(args, "size") ?? 12  // 1.5pt

        // 取得段落索引
        let paragraphIndices = doc.body.children.enumerated().compactMap { (i, child) -> Int? in
            if case .paragraph = child { return i }
            return nil
        }

        guard paragraphIndex >= 0 && paragraphIndex < paragraphIndices.count else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        let actualIndex = paragraphIndices[paragraphIndex]
        if case .paragraph(var para) = doc.body.children[actualIndex] {
            // 使用段落底部邊框作為水平線
            let borderType: ParagraphBorderType
            switch style {
            case "double": borderType = .double
            case "dotted": borderType = .dotted
            case "dashed": borderType = .dashed
            case "thick": borderType = .thick
            default: borderType = .single
            }

            let borderStyle = ParagraphBorderStyle(type: borderType, color: color, size: size, space: 1)
            para.properties.border = ParagraphBorder(bottom: borderStyle)
            doc.body.children[actualIndex] = .paragraph(para)
        }

        try await storeDocument(doc, for: docId)

        return "Horizontal line added below paragraph \(paragraphIndex) (style: \(style), color: #\(color), size: \(size))"
    }

    /// 設定避頭尾控制
    private func setWidowOrphan(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let enable = try optionalBool(args, "enable") ?? true
        let paragraphIndex = try optionalInt(args, "paragraph_index")

        // 避頭尾在 OOXML 中是 <w:widowControl/>
        // 這通常在段落或文件設定中

        if let pIndex = paragraphIndex {
            // 套用到指定段落
            let paragraphIndices = doc.body.children.enumerated().compactMap { (i, child) -> Int? in
                if case .paragraph = child { return i }
                return nil
            }

            guard pIndex >= 0 && pIndex < paragraphIndices.count else {
                throw WordError.invalidIndex(pIndex)
            }

            let actualIndex = paragraphIndices[pIndex]
            if case .paragraph(var para) = doc.body.children[actualIndex] {
                // keepLines 是最接近的屬性（段落不分頁）
                para.properties.keepLines = enable
                doc.body.children[actualIndex] = .paragraph(para)
            }

            try await storeDocument(doc, for: docId)
            return "Widow/orphan control \(enable ? "enabled" : "disabled") for paragraph \(pIndex)"
        } else {
            // 套用到全文件所有段落
            let paragraphIndices = doc.body.children.enumerated().compactMap { (i, child) -> Int? in
                if case .paragraph = child { return i }
                return nil
            }

            for actualIndex in paragraphIndices {
                if case .paragraph(var para) = doc.body.children[actualIndex] {
                    para.properties.keepLines = enable
                    doc.body.children[actualIndex] = .paragraph(para)
                }
            }

            try await storeDocument(doc, for: docId)
            return "Widow/orphan control \(enable ? "enabled" : "disabled") for all paragraphs"
        }
    }

    /// 設定與下段同頁
    private func setKeepWithNext(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let enable = try optionalBool(args, "enable") ?? true

        // 取得段落索引
        let paragraphIndices = doc.body.children.enumerated().compactMap { (i, child) -> Int? in
            if case .paragraph = child { return i }
            return nil
        }

        guard paragraphIndex >= 0 && paragraphIndex < paragraphIndices.count else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        let actualIndex = paragraphIndices[paragraphIndex]
        if case .paragraph(var para) = doc.body.children[actualIndex] {
            para.properties.keepNext = enable
            doc.body.children[actualIndex] = .paragraph(para)
        }

        try await storeDocument(doc, for: docId)

        return "Keep with next \(enable ? "enabled" : "disabled") for paragraph \(paragraphIndex)"
    }

    // MARK: - Phase 2: 浮水印與文件保護 (#208 — real implementation, replacing the #201 honest stubs)

    /// #208 shared XML-attribute-value escape for the VML fragments this
    /// section builds by hand (no ooxml-swift public escaper exists for this —
    /// see `Header.escapeXML`/`escapeXMLAttribute`, both private to that
    /// module).
    private static func vmlAttributeEscape(_ s: String) -> String {
        s.replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&apos;")
    }

    /// A paragraph this section itself inserted, and only such a paragraph:
    /// every run carries nothing but a watermark `<w:pict>` rawElement. Used
    /// both to make insert idempotent (replace, not accumulate) and to find
    /// what `remove_watermark` must remove.
    private static func paragraphIsWatermarkOnly(_ paragraph: Paragraph) -> Bool {
        !paragraph.runs.isEmpty && paragraph.runs.allSatisfy { run in
            guard let elements = run.rawElements, !elements.isEmpty else { return false }
            return elements.allSatisfy { el in
                el.name == "pict" && (el.xml.contains("PowerPlusWaterMarkObject") || el.xml.contains("WordPictureWatermark"))
            }
        }
    }

    private static func firstRegexCapture(_ pattern: String, in text: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: pattern) else { return nil }
        let ns = text as NSString
        guard let m = regex.firstMatch(in: text, range: NSRange(location: 0, length: ns.length)), m.numberOfRanges >= 2 else { return nil }
        return ns.substring(with: m.range(at: 1))
    }

    /// Removes any existing watermark paragraph(s) from `header` (see
    /// `paragraphIsWatermarkOnly`) and, for an image watermark, the
    /// header-local image relationship its `<v:imagedata r:id="…">`
    /// referenced — leaving that relationship behind would be exactly the
    /// #175/#199 orphan signature (declared, no longer referenced) on the
    /// very next save.
    ///
    /// #208 R2 F2: this function sees one header at a time and cannot by
    /// itself decide whether the underlying media FILE is now unreferenced
    /// (another header, or a second relationship, may still point at it) —
    /// so it reports every removed relationship's `target` back to the
    /// caller, which has the whole `WordDocument` and can check. Pre-R2 this
    /// only removed the relationship and left the media file behind
    /// unconditionally: every `insert_image_watermark` → `remove_watermark`
    /// cycle grew `word/media/` by one PNG the package never referenced
    /// again — not caught by `PackageInspector`'s orphan detection (that
    /// finds a relationship with no reference, not a media file with no
    /// relationship at all) or by any tool's `list_images`/`save_document`
    /// check.
    @discardableResult
    private static func stripWatermark(from header: inout Header) -> (changed: Bool, removedMediaTargets: [String]) {
        var staleRelationshipIds: Set<String> = []
        let before = header.bodyChildren.count
        header.bodyChildren.removeAll { child in
            guard case .paragraph(let para) = child, paragraphIsWatermarkOnly(para) else { return false }
            for run in para.runs {
                for el in run.rawElements ?? [] where el.name == "pict" {
                    if let rid = firstRegexCapture(#"<v:imagedata[^>]*\br:id="([^"]+)""#, in: el.xml) {
                        staleRelationshipIds.insert(rid)
                    }
                }
            }
            return true
        }
        var removedTargets: [String] = []
        if !staleRelationshipIds.isEmpty {
            removedTargets = header.relationships.relationships
                .filter { staleRelationshipIds.contains($0.id) }
                .map(\.target)
            header.relationships.relationships.removeAll { staleRelationshipIds.contains($0.id) }
        }
        return (header.bodyChildren.count != before || !staleRelationshipIds.isEmpty, removedTargets)
    }

    /// True when `target` (a relationship `Target` string, e.g.
    /// `"media/watermark1.png"`) is still declared by ANY relationship
    /// anywhere this reader knows about — another header, a footer, or the
    /// document body's own `document.images`. Callers check this AFTER
    /// applying their own `stripWatermark` removals to `doc`, so a target
    /// two headers happen to share is not deleted out from under the
    /// surviving one.
    private static func mediaTargetStillReferenced(_ target: String, in doc: WordDocument) -> Bool {
        if doc.headers.contains(where: { header in header.relationships.relationships.contains { $0.target == target } }) { return true }
        if doc.footers.contains(where: { footer in footer.relationships.relationships.contains { $0.target == target } }) { return true }
        if doc.images.contains(where: { "media/\($0.fileName)" == target }) { return true }
        return false
    }

    /// #208 R2 F2: deletes each media file in `removedTargets` from the
    /// package archive, but only the ones nothing in `doc` still points at
    /// (see `mediaTargetStillReferenced`). Best-effort — a file that is
    /// already gone, or a document with no archive to delete from (a
    /// `create_document` session; image watermarks require one already, per
    /// `insertImageWatermark`'s own guard, so this is reached with a
    /// non-empty `removedTargets` only when an archive exists), is silently
    /// skipped rather than failing the whole remove/replace.
    private func cleanupOrphanedWatermarkMedia(_ removedTargets: [String], in doc: WordDocument) {
        guard let archiveTempDir = doc.archiveTempDir, !removedTargets.isEmpty else { return }
        let wordDir = archiveTempDir.appendingPathComponent("word")
        for target in Set(removedTargets) where !Self.mediaTargetStillReferenced(target, in: doc) {
            // Security: `target` is an attacker-controlled relationship
            // Target string read from inside the .docx (a header rels entry
            // a malicious document declared) — this is the DELETE-side
            // sibling of the path-traversal `UntypedPartImages` documents
            // fixing on the read side. A `Target` such as
            // "../../../../etc/hosts" would, unchecked, hand
            // `FileManager.removeItem` a path outside the unzipped package
            // entirely. Reuse the same containment check: refuse (skip)
            // anything that would resolve outside `archiveTempDir`.
            guard let resolved = UntypedPartImages.resolvePackageRelativeTarget(
                target, baseDir: wordDir, packageRoot: archiveTempDir
            ) else { continue }
            try? FileManager.default.removeItem(at: resolved)
        }
    }

    /// A header's `rootAttributes` captured from a real source document (a
    /// non-empty map) carries only the `xmlns:*` the ORIGINAL header actually
    /// used — `ContainerRootTag.render` then emits exactly that set, not the
    /// API-built 5-namespace default (which only applies when
    /// `rootAttributes` is empty). A plain header with no prior VML content
    /// therefore has no `xmlns:v`/`xmlns:o`/`xmlns:w10` declared; writing a
    /// `<v:shape>` into it without adding them first would leave `v:`/`o:`
    /// prefixes undeclared — invalid XML libxml2 refuses to parse back. Only
    /// touches a non-empty map (an empty one already gets the full template).
    private static func ensureVMLNamespaces(in header: inout Header) {
        guard !header.rootAttributes.isEmpty else { return }
        for (key, value) in [
            ("xmlns:v", "urn:schemas-microsoft-com:vml"),
            ("xmlns:o", "urn:schemas-microsoft-com:office:office"),
            ("xmlns:w10", "urn:schemas-microsoft-com:office:word"),
        ] where header.rootAttributes[key] == nil {
            header.rootAttributes[key] = value
        }
    }

    /// Real Word VML boilerplate for the `_x0000_t136` "text plaque" preset
    /// shape a text watermark uses (`type="#_x0000_t136"` below references
    /// it). Declared once per header that carries the watermark — the small
    /// duplication cost if a document has 2-3 header types is preferable to
    /// tracking cross-header shapetype state for a fixed, content-free block.
    private static let watermarkShapetypeXML = """
    <v:shapetype id="_x0000_t136" coordsize="1600,21600" o:spt="136" adj="10800" \
    path="m@7,0l@8,5400,@7,21600@9,5400xe"><v:formulas><v:f eqn="sum #0 0 10800"/>\
    <v:f eqn="prod #0 2 1"/><v:f eqn="sum 21600 0 @1"/><v:f eqn="sum 0 0 @2"/>\
    <v:f eqn="sum 21600 0 @3"/><v:f eqn="if @0 @3 0"/><v:f eqn="if @0 21600 @1"/>\
    <v:f eqn="if @0 0 @2"/><v:f eqn="if @0 @4 21600"/><v:f eqn="mid @5 @6"/>\
    <v:f eqn="mid @8 @5"/><v:f eqn="mid @7 @8"/><v:f eqn="mid @6 @7"/>\
    <v:f eqn="sum @6 0 @5"/></v:formulas><v:path o:connecttype="custom" \
    o:connectlocs="@9,0;0,@5;@9,21600;21600,@5" o:connectangles="270,180,90,0" \
    textpathok="t"/><v:textpath on="t" fitshape="t"/></v:shapetype>
    """

    /// The `<w:pict>` fragment for a text watermark — see #208's target shape.
    private static func textWatermarkPictXML(font: String, color: String, size: Int, semitransparent: Bool, rotation: Int, text: String) -> String {
        let opacity = semitransparent ? "0.5" : "1"
        return "<w:pict>" + watermarkShapetypeXML
            + "<v:shape id=\"PowerPlusWaterMarkObject1\" o:spid=\"_x0000_s2051\" type=\"#_x0000_t136\" "
            + "style=\"position:absolute;margin-left:0;margin-top:0;width:415pt;height:207.5pt;"
            + "rotation:\(rotation);z-index:-251654144;mso-position-horizontal:center;"
            + "mso-position-horizontal-relative:margin;mso-position-vertical:center;"
            + "mso-position-vertical-relative:margin\" o:allowincell=\"f\" "
            + "fillcolor=\"#\(vmlAttributeEscape(color))\" stroked=\"f\">"
            + "<v:fill opacity=\"\(opacity)\"/>"
            + "<v:textpath style=\"font-family:&quot;\(vmlAttributeEscape(font))&quot;;font-size:\(size)pt\" "
            + "string=\"\(vmlAttributeEscape(text))\"/></v:shape></w:pict>"
    }

    /// The `<w:pict>` fragment for an image watermark — see #208's target
    /// shape. `gain`/`blacklevel` are the washout (faded) effect; omitted
    /// when the caller asked for a full-strength image.
    private static func imageWatermarkPictXML(relationshipId: String, washout: Bool, widthPt: Double, heightPt: Double) -> String {
        let washoutAttrs = washout ? " gain=\"19661f\" blacklevel=\"22938f\"" : ""
        return "<w:pict><v:shape id=\"WordPictureWatermark1\" o:spid=\"_x0000_s2052\" type=\"#_x0000_t75\" "
            + "style=\"position:absolute;left:0;top:0;width:\(String(format: "%.1f", widthPt))pt;"
            + "height:\(String(format: "%.1f", heightPt))pt;z-index:-251657216;mso-position-horizontal:center;"
            + "mso-position-horizontal-relative:margin;mso-position-vertical:center;"
            + "mso-position-vertical-relative:margin\" o:allowincell=\"f\">"
            + "<v:imagedata r:id=\"\(vmlAttributeEscape(relationshipId))\" o:title=\"\"\(washoutAttrs)/></v:shape></w:pict>"
    }

    private static func freshRelationshipId(existing: [String]) -> String {
        let used = Set(existing.compactMap { id -> Int? in
            guard id.hasPrefix("rId") else { return nil }
            return Int(id.dropFirst(3))
        })
        var n = 1
        while used.contains(n) { n += 1 }
        return "rId\(n)"
    }

    private static func freshWatermarkMediaFileName(ext: String, in archiveTempDir: URL) -> String {
        let mediaDir = archiveTempDir.appendingPathComponent("word/media", isDirectory: true)
        let fm = FileManager.default
        var n = 1
        while fm.fileExists(atPath: mediaDir.appendingPathComponent("watermark\(n).\(ext)").path) { n += 1 }
        return "watermark\(n).\(ext)"
    }

    private static let watermarkImageAllowedExtensions: Set<String> = ["png", "jpg", "jpeg", "gif", "bmp", "tif", "tiff"]

    /// #208 security guard (issue body: "image_path 一旦真的被讀進 media part，
    /// 就是任意絕對路徑 → 內容嵌進 .docx → 隨文件外流的原語"): extension
    /// whitelist + magic-byte sniff + size cap. Deliberately does NOT also
    /// restrict `image_path` to the open document's own directory (no
    /// existing tool in this server does — `insert_image_from_path` accepts
    /// any absolute path — and Session state does not currently expose a
    /// "this doc_id's directory" allowlist to check against); that narrower
    /// restriction is a documented residual, not silently dropped.
    private static func watermarkImageMagicBytesMatch(_ data: Data, ext: String) -> Bool {
        // `Data.starts(with:)` only ever inspects as many leading bytes as
        // the pattern needs — no separate truncation step, so this stays
        // outside TruncationPolicySweepTests' "hardcoded text truncation"
        // sweep (this is a binary magic-number check, not text elision).
        switch ext {
        case "png": return data.starts(with: [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A])
        case "jpg", "jpeg": return data.count >= 2 && data[data.startIndex] == 0xFF && data[data.startIndex + 1] == 0xD8
        case "gif": return data.starts(with: Array("GIF87a".utf8)) || data.starts(with: Array("GIF89a".utf8))
        case "bmp": return data.count >= 2 && data[data.startIndex] == 0x42 && data[data.startIndex + 1] == 0x4D
        case "tif", "tiff":
            return data.starts(with: [0x49, 0x49, 0x2A, 0x00]) || data.starts(with: [0x4D, 0x4D, 0x00, 0x2A])
        default: return false
        }
    }

    private static let watermarkImageMaxBytes = 10 * 1024 * 1024

    /// 插入文字浮水印 (#208)
    private func insertWatermark(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let text = args["text"]?.stringValue, !text.isEmpty else {
            throw WordError.missingParameter("text")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let font = args["font"]?.stringValue ?? "Calibri Light"
        let color = args["color"]?.stringValue ?? "C0C0C0"
        let size = try optionalInt(args, "size") ?? 72
        guard size > 0 else {
            throw WordError.invalidParameter("size", "必須是正整數（字型點數），不接受 \(size)")
        }
        let semitransparent = try optionalBool(args, "semitransparent") ?? true
        let rotation = try optionalInt(args, "rotation") ?? -45

        // #208 residual note: a document with zero headers gets one
        // auto-created default header (mirrors Word's own "Insert Watermark"
        // behavior on a document with none) so the watermark has somewhere
        // to live.
        if doc.headers.isEmpty {
            _ = doc.addHeader(text: "", type: .default)
        }

        var touchedHeaderIds: [String] = []
        var removedMediaTargets: [String] = []
        for i in doc.headers.indices {
            var header = doc.headers[i]
            let (_, targets) = Self.stripWatermark(from: &header)
            removedMediaTargets.append(contentsOf: targets)
            Self.ensureVMLNamespaces(in: &header)
            var run = Run(text: "")
            run.rawElements = [RawElement(name: "pict", xml: Self.textWatermarkPictXML(
                font: font, color: color, size: size, semitransparent: semitransparent, rotation: rotation, text: text))]
            header.bodyChildren.insert(.paragraph(Paragraph(runs: [run])), at: 0)
            doc.headers[i] = header
            doc.markPartDirty("word/\(header.fileName)")
            touchedHeaderIds.append(header.id)
        }
        // A header that previously carried an IMAGE watermark and now gets a
        // text one: stripWatermark above already removed that relationship;
        // clean up its now-orphaned media file too (#208 R2 F2).
        cleanupOrphanedWatermarkMedia(removedMediaTargets, in: doc)

        try await storeDocument(doc, for: docId)
        return "Inserted text watermark '\(text)' into \(touchedHeaderIds.count) header part(s): \(touchedHeaderIds.joined(separator: ", "))"
    }

    /// 插入圖片浮水印 (#208)
    private func insertImageWatermark(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let imagePath = args["image_path"]?.stringValue else {
            throw WordError.missingParameter("image_path")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let scale = try optionalInt(args, "scale") ?? 100
        guard scale > 0, scale <= 1000 else {
            throw WordError.invalidParameter("scale", "必須介於 1 到 1000 之間（百分比），不接受 \(scale)")
        }
        let washout = try optionalBool(args, "washout") ?? true

        guard FileManager.default.fileExists(atPath: imagePath) else {
            throw WordError.fileNotFound(imagePath)
        }
        let ext = (imagePath as NSString).pathExtension.lowercased()
        guard Self.watermarkImageAllowedExtensions.contains(ext) else {
            throw WordError.invalidParameter("image_path", "副檔名 '\(ext)' 不在允許清單內（\(Self.watermarkImageAllowedExtensions.sorted().joined(separator: "/"))）")
        }
        guard let imageData = FileManager.default.contents(atPath: imagePath) else {
            throw WordError.fileNotFound(imagePath)
        }
        guard imageData.count <= Self.watermarkImageMaxBytes else {
            throw WordError.invalidParameter("image_path", "檔案大小 \(imageData.count) bytes 超過上限 \(Self.watermarkImageMaxBytes) bytes（10MB）")
        }
        guard Self.watermarkImageMagicBytesMatch(imageData, ext: ext) else {
            throw WordError.invalidParameter("image_path", "檔案內容的魔數（magic bytes）與副檔名 '\(ext)' 不符，拒絕當成圖片嵌入")
        }

        // #208 residual: header-scoped media needs a package archive to
        // write into directly (`markPartDirty`'s documented external-writer
        // path — see its doc comment in ooxml-swift). `document.images` is
        // NOT an option here: every entry there gets an unconditional
        // relationship in word/document.xml.rels (DocxWriter.
        // buildTypedRelationships), which for a header-only image is
        // exactly the #175/#199 orphan signature in the WRONG part's rels —
        // not a save-gate false positive but an actually-broken package (a
        // header's r:id resolves against its OWN part's rels, never
        // document.xml.rels). A document created via create_document and
        // never saved+reopened has no archive to write into; text watermarks
        // (pure typed-model, no media) have no such requirement.
        guard let archiveTempDir = doc.archiveTempDir else {
            throw ToolRefusal("""
            insert_image_watermark: this document has no package archive to host a header-scoped media file \
            (it was created with create_document and has not been saved+reopened). Save the document, reopen \
            it with open_document, then retry — or use insert_watermark for a text watermark, which has no \
            such requirement.
            """)
        }

        if doc.headers.isEmpty {
            _ = doc.addHeader(text: "", type: .default)
        }

        let mediaFileName = Self.freshWatermarkMediaFileName(ext: ext, in: archiveTempDir)
        let mediaDir = archiveTempDir.appendingPathComponent("word/media", isDirectory: true)
        do {
            try FileManager.default.createDirectory(at: mediaDir, withIntermediateDirectories: true)
            try imageData.write(to: mediaDir.appendingPathComponent(mediaFileName))
        } catch {
            throw WordError.writeError("could not write watermark media into the package archive: \(error.localizedDescription)")
        }
        // Content_Types needs a Default entry for this extension whether or
        // not the package already had any image of this type — written the
        // same way (direct archive edit) since this media file bypasses
        // document.images, so the typed writer's `hasNewTypedParts` scan
        // never sees it.
        Self.ensureWatermarkContentTypeDefault(ext: ext, in: archiveTempDir)

        let nativeSize = try? ImageDimensions.detect(path: imagePath)
        let scaleFactor = Double(scale) / 100
        let widthPt: Double
        let heightPt: Double
        if let nativeSize, nativeSize.widthPx > 0, nativeSize.heightPx > 0 {
            widthPt = Double(nativeSize.widthPx) * 0.75 * scaleFactor
            heightPt = Double(nativeSize.heightPx) * 0.75 * scaleFactor
        } else {
            // ImageDimensions.detect only parses PNG/JPEG headers; gif/bmp/tiff
            // fall back to a fixed placeholder box rather than failing the
            // whole insert over a size estimate.
            widthPt = 300 * scaleFactor
            heightPt = 300 * scaleFactor
        }

        var touchedHeaderIds: [String] = []
        var removedMediaTargets: [String] = []
        for i in doc.headers.indices {
            var header = doc.headers[i]
            let (_, targets) = Self.stripWatermark(from: &header)
            removedMediaTargets.append(contentsOf: targets)
            Self.ensureVMLNamespaces(in: &header)

            let headerRId = Self.freshRelationshipId(existing: header.relationships.relationships.map(\.id))
            header.relationships.relationships.append(Relationship(id: headerRId, type: .image, target: "media/\(mediaFileName)"))

            var run = Run(text: "")
            run.rawElements = [RawElement(name: "pict", xml: Self.imageWatermarkPictXML(
                relationshipId: headerRId, washout: washout, widthPt: widthPt, heightPt: heightPt))]
            header.bodyChildren.insert(.paragraph(Paragraph(runs: [run])), at: 0)

            doc.headers[i] = header
            doc.markPartDirty("word/\(header.fileName)")
            touchedHeaderIds.append(header.id)
        }
        // Replacing a prior watermark (text or image) on any of these headers
        // just orphaned its media file(s), if any — delete what's now
        // unreferenced (#208 R2 F2). The just-written `mediaFileName`
        // itself is always still referenced (every touched header's new
        // relationship points at it), so this can never delete what was just
        // written.
        cleanupOrphanedWatermarkMedia(removedMediaTargets, in: doc)

        try await storeDocument(doc, for: docId)
        return "Inserted image watermark from '\((imagePath as NSString).lastPathComponent)' into \(touchedHeaderIds.count) header part(s): \(touchedHeaderIds.joined(separator: ", "))"
    }

    /// Direct-archive edit — see `insertImageWatermark`'s doc comment for why
    /// this bypasses the typed `document.images`-driven Content_Types path.
    /// Best-effort: a missing or unreadable `[Content_Types].xml` leaves the
    /// package as-is rather than failing the whole insert (the media bytes
    /// and header relationship are still written; a package this malformed
    /// already has bigger problems than one Default entry).
    private static func ensureWatermarkContentTypeDefault(ext: String, in archiveTempDir: URL) {
        let url = archiveTempDir.appendingPathComponent("[Content_Types].xml")
        guard var xml = try? String(contentsOf: url, encoding: .utf8) else { return }
        guard !xml.contains("Extension=\"\(ext)\"") else { return }
        guard let insertRange = xml.range(of: "</Types>") else { return }
        let mime: String
        switch ext {
        case "png": mime = "image/png"
        case "jpg", "jpeg": mime = "image/jpeg"
        case "gif": mime = "image/gif"
        case "bmp": mime = "image/bmp"
        case "tif", "tiff": mime = "image/tiff"
        default: mime = "image/\(ext)"
        }
        xml.insert(contentsOf: "<Default Extension=\"\(ext)\" ContentType=\"\(mime)\"/>", at: insertRange.lowerBound)
        try? xml.write(to: url, atomically: true, encoding: .utf8)
    }

    /// 移除浮水印 (#208). A document with no watermark returns success
    /// (nothing to do) rather than failing — see issue body.
    private func removeWatermark(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        var touchedHeaderIds: [String] = []
        var removedMediaTargets: [String] = []
        for i in doc.headers.indices {
            var header = doc.headers[i]
            let (changed, targets) = Self.stripWatermark(from: &header)
            if changed {
                doc.headers[i] = header
                doc.markPartDirty("word/\(header.fileName)")
                touchedHeaderIds.append(header.id)
                removedMediaTargets.append(contentsOf: targets)
            }
        }

        guard !touchedHeaderIds.isEmpty else {
            return "No watermark found; nothing removed"
        }
        // #208 R2 F2: delete the media file(s) an image watermark's
        // relationship pointed at, once nothing else in the document still
        // references them — otherwise every insert→remove cycle leaves one
        // more unreferenced PNG behind permanently (see stripWatermark's doc
        // comment).
        cleanupOrphanedWatermarkMedia(removedMediaTargets, in: doc)

        try await storeDocument(doc, for: docId)
        return "Removed watermark from \(touchedHeaderIds.count) header part(s): \(touchedHeaderIds.joined(separator: ", "))"
    }

    /// 設定文件保護
    private func protectDocument(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let protectionType = args["protection_type"]?.stringValue else {
            throw WordError.missingParameter("protection_type")
        }
        guard openDocuments[docId] != nil else {
            throw WordError.documentNotFound(docId)
        }

        let validTypes = ["readOnly", "comments", "trackedChanges", "forms"]
        guard validTypes.contains(protectionType) else {
            throw ToolRefusal("Invalid protection type. Valid options: \(validTypes.joined(separator: ", "))")
        }

        throw ToolNotImplemented(
            tool: "protect_document", issue: "#172",
            missing: "<w:documentProtection w:edit=\"\(protectionType)\" w:enforcement=\"1\"/> into word/settings.xml")
    }

    /// 移除文件保護
    private func unprotectDocument(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard openDocuments[docId] != nil else {
            throw WordError.documentNotFound(docId)
        }

        throw ToolNotImplemented(
            tool: "unprotect_document", issue: "#172",
            missing: "the removal of <w:documentProtection> from word/settings.xml")
    }

    /// 設定文件開啟密碼
    private func setDocumentPassword(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let password = args["password"]?.stringValue else {
            throw WordError.missingParameter("password")
        }
        guard openDocuments[docId] != nil else {
            throw WordError.documentNotFound(docId)
        }

        _ = password
        // Not merely unwritten — out of reach of this stack. An open-password
        // is OLE Compound Document encryption of the whole container, not an
        // OOXML part, so no amount of settings.xml work reaches it.
        throw ToolNotImplemented(
            tool: "set_document_password", issue: "#172",
            missing: "OLE Compound Document encryption of the whole .docx container (not an OOXML part)")
    }

    /// 移除文件開啟密碼
    private func removeDocumentPassword(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard args["current_password"]?.stringValue != nil else {
            throw WordError.missingParameter("current_password")
        }
        guard openDocuments[docId] != nil else {
            throw WordError.documentNotFound(docId)
        }

        throw ToolNotImplemented(
            tool: "remove_document_password", issue: "#172",
            missing: "decryption of the OLE Compound Document container (not an OOXML part)")
    }

    /// The known `w:edGrp` values ECMA-376 `ST_EdGrp` defines. `editor_group`
    /// is validated against this closed set rather than passed through, so a
    /// typo produces a loud rejection instead of a silently-wrong permission.
    static let permissionEditorGroups: Set<String> = [
        "everyone", "administrators", "contributors", "editors", "owners", "current",
    ]

    /// True when a `.table` body child falls inside the region
    /// `restrictEditingRegion` would actually mark editable for
    /// `[startParagraph, endParagraph]` (both inclusive, same counting
    /// `WordDocument.getParagraphs()` uses — descends into content controls
    /// transparently, does not descend into tables). che-word-mcp#184
    /// Acceptance: "A range spanning a table… is rejected rather than
    /// silently clamped" — `getParagraphs()` skips tables entirely, so two
    /// paragraphs that look adjacent in its flattened index space can have a
    /// whole table between them in real document flow.
    ///
    /// **This is NOT simply "a table between the two REQUESTED paragraphs"**
    /// — it must match where `<w:permStart>` / `<w:permEnd>` actually land.
    /// `restrictEditingRegion` anchors `<w:permStart>` to the END of the
    /// PRECEDING paragraph (`startParagraph - 1`), because ooxml-swift can
    /// only place an API-appended marker after a paragraph's own content —
    /// so the true editable span begins at the body-order GAP between
    /// paragraph `startParagraph - 1` and paragraph `startParagraph`, not at
    /// paragraph `startParagraph` itself. A table sitting in exactly that
    /// gap (immediately after the anchor, immediately before the requested
    /// start) is document-flow-INSIDE the marked range even though it is
    /// outside the caller's requested `[startParagraph, endParagraph]`
    /// window — a real bug an independent review caught (R2): the original
    /// condition (`count >= startParagraph + 1`) started counting one
    /// paragraph too late and missed exactly this gap.
    ///
    /// The END side has NO symmetric borrowed-anchor gap to worry about:
    /// `<w:permEnd>` is appended to paragraph `endParagraph` ITSELF (not to
    /// `endParagraph + 1`), so the range closes at that paragraph's own
    /// `</w:p>` — anything from the NEXT body-order gap onward (including a
    /// table right after `endParagraph`) is genuinely outside the marked
    /// range, confirmed by `testAdjacentRangeNotCrossingTheTableStillSucceeds`.
    /// Re-derived and confirmed independently during R2, not merely copied
    /// from the review's suggested one-line patch.
    static func restrictedRangeSpansTable(_ children: [BodyChild], startParagraph: Int, endParagraph: Int) -> Bool {
        var count = 0
        return spansTable(children, startParagraph: startParagraph, endParagraph: endParagraph, count: &count)
    }

    private static func spansTable(_ children: [BodyChild], startParagraph: Int, endParagraph: Int, count: inout Int) -> Bool {
        for child in children {
            switch child {
            case .paragraph:
                count += 1
            case .table:
                // The table sits in the gap between paragraph (count-1) and
                // paragraph count. That gap is inside the MARKED range
                // exactly when its right-hand paragraph (count) is at-or-
                // after the anchor gap's own right edge (startParagraph —
                // NOT startParagraph + 1: the gap immediately after the
                // permStart anchor, i.e. between startParagraph - 1 and
                // startParagraph, is itself inside the range) AND its
                // left-hand paragraph (count - 1) is at-or-before endParagraph
                // (equivalently: count <= endParagraph).
                if count >= startParagraph && count <= endParagraph { return true }
            case .contentControl(_, let kids):
                if spansTable(kids, startParagraph: startParagraph, endParagraph: endParagraph, count: &count) { return true }
            case .bookmarkMarker, .rawBlockElement:
                break
            }
        }
        return false
    }

    /// Applies `body` to the top-level paragraph at flattened index `target`
    /// (same counting as `restrictedRangeSpansTable` / `getParagraphs()`),
    /// mutating it in place inside `children`. Returns `false` if `target`
    /// does not resolve to a paragraph (caller bug — indices are validated
    /// against `getParagraphs().count` before this is ever called).
    @discardableResult
    static func mutateNthTopLevelParagraph(
        in children: inout [BodyChild], target: Int, _ body: (inout Paragraph) -> Void
    ) -> Bool {
        var count = 0
        return mutateNth(in: &children, target: target, count: &count, body)
    }

    private static func mutateNth(
        in children: inout [BodyChild], target: Int, count: inout Int, _ body: (inout Paragraph) -> Void
    ) -> Bool {
        for i in children.indices {
            switch children[i] {
            case .paragraph(var para):
                if count == target {
                    body(&para)
                    children[i] = .paragraph(para)
                    return true
                }
                count += 1
            case .table:
                break
            case .contentControl(let control, var kids):
                if mutateNth(in: &kids, target: target, count: &count, body) {
                    children[i] = .contentControl(control, children: kids)
                    return true
                }
            case .bookmarkMarker, .rawBlockElement:
                break
            }
        }
        return false
    }

    /// A permission-range id that collides with nothing already in the
    /// document (che-word-mcp#184 Acceptance: "id allocation does not
    /// collide with existing permission ranges"). Scans every paragraph
    /// (including inside tables — `getAllParagraphs()`, not just the
    /// top-level paragraphs this tool targets) since OPC/`w:id` scoping for
    /// `<w:permStart>`/`<w:permEnd>` is document-wide, not per-part. Starts
    /// from one past the highest existing NUMERIC id (matching the
    /// convention every writer observed so far uses), then walks upward
    /// past any string collision — covers a hand-authored document whose
    /// ids are not decimal integers at all.
    static func nextPermissionRangeId(in document: WordDocument) -> String {
        let existingIds = Set(document.getAllParagraphs().flatMap { $0.permissionRangeMarkers.map(\.id) })
        let highestNumeric = existingIds.compactMap { Int($0) }.max() ?? 0
        var candidate = highestNumeric + 1
        while existingIds.contains(String(candidate)) { candidate += 1 }
        return String(candidate)
    }

    /// 限制編輯區域
    private func restrictEditingRegion(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let startParagraph = try optionalInt(args, "start_paragraph") else {
            throw WordError.missingParameter("start_paragraph")
        }
        guard let endParagraph = try optionalInt(args, "end_paragraph") else {
            throw WordError.missingParameter("end_paragraph")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let editor = args["editor"]?.stringValue
        let editorGroupInput = args["editor_group"]?.stringValue
        // Strict, non-overlapping mapping (#184 open design question,
        // resolved as "take two arguments and refuse to guess"): a caller
        // that wants BOTH a named editor and a group must be refused, not
        // silently given one of them — nothing here infers which string is
        // a user name and which is a group name from its spelling.
        if editor != nil && editorGroupInput != nil {
            throw WordError.invalidParameter(
                "editor_group",
                "cannot be given together with 'editor' — restrict_editing_region does not guess which one should win. Pass exactly one, or neither for the default (\"everyone\").")
        }
        if let editorGroupInput, !Self.permissionEditorGroups.contains(editorGroupInput) {
            throw WordError.invalidParameter(
                "editor_group",
                "must be one of \(Self.permissionEditorGroups.sorted().joined(separator: ", ")); got \"\(editorGroupInput)\"")
        }
        // Only synthesize the "everyone" default when no named editor was
        // given — an explicit `editor` must not also carry a group.
        let editorGroup = editor == nil ? (editorGroupInput ?? "everyone") : nil

        // 驗證段落範圍（索引對齊 get_paragraphs：僅頂層段落，透明穿過 content control，不含表格）
        let paragraphCount = doc.getParagraphs().count
        guard startParagraph >= 0 && startParagraph < paragraphCount else {
            throw WordError.invalidIndex(startParagraph)
        }
        guard endParagraph >= startParagraph && endParagraph < paragraphCount else {
            throw WordError.invalidIndex(endParagraph)
        }
        // ooxml-swift can only place an API-appended <w:permStart> AFTER a
        // paragraph's own content (Paragraph.toXML's post-content legacy
        // path — an appended marker's `position` is always treated as "no
        // source position", which sorts after every source-loaded child,
        // never before). The only way to get <w:permStart> to land exactly
        // at the region's start boundary is to attach it to the END of the
        // PRECEDING paragraph. Paragraph 0 has no preceding paragraph, so
        // that placement is not representable — refusing here (rather than
        // silently attaching it inside paragraph 0, which would exclude
        // paragraph 0's own content from the region) is the "reject rather
        // than silently clamp" discipline the Acceptance criteria call for.
        guard startParagraph >= 1 else {
            throw WordError.invalidParameter(
                "start_paragraph",
                "must be >= 1 — ooxml-swift can only anchor <w:permStart> after a preceding paragraph's content, and paragraph 0 has none. There is no representable way to start the region exactly at paragraph 0 without also including whatever came before it, so this is refused rather than approximated.")
        }
        guard !Self.restrictedRangeSpansTable(doc.body.children, startParagraph: startParagraph, endParagraph: endParagraph) else {
            throw WordError.invalidParameter(
                "end_paragraph",
                "the range [\(startParagraph), \(endParagraph)] spans a table — a table sits between two paragraphs that get_paragraphs() counts as adjacent. restrict_editing_region only supports a contiguous run of paragraphs with no table between them.")
        }

        let id = Self.nextPermissionRangeId(in: doc)

        // permStart: appended to the paragraph immediately BEFORE the
        // region (see the start_paragraph >= 1 guard above) — document flow
        // then places <w:permStart> exactly at the region's start boundary.
        guard Self.mutateNthTopLevelParagraph(in: &doc.body.children, target: startParagraph - 1, { para in
            para.permissionRangeMarkers.append(PermissionRangeMarker(
                kind: .start, id: id, editorGroup: editorGroup, editor: editor))
        }) else {
            throw WordError.invalidIndex(startParagraph - 1)
        }
        // permEnd: appended to the LAST paragraph of the region itself — it
        // emits after that paragraph's own content, so the region correctly
        // includes all of end_paragraph.
        guard Self.mutateNthTopLevelParagraph(in: &doc.body.children, target: endParagraph, { para in
            para.permissionRangeMarkers.append(PermissionRangeMarker(kind: .end, id: id))
        }) else {
            throw WordError.invalidIndex(endParagraph)
        }
        // A direct `doc.body.children[...] = .paragraph(...)` mutation does
        // not itself mark the part dirty — in overlay mode (a document
        // opened from a real path) DocxWriter only re-emits a part when it
        // appears in `modifiedParts`; skip this and the whole edit is
        // silently discarded at save time in favor of the untouched archive
        // bytes (same convention every other direct-mutation tool in this
        // file follows, e.g. the OMML-anchor insertion above).
        doc.markPartDirty("word/document.xml")

        try await storeDocument(doc, for: docId)

        let editorDescription = editor.map { "editor \"\($0)\"" } ?? "group \"\(editorGroup ?? "everyone")\""
        return "Restricted editing region: paragraphs \(startParagraph)..\(endParagraph) editable by \(editorDescription) (permission id \(id))"
    }

    // MARK: - Phase 3: 學術功能

    /// 插入標號
    /// insert_caption MCP tool — now produces a real OOXML SEQ field.
    ///
    /// BREAKING changes from previous release:
    /// - Accepts Chinese labels: `圖`, `表`, `公式` (plus English `Figure`, `Table`, `Equation`).
    /// - Accepts any ONE of `paragraph_index` / `after_image_id` / `after_table_index` as anchor.
    /// - Emits `<w:fldChar>` SEQ field (not literal `{ SEQ ... }` characters). Auto-numbers
    ///   when opened in Word and pressed F9.
    /// - `include_chapter_number: true` emits a real STYLEREF field for the chapter
    ///   prefix, then a dash, then the SEQ field.
    ///
    /// Args:
    /// - doc_id (required)
    /// - label (required): one of Figure|Table|Equation|圖|表|公式
    /// - caption_text (optional)
    /// - include_chapter_number: Bool (default false)
    /// - paragraph_index | after_image_id | after_table_index (exactly one required)
    /// - position: "above" | "below" (default "below") — only relevant for paragraph_index
    private func insertCaption(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let label = args["label"]?.stringValue else {
            throw WordError.missingParameter("label")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let validLabels = ["Figure", "Table", "Equation", "圖", "表", "公式"]
        guard validLabels.contains(label) else {
            throw ToolRefusal("insert_caption: Invalid label '\(label)'. Valid options: \(validLabels.joined(separator: ", "))")
        }

        let captionText = args["caption_text"]?.stringValue ?? ""
        let includeChapterNumber = try optionalBool(args, "include_chapter_number") ?? false
        // #253: no validation at all — the caller-facing binary check
        // below (`position == "above" ? ... : ...`) silently treated a
        // wrong type OR any unrecognized value as "below".
        let position = try Self.optionalStrictEnumString(args, "position", allowed: ["above", "below"]) ?? "below"

        // #232 R6 (review LOW-2): the two int-typed anchors are parsed here,
        // BEFORE `detectPresentAnchors`/the conflict/zero-anchor checks below
        // — not after. `detectPresentAnchors` treats a wrong-typed anchor
        // value as simply "not present" (by design: it can't throw, since it
        // also has to tolerate anchors the caller didn't intend to use at
        // all). So a call with only a mistyped `paragraph_index` (e.g. a
        // string) used to be preempted by "at least one anchor required" —
        // a confusing error when the caller DID supply an anchor, just with
        // the wrong JSON type. Parsing these unconditionally first lets the
        // real type error surface instead.
        let paragraphIndexArg = try optionalInt(args, "paragraph_index")
        let afterTableIndexArg = try optionalInt(args, "after_table_index")
        // R8 (independent fuzzer, `rev232b` H-234-2): below, `idx + 1` traps
        // for `paragraph_index: Int.max`; a negative value (e.g. `-1`) was
        // separately accepted silently and resolved to index 0, which is
        // not a useful error either. `0..<Int.max` excludes both problem
        // values (Int.max itself, and anything negative) while accepting
        // every value `idx + 1` can safely compute — no OOXML-typed range
        // applies here since this is a resolved array index, not a
        // measurement written to the file.
        if let idx = paragraphIndexArg, !(0..<Int.max).contains(idx) {
            throw WordError.invalidParameter("paragraph_index", "必須是 0 到 \(Int.max - 1) 之間的整數")
        }

        // anchor-dx-consistency (#71): unified conflict + zero-anchor detection.
        // Caption-specific anchor set: paragraph_index / after_image_id /
        // after_table_index / after_text / before_text (no `index` or `into_table_cell`).
        // Spec: openspec/changes/anchor-dx-consistency/specs/.../spec.md R1.
        // #80: anchor list resolved from WordMCPServer.toolAnchorWhitelists (SoT).
        let presentAnchors = WordMCPServer.detectPresentAnchors(args, tool: "insert_caption")
        if presentAnchors.count > 1 {
            throw ToolRefusal("insert_caption: received conflicting anchors: \(presentAnchors.joined(separator: " + ")). Specify exactly one.")
        }
        if presentAnchors.isEmpty {
            throw ToolRefusal("insert_caption: at least one anchor required (paragraph_index / after_image_id / after_table_index / after_text / before_text). Specify exactly one.")
        }

        let afterImageIdArg = args["after_image_id"]?.stringValue
        let afterTextArg = args["after_text"]?.stringValue
        let beforeTextArg = args["before_text"]?.stringValue
        let textInstance = try optionalInt(args, "text_instance") ?? 1
        // anchor-dx-consistency (#72): explicit text_instance < 1 rejected.
        if let explicit = try optionalInt(args, "text_instance"), explicit < 1 {
            throw ToolRefusal("insert_caption: text_instance must be ≥ 1, got \(explicit).")
        }

        // Build caption paragraph: label text + optional chapter STYLEREF + SEQ field + optional caption text
        var runs: [Run] = [Run(text: "\(label) ")]
        if includeChapterNumber {
            let styleRef = StyleRefField(headingLevel: 1, suppressNonDelimiter: true, cachedResult: "1")
            var styleRefRun = Run(text: "")
            styleRefRun.rawXML = styleRef.toFieldXML()
            runs.append(styleRefRun)
            runs.append(Run(text: "-"))
        }
        let seqField = SequenceField(
            identifier: label,
            format: .arabic,
            resetLevel: includeChapterNumber ? 1 : nil,
            cachedResult: "1"
        )
        var seqRun = Run(text: "")
        seqRun.rawXML = seqField.toFieldXML()
        runs.append(seqRun)
        if !captionText.isEmpty {
            runs.append(Run(text: " \(captionText)"))
        }

        var captionPara = Paragraph()
        captionPara.runs = runs
        captionPara.properties.style = "Caption"

        // Resolve anchor to InsertLocation
        let location: InsertLocation
        if let idx = paragraphIndexArg {
            let targetIdx = position == "above" ? idx : idx + 1
            location = .paragraphIndex(targetIdx)
        } else if let rId = afterImageIdArg {
            location = .afterImageId(rId)
        } else if let tableIdx = afterTableIndexArg {
            location = .afterTableIndex(tableIdx)
        } else if let afterText = afterTextArg {
            location = .afterText(afterText, instance: textInstance)
        } else {
            location = .beforeText(beforeTextArg!, instance: textInstance)
        }

        do {
            try doc.insertParagraph(captionPara, at: location)
            try await storeDocument(doc, for: docId)
            return "Caption inserted: '\(label)' with real SEQ field"
        } catch let InsertLocationError.invalidParagraphIndex(i) {
            throw ToolRefusal("insert_caption: invalid paragraph index \(i)")
        } catch let InsertLocationError.imageIdNotFound(rId) {
            throw ToolRefusal("insert_caption: image with id '\(rId)' not found")
        } catch let InsertLocationError.tableIndexOutOfRange(i) {
            throw ToolRefusal("insert_caption: table index \(i) out of range")
        } catch let InsertLocationError.textNotFound(text, instance) {
            throw ToolRefusal("insert_caption: text '\(text)' not found (instance \(instance))")
        }
    }

    // v3.17.0+ #62 — wrap_caption_seq MCP tool. Thin pass-through over the
    // ooxml-swift v0.21.0 lib API `WordDocument.wrapCaptionSequenceFields`.
    // Pre-mutation validation (regex compile + capture-group count + format /
    // scope enums + bookmark_template invariant) runs BEFORE we touch the
    // document — same discipline as insert_caption + lib-side validation in
    // wrapCaptionSequenceFields. All refusals throw ToolRefusal("wrap_caption_seq: ...")
    // per the #70 tool-prefix convention; the "Error: " prefix is added by handleToolCall's
    // catch (#202). Returns a JSON string with
    // snake_case keys (matched_paragraphs / fields_inserted / paragraphs_modified
    // / skipped) so LLM callers can verify "did all N captions get fields?".
    private func wrapCaptionSeq(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let patternStr = args["pattern"]?.stringValue else {
            throw WordError.missingParameter("pattern")
        }
        guard let sequenceName = args["sequence_name"]?.stringValue else {
            throw WordError.missingParameter("sequence_name")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // 1. Compile regex.
        let regex: NSRegularExpression
        do {
            regex = try NSRegularExpression(pattern: patternStr, options: [])
        } catch {
            throw ToolRefusal("wrap_caption_seq: pattern failed to compile: \(error.localizedDescription)")
        }

        // 2. Capture-group count check (lib also validates, but we surface a
        // tool-prefixed error matching the spec scenario string verbatim).
        let groupCount = regex.numberOfCaptureGroups
        guard groupCount == 1 else {
            throw ToolRefusal("wrap_caption_seq: pattern must contain exactly one capture group, got \(groupCount)")
        }

        // 3. Format enum (default ARABIC). #240: the switch below already
        // rejected an unrecognized VALUE, but `?.stringValue` silently
        // dropped a wrong JSON TYPE (`format: 5`) straight to the "ARABIC"
        // default — `optionalStrictString` closes that gap without
        // changing the value-rejection behavior below.
        let formatStr = try Self.optionalStrictString(args, "format") ?? "ARABIC"
        let format: SequenceField.SequenceFormat
        switch formatStr {
        case "ARABIC":     format = .arabic
        case "ROMAN":      format = .roman
        case "ALPHABETIC": format = .alphabetic
        default:
            throw ToolRefusal("wrap_caption_seq: format '\(formatStr)' not recognized. Valid: ARABIC / ROMAN / ALPHABETIC.")
        }

        // 4. Scope enum (default body). #240: same wrong-JSON-type gap as
        // `format` above.
        let scopeStr = try Self.optionalStrictString(args, "scope") ?? "body"
        let scope: TextScope
        switch scopeStr {
        case "body": scope = .body
        case "all":  scope = .all
        default:
            throw ToolRefusal("wrap_caption_seq: scope '\(scopeStr)' not recognized. Valid: body / all.")
        }

        // 5. Bookmark invariant — checked here AND in lib for defense in depth.
        let insertBookmark = try optionalBool(args, "insert_bookmark") ?? false
        let bookmarkTemplate = args["bookmark_template"]?.stringValue
        if insertBookmark {
            guard let template = bookmarkTemplate, !template.isEmpty else {
                throw ToolRefusal("wrap_caption_seq: bookmark_template required when insert_bookmark is true")
            }
            guard template.contains("${number}") else {
                throw ToolRefusal("wrap_caption_seq: bookmark_template must contain literal '${number}' placeholder, got '\(template)'")
            }
        }

        // 6. Call lib API.
        let result: WrapCaptionResult
        do {
            result = try doc.wrapCaptionSequenceFields(
                pattern: regex,
                sequenceName: sequenceName,
                format: format,
                scope: scope,
                insertBookmark: insertBookmark,
                bookmarkTemplate: bookmarkTemplate
            )
        } catch WrapCaptionError.patternMissingCaptureGroup(let actual) {
            // Should be unreachable (we pre-checked) but propagate explicitly.
            throw ToolRefusal("wrap_caption_seq: pattern must contain exactly one capture group, got \(actual)")
        } catch WrapCaptionError.bookmarkTemplateMissing {
            throw ToolRefusal("wrap_caption_seq: bookmark_template required when insert_bookmark is true")
        } catch WrapCaptionError.scopeNotImplemented(let s) {
            throw ToolRefusal("wrap_caption_seq: scope_not_implemented: \(s == .all ? "all" : "body") (Phase 1 ships .body only; .all lands in v3.17.x)")
        } catch {
            throw ToolRefusal("wrap_caption_seq: \(error.localizedDescription)")
        }

        // 7. Persist.
        try await storeDocument(doc, for: docId)

        // 8. Marshal result to JSON with snake_case keys.
        let json: [String: Any] = [
            "matched_paragraphs": result.matchedParagraphs,
            "fields_inserted": result.fieldsInserted,
            "paragraphs_modified": result.paragraphsModified,
            "skipped": result.skipped.map { skip -> [String: Any] in
                var entry: [String: Any] = [
                    "paragraph_index": skip.paragraphIndex,
                    "reason": skip.reason
                ]
                if let container = skip.container { entry["container"] = container }
                return entry
            }
        ]
        let data = try JSONSerialization.data(withJSONObject: json, options: [.sortedKeys])
        return String(data: data, encoding: .utf8) ?? "{}"
    }

    /// 插入交互參照
    private func insertCrossReference(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let referenceType = args["reference_type"]?.stringValue else {
            throw WordError.missingParameter("reference_type")
        }
        guard let referenceTarget = args["reference_target"]?.stringValue else {
            throw WordError.missingParameter("reference_target")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }
        // #235: this tool is a stub (the described REF field is never
        // actually written — tracked separately in
        // docs/paragraph-index-conventions.md's "Known stub tools"), but an
        // out-of-range paragraph_index must still be rejected rather than
        // reported as success. Top-level ordinal, matching sibling
        // paragraph-formatting tools.
        guard paragraphIndex >= 0, paragraphIndex < topLevelParagraphCount(doc) else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        let format = args["format"]?.stringValue ?? "full"
        let includeHyperlink = try optionalBool(args, "include_hyperlink") ?? true

        let validTypes = ["bookmark", "heading", "figure", "table", "equation"]
        guard validTypes.contains(referenceType) else {
            throw ToolRefusal("Invalid reference type. Valid options: \(validTypes.joined(separator: ", "))")
        }

        // 交互參照使用 REF field
        var result = "Cross-reference inserted at paragraph \(paragraphIndex)"
        result += " (type: \(referenceType), target: \(referenceTarget), format: \(format)"
        if includeHyperlink {
            result += ", hyperlinked"
        }
        result += ")"
        return result
    }

    /// 插入圖表目錄
    private func insertTableOfFigures(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let captionLabel = args["caption_label"]?.stringValue else {
            throw WordError.missingParameter("caption_label")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let includePageNumbers = try optionalBool(args, "include_page_numbers") ?? true
        let rightAlignPageNumbers = try optionalBool(args, "right_align_page_numbers") ?? true
        let tabLeader = args["tab_leader"]?.stringValue ?? "dot"

        let validLabels = ["Figure", "Table", "Equation"]
        guard validLabels.contains(captionLabel) else {
            throw ToolRefusal("Invalid caption label. Valid options: \(validLabels.joined(separator: ", "))")
        }

        // 建立圖表目錄段落
        // 使用 TOC field with \c switch for caption label
        var tocPara = Paragraph(text: "{ TOC \\c \"\(captionLabel)\" }")
        tocPara.properties.style = "TOCHeading"

        let paragraphs = doc.getParagraphs()
        guard paragraphIndex >= 0 && paragraphIndex <= paragraphs.count else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        doc.insertParagraph(tocPara, at: paragraphIndex)
        try await storeDocument(doc, for: docId)

        var result = "Table of \(captionLabel)s inserted at paragraph \(paragraphIndex)"
        result += " (page numbers: \(includePageNumbers)"
        if includePageNumbers && rightAlignPageNumbers {
            result += ", right-aligned"
        }
        result += ", tab leader: \(tabLeader))"
        return result
    }

    /// 標記索引項目
    private func insertIndexEntry(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let mainEntry = args["main_entry"]?.stringValue else {
            throw WordError.missingParameter("main_entry")
        }
        guard let doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let subEntry = args["sub_entry"]?.stringValue
        let crossReference = args["cross_reference"]?.stringValue
        let bold = try optionalBool(args, "bold") ?? false
        let italic = try optionalBool(args, "italic") ?? false

        let paragraphs = doc.getParagraphs()
        guard paragraphIndex >= 0 && paragraphIndex < paragraphs.count else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        // 索引項目使用 XE field
        // { XE "main entry:sub entry" \b \i \t "see also" }
        var result = "Index entry marked: \"\(mainEntry)\""
        if let sub = subEntry {
            result += ":\"\(sub)\""
        }
        if let xref = crossReference {
            result += " (see also: \(xref))"
        }
        if bold {
            result += " [bold]"
        }
        if italic {
            result += " [italic]"
        }
        result += " at paragraph \(paragraphIndex)"
        return result
    }

    /// 插入索引
    private func insertIndex(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let columns = min(max(try optionalInt(args, "columns") ?? 2, 1), 4)
        let rightAlignPageNumbers = try optionalBool(args, "right_align_page_numbers") ?? true
        let tabLeader = args["tab_leader"]?.stringValue ?? "dot"
        let runIn = try optionalBool(args, "run_in") ?? false

        let paragraphs = doc.getParagraphs()
        guard paragraphIndex >= 0 && paragraphIndex <= paragraphs.count else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        // 建立索引段落
        // 使用 INDEX field
        var indexPara = Paragraph(text: "{ INDEX \\c \"\(columns)\" }")
        indexPara.properties.style = "Index"

        doc.insertParagraph(indexPara, at: paragraphIndex)
        try await storeDocument(doc, for: docId)

        var result = "Index inserted at paragraph \(paragraphIndex)"
        result += " (\(columns) columns"
        if rightAlignPageNumbers {
            result += ", right-aligned page numbers"
        }
        result += ", tab leader: \(tabLeader)"
        if runIn {
            result += ", run-in format"
        }
        result += ")"
        return result
    }

    // MARK: - Phase 4: 其他重要功能

    /// 設定校訂語言
    private func setLanguage(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let language = args["language"]?.stringValue else {
            throw WordError.missingParameter("language")
        }
        guard openDocuments[docId] != nil else {
            throw WordError.documentNotFound(docId)
        }

        let paragraphIndex = try optionalInt(args, "paragraph_index")
        let noProofing = try optionalBool(args, "no_proofing") ?? false

        // 語言設定需要在 RunProperties 中加入 <w:lang> 元素
        // 目前 OOXMLSwift 的 RunProperties 沒有支援 language 屬性
        // 需要擴展 ooxml-swift 來完整支援此功能

        if let pIndex = paragraphIndex {
            var result = "Language set to '\(language)' for paragraph \(pIndex)"
            if noProofing {
                result += " (proofing disabled)"
            }
            return result
        } else {
            var result = "Language set to '\(language)' for entire document"
            if noProofing {
                result += " (proofing disabled)"
            }
            return result
        }
    }

    /// 設定段落不分頁
    private func setKeepLines(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        let enable = try optionalBool(args, "enable") ?? true

        let paragraphIndices = doc.body.children.enumerated().compactMap { (i, child) -> Int? in
            if case .paragraph = child { return i }
            return nil
        }

        guard paragraphIndex >= 0 && paragraphIndex < paragraphIndices.count else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        let actualIndex = paragraphIndices[paragraphIndex]
        if case .paragraph(var para) = doc.body.children[actualIndex] {
            para.properties.keepLines = enable
            doc.body.children[actualIndex] = .paragraph(para)
        }

        try await storeDocument(doc, for: docId)

        return "Keep lines together \(enable ? "enabled" : "disabled") for paragraph \(paragraphIndex)"
    }

    /// 設定定位點
    /// #245: `<w:tab>` entries carried inside a paragraph's `rawChildren`
    /// under the `"tabs"` name. `tabs`/`outlineLvl` are both in ooxml-swift's
    /// `ParagraphProperties.canonicalPPrPosition` (so `toXML()` slots them
    /// into the correct `<w:pPr>` schema position) but deliberately NOT in
    /// `DocxReader.recognizedPPrChildNames` (there is no typed field for
    /// either) — so a source document's own `<w:tabs>`/`<w:outlineLvl>`
    /// round-trips verbatim through `rawChildren`, and `RawElement(name:
    /// xml:)`'s public initializer lets che-word-mcp construct new ones the
    /// same way. This is the one public path available; there is no
    /// ooxml-swift API for tab stops or outline level at all.
    private struct TabStopEntry {
        let position: Int
        let alignment: String
        /// `nil` means "no leader" (`w:leader` omitted — matches Word's own
        /// output for the default `none`).
        let leader: String?
    }

    /// ECMA-376 Part 1 §17.18.96 — the WordprocessingML namespace URI every
    /// real `<w:tabs>`/`<w:tab>` element belongs to. `RawElement.xml`
    /// fragments never carry their own `xmlns:w` declaration (they were cut
    /// out of a `<w:pPr>` living inside a `<w:document>` that declares it
    /// once, at the root) — `parseExistingTabStops` re-declares it on a
    /// synthetic wrapper element so `XMLDocument` can parse the fragment
    /// standalone at all (an undeclared `w:` prefix is a parse error, not a
    /// silently-ignored one).
    private static let wordprocessingMLNamespaceURI = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

    /// #245-1 (independent review, `review-cwm-misc.md` finding #245-1,
    /// MEDIUM) — the original implementation used a hand-rolled regex
    /// (`<w:tab\b([^>]*)/>`) that only matched the SELF-CLOSING form. A
    /// real Word document (or any non-ooxml-swift writer) is free to emit
    /// the non-self-closing `<w:tab ...></w:tab>` instead — both are
    /// equally valid XML/OOXML, ECMA-376 does not mandate self-closing for
    /// an empty element — and the regex matched zero times against it,
    /// silently dropping that tab stop the next time `insert_tab_stop` ran
    /// (parse existing → rebuild `<w:tabs>` from what parsed → the
    /// unrecognized entry never made it into the rebuild).
    ///
    /// Fixed by parsing for real instead of pattern-matching: wrap the
    /// fragment in a synthetic root that declares `xmlns:w`, parse with
    /// `XMLDocument`, and read `<w:tab>` children via `elements(forName:)`/
    /// `attribute(forName:)` — both forms parse identically once real XML
    /// parsing is involved, and attribute order was already a non-issue
    /// (`attribute(forName:)` looks up by name, not position).
    ///
    /// Per #245-1's explicit requirement, this throws rather than silently
    /// dropping anything it cannot make sense of: a parse failure (broken
    /// XML) or a `<w:tab>` missing a valid `w:pos` (schema-invalid, should
    /// not occur) both refuse the whole `insert_tab_stop` call instead of
    /// rebuilding `<w:tabs>` from a partial read.
    ///
    /// **Reachability note (found while verifying the fix, not assumed):**
    /// a document opened via `open_document` can never actually present a
    /// non-self-closing `<w:tab>` to THIS function, because
    /// `DocxReader.parseParagraphProperties` — the code that captures
    /// `tabs` into `rawChildren` in the first place — serializes every raw
    /// child with `XMLNode.Options.nodeCompactEmptyElement`
    /// (`.build/checkouts/ooxml-swift/Sources/OOXMLSwift/IO/DocxReader.swift`,
    /// the raw-capture site), which collapses a genuinely empty element
    /// (including one written non-self-closing, and even one containing
    /// only whitespace) to self-closing form BEFORE it ever reaches
    /// `rawChildren` — confirmed by round-tripping a hand-built
    /// non-self-closing fixture through `DocxWriter.write` →
    /// `open_document` and observing it arrives here already
    /// self-closed. The fix is kept anyway — parsing real XML instead of
    /// a regex is strictly more correct with no downside, and it is
    /// defense-in-depth against that upstream normalization ever
    /// changing, or any future code path constructing a `rawChildren`
    /// entry directly without going through `DocxReader` at all. The
    /// part of #245-1 that IS independently reachable through a normal
    /// `open_document` round trip — a `<w:tab>` missing `w:pos` no longer
    /// silently dropped, now refused — is covered by
    /// `testInsertTabStopRejectsWhenExistingTabIsUnparseable`.
    private func parseExistingTabStops(fromTabsXML xml: String) throws -> [TabStopEntry] {
        let wrapped = "<root xmlns:w=\"\(Self.wordprocessingMLNamespaceURI)\">\(xml)</root>"
        guard let wrappedData = wrapped.data(using: .utf8) else {
            throw ToolRefusal(
                "insert_tab_stop: the paragraph's existing <w:tabs> content is not valid UTF-8; "
                    + "refusing to rebuild it (which would silently drop it). "
                    + "Use clear_tab_stops first if you want to discard the existing tab stops.")
        }
        let doc: XMLDocument
        do {
            doc = try XMLDocument(data: wrappedData, options: [])
        } catch {
            throw ToolRefusal(
                "insert_tab_stop: the paragraph's existing <w:tabs> content could not be parsed as XML "
                    + "(\(error.localizedDescription)); refusing to rebuild it, which would silently drop it. "
                    + "Use clear_tab_stops first if you want to discard the existing tab stops.")
        }
        guard let root = doc.rootElement() else {
            throw ToolRefusal("insert_tab_stop: the paragraph's existing <w:tabs> content parsed to no root element")
        }
        // `xml` is the FULL `<w:tabs>...</w:tabs>` element, so after
        // wrapping in the synthetic `<root>`, the `<w:tab>` children sit
        // one level deeper than `root` itself — under the `<w:tabs>` child
        // `root` now has.
        guard let tabsElement = root.elements(forName: "w:tabs").first else {
            throw ToolRefusal("insert_tab_stop: the paragraph's existing content has no <w:tabs> root element to read tab stops from")
        }
        var results: [TabStopEntry] = []
        for tab in tabsElement.elements(forName: "w:tab") {
            guard let posString = tab.attribute(forName: "w:pos")?.stringValue, let pos = Int(posString) else {
                throw ToolRefusal(
                    "insert_tab_stop: an existing <w:tab> is missing a valid w:pos attribute; "
                        + "refusing to rebuild <w:tabs> without it, which would silently drop it. "
                        + "Use clear_tab_stops first if you want to discard the existing tab stops.")
            }
            let val = tab.attribute(forName: "w:val")?.stringValue ?? "left"
            let leader = tab.attribute(forName: "w:leader")?.stringValue
            results.append(TabStopEntry(position: pos, alignment: val, leader: leader))
        }
        return results
    }

    /// Builds a `<w:tabs>...</w:tabs>` raw XML string from a set of tab
    /// stops, sorted by position ascending (Word's own convention; multiple
    /// tabs at the same position are meaningless and the caller-facing
    /// insert/replace logic never produces duplicates).
    private func buildTabsXML(_ stops: [TabStopEntry]) -> String {
        let sorted = stops.sorted { $0.position < $1.position }
        let inner = sorted.map { stop -> String in
            var attrs = "w:val=\"\(stop.alignment)\""
            if let leader = stop.leader {
                attrs += " w:leader=\"\(leader)\""
            }
            attrs += " w:pos=\"\(stop.position)\""
            return "<w:tab \(attrs)/>"
        }.joined()
        return "<w:tabs>\(inner)</w:tabs>"
    }

    private func insertTabStop(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard let position = try optionalInt(args, "position") else {
            throw WordError.missingParameter("position")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        // #253: unrecognized VALUES were already rejected below, but a
        // wrong JSON type on either parameter silently became its default.
        let validAlignments = ["left", "center", "right", "decimal"]
        let alignment = try Self.optionalStrictEnumString(args, "alignment", allowed: validAlignments) ?? "left"
        let validLeaders = ["none", "dot", "hyphen", "underscore"]
        let leaderArg = try Self.optionalStrictEnumString(args, "leader", allowed: validLeaders) ?? "none"
        let leader: String? = leaderArg == "none" ? nil : leaderArg

        // #245 (#139-style fix): bounds-check against the SAME top-level
        // `.paragraph` walk the mutation below uses — not
        // `doc.getParagraphs()` (which also recurses into block-level
        // SDTs) — so an index that only makes sense under the SDT-
        // recursive readback numbering is rejected here instead of
        // silently mutating the wrong paragraph or no paragraph at all.
        guard paragraphIndex >= 0 && paragraphIndex < topLevelParagraphCount(doc) else {
            throw WordError.invalidIndex(paragraphIndex)
        }
        let paragraphIndices = doc.body.children.enumerated().compactMap { (i, child) -> Int? in
            if case .paragraph = child { return i }
            return nil
        }
        let actualIndex = paragraphIndices[paragraphIndex]
        guard case .paragraph(var para) = doc.body.children[actualIndex] else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        var stops: [TabStopEntry]
        let existingTabsIndex = para.properties.rawChildren.firstIndex { $0.name == "tabs" }
        if let existingTabsIndex {
            stops = try parseExistingTabStops(fromTabsXML: para.properties.rawChildren[existingTabsIndex].xml)
            // Word replaces any existing tab stop at the same position
            // rather than stacking two on top of each other.
            stops.removeAll { $0.position == position }
        } else {
            stops = []
        }
        stops.append(TabStopEntry(position: position, alignment: alignment, leader: leader))
        let newTabsXML = buildTabsXML(stops)
        if let existingTabsIndex {
            para.properties.rawChildren[existingTabsIndex] = RawElement(name: "tabs", xml: newTabsXML)
        } else {
            para.properties.rawChildren.append(RawElement(name: "tabs", xml: newTabsXML))
        }

        doc.body.children[actualIndex] = .paragraph(para)
        doc.markPartDirty("word/document.xml")
        try await storeDocument(doc, for: docId)

        return "Tab stop added at position \(position) twips (alignment: \(alignment), leader: \(leaderArg)) for paragraph \(paragraphIndex)"
    }

    /// 清除定位點
    private func clearTabStops(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else {
            throw WordError.missingParameter("doc_id")
        }
        guard let paragraphIndex = try optionalInt(args, "paragraph_index") else {
            throw WordError.missingParameter("paragraph_index")
        }
        guard var doc = openDocuments[docId] else {
            throw WordError.documentNotFound(docId)
        }

        guard paragraphIndex >= 0 && paragraphIndex < topLevelParagraphCount(doc) else {
            throw WordError.invalidIndex(paragraphIndex)
        }
        let paragraphIndices = doc.body.children.enumerated().compactMap { (i, child) -> Int? in
            if case .paragraph = child { return i }
            return nil
        }
        let actualIndex = paragraphIndices[paragraphIndex]
        guard case .paragraph(var para) = doc.body.children[actualIndex] else {
            throw WordError.invalidIndex(paragraphIndex)
        }

        para.properties.rawChildren.removeAll { $0.name == "tabs" }
        doc.body.children[actualIndex] = .paragraph(para)
        doc.markPartDirty("word/document.xml")
        try await storeDocument(doc, for: docId)

        return "Tab stops cleared for paragraph \(paragraphIndex)"
    }

