        }
        return Self.renderNumberingDefinitionsJSON(doc.numbering, scope: numId)
    }

    private func createNumberingDefinition(args: [String: Value]) async throws -> String {
        guard let docId = args["doc_id"]?.stringValue else { throw WordError.missingParameter("doc_id") }
        guard var doc = openDocuments[docId] else { throw WordError.documentNotFound(docId) }
        guard let levelsArr = args["levels"]?.arrayValue else { throw WordError.missingParameter("levels") }

        var levels: [Level] = []
        for item in levelsArr {
            // #232 R6 (review H1): `start` parsed BEFORE the required-field
            // guard, not after — an item missing `num_format`/`lvl_text`
            // used to `continue` first, so a mistyped `start` on that same
            // item was never validated. Same class as set_latent_styles.
            guard let obj = item.objectValue else { continue }
            let startArg = try optionalInt(obj, "start")
            guard let ilvl = try optionalInt(obj, "ilvl"),
                  let fmtStr = obj["num_format"]?.stringValue,
                  let lvlText = obj["lvl_text"]?.stringValue
            else { continue }
            // R8 (independent fuzzer, `rev232b` H-234-1): `indent: 720 *
            // (ilvl + 1)` traps for `ilvl` near `Int.max`/`Int.min` — this
            // is exactly #234's own broadened audit criterion ("使用者輸入
            // 經任何算術...後轉成 Int 的所有路徑"), missed because the grep
            // that found #234's 8 sites looked for `variable * literal` /
            // `literal * variable`; this site's shape is `literal *
            // (variable + literal)`, one level of parenthesization away.
            // Word's own numbering UI only exposes list levels 0–8 (9
            // levels total) — `set_list_level` (ooxml-swift
            // `Document.swift`) already enforces this identical range for
            // the sibling `level` parameter with the message "Must be
            // between 0 and 8"; matched here for consistency.
            guard (0...8).contains(ilvl) else {
                throw WordError.invalidParameter("ilvl", "必須介於 0 到 8 之間")
            }
            let fmt = NumberFormat(rawValue: fmtStr) ?? .decimal
            let start = startArg ?? 1
            levels.append(Level(ilvl: ilvl, start: start, numFmt: fmt, lvlText: lvlText, indent: 720 * (ilvl + 1)))
        }
        do {
            let numId = try doc.createNumberingDefinition(levels: levels)
            try await storeDocument(doc, for: docId)
            return "{ \"num_id\": \(numId) }"
        } catch WordError.invalidIndex(let count) {
            // #238: this used to `return` a `{ "error": "invalid_levels", ... }`
            // string as if it were a normal successful result — `isError` was
            // never set, so a caller that only checks `isError` (rather than
            // parsing the body as JSON looking for an "error" key) believed
            // the call had succeeded. `count` is 0 when every item in
            // `levels` was missing a required field (ilvl/num_format/
            // lvl_text) and therefore skipped above; otherwise it is
            // `levels.count` when ooxml-swift's own upper bound (max 9
            // levels) was exceeded.
            let reason = count == 0
                ? "no valid level entries (each requires 'ilvl', 'num_format', 'lvl_text')"
                : "\(count) levels given, but at most 9 are allowed"
            throw ToolRefusal("create_numbering_definition: invalid 'levels' — \(reason)")
        }
    }

